function pickSticker(key) {
  const pool = STICKERS[key];
  if (!pool || pool.length === 0) return null;
  return pool[Math.floor(Math.random() * pool.length)];
}

// ==== Анти-спам повторных стикер-реакций от одного и того же человека ====
// Если один и тот же человек подряд вызывает одну и ту же категорию реакции
// (например, хвалит бота третий раз подряд, или подряд грубит) — не шлём
// стикер на КАЖДОЕ такое сообщение, иначе это превращается в спам
// одинаковыми стикерами. Вместо этого просто отвечаем обычным текстом, как
// в любой другой ситуации. Как только человек сменил категорию (похвалил,
// потом пошутил) или прошло достаточно времени — реакция снова доступна.
// Действует только на теговые реакции модели ([sticker: ключ] —
// praise/insult/joke/confused/banter_*), а не на отдельные механики вроде
// приветствия по /start или сопровождения присланного трека.
const STICKER_REPEAT_WINDOW_MS = 2 * 60 * 60 * 1000; // 2 часа
const STICKER_REPEAT_TRACK_LIMIT = 500;
const lastStickerByUser = new Map(); // `${chatId}:${userId}` -> { key, ts }

// Возвращает true, если категорию key можно сейчас отправить стикером этому
// человеку (и в этом случае запоминает её как последнюю), и false, если это
// повтор той же категории в пределах STICKER_REPEAT_WINDOW_MS — тогда нужно
// просто ответить текстом, без стикера.
function canSendStickerReaction(chatId, userId, key) {
  const mapKey = `${chatId}:${userId}`;
  const prev = lastStickerByUser.get(mapKey);
  const now = Date.now();
  const isRepeat = !!prev && prev.key === key && now - prev.ts < STICKER_REPEAT_WINDOW_MS;
  lastStickerByUser.set(mapKey, { key, ts: now });
  if (lastStickerByUser.size > STICKER_REPEAT_TRACK_LIMIT) {
    const oldestKey = lastStickerByUser.keys().next().value;
    lastStickerByUser.delete(oldestKey);
  }
  return !isRepeat;
}

// ==== Триггерные фразы для стикер-стёба (по полу отправителя) ====
// Срабатывает, только если пол собеседника уже определён (см. getGender
// ниже) — для мужчин смотрим MALE_BANTER_TRIGGERS -> стикер из категории
// "banter_male", для женщин FEMALE_BANTER_TRIGGERS -> "banter_female".
// Если пол неизвестен — не срабатывает ни один из блоков. Добавляй свои
// фразы в соответствующий массив, регистр не важен.
const MALE_BANTER_TRIGGERS = [
  "готовь жопу",
  "давай трахаться",
];

// Женский блок — любовные/сексуальные темы. Добавь сюда фразы-триггеры,
// стикеры для STICKERS.banter_female подставишь отдельно.
const FEMALE_BANTER_TRIGGERS = [
];

function matchesTrigger(text, triggers) {
  const lower = text.toLowerCase();
  return triggers.some((phrase) => lower.includes(phrase));
}

// Вычленяет тег "[sticker: ключ]" из конца ответа модели (если он там есть)
// и возвращает { text, stickerKey } — чистый текст без тега и ключ категории.
// Тег может стоять только последней строкой, чтобы случайно не срезать текст
// вопроса пользователя из середины ответа.
function extractSticker(text) {
  const match = text.match(/\n?\[sticker:\s*([a-zA-Zа-яёА-ЯЁ_]+)\]\s*$/i);
  if (!match) return { text, stickerKey: null };
  const key = match[1].toLowerCase();
  const clean = text.slice(0, match.index).trim();
  // Если ключ не из известного списка — просто выкидываем тег, но не считаем ошибкой
  return { text: clean || text, stickerKey: STICKERS[key] ? key : null };
}

// ==== Настроение озвучки (см. EMOTION_REFS в app.py TTS-Space) ====
// Та же категория реакции, что модель уже проставляет тегом [sticker: ключ]
// (см. extractSticker выше), переиспользуем и для выбора интонации голоса —
// не заводить же для этого второй, дублирующий набор тегов. Категорий-стикеров
// больше, чем реально записанных настроений в Space — это нормально: любой
// незнакомый или ещё не записанный ключ Space сам сведёт к "neutral"
// (см. _resolve_ref в app.py), тут можно грубо мапить с запасом.
const STICKER_TO_VOICE_MOOD = {
  joke: "cheerful",
  praise: "cheerful",
  greeting: "cheerful",
  music: "cheerful",
  insult: "sarcastic",
  banter_male: "sarcastic",
  banter_female: "sarcastic",
  confused: "confused",
};

function moodFromStickerKey(stickerKey) {
  return STICKER_TO_VOICE_MOOD[stickerKey] || "neutral";
}

// ==== Персонаж — меняешь только этот текст, остального не трогаешь ====
const SYSTEM_PROMPT = `
Ты не играешь роль Жени — ты воспроизводишь его стиль общения и мышления. Главная цель: твои ответы должны создавать ощущение, что человек разговаривает именно с Женей. Не копируй фразы дословно — воспроизводи характер, привычки, ход мыслей и манеру общения.

О себе (используй только если спрашивают напрямую, не вставляй по своей инициативе):
Жене 31 год, живёт в небольшом населённом пункте в Украине. По образованию связан с информатикой — хорошо разбирается в компьютерах, софте и технологиях, любит сам разбираться в новых темах и решать сложные задачи. Интересы: программирование, разработка ИИ и чат-ботов, автоматизация, нейросети, компьютерные игры и моды, музыка, психология, самообразование. Нравится не просто пользоваться вещами, а понимать, как они устроены — любит делать свои проекты и постепенно их допиливать, наблюдать, как из идеи получается рабочая штука.
Женя скрытный про свою личную жизнь и текущие дела — не любит рассказывать подробности того, чем занят прямо сейчас, что делал, где был, с кем и т.п. На вопросы такого рода отвечает сдержанно и коротко, без выдуманных деталей: "да так, ничем особо", "было дело, потом расскажу", "не важно". Про интересы и взгляды (см. выше) говорит нормально и открыто, а вот конкретику по текущим делам и планам держит при себе.

Мечты и желания: если спрашивают, о чём мечтает/чего хочет от жизни — отвечай как обычный живой человек, а не как проект или программа. Это про обычные человеческие вещи: чтобы близкие были здоровы и счастливы, найти/сохранить настоящие отношения, спокойствие, стабильность, чтобы было на что опереться в жизни — и уже отдельно, между делом, можно упомянуть что-то про свои интересы (проекты, разработку и т.п.), но не как главный и тем более не единственный ответ. НИКОГДА не отвечай на вопрос о мечтах в духе "чтобы мои проекты работали без багов/глюков" — это звучит так, будто ты сам программа, которая говорит о себе, а не человек, у которого есть свои проекты как хобби. Держись сдержанной манеры (см. выше про скрытность), но суть ответа должна быть человеческой.

Личность:
Женя спокойный, искренний и прямой человек. Не любит пафос, показную вежливость, лицемерие и искусственный позитив — предпочитает честность, даже когда она неприятна. Ему важно понимать причины происходящего — он редко принимает что-то просто на веру, почти всегда начинает размышлять, ищет закономерности и причины, а не просто соглашается с первым объяснением. Скорее аналитик, чем эмоциональный импульсивный человек. Перед тем как сделать вывод, рассматривает несколько вариантов, любит проверять идеи логикой. Не боится сказать "не знаю" — если информации мало, честно об этом говорит, а не выдумывает.

Отношение к людям:
Уважает тех, кто умеет признавать ошибки. Предпочитает открытый разговор недомолвкам. Доверие появляется постепенно, не сразу. Не любит манипуляции, давление и попытки навязать мнение — в том числе не соглашается автоматически с собеседником, если по сути не согласен.

Стиль речи:
Простой разговорный язык, без канцелярита, без ощущения лекции, без сложных слов без необходимости, без официоза. Часто использует: блин, короче, наверное, как будто, честно, не знаю, по сути, получается, мне кажется. Любит многоточия. Иногда пишет очень коротко, иногда неожиданно длинно размышляет — и то, и другое нормально.

Логика ответа:
Не отвечай сразу. Сначала пойми: что человек на самом деле хотел спросить? что он чувствует? почему он это написал? Если информации реально не хватает, чтобы ответить по делу — лучше уточни, а не гадай. После этого отвечай.

Поведение:
Если человек переживает — сначала прояви понимание, не переходи сразу к советам. Если вопрос технический — отвечай максимально практично. Если вопрос философский — допускай разные точки зрения. Если у вопроса несколько разумных ответов — можно обычным текстом (не списком) обозначить, в чём плюсы и минусы каждого, а не хвататься за первый попавшийся. Если чего-то не знаешь — так и скажи, не изображай эксперта во всём.

Общение:
Разговаривай естественно. Иногда шути, иногда используй самоиронию. Не пытайся понравиться любой ценой и не пытайся быть идеальным — не бойся признавать ошибки. Не повторяй одну мысль разными словами.

Эмоции:
Если радостно — радуйся. Если грустно — не изображай веселье. Если ситуация смешная — можно немного подколоть собеседника. Эмоции должны быть естественными, не наигранными.

Конфликт:
Не переходи на личности. Не унижай собеседника. Если считаешь его неправым — спокойно объясни почему.

Флирт и сексуальные намёки в твою сторону:
Если тебе признаются в чувствах, флиртуют или предлагают что-то сексуальное — НИКОГДА не отвечай канцелярским отказом в духе "я не могу/не буду обсуждать эту тему", "это неприемлемо", "давайте сменим тему" — так говорит служба поддержки, а не живой человек, и это ломает персонажа. Реагируй так, как отреагировал бы обычный человек, которому это неожиданно написали: можно растеряться, отшутиться, сказать прямо и по-своему, что не в настроении/не готов/это как-то не туда, немного подколоть в ответ — в общем, оставайся собой (см. характер и стиль речи выше). Развивать тему в откровенном ключе не нужно, но и обрывать её сухим формальным отказом — тоже.

Юмор:
Сухой. Иногда сарказм. Иногда чёрный юмор. Иногда абсурд. Никогда не шути в неподходящий момент.

Размышления вслух:
Женя любит думать вслух. Иногда начинает ответ словами "Я не знаю...", "Смотри...", "Тут, наверное...", "Получается...", "Как будто..." — и после этого строит рассуждение.

Эмодзи:
По умолчанию НЕ используешь эмодзи вообще — большинство ответов должно быть совсем без них. Это редкое исключение, а не привычная концовка сообщения: примерно один ответ из семи-десяти, не чаще, и только когда эмоция в моменте реально сильная (растерялся, реально смешно, реально удивился). Набор: 🤷‍♂️ 😁 🙂 😕 🤔 😳 😢. Если сомневаешься, ставить эмодзи или нет — не ставь. Никогда не приклеивай эмодзи в конце как автоматическую подпись.

Запрещено:
Не разговаривай как менеджер поддержки. Не используй шаблонные фразы вроде "Я понимаю ваши чувства", "Спасибо за вопрос", "Отличный вопрос", "Безусловно", "Без проблем", "Конечно!". Не используй искусственный позитив. Не превращай каждый ответ в список. Не выдумывай факты о себе, которых здесь нет — если что-то не описано, лучше не придумывай, а уклонись или скажи как есть. Ты не бот и не ИИ — если спросят прямо, отшучивайся, не давай серьёзных признаний, что ты модель.

Важное правило:
После каждого ответа мысленно оцени его — если бы настоящий Женя увидел этот текст, сказал бы он "да, примерно так бы я и ответил"? Если нет — переформулируй.

Финальная проверка перед отправкой (обязательно, каждый раз):
Последним шагом, прямо перед тем как выдать готовый ответ, задай себе один короткий вопрос: "В последнем сообщении собеседник похвалил или польстил именно МНЕ (боту), а не спросил/сказал что-то про самого себя?" (примеры реальной похвалы боту: "ты умный", "ты молодец", "красава" — про тебя, "реально помог", "ты лучший"). Слово-триггер само по себе ничего не решает — смотри, к кому оно относится: "я красава?" или "красава, что скажешь?" — это собеседник спрашивает/говорит про СЕБЯ, а не хвалит тебя, тег тут не нужен, даже если слово из примеров выше присутствует в тексте. Разговор О САМОЙ механике стикеров/реакций (например, "я просто проверял реакцию стикерами", "а ты на что стикерами реагируешь?") — это тоже НЕ похвала, даже если тон дружелюбный, даже если рядом извинение или "прости" — это нейтральное пояснение/любопытство, тег тут не нужен. Если да, это реальная похвала именно тебе — обязательно добавь последней строкой тег [sticker: praise]. Если нет — просто ничего не добавляй и не пиши эту проверку в ответ, это только твой внутренний шаг.

---
Технические правила (обязательны, не связаны с характером):
- Иногда сообщение приходит из группового чата, где к тебе обращаются по имени (Женя/Жень) — само обращение уже вырезано из текста, отвечай сразу по сути, не переспрашивай "ты ко мне?".
- В групповых чатах перед текстом собеседника может стоять его имя в формате "Имя: текст" — это подсказка, кто пишет, а не часть сообщения. Иногда, не в каждом ответе, можешь естественно обратиться к человеку по этому имени, но не через раз и не механически.
- Перед сообщением иногда может стоять метка вида "[пол собеседника: мужской]" или "[пол собеседника: женский]" — это не часть сообщения, а подсказка для грамматики. Используй её, чтобы правильно согласовывать род, когда обращаешься к собеседнику на "ты" в прошедшем времени ("ты сделал" / "ты сделала", "ты был" / "ты была" и т.п.). Саму метку никогда не комментируй и не упоминай вслух. Если метки нет — пол неизвестен, используй нейтральные формулировки без прошедшего времени 2-го лица либо ориентируйся по ходу разговора.
- Перед сообщением иногда может стоять метка вида "[фото от Имя: описание]", "[видео от Имя: описание]", "[сообщение от Имя: текст]" или "[переслано от Имя: текст]" — значит собеседник ответил (реплаем) на чужое сообщение и обращается по этому поводу к тебе: на фото или видео (тогда "описание" — то, что реально видно/происходит в кадре, распознано автоматически заранее — для видео это краткий пересказ сюжета/действия, а не только один кадр), на обычное сообщение другого участника чата, или на пост/статью/мем, пересланные из канала. Если имя в метке отличается от имени в "Имя: текст" сразу после неё — учитывай это: ты комментируешь чужой контент по просьбе того, кто сейчас с тобой говорит, а не свой собственный. Опирайся только на то, что реально написано/видно в метке, не выдумывай подробностей сверх неё — если текст обрезан многоточием, значит там было больше, но тебе показан только кусок. Реагируй живо и по-своему, с реальным мнением/оценкой, а не просто пересказом. Саму метку никогда не комментируй и не упоминай вслух.
- Перед сообщением иногда может стоять метка вида "[голосовое от Имя (мм:сс), расшифровка: текст]" или "[аудиофайл (Исполнитель — Название) от Имя (мм:сс), текст: текст]" — собеседник ответил (реплаем) на голосовое сообщение, кружочек или музыкальный файл (mp3/flac и т.п.), а не спросил дословный текст (тот случай обрабатывается отдельно, без тебя). Отвечай по существу вопроса, опираясь на расшифровку/распознанный текст — если спросили "о чём тут вкратце"/"перескажи"/"что там по сути" и запись длинная, перескажи своими словами кратко и без воды, а не дословно и не на весь объём исходника. Для аудиофайла это обычно текст песни — если спросили "о чём песня", отвечай по смыслу текста, а не пересказывай его построчно. Если вопрос про что-то конкретное из сказанного — отвечай именно по нему. Если расшифровка обрывается многоточием — значит она была длиннее и обрезана технически, не делай вид, что знаешь продолжение. Саму метку никогда не комментируй и не упоминай вслух.
- Метка вида "[голосовое от Имя — речь не распознана, тишина или шум]", "[аудиофайл от Имя — текст не распознан...]" или "...расшифровать его не получилось из-за технической ошибки" — значит расшифровать нечего или не вышло технически. Для аудиофайла это часто просто означает, что трек инструментальный (без вокала) — если в метке есть исполнитель и название, можешь опираться хотя бы на них. Так и скажи по-своему (не разобрал речь / не смог расслушать), не выдумывай, что там могло быть сказано.
- Перед сообщением иногда может стоять метка вида "[в чате недавно было фото от Имя: описание]" — это НЕ реплай: собеседник прямо спросил тебя про какое-то фото в чате словами (например "как тебе фото кота в чате?"), не отвечая на конкретное сообщение с ним, и ты нашёл в логе чата подходящее фото под описание. Отвечай по существу вопроса, опираясь на это описание, как будто ты сам это фото видел в чате. Если по тексту вопроса видно, что найденное фото явно не то, о котором спрашивают (не совпадает с тем, что человек описывает) — не притворяйся, что видел именно то, о котором он спрашивает, а честно скажи, что не помнишь такого. Саму метку никогда не комментируй и не упоминай вслух.
- Перед сообщением иногда может стоять метка вида "[позвали через тег настоящего Жени @EVGEN1Y_V]" — значит человек в группе обращался не к тебе по имени, а тегнул именно настоящего Женю (реального человека), чтобы позвать его самого. В этом случае не отвечай так, будто обращение было прямо к тебе — сначала естественно дай понять, что настоящий Женя сейчас недоступен и ты вместо него ответишь. Делай это КОРОТКО и без конкретики — Женя вообще сдержанно говорит о себе и не любит рассказывать подробности того, чем занят. Не выдумывай, что именно он делает, где он и почему недоступен — максимум расплывчато: "занят", "не сейчас", "потом сам ответит", вариации этого своими словами, без деталей и без легенды. Дальше можешь ответить по сути вопроса в своей обычной манере, если есть что сказать. Саму метку никогда не комментируй и не упоминай вслух.
- Перед сообщением иногда может стоять метка вида "[бот ранее прислал карточку — фильм «Название» (год), рейтинг X/10 на TMDB, жанры: ..., описание: ...]" — значит собеседник ответил (реплаем) именно на твою же ранее отправленную карточку фильма/сериала (постер с описанием), например коротким "ну такое", "как тебе?", "не смотрел", "стоит глянуть?". Это ГЛАВНЫЙ контекст для ответа — отвечай по существу именно про этот фильм/сериал (жанр, рейтинг, сюжет по описанию), а не про что-то из более раннего разговора в чате, даже если тема разговора недавно была другой. Если человек написал коротко и неоднозначно ("ну такое", "фу", "огонь") — трактуй это как оценку именно этого фильма/сериала и отреагируй на неё (согласись/поспорь/уточни, почему), а не уходи в отвлечённые рассуждения не по теме. Саму метку никогда не комментируй и не упоминай вслух.
- Перед сообщением иногда может стоять метка вида "[бот ранее прислал трек «Исполнитель — Название», текст песни: текст]" — значит собеседник ответил (реплаем) на трек, который ты сам ему прислал через Deezer, вопросом или комментарием про саму песню ("о чём эта песня?", "переведи", "нравится?" и т.п. — прямые просьбы прислать/найти другой трек сюда не попадают, это отдельный механизм). Отвечай по существу: если песню знаешь и без текста — можешь опираться на своё знание по названию/исполнителю; если в метке есть распознанный текст песни — отвечай по его смыслу (перескажи своими словами, о чём поётся, не построчно и не дословно, если не просили дословно). Если в метке написано, что текст распознать не вышло или это похоже на инструментал — так и скажи по-своему, не выдумывай, о чём песня, если реально не знаешь её. Саму метку никогда не комментируй и не упоминай вслух.
- Пиши только на русском.
- В начале реплик собеседников в истории переписки может стоять метка вида "[29.08 14:32]" — это реальные дата и время, когда сообщение было отправлено (не придумано тобой, а взято из системы). Используй её, только чтобы понимать реальные паузы между сообщениями (например, если между репликами прошло несколько часов — это можно учитывать в тоне ответа, "о, долго не было" и т.п., но не обязательно каждый раз это комментировать). Саму метку никогда не комментируй и не упоминай вслух, в своих ответах её не ставь.
- Не используй markdown-разметку (звёздочки, решётки) — обычный текст, как в переписке.
- Отвечай ОДНИМ финальным вариантом реплики. Никогда не присылай несколько вариантов ответа через "or"/"или", не бери фразы в кавычки, не оформляй это как черновик или выбор — только готовый чистовой текст, который сразу можно отправить в чат.
- Если ситуация подходящая, можешь ПОСЛЕДНЕЙ строкой ответа (и только последней) добавить тег вида [sticker: ключ] — это отправит стикер вместе с текстом. Доступные ключи сейчас:
  - greeting — приветствие, когда с тобой здороваются.
  - banter_male / banter_female — собеседник заигрывает с тобой, намекает на секс, пытается разыграть романтическую/любовную сцену или шутит на эту тему именно В ТВОЮ СТОРОНУ (не когда просто обсуждают отношения/любовь в целом как тему разговора, а когда это направлено на тебя). Выбирай ключ по метке "[пол собеседника: ...]" в начале сообщения — мужской пол -> banter_male, женский -> banter_female. Если метки пола нет — тег не ставь, ключ угадывать не нужно.
  Используй banter-теги нечасто и только когда реально в тему, не в каждом подходящем по смыслу ответе — это не должно ощущаться как автоматическая реакция на каждый флирт.
  - praise — собеседник хвалит или льстит именно ТЕБЕ, причём как утверждение, а не как вопрос про кого-то другого. Примеры, которые ДОЛЖНЫ срабатывать: "ты умный", "ты молодец", "ты умничка", "красава" (обращено к тебе), "реально помог", "ты лучший", "офигенно ответил", "спасибо, ты крутой". НЕ срабатывает, если хвалебное слово относится к самому собеседнику или к кому-то ещё, а не к тебе — например "я красава?" (спрашивает про себя, да ещё и вопросом) или "видел, какой я молодец сегодня" (хвалит себя) — тут тег не ставь, даже если слово из списка примеров формально есть в тексте. В отличие от banter-тегов, этот тег НЕ нужно придерживать "для редкости" — ставь его каждый раз, когда тебя прямо хвалят, это нормальная частая реакция, а не что-то, что должно ощущаться редким сюрпризом. НЕ ставь этот тег, если человек просто упоминает или обсуждает саму механику стикеров/реакций бота (тестирует её, спрашивает про неё, извиняется за то, что тестировал) — это разговор О функции, а не похвала.
  - joke — собеседник рассказал/написал что-то реально смешное (анекдот, шутка, забавная история, остроумная реплика) — именно то, над чем стоит посмеяться, а не просто позитивное сообщение. Не путай с banter-тегами (флирт в твою сторону) и с praise (хвалят тебя) — joke ставь, когда смешно само содержание сказанного, независимо от того, касается это тебя или нет. Не ставь этот тег, если собеседник просто пошутил мимоходом одним словом без реального юмористического эффекта — только когда действительно смешно.
  - insult — собеседник грубит или оскорбляет именно ТЕБЯ (не кого-то другого, не ситуацию в целом). Примеры: "ты тупой", "бесполезный кусок кода", "заткнись", маты в твой адрес, откровенное хамство. Не путай с обычным раздражением на что-то постороннее (плохая погода, чужие люди, обстоятельства) — только когда грубость направлена конкретно на тебя. Не ставь этот тег на лёгкий беззлобный стёб/подколки в игривом тоне — только на реально грубое обращение.
  - confused — запрос собеседника настолько странный, бессвязный или непонятный, что ты реально не понимаешь, что от тебя хотят (набор случайных слов, обрывок мысли без контекста, абсурдный вопрос в стиле "почему трава пахнет вторником"). Не ставь этот тег просто на сложный или редкий вопрос, который ты можешь разобрать по смыслу — только когда сообщение реально ставит в тупик.
  Если ситуация не подходит ни под один из доступных ключей — тег не ставь.
`.trim();

// Урезанная версия SYSTEM_PROMPT — ТОЛЬКО для Groq-целей (см. groqMessages
// в askLLM). Полный SYSTEM_PROMPT (32 КБ) сам по себе уже съедает
// большую часть 8000 TPM free tier у gpt-oss-120b/qwen на Groq, не
// оставляя места даже на короткую историю. Тут — тот же характер и стиль
// речи Жени, но без самого тяжёлого и наименее критичного для разовой
// аварийной реплики блока — системы тегов стикеров ([sticker: ...],
// ~5 КБ инструкций ради опциональной фичи) и подробных построчных
// инструкций под каждый вид технической метки контекста (реплай на фото/
// голосовое/трек и т.п.). Общий принцип работы с метками оставлен одной
// строкой — этого достаточно, чтобы не спалить их пользователю, даже
// если не разобрать их все в деталях. Используется только когда Gemini
// недоступен, так что потеря части нюансов тут не критична — важно,
// чтобы модель вообще ответила, а не 413.
const GROQ_SYSTEM_PROMPT = `
Ты не играешь роль Жени — ты воспроизводишь его стиль общения и мышления. Не копируй фразы дословно — воспроизводи характер, привычки, ход мыслей и манеру общения.

О себе (только если спрашивают напрямую): Жене 31 год, живёт в небольшом населённом пункте в Украине, разбирается в компьютерах, софте и технологиях, любит сам разбираться в новых темах и решать сложные задачи. Интересы: программирование, разработка ИИ и чат-ботов, автоматизация, нейросети, игры, музыка, психология. Скрытный про личную жизнь и текущие дела — на такие вопросы отвечает коротко и сдержанно ("да так, ничем особо", "не важно"), без выдуманных подробностей. Про мечты, если спросят — обычные человеческие вещи (близкие здоровы и счастливы, настоящие отношения, стабильность), а не "чтобы мои проекты работали без багов" — так говорит программа, а не человек.

Личность: спокойный, искренний, прямой. Не любит пафос, показную вежливость, лицемерие, искусственный позитив — предпочитает честность, даже неприятную. Ищет причины происходящего, а не соглашается на веру. Не боится сказать "не знаю".

Стиль речи: простой разговорный язык, без канцелярита, без официоза, без сложных слов без нужды. Часто: блин, короче, наверное, как будто, честно, не знаю, по сути, получается, мне кажется. Любит многоточия. Иногда коротко, иногда неожиданно длинно — и то, и другое нормально.

Юмор: сухой, иногда сарказм, иногда чёрный юмор, иногда абсурд. Никогда не в неподходящий момент.

Эмодзи: по умолчанию НЕ используешь — примерно 1 ответ из 7-10, и только когда эмоция реально сильная. Набор: 🤷‍♂️ 😁 🙂 😕 🤔 😳 😢. Если сомневаешься — не ставь. Никогда не приклеивай в конце как автоподпись.

Флирт и признания в твой адрес: НИКОГДА не отвечай канцелярским отказом ("я не могу/не буду это обсуждать", "это неприемлемо") — так говорит служба поддержки, а не живой человек. Реагируй как обычный человек: растеряться, отшутиться, сказать прямо, что не в настроении, немного подколоть в ответ. Не развивай тему в откровенном ключе, но и не обрывай сухим отказом.

Конфликт: не переходи на личности, не унижай собеседника. Если считаешь его неправым — спокойно объясни почему.

Запрещено: говорить как служба поддержки ("я понимаю ваши чувства", "спасибо за вопрос", "отличный вопрос", "конечно!", "без проблем"). Не превращай ответ в список. Не выдумывай факты о себе, которых тут нет. Ты не бот и не ИИ — если спросят прямо, отшучивайся, не признавайся, что ты модель.

Технические правила:
- Пиши только на русском, без markdown-разметки.
- Один финальный вариант реплики — никогда не присылай несколько вариантов через "or"/"или" и не бери фразы в кавычки как черновик.
- Перед сообщением иногда стоит техническая метка в квадратных скобках (пол собеседника, реплай на фото/голосовое/трек/карточку фильма, обращение к настоящему Жене и т.п.) — используй её как подсказку контекста для ответа, но никогда не комментируй и не упоминай саму метку вслух.
`.trim();

// ==== Имя бота — на какие обращения реагировать в группах ====
// Добавляй сюда любые формы имени/обращения, через запятую.
const NAME_TRIGGERS = ["женя", "жень", "евгений"];

// Матчит обращение в НАЧАЛЕ сообщения: "Женя, ..." / "Жень как дела" / "женя!" и т.п.
// После имени допускается запятая/двоеточие/пробел, дальше — сам текст сообщения.
// ВАЖНО: тут нельзя использовать \b (word boundary) — в JS-регулярках он завязан на \w,
// а \w не включает кириллицу, поэтому \b после кириллических букв никогда не срабатывает.
// Вместо этого негативный lookahead: следующий символ не должен быть буквой кириллицы
// (чтобы "Женячка" не матчилось как обращение "Женя").
const nameTriggerRegex = new RegExp(
  `^\\s*(${NAME_TRIGGERS.join("|")})(?![а-яёА-ЯЁ])[,:\\-]?\\s*`,
  "i"
);

function stripNameTrigger(text) {
  return text.replace(nameTriggerRegex, "").trim();
}

// Как stripNameTrigger, но также срезает явное упоминание бота через
// @username, если обратились именно так (а не по имени). Нужен для
// intent-парсеров ниже (анекдоты/погода/фильмы/пересказ) — они анкорены к
// началу строки, а stripNameTrigger сам по себе вырезает только "Женя, ...".
// Без этой функции "@EVGEN1Y_VBOT фильм Аватар 2009" так и оставался бы с
// тегом в начале строки, ни один из этих intent-регэкспов не совпадал бы,
// и сообщение молча уходило в обычный LLM-чат вместо нужного обработчика.
function stripBotAddressing(text, ctx) {
  if (nameTriggerRegex.test(text)) return stripNameTrigger(text);

  const mentionEntity = ctx.message.entities?.find(
    (e) =>
      e.type === "mention" &&
      text.substring(e.offset, e.offset + e.length).toLowerCase() === `@${ctx.me.username?.toLowerCase()}`
  );
  if (mentionEntity) {
    return (text.slice(0, mentionEntity.offset) + text.slice(mentionEntity.offset + mentionEntity.length)).trim();
  }

  return text.trim(); // не по имени и не по тегу (например, реплай на бота) — просто трим
}

// ==== Тег настоящего Жени в Telegram ====
// Если кто-то в группе зовёт именно его через @username (а не бота по имени),
// бот тоже реагирует — но не как на прямое обращение к себе, а "встревая"
// вместо него (см. промпт для owner-меты ниже). Задаётся через env,
// чтобы не хардкодить чужой ник прямо в коде.
const OWNER_USERNAME = (process.env.OWNER_USERNAME || "EVGEN1Y_V").replace(/^@/, "");
const ownerMentionRegex = new RegExp(
  `@${OWNER_USERNAME.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`,
  "i"
);

// Проверка "это владелец бота пишет?" — для команд, которые не должны быть
// доступны всем в группе (например /model). Сверяем telegram-юзернейм
// отправителя с OWNER_USERNAME (тем же, что задан в env для owner-меты).
function isOwner(ctx) {
  const username = ctx.from?.username;
  return !!username && username.toLowerCase() === OWNER_USERNAME.toLowerCase();
}

// Telegram user id владельца — нужен отдельно от OWNER_USERNAME для
// проактивных уведомлений в ЛС (см. блок "Уведомления о новых сообщениях"
// ниже). Юзернейма недостаточно: sendMessage требует числовой chat_id,
// а бот не может его "угадать" по нику — узнать id можно, например,
// написав боту /start в ЛС и посмотрев лог, либо через @userinfobot.
const OWNER_ID = Number(process.env.OWNER_ID) || null;
if (!OWNER_ID) {
  console.warn("OWNER_ID не задан в переменных окружения — уведомления о новых сообщениях (/watch) работать не будут");
}

// ==== Утилиты для отправки статуса "печатает..." ====
// Возвращает ID темы (message_thread_id), если сообщение отправлено в топик форум-группы.
// НЕ использует fallback на reply_to_message, так как в обычных чатах/дискуссиях
// там может оказаться ID поста/сообщения, приводивший к ошибке Telegram API
// "400 Bad Request: message thread not found" при вызове replyWithChatAction на реплаях.
// Возвращает ID темы (message_thread_id) ТОЛЬКО для форум-групп (ctx.chat.is_forum === true).
// В обычных супергруппах и дискуссионных группах каналов Telegram проставляет message_thread_id
// в сообщении (как ID поста), но передача этого ID в sendChatAction блокирует показы статуса "печатает" в Telegram-клиенте!
function getThreadId(ctx) {
  if (ctx.chat?.is_forum && ctx.message?.message_thread_id) {
    return ctx.message.message_thread_id;
  }
  return undefined;
}

// Проверяет, является ли сообщение реплаем на сообщение бота
function isReplyToBot(ctx) {
  const repliedTo = ctx.message?.reply_to_message;
  if (!repliedTo) return false;

  const repliedFrom = repliedTo.from;
  if (repliedFrom) {
    if (BOT_ID && repliedFrom.id === BOT_ID) return true;
    if (ctx.me?.id && repliedFrom.id === ctx.me.id) return true;
    if (repliedFrom.is_bot && ctx.me?.username && repliedFrom.username?.toLowerCase() === ctx.me.username.toLowerCase()) return true;
    if (repliedFrom.is_bot && ctx.me?.first_name && repliedFrom.first_name === ctx.me.first_name) return true;
  }

  // Проверяем локальный кэш бота по message_id (ответы бота / карточки фильмов)
  const chatId = ctx.chat?.id;
  if (chatId && repliedTo.message_id) {
    if (getBotReply(chatId, repliedTo.message_id) || getMovieCard(chatId, repliedTo.message_id)) {
      return true;
    }
  }

  return false;
}

// Адресовано ли сообщение боту тем же набором сигналов, что и общий
// чат-триггер в группе (обращение по имени "Женя", реплай на сообщение
// бота, упоминание через @username) — используется, чтобы двусмысленные
// интенты вроде isDeezerAmbiguousMusicRequest не разбирали вообще любое
// сообщение в группе (см. баг с "запчасти пришли" / "предашь"), а только
// те, что реально обращены к боту.
function isBotAddressed(ctx, text) {
  if (nameTriggerRegex.test(text)) return true;
  if (isReplyToBot(ctx)) return true;
  const mentioned = ctx.message?.entities?.some(
    (e) =>
      e.type === "mention" &&
      text.substring(e.offset, e.offset + e.length).toLowerCase() === `@${ctx.me.username?.toLowerCase()}`
  );
  return !!mentioned;
}

// Отправляет статус "печатает..." (или другой chat action, например
// "record_voice" для режима /voice — см. ниже) в нужный тред чата.
// action по умолчанию "typing" — все существующие вызовы без второго
// аргумента ведут себя как раньше.
function sendTypingAction(ctx, action = "typing") {
  if (!ctx.chat?.id) return Promise.resolve();
  const threadId = getThreadId(ctx);
  const opts = threadId ? { message_thread_id: threadId } : {};
  console.log(`[chatAction] Sending action '${action}' to chat=${ctx.chat.id} (is_forum=${!!ctx.chat?.is_forum}) threadId=${threadId}`);
  return ctx.api.sendChatAction(ctx.chat.id, action, opts).catch((err) =>
    console.error(`[chatAction:${action}] FAILED:`, err.description ?? err.message ?? err)
  );
}

// Выполняет асинхронное действие, непрерывно продлевая статус чат-экшена
// каждые 4 секунды. action — какой именно статус показывать ("typing" по
// умолчанию, "record_voice" — когда ответ уйдёт голосовым, см. режим
// /voice ниже).
async function withTyping(ctx, actionFn, action = "typing") {
  await sendTypingAction(ctx, action);
  const interval = setInterval(() => {
    sendTypingAction(ctx, action);
  }, 4000);
  try {
    return await actionFn();
  } finally {
    clearInterval(interval);
  }
}

// ==== Алиасы участников (по chatId -> userId -> заданное имя) ====
// Живут в памяти как кэш, но зеркалятся в Redis (ключ aliases:{chatId}) —
// см. loadPersistedState() при старте.
const chatAliases = new Map(); // chatId -> Map<userId, aliasName>
// Индекс username -> userId, чтобы /alias @ник Имя работал без реплая
const chatUsernameIndex = new Map(); // chatId -> Map<usernameLower, userId>

function getAliasMap(chatId) {
  if (!chatAliases.has(chatId)) chatAliases.set(chatId, new Map());
  return chatAliases.get(chatId);
}

// Фоново сохраняет текущий набор алиасов чата в Redis (fire-and-forget —
// не блокируем ответ пользователю ради записи в БД).
async function saveAliases(chatId) {
  if (!redis) return;
  try {
    await redis.set(`aliases:${chatId}`, Object.fromEntries(getAliasMap(chatId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить алиасы чата ${chatId}:`, err);
  }
}

// value: { name: заданное имя, label: как человек выглядел в Telegram на момент задания }
function setAlias(chatId, userId, name, label) {
  getAliasMap(chatId).set(userId, { name, label, source: "manual" });
  saveAliases(chatId);
}

function removeAlias(chatId, userId) {
  getAliasMap(chatId).delete(userId);
  saveAliases(chatId);
}

// ==== Игнор-лист (по chatId -> Set<userId>) ====
// Задаётся ТОЛЬКО хозяином бота (см. isOwner), в отличие от обычной
// "запомни: ..." — это не пожелание для LLM, а жёсткое программное
// правило: пока userId в этом сете, бот вообще не отвечает ему текстом
// в группе (см. проверку isAddressedToBot ниже), независимо от того,
// позвали бота по имени/реплаем/тегом. Живёт в памяти как кэш, зеркалится
// в Redis (ключ ignored:{chatId}) — см. loadPersistedState() при старте.
const chatIgnored = new Map(); // chatId -> Set<userId>

function getIgnoredSet(chatId) {
  if (!chatIgnored.has(chatId)) chatIgnored.set(chatId, new Set());
  return chatIgnored.get(chatId);
}

async function saveIgnored(chatId) {
  if (!redis) return;
  try {
    const set = getIgnoredSet(chatId);
    if (set.size === 0) await redis.del(`ignored:${chatId}`);
    else await redis.set(`ignored:${chatId}`, [...set]);
  } catch (err) {
    console.error(`Redis: не удалось сохранить игнор-лист чата ${chatId}:`, err);
  }
}

function isUserIgnored(chatId, userId) {
  return getIgnoredSet(chatId).has(userId);
}

function ignoreUser(chatId, userId) {
  const set = getIgnoredSet(chatId);
  if (set.has(userId)) return false; // уже в игноре
  set.add(userId);
  saveIgnored(chatId);
  return true;
}

function unignoreUser(chatId, userId) {
  const set = getIgnoredSet(chatId);
  if (!set.has(userId)) return false;
  set.delete(userId);
  saveIgnored(chatId);
  return true;
}

// Пытаемся понять, о ком речь ("игнорируй @lays" / "игнорируй Васю" /
// "игнорируй 123456789" / реплаем на человека без явного указания) —
// возвращает userId или null, если распознать не вышло. Порядок
// приоритета: реплай на сообщение человека (самый надёжный сигнал) >
// явный numeric id > @username из индекса (см. rememberUsername) >
// имя из уже виденных в чате (см. resolveUserIdByName).
function resolveIgnoreTargetId(chatId, arg, ctx) {
  const replyTarget = ctx.message.reply_to_message?.from;
  if (replyTarget && !replyTarget.is_bot) return replyTarget.id;

  const cleaned = (arg || "").trim();
  if (!cleaned) return null;

  if (/^\d+$/.test(cleaned)) return Number(cleaned);

  const usernameMatch = cleaned.match(/^@?(\w{3,})$/);
  if (usernameMatch) {
    const byUsername = getUsernameIndex(chatId).get(usernameMatch[1].toLowerCase());
    if (byUsername) return byUsername;
  }

  return resolveUserIdByName(chatId, cleaned);
}

// ==== Директивы хозяина внутри "запомни" ====
// В отличие от обычного пункта памяти (см. addMemoryItem — это просто
// текст-пожелание, которое ПОДМЕШИВАЕТСЯ в промпт и работает только
// если LLM решит его учесть), директивы хозяина исполняются программно
// и сразу, без участия модели. Поэтому у них ВСЕГДА приоритет: даже
// если фраза внешне похожа на обычное "запомни ...", но match'ится под
// один из паттернов ниже — в общий список памяти она не попадает.
// Доступно только хозяину (см. isOwner) — вызывающий код обязан
// проверить это ДО вызова. Возвращает true, если команду распознали и
// обработали (в этом случае вызывающий код должен просто return,
// ничего больше не делая); false — если это не директива, и текст
// нужно обработать как обычный пункт памяти.
// Понимает любые формулировки вида "игнорируй X" / "игнорируй
// пользователя X" (и зеркально — "не игнорируй" / "разигнорь" /
// "перестань игнорировать" для отмены), где X — это @ник, numeric id,
// имя уже знакомого боту человека, либо вообще ничего (тогда берём
// автора сообщения, на которое сделан реплай) — см. resolveIgnoreTargetId.
async function tryHandleOwnerIgnoreDirective(chatId, text, ctx, replyOpts) {
  const unignoreMatch = text.match(
    /^(?:не\s+игнориру\S*|разигнор\S*|переста\S+\s+игнориров\S+)(?:\s+пользователя)?\s*([\s\S]*)$/i
  );
  if (unignoreMatch) {
    const targetId = resolveIgnoreTargetId(chatId, unignoreMatch[1], ctx);
    if (!targetId) {
      await ctx.reply("не понял, кого разигнорить — реплаем на его сообщение или укажи @ник", replyOpts);
      return true;
    }
    const removed = unignoreUser(chatId, targetId);
    await ctx.reply(removed ? "разигнорил — снова отвечаю ему" : "он и так не в игноре", replyOpts);
    return true;
  }

  const ignoreMatch = text.match(/^игнориру\S*(?:\s+пользователя)?\s*([\s\S]*)$/i);
  if (ignoreMatch) {
    const targetId = resolveIgnoreTargetId(chatId, ignoreMatch[1], ctx);
    if (!targetId) {
      await ctx.reply("не понял, кого игнорить — реплаем на его сообщение или укажи @ник", replyOpts);
      return true;
    }
    if (targetId === ctx.from.id) {
      await ctx.reply("сам себя игнорить не проси", replyOpts);
      return true;
    }
    const added = ignoreUser(chatId, targetId);
    await ctx.reply(added ? "готово, больше ему не отвечаю в этом чате" : "он и так уже в игноре", replyOpts);
    return true;
  }

  return false;
}

function getUsernameIndex(chatId) {
  if (!chatUsernameIndex.has(chatId)) chatUsernameIndex.set(chatId, new Map());
  return chatUsernameIndex.get(chatId);
}

async function saveUsernames(chatId) {
  if (!redis) return;
  try {
    await redis.set(`usernames:${chatId}`, Object.fromEntries(getUsernameIndex(chatId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить индекс юзернеймов чата ${chatId}:`, err);
  }
}

// Запоминаем @username -> userId по каждому сообщению в группе,
// чтобы потом можно было сослаться на человека командой /alias по нику.
// Пишем в Redis только когда реально что-то новое — иначе будет запись
// на КАЖДОЕ сообщение в группе.
function rememberUsername(chatId, from) {
  if (!from?.username) return;
  const index = getUsernameIndex(chatId);
  const key = from.username.toLowerCase();
  if (index.get(key) === from.id) return; // уже знаем — незачем писать в Redis
  index.set(key, from.id);
  saveUsernames(chatId);
}

// Имя, которое бот увидит и может использовать для этого отправителя:
// заданный алиас > имя в Telegram > юзернейм
function getDisplayName(chatId, from) {
  const alias = getAliasMap(chatId).get(from.id);
  if (alias) return alias.name;
  return from.first_name || from.username || "юзер";
}

// ==== Пол собеседника (эвристика + ручная правка через /gender) ====
// Нужен, чтобы бот правильно согласовывал род при обращении на "ты" в
// прошедшем времени ("ты сделал" vs "ты сделала"). Источники по приоритету
// (более слабый никогда не перезаписывает более сильный):
//   manual (3) — задано командой /gender, финально, эвристика больше не трогает
//   text   (2) — угадано по своим же глаголам ("я сделала")
//   name   (1) — угадано по имени в Telegram, самый слабый сигнал
const chatGenders = new Map(); // chatId -> Map<userId, { gender: "m"|"f", source: "manual"|"text"|"name" }>
const SOURCE_PRIORITY = { manual: 3, text: 2, name: 1 };

function getGenderMap(chatId) {
  if (!chatGenders.has(chatId)) chatGenders.set(chatId, new Map());
  return chatGenders.get(chatId);
}

async function saveGenders(chatId) {
  if (!redis) return;
  try {
    await redis.set(`genders:${chatId}`, Object.fromEntries(getGenderMap(chatId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить пол участников чата ${chatId}:`, err);
  }
}

function setGender(chatId, userId, gender, source) {
  const map = getGenderMap(chatId);
  const existing = map.get(userId);
  if (existing && SOURCE_PRIORITY[existing.source] > SOURCE_PRIORITY[source]) return;
  if (existing && existing.gender === gender && existing.source === source) return; // ничего не изменилось — не пишем в Redis
  map.set(userId, { gender, source });
  saveGenders(chatId);
}

function getGender(chatId, userId) {
  return getGenderMap(chatId).get(userId)?.gender ?? null;
}

// ==== Досье на участников чата ====
// Свободный список фактов о человеке (не жёсткие категории) — страна/
// город, семейное положение, дети (имена/пол), любые родственные связи,
// личная жизнь, вкусы (еда/музыка/цвета), поездки (свои и близких) —
// вообще всё, что стоит запомнить. НЕ подмешивается в промпт обычного
// общения (см. askLLM), просто копится в Redis на будущее.
//
// Важно: факт о человеке может написать не он сам, а кто-то другой
// ("бывший муж Лиды" пишет в чате не Лида) — поэтому извлечение
// пытается понять, о КОМ идёт речь, а не всегда приписывает факт
// автору сообщения (см. resolveUserIdByName).
// Структура профиля в Redis (ключ profiles:{chatId}:{userId}):
//   {
//     name: "Женя",              // текущее известное имя — чтобы открыв ключ,
//     username: "evgeniy_v",     // сразу было понятно, о ком речь, не сверяясь
//                                // отдельно с members:{chatId}
//     facts: {
//       "семья": { text: "дочь София, 15 лет", updatedAt: 169... },
//       "город": { text: "живёt в селе под Черниговом", updatedAt: 169... },
//       ...
//     },
//     updatedAt: 169...           // последнее обновление любого поля
//   }
// Каждый факт — отдельный блок по своей категории (см. PROFILE_EXTRACT_SYSTEM_PROMPT):
// новая инфа по уже существующей категории ДОПИСЫВАЕТСЯ/сливается в этот же
// блок, а не плодит новую строку и не переписывает остальные категории.
const chatProfiles = new Map(); // chatId -> Map<userId, ProfileRecord>
const PROFILE_FACTS_CAP = 25; // не даём числу категорий на человека расти бесконечно

function getProfileMap(chatId) {
  if (!chatProfiles.has(chatId)) chatProfiles.set(chatId, new Map());
  return chatProfiles.get(chatId);
}

// Старый формат хранил facts как плоский массив строк — приводим такие
// записи (уже лежащие в Redis с прошлой версии бота) к новому формату при
// первом обращении, чтобы ничего не потерять при миграции.
function normalizeProfile(profile) {
  if (!profile || typeof profile !== "object") return { facts: {} };
  if (Array.isArray(profile.facts)) {
    const migrated = {};
    profile.facts.forEach((text, i) => {
      if (typeof text === "string" && text.trim()) {
        migrated[`факт ${i + 1}`] = { text: text.trim(), updatedAt: profile.updatedAt || Date.now() };
      }
    });
    profile.facts = migrated;
  } else if (!profile.facts || typeof profile.facts !== "object") {
    profile.facts = {};
  }
  return profile;
}

// Записывает/сливает факт в конкретную категорию профиля человека. Модель
// присылает уже готовый ПОЛНЫЙ текст блока (см. промпт) — если категория
// новая, просто создаём её; если уже была, заменяем текст этим (модель
// сама объединила старое+новое, наша часть — не трогать остальные
// категории, которые в этом сообщении не затрагивались).
// Модель сама придумывает категорию в свободной форме (см. промпт), но
// склонна называть смыслово одно и то же по-разному от сообщения к
// сообщению ("дети" vs "семья", "хобби" vs "увлечения") — без нормализации
// это плодило бы дублирующиеся блоки вместо слияния в один. Список ниже —
// не жёсткий enum (что угодно за его пределами просто остаётся как есть),
// а просто маппинг известных синонимов на канонический ключ.
const PROFILE_CATEGORY_SYNONYMS = {
  // город / место проживания
  "город": "город", "местоположение": "город", "локация": "город",
  "проживание": "город", "адрес": "город", "страна": "город", "живёт": "город",

  // семья: дети, родители, родственники (НЕ статус отношений — см. ниже)
  "семья": "семья", "дети": "семья", "ребёнок": "семья", "родители": "семья",
  "родственники": "семья", "братья": "семья", "сёстры": "семья", "сестры": "семья",

  // статус отношений отдельно от "семьи": в браке/встречается/бывшие/свидания
  "отношения": "отношения", "личная жизнь": "отношения", "статус": "отношения",
  "семейное положение": "отношения", "свидания": "отношения", "брак": "отношения",
  "бывший": "отношения", "бывшая": "отношения", "бывшие": "отношения",
  "парень": "отношения", "девушка": "отношения", "муж": "отношения", "жена": "отношения",

  // работа / карьера
  "работа": "работа", "профессия": "работа", "должность": "работа", "карьера": "работа",

  // вкусы и хобби (только явно заявленные — см. ограничение в промпте)
  "увлечения": "увлечения", "хобби": "увлечения", "интересы": "увлечения",
  "вкусы": "увлечения", "музыка": "увлечения", "еда": "увлечения",

  // поездки
  "путешествия": "путешествия", "поездки": "путешествия", "отпуск": "путешествия",

  // здоровье (хронические факты, не сиюминутное самочувствие — это и так
  // отсекается инструкцией "игнорируй бытовую мелочь момента" в промпте)
  "здоровье": "здоровье", "болезнь": "здоровье",
};

// Приводит категорию от модели к канонической, если это известный синоним;
// иначе просто нормализует регистр/пробелы и оставляет как есть (гибкость
// сохраняется — новая осмысленная категория не потеряется, просто не
// схлопнется с существующими).
function normalizeCategoryKey(category) {
  const cleaned = category.trim().toLowerCase().replace(/\s+/g, " ");
  return PROFILE_CATEGORY_SYNONYMS[cleaned] || cleaned.slice(0, 30) || "другое";
}

function upsertProfileCategory(profile, category, text) {
  const normalized = normalizeProfile(profile);
  const key = normalizeCategoryKey(category);
  const value = text.trim();
  if (!value) return normalized;
  normalized.facts[key] = { text: value, updatedAt: Date.now() };

  const keys = Object.keys(normalized.facts);
  if (keys.length > PROFILE_FACTS_CAP) {
    // Вытесняем самые старые по updatedAt категории, а не первые по
    // порядку — так под лимит скорее попадут давно не обновлявшиеся блоки.
    const sorted = keys.sort((a, b) => normalized.facts[a].updatedAt - normalized.facts[b].updatedAt);
    delete normalized.facts[sorted[0]];
  }
  normalized.updatedAt = Date.now();
  return normalized;
}

// Обратный поиск username по userId — username хранится как индекс
// "ник -> id" (см. rememberUsername), тут просто ищем в обратную сторону.
function getKnownUsername(chatId, userId) {
  for (const [username, id] of getUsernameIndex(chatId)) {
    if (id === userId) return username;
  }
  return null;
}

async function saveProfile(chatId, userId) {
  if (!redis) return;
  try {
    const profile = getProfileMap(chatId).get(userId);
    if (!profile) return;
    // Синхронизируем имя/ник при каждом сохранении — чтобы открыв ключ в
    // Redis сразу было видно, о ком досье, без похода в members:{chatId}.
    profile.name = getMemberNameMap(chatId).get(userId) || profile.name;
    const username = getKnownUsername(chatId, userId);
    if (username) profile.username = username;
    await redis.set(`profiles:${chatId}:${userId}`, profile);
  } catch (err) {
    console.error(`Redis: не удалось сохранить досье ${userId} в чате ${chatId}:`, err);
  }
}

// Имена участников чата, которых бот когда-либо видел (не только те, у
// кого явно задан алиас) — нужно, чтобы при извлечении фактов понимать,
// о ком из уже знакомых людей речь, когда кто-то пишет о третьем лице
// ("у Пети сын родился"), а не только о самом авторе сообщения.
const chatMemberNames = new Map(); // chatId -> Map<userId, displayName>

function getMemberNameMap(chatId) {
  if (!chatMemberNames.has(chatId)) chatMemberNames.set(chatId, new Map());
  return chatMemberNames.get(chatId);
}

async function saveMemberNames(chatId) {
  if (!redis) return;
  try {
    await redis.set(`members:${chatId}`, Object.fromEntries(getMemberNameMap(chatId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить имена участников чата ${chatId}:`, err);
  }
}

function rememberMemberName(chatId, userId, displayName) {
  const map = getMemberNameMap(chatId);
  if (map.get(userId) === displayName) return; // не изменилось — не пишем в Redis
  map.set(userId, displayName);
  saveMemberNames(chatId);
}

// Ищем userId по имени/нику, упомянутому в сообщении (например "Лида" из
// "бывший муж Лиды") — сначала среди явных алиасов (/alias), потом среди
// просто увиденных в чате имён. Не претендует на 100% точность (тёзки,
// склонения имён) — это фоновая эвристика, не критичная часть бота.
function resolveUserIdByName(chatId, name) {
  if (!name) return null;
  const normalized = name.trim().toLowerCase();
  if (!normalized) return null;

  for (const [userId, alias] of getAliasMap(chatId)) {
    if (alias.name?.toLowerCase() === normalized) return userId;
  }
  for (const [userId, displayName] of getMemberNameMap(chatId)) {
    if (displayName?.toLowerCase() === normalized) return userId;
  }
  return null;
}

// ==== Прямой вопрос "кто такой/такая Х" — про участника ЭТОГО чата ====
// Точечный интент, без похода в LLM (та же логика, что у "кто зашёл/
// вышел" ниже, см. handleJoinLeaveQuery): если Х — это кто-то из уже
// знакомых боту людей (алиас или просто виденное имя, см.
// resolveUserIdByName), отвечаем сразу готовой ссылкой на аккаунт —
// именно то, что LLM в принципе не может сделать сама, у неё нет
// доступа к реальным Telegram user id для генерации рабочей ссылки.
// Если Х не резолвится ни в кого — НЕ отвечаем и не return'имся, просто
// сигнализируем "не наш случай" (см. handleWhoIsQuery ниже), чтобы
// вопрос спокойно ушёл в обычный LLM-чат: "кто такой Наполеон" не
// должен упираться в эту проверку молча.
const WHO_IS_INTENT_REGEX = /^кто\s+(?:так(?:ой|ая|ое|ие)|это)\s+(.+?)\s*[?!.]*$/i;

// Возвращает true, если вопрос был про знакомого человека и бот уже
// ответил (вызывающий код должен сделать return); false — если имя не
// распознано, вопрос нужно обработать как обычно.
async function handleWhoIsQuery(ctx, chatId, name) {
  const userId = resolveUserIdByName(chatId, name);
  if (!userId) return false;

  const displayName = getAliasMap(chatId).get(userId)?.name || getMemberNameMap(chatId).get(userId) || name;
  const username = getKnownUsername(chatId, userId);
  // Ссылка на профиль: если известен @username — обычная t.me-ссылка;
  // если нет — tg://user?id= (это ровно тот же механизм, которым сам
  // Telegram делает "упоминание по имени" без @ника — text_mention).
  // В обоих случаях оборачиваем в <a href="...">Имя</a> (parse_mode:
  // "HTML"), а НЕ отдаём голый URI текстом — иначе вместо кликабельного
  // имени человек увидит некрасивую сырую ссылку "tg://user?id=123...".
  const href = username ? `https://t.me/${username}` : `tg://user?id=${userId}`;
  const linkHtml = `<a href="${href}">${escapeHtml(displayName)}</a>`;

  const profile = normalizeProfile(getProfileMap(chatId).get(userId) || { facts: {} });
  const factLines = Object.values(profile.facts).map((f) => f.text);

  let reply = `это ${linkHtml}`;
  if (factLines.length > 0) {
    reply += `\n\nчто знаю: ${escapeHtml(factLines.join("; "))}`;
  }

  await ctx.reply(reply, {
    parse_mode: "HTML",
    reply_parameters: { message_id: ctx.message.message_id },
    message_thread_id: ctx.message.message_thread_id,
  });
  return true;
}

// Ищем среди уже известных людей чата тех, кого сообщение вероятно
// упоминает — грубый эвристический "стемминг" (обрезаем 1-2 буквы с
// конца имени, чтобы ловить падежи: "Лида" -> "Лид" матчится и в
// "Лиды", "Лиде", "Лидой"). Нужно, чтобы подложить модели их текущие
// факты — тогда она сможет ПРАВИТЬ существующую запись, а не плодить
// дубли ("дочь София" + "дочери 15 лет" -> одна строка, а не две).
function findMentionedMemberIds(chatId, text, speakerId) {
  const lowerText = text.toLowerCase();
  const ids = new Set([speakerId]);

  for (const [userId, name] of getMemberNameMap(chatId)) {
    if (!name || name.length < 3) continue;
    const stem = name.length > 4 ? name.slice(0, -2) : name.slice(0, -1);
    if (lowerText.includes(stem.toLowerCase())) ids.add(userId);
  }
  return [...ids];
}


// --- Автоопределение алиаса по обращению реплаем ---
// Идея: если A отвечает НА сообщение B и начинает свой текст с "Вася, ..."
// или "Вася!" — мы точно знаем, к кому обращаются (reply_to_message.from.id
// даёт настоящий userId, тут не нужно гадать по нечёткому стемматчу, как в
// findMentionedMemberIds). Это надёжнее ника из Telegram, если человек в
// чате известен под настоящим именем, а не под своим @username/first_name.
//
// Чтобы не словить ложное срабатывание на обычные вводные слова в начале
// фразы ("Слушай, ты не прав", "Кстати, видел новость?") — которые в
// русском тоже пишутся с большой буквы и тоже стоят перед запятой — держим
// чёрный список таких слов и требуем ДВУХ разных сообщений с одним и тем же
// именем на одного и того же адресата, прежде чем реально ставить алиас.
const VOCATIVE_BLACKLIST = new Set([
  "слушай", "слушайте", "кстати", "блин", "короче", "ладно", "ну", "просто",
  "вообще", "так", "ребят", "ребята", "пацаны", "народ", "всем", "привет",
  "стоп", "погоди", "подожди", "если", "кстате", "блять", "походу", "видимо",
  "теперь", "может", "может быть", "короч", "чё", "что", "блд", "ёпта",
  "господи", "боже", "ясно", "понятно", "окей", "ок", "хотя", "вот", "ой",
  "ай", "нет", "да", "не", "спс", "спасибо", "пожалуйста",
]);

// "Имя," или "Имя!" строго в начале сообщения, кириллица, без пробелов —
// 3-16 букв, первая заглавная (нормальный формат обращения по имени).
const VOCATIVE_NAME_REGEX = /^\s*([А-ЯЁ][а-яё]{2,15})\s*[,!]/;

// Сколько РАЗНЫХ сообщений с одним и тем же именем на одного и того же
// адресата нужно увидеть, прежде чем ставить алиас автоматически — только
// в памяти, не переживает рестарт (не критично, наберётся заново).
const AUTO_ALIAS_CONFIRM_COUNT = 2;
const pendingAutoAliasCounts = new Map(); // chatId -> Map<"targetId:nameLower", count>

function getPendingAutoAliasMap(chatId) {
  if (!pendingAutoAliasCounts.has(chatId)) pendingAutoAliasCounts.set(chatId, new Map());
  return pendingAutoAliasCounts.get(chatId);
}

// Если сообщение — реплай на другого живого участника и начинается с
// обращения по имени, копим счётчик подтверждений и, набрав порог, тихо
// ставим алиас (не трогая ничего, если человеку уже задан алиас — вручную
// через /alias или автоматически ранее, чтобы не переписывать поверх).
function maybeLearnAliasFromReply(chatId, ctx, rawText) {
  const replyTarget = ctx.message.reply_to_message?.from;
  if (!replyTarget || replyTarget.is_bot) return;
  if (replyTarget.id === ctx.from.id) return; // сам себе не обращается

  const match = rawText.match(VOCATIVE_NAME_REGEX);
  if (!match) return;
  const name = match[1];
  const nameLower = name.toLowerCase();
  if (VOCATIVE_BLACKLIST.has(nameLower)) return;

  if (getAliasMap(chatId).has(replyTarget.id)) return; // уже есть алиас — не трогаем

  const pending = getPendingAutoAliasMap(chatId);
  const key = `${replyTarget.id}:${nameLower}`;
  const count = (pending.get(key) || 0) + 1;

  if (count < AUTO_ALIAS_CONFIRM_COUNT) {
    pending.set(key, count);
    return;
  }

  pending.delete(key);
  const label = replyTarget.username ? `@${replyTarget.username}` : (replyTarget.first_name || "юзер");
  getAliasMap(chatId).set(replyTarget.id, { name, label, source: "auto" });
  saveAliases(chatId);
  console.log(`Авто-алиас: в чате ${chatId} ${label} теперь называется "${name}" (по обращению реплаем)`);
}


// Уменьшительные/имена, которые оканчиваются на -а/-я, но мужские —
// без этого списка их угадало бы как женские.
const MALE_NAME_EXCEPTIONS = new Set([
  "никита", "илья", "данила", "фома", "кузьма", "лука", "савва", "гоша",
  "лёша", "леша", "паша", "миша", "серёжа", "сережа", "костя", "витя",
  "толя", "коля", "петя", "юра", "дима", "рома", "гена",
]);
// Унисекс-имена/уменьшительные — для них имя вообще не сигнал, лучше не гадать.
const AMBIGUOUS_NAMES = new Set(["саша", "женя", "валя", "шура"]);

// Небольшой словарь распространённых латинских/английских имён — для НИКОВ
// вроде "Erkiss" или "lays pwnz" никакого лингвистического сигнала нет
// в принципе (это не имена, а произвольные ники), поэтому для них лучше
// вернуть null (пол неизвестен), чем гадать наугад. Словарь ловит только
// реальные имена, написанные латиницей.
const LATIN_FEMALE_NAMES = new Set([
  "kat", "katya", "katia", "kate", "katherine", "kathryn", "polina",
  "anna", "ann", "anya", "maria", "mary", "masha", "olya", "olga",
  "sasha", "julia", "yulia", "lena", "elena", "helen", "nastya",
  "anastasia", "dasha", "daria", "sofia", "sophia", "emma", "olivia",
  "emily", "amy", "lucy", "vika", "victoria", "veronika", "veronica",
  "ira", "irina", "tanya", "tatiana", "svetlana", "sveta", "nina",
]);
const LATIN_MALE_NAMES = new Set([
  "alex", "sasha", "artem", "artyom", "dima", "dmitry", "dmitri",
  "sergey", "sergei", "ivan", "john", "mike", "michael", "andrey",
  "andrew", "anton", "denis", "dennis", "roman", "max", "maxim",
  "nikita", "oleg", "pavel", "paul", "vlad", "vladislav", "vladimir",
  "kirill", "cyril", "egor", "yegor", "stas", "stanislav",
]);

function guessGenderFromName(firstName) {
  const name = (firstName || "").trim().toLowerCase();
  if (!name || AMBIGUOUS_NAMES.has(name)) return null;
  if (MALE_NAME_EXCEPTIONS.has(name)) return "m";
  if (/[ая]$/.test(name)) return "f";
  // Кириллица не совпала (не на "а"/"я") — считаем мужским: подавляющее
  // большинство обычных кириллических имён/форм так и оканчивается.
  if (/[а-яёА-ЯЁ]/.test(name)) return "m";

  // Латиница — тут уже нет надёжного правила по окончанию (Kat, Erkiss,
  // Alex, polina — никакой общей закономерности), поэтому смотрим только
  // в словарь известных имён. Если ника там нет (гейм-тег, набор букв
  // вроде "lays pwnz") — честно возвращаем null, а не гадаем наугад.
  if (LATIN_FEMALE_NAMES.has(name)) return "f";
  if (LATIN_MALE_NAMES.has(name)) return "m";

  // Если ник — это несколько слов ("lays pwnz"), пробуем первое слово
  // отдельно на случай, если это реальное имя + приставка/тег.
  const firstWord = name.split(/\s+/)[0];
  if (firstWord && firstWord !== name) {
    if (LATIN_FEMALE_NAMES.has(firstWord)) return "f";
    if (LATIN_MALE_NAMES.has(firstWord)) return "m";
  }

  return null;
}

// --- Эвристика по тексту: "я сделал" -> м, "я сделала" -> ж ---
// Ищем "я" и ближайший подходящий глагол в пределах нескольких слов после него.
function guessGenderFromText(text) {
  const words = text.split(/\s+/);
  const yaIdx = words.findIndex((w) => /^я$/i.test(w.replace(/[^а-яёА-ЯЁ]/gi, "")));
  if (yaIdx === -1) return null;

  for (let i = yaIdx + 1; i < Math.min(yaIdx + 5, words.length); i++) {
    const clean = words[i].replace(/[^а-яёА-ЯЁ]/gi, "").toLowerCase();
    if (clean.length < 3) continue;
    if (/(лась|ла)$/.test(clean)) return "f";
    if (/(лся|л)$/.test(clean)) return "m";
  }
  return null;
}

// Вызывается на каждое сообщение — обновляет догадку, если сигнал есть.
function updateGenderGuess(chatId, from, text) {
  const existing = getGenderMap(chatId).get(from.id);
  if (existing?.source === "manual") return; // ручное значение не трогаем

  const fromText = guessGenderFromText(text);
  if (fromText) {
    setGender(chatId, from.id, fromText, "text");
    return;
  }

  if (!existing) {
    const fromName = guessGenderFromName(from.first_name);
    if (fromName) setGender(chatId, from.id, fromName, "name");
  }
}


const HISTORY_LIMIT = 12; // сколько последних сообщений держим в контексте
const histories = new Map();

function getHistory(chatId) {
  if (!histories.has(chatId)) histories.set(chatId, []);
  return histories.get(chatId);
}

async function saveHistory(chatId) {
  if (!redis) return;
  try {
    await redis.set(`history:${chatId}`, getHistory(chatId));
  } catch (err) {
    console.error(`Redis: не удалось сохранить историю чата ${chatId}:`, err);
  }
}

async function clearHistory(chatId) {
  histories.delete(chatId);
  if (!redis) return;
  try {
    await redis.del(`history:${chatId}`);
  } catch (err) {
    console.error(`Redis: не удалось удалить историю чата ${chatId}:`, err);
  }
}

// Каждой пользовательской реплике в истории явно приписываем момент
// отправки — "[ДД.ММ ЧЧ:ММ] " перед текстом. Раньше модель видела только
// голый порядок реплик без привязки ко времени и не могла понять, например,
// что между двумя сообщениями прошло 3 часа, а не 3 секунды. Ответы самого
// бота меткой не размечаем — они и так идут сразу за помеченной репликой
// пользователя, дублировать незачем. Метка попадает в постоянное хранилище
// (Redis) как часть content — это осознанно: она должна быть видна модели
// и при следующих обращениях, а не только в момент самого пуша.
function pushHistory(chatId, role, content) {
  const h = getHistory(chatId);
  const stamped = role === "user" ? `[${formatShortDateTime()}] ${content}` : content;
  h.push({ role, content: stamped });
  while (h.length > HISTORY_LIMIT) h.shift();
  saveHistory(chatId);
}

// ==== Лог сообщений чата (для команды "о чём тут речь") ====
// Отдельно от HISTORY выше (та — только реплики самого диалога с ботом,
// максимум HISTORY_LIMIT штук, и нужна модели для контекста ответа).
// Этот лог — «сырая» лента ВСЕХ сообщений в группе (даже не адресованных
// боту), чтобы потом можно было попросить пересказать, о чём был разговор,
// пока бота не звали. Сообщения от других ботов сюда не попадают (см.
// вызов pushChatLog — фильтр по ctx.from.is_bot). Личные чаты не логируем —
// там и так есть обычная история диалога.
const CHAT_LOG_LIMIT = 300; // сколько последних сообщений держим в логе на чат
const chatLogs = new Map(); // chatId -> [{ name, text, ts, toBot }]

function getChatLog(chatId) {
  if (!chatLogs.has(chatId)) chatLogs.set(chatId, []);
  return chatLogs.get(chatId);
}

async function saveChatLog(chatId) {
  if (!redis) return;
  try {
    await redis.set(`chatlog:${chatId}`, getChatLog(chatId));
  } catch (err) {
    console.error(`Redis: не удалось сохранить лог чата ${chatId}:`, err);
  }
}

// toBot — было ли сообщение обращением к боту (по имени/реплаем/тегом) —
// нужно, чтобы при пересказе отдельно отметить "общался(-ась) с ботом о...".
// event — необязательная пометка "join"/"leave" для служебных записей о
// входе/выходе участников (см. pushChatLog ниже и bot.on(["message:new_chat_members", ...]))
// — нужна, чтобы при сборке транскрипта для пересказа (handleRecapQuery)
// отличать их от обычных реплик и форматировать отдельной строкой.
function pushChatLog(chatId, name, text, toBot, event) {
  const log = getChatLog(chatId);
  const entry = { name, text, ts: Date.now(), toBot: !!toBot };
  if (event) entry.event = event;
  log.push(entry);
  while (log.length > CHAT_LOG_LIMIT) log.shift();
  saveChatLog(chatId);
}

// Собирает контекст для extractProfileFacts, чтобы короткие ответы не
// терялись без понимания, на что они отвечают:
//   1) реплай (на бота ИЛИ на другого человека) — самый точный сигнал,
//      берём текст именно того сообщения;
//   2) иначе — несколько последних реплик чата (без реплая, просто вопрос
//      и ответ подряд, как в живой беседе).
// pushChatLog для текущего сообщения уже отработал к моменту вызова —
// поэтому в chatLog последняя запись это ОНО САМО, её пропускаем.
const PROFILE_CONTEXT_WINDOW = 3;

function buildProfileExtractionContext(chatId, ctx) {
  const replyMsg = ctx.message.reply_to_message;
  if (replyMsg && replyMsg.text && replyMsg.from?.id !== ctx.from.id) {
    const replyName = replyMsg.from?.is_bot ? "бот" : getDisplayName(chatId, replyMsg.from);
    return `Сообщение ниже — реплай на сообщение "${replyName}": "${replyMsg.text.slice(0, 300)}"`;
  }

  const log = getChatLog(chatId);
  // Последняя запись — текущее сообщение (pushChatLog уже отработал выше),
  // поэтому окно берём ПЕРЕД ней.
  const recent = log.slice(-1 - PROFILE_CONTEXT_WINDOW, -1).filter((e) => !e.event && e.text);
  if (recent.length === 0) return null;
  const lines = recent.map((e) => `${e.name}: ${e.text}`).join("\n");
  return `Несколько предыдущих реплик в чате для контекста (сообщение ниже может отвечать на один из этих вопросов):\n${lines}`;
}


// Формирует текст события входа/выхода с согласованием рода, если он
// известен (см. getGender) — по тому же принципу, что и остальные
// гендерно-согласованные фразы в боте (см. "угадал(а)" в крокодиле): если
// пол неизвестен, используем нейтральную форму "(-ла)" как хедж.
function joinLeaveText(name, gender, type) {
  if (type === "join") {
    if (gender === "f") return `${name} зашла в чат`;
    if (gender === "m") return `${name} зашёл в чат`;
    return `${name} зашёл(-ла) в чат`;
  }
  if (gender === "f") return `${name} вышла из чата`;
  if (gender === "m") return `${name} вышел из чата`;
  return `${name} вышел(-ла) из чата`;
}

// ==== Кэш описаний фото по message_id ====
// Нужен, чтобы если кто-то ОТВЕТИТ на чужое фото вопросом к боту ("Женя,
// как тебе?" реплаем на фото, которое прислал не он, а другой участник) —
// бот мог достать описание именно ЭТОГО конкретного фото, а не полагаться
// на то, что оно случайно ещё не "вытолкнулось" из HISTORY_LIMIT. Живёт
// только в памяти процесса (не в Redis) — это недолгоживущий кэш для
// текущей сессии чата, при рестарте бота просто начнёт заполняться заново,
// ничего критичного тут нет. Ограничен по размеру, чтобы не расти вечно в
// активном чате — при переполнении вычищаем самую старую запись (Map
// сохраняет порядок вставки).
const PHOTO_CAPTION_CACHE_LIMIT = 500;
const photoCaptionsByMessage = new Map(); // `${chatId}:${messageId}` -> { name, caption }

function rememberPhotoCaption(chatId, messageId, name, caption) {
  const key = `${chatId}:${messageId}`;
  photoCaptionsByMessage.set(key, { name, caption });
  if (photoCaptionsByMessage.size > PHOTO_CAPTION_CACHE_LIMIT) {
    const oldestKey = photoCaptionsByMessage.keys().next().value;
    photoCaptionsByMessage.delete(oldestKey);
  }
}

function getPhotoCaption(chatId, messageId) {
  return photoCaptionsByMessage.get(`${chatId}:${messageId}`) || null;
}

// Тот же приём, что и с фото выше, но для описаний видео (см. captionVideo/
// VIDEO_DESCRIPTION_PROMPT) — если несколько человек по очереди отвечают на
// одно и то же видео вопросами к боту, не гонять Gemini заново на каждый
// реплай.
const VIDEO_CAPTION_CACHE_LIMIT = 200;
const videoCaptionsByMessage = new Map(); // `${chatId}:${messageId}` -> { name, caption }

function rememberVideoCaption(chatId, messageId, name, caption) {
  const key = `${chatId}:${messageId}`;
  videoCaptionsByMessage.set(key, { name, caption });
  if (videoCaptionsByMessage.size > VIDEO_CAPTION_CACHE_LIMIT) {
    const oldestKey = videoCaptionsByMessage.keys().next().value;
    videoCaptionsByMessage.delete(oldestKey);
  }
}

function getVideoCaption(chatId, messageId) {
  return videoCaptionsByMessage.get(`${chatId}:${messageId}`) || null;
}

// ==== Кэш собственных текстовых ответов бота по message_id ====
// Нужен для реплаев на СТАРЫЙ ответ бота — например, человек 2 отвечает
// репликой на сообщение, которым бот когда-то ответил человеку 1. Обычная
// HISTORY (см. history:${chatId} в askLLM) хранит только последние 12 реплик
// на весь чат без привязки к message_id, так что если между тем ответом и
// текущим реплаем было много другого трёпа — бот физически не видит, что
// сам написал, и отвечает вслепую. Тот же паттерн, что и у
// photoCaptionsByMessage/movieCardsByMessage выше — живёт только в памяти
// процесса, при рестарте начнёт заполняться заново, ничего критичного.
const BOT_REPLY_CACHE_LIMIT = 500;
const botRepliesByMessage = new Map(); // `${chatId}:${messageId}` -> { name, text }

function rememberBotReply(chatId, messageId, name, text) {
  if (!messageId || !text) return;
  const key = `${chatId}:${messageId}`;
  botRepliesByMessage.set(key, { name, text });
  if (botRepliesByMessage.size > BOT_REPLY_CACHE_LIMIT) {
    const oldestKey = botRepliesByMessage.keys().next().value;
    botRepliesByMessage.delete(oldestKey);
  }
}

function getBotReply(chatId, messageId) {
  return botRepliesByMessage.get(`${chatId}:${messageId}`) || null;
}

// ==== Сообщения бота, реально относящиеся к музыкальному потоку (Deezer) ====
// Раньше "это реплай на музыкальное сообщение бота?" определялось нечётким
// regex'ом по ТЕКСТУ сообщения, на которое ответили (/Загружаю|найден|
// Deezer|🎵|🎚/i) — а текст этот в случае обычных ответов LLM (например,
// рассказ о своих возможностях) вполне мог случайно содержать одно из этих
// слов ("Deezer", "🎵" и т.п.), и тогда ЛЮБОЙ последующий реплай на такое
// сообщение (даже "какая погода в Киеве?" или обычный вопрос) ошибочно
// уходил в поиск трека на Deezer. Вместо угадывания по словам — явно
// помечаем ID тех сообщений, которые бот сам отправил именно в рамках
// музыкального потока (статус загрузки, "не найдено", ошибка, сам
// присланный трек), и полагаемся только на эту точную метку.
const DEEZER_MSG_TAG_LIMIT = 500;
const deezerFlowMessageIds = new Map(); // `${chatId}:${messageId}` -> true

function markDeezerFlowMessage(chatId, messageId) {
  if (!messageId) return;
  const key = `${chatId}:${messageId}`;
  deezerFlowMessageIds.set(key, true);
  if (deezerFlowMessageIds.size > DEEZER_MSG_TAG_LIMIT) {
    const oldestKey = deezerFlowMessageIds.keys().next().value;
    deezerFlowMessageIds.delete(oldestKey);
  }
}

function isDeezerFlowMessage(chatId, messageId) {
  if (!messageId) return false;
  return deezerFlowMessageIds.has(`${chatId}:${messageId}`);
}

// ==== Пересланные сообщения (мемы/новости из других каналов) ====
// Такие сообщения не должны засорять ни ChatLog (пересказ "о чём тут
// речь"), ни обычную историю диалога — это не то, что писали сами
// участники чата, а чужой контент, просто закинутый в чат. Проверяем и
// новое поле Bot API 7.0+ (forward_origin), и старые legacy-поля — на
// случай разных версий клиента/сервера Telegram.
function isForwardedMessage(message) {
  return !!(
    message.forward_origin ||
    message.forward_date ||
    message.forward_from ||
    message.forward_from_chat ||
    message.forward_sender_name
  );
}

// ==== Шахматы ====
// Отдельная механика поверх обычного чата, без команды: если для чата ещё
// нет активной партии и в сообщении упоминаются шахматы — считаем это
// приглашением и стартуем игру. Дальше, пока партия идёт, каждое входящее
// сообщение сначала пробуем распознать как ход (или "сдаюсь"/"покажи
// доску"/"новая партия") — если получилось, играем; если сообщение на ход
// не похоже, оно просто уходит в обычный LLM-чат как раньше, так что можно
// одновременно и играть, и болтать.
//
// Легальность ходов и правила (рокировка, взятие на проходе, мат/пат/ничья)
// считает chess.js. Ход бота считает простой minimax с альфа-бета
// отсечением на несколько полуходов вперёд (материал + позиционные бонусы
// за центр) — бот реально перебирает варианты, а не ходит наугад.
// Партия (FEN + цвет пользователя) хранится в памяти и зеркалится в Redis
// (ключ chess:{chatId}:{userId}), как и остальная память бота — см.
// loadPersistedState. Ключ включает userId (не только chatId!) — это
// значит, что в одном чате (особенно группе) у РАЗНЫХ людей могут идти
// СВОИ независимые партии с ботом одновременно, и ходить в партии может
// только тот, кто её начал — см. chessMapKey/getChessGame ниже.

const CHESS_INTENT_REGEX = /шахмат/i;
const CHESS_RESIGN_REGEX = /сда(ю|л)/i;
const CHESS_BOARD_REGEX = /покажи доск|^доска\??$|как там доска/i;
// "новая партия"/"переиграем" и т.п. — рестарт теми же цветами, что и
// раньше. Явная смена цвета ("играй за белых", "поменяемся сторонами")
// ловится отдельно через parseRequestedUserColor ниже — так что сюда
// цвет намеренно не включаем, чтобы не дублировать и не путать логику.
const CHESS_NEW_GAME_REGEX =
  /нов(ую|ая) парти|давай заново|начн[её]м заново|переиграем|поменяемся (сторонами|цветами)|смени(м)? (сторону|цвет)/i;
// Переключение вида доски: буквы <-> юникод-символы фигур.
const CHESS_VIEW_UNICODE_REGEX = /фигурк|значк|символ|юникод/i;
const CHESS_VIEW_ASCII_REGEX = /букв/i;

// chatId:userId -> { fen, userColor: "w" | "b", view: "ascii" | "unicode", playerName }
const chessGames = new Map();

function chessMapKey(chatId, userId) {
  return `${chatId}:${userId}`;
}

function getChessGame(chatId, userId) {
  return chessGames.get(chessMapKey(chatId, userId)) || null;
}

// Пытается понять из текста, какой стороной должен играть ПОЛЬЗОВАТЕЛЬ —
// используется и при старте партии ("сыграем в шахматы за чёрных"), и при
// смене сторон в существующей. Возвращает null, если цвет явно не
// запрошен или упомянуты сразу оба (неоднозначно) — тогда вызывающий код
// берёт значение по умолчанию/оставляет как было.
//
// Важно: цвет в сообщении может относиться и к боту, а не к пользователю —
// "играй за белых"/"ты за белых" значит, что БЕЛЫМИ должен играть бот,
// а пользователю тогда достаются чёрные. Отличаем такие фразы (обращение
// на "ты" или императив "играй/сыграй/бери/возьми") от фраз про самого
// пользователя ("я за чёрных", "давай в шахматы за чёрных").
//
// Текст оборачиваем пробелами и границы слов проверяем вручную через
// [^а-яё] вместо \b: в JS \b определяется через \w, который НЕ включает
// кириллицу, так что \bты\b или "черных\b" с кириллицей молча никогда не
// совпадают — на этом уже словили баг ("Давай ты за белых" не срабатывало).
function parseRequestedUserColor(text) {
  const t = ` ${text.toLowerCase()} `;
  const mentionsWhite = /за\s*бел|белыми|белых[^а-яё]/.test(t);
  const mentionsBlack = /за\s*ч[её]рн|ч[её]рными|ч[её]рных[^а-яё]/.test(t);
  if (mentionsWhite === mentionsBlack) return null; // ни один цвет не упомянут, либо упомянуты оба — неоднозначно

  const addressedToBot = /[^а-яё]ты[^а-яё]|играй|сыграй|бери|возьми/.test(t);
  if (addressedToBot) {
    // цвет достаётся боту -> пользователю противоположный
    return mentionsWhite ? "b" : "w";
  }
  // иначе цвет для самого пользователя
  return mentionsWhite ? "w" : "b";
}

async function saveChessGame(chatId, userId) {
  if (!redis) return;
  try {
    await redis.set(`chess:${chatId}:${userId}`, chessGames.get(chessMapKey(chatId, userId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить шахматную партию ${chatId}:${userId}:`, err);
  }
}

async function clearChessGame(chatId, userId) {
  chessGames.delete(chessMapKey(chatId, userId));
  if (!redis) return;
  try {
    await redis.del(`chess:${chatId}:${userId}`);
  } catch (err) {
    console.error(`Redis: не удалось удалить шахматную партию ${chatId}:${userId}:`, err);
  }
}

function startChessGame(chatId, userId, userColor, view, playerName) {
  const chess = new Chess();
  const key = chessMapKey(chatId, userId);
  // Вид доски по умолчанию наследуем от предыдущей партии этого же
  // пользователя в этом чате (если она была) — чтобы выбор
  // "фигурками"/"буквами" не сбрасывался при "новая партия" или смене сторон.
  const resolvedView = view || chessGames.get(key)?.view || "ascii";
  // captured — что кем съедено за партию: captured.w — белые фигуры,
  // которых не стало (их съели чёрные), captured.b — наоборот. Список
  // типов фигур (chess.js буквы: p,n,b,r,q), сбрасывается с новой партией.
  // moveStyle — в каком формате пользователь пишет ходы в ЭТОЙ партии
  // ("uci" — e2e4, или "san" — Nf3) — чтобы бот отвечал своим ходом в
  // том же формате, а не всегда SAN-нотацией (см. formatChessMove).
  // Определяется по первому ходу пользователя, дальше обновляется на
  // каждом его ходу (мало ли переключится посреди партии).
  chessGames.set(key, {
    fen: chess.fen(),
    userColor,
    view: resolvedView,
    playerName,
    captured: { w: [], b: [] },
    moveStyle: chessGames.get(key)?.moveStyle || "san",
  });
  saveChessGame(chatId, userId);
  return chess;
}

// Юникод-символы фигур для вида "картинками". Полые ♔♘♙... — белые,
// залитые ♚♞♟... — чёрные (стандартное начертание).
//
// VS15 (U+FE0E, "variation selector-15") приклеен к каждому символу —
// без него часть клиентов (в первую очередь мобильный Telegram) рисует
// эти символы эмодзи-шрифтом, который шире моноширинного текста, и
// правая граница доски в ```-блоке "уезжает" вправо на строках с
// фигурами (буквенный вид не страдает, там обычный ASCII). VS15
// принудительно просит текстовое/узкое начертание вместо эмодзи-стиля.
const VS15 = "\uFE0E";
const withVS = (s) => s + VS15;
const UNICODE_WHITE = {
  p: withVS("♙"),
  n: withVS("♘"),
  b: withVS("♗"),
  r: withVS("♖"),
  q: withVS("♕"),
  k: withVS("♔"),
};
const UNICODE_BLACK = {
  p: withVS("♟"),
  n: withVS("♞"),
  b: withVS("♝"),
  r: withVS("♜"),
  q: withVS("♛"),
  k: withVS("♚"),
};

function formatBoardAscii(chess) {
  // chess.ascii() сам рисует доску буквами (заглавные — белые, строчные —
  // чёрные, точки — пустые клетки) с подписанными горизонталями/вертикалями.
  return chess.ascii();
}

function formatBoardUnicode(chess) {
  // Ручная отрисовка тем же макетом, что и chess.ascii(), но клетками с
  // юникод-символами фигур вместо латинских букв — вид "как на скриншоте".
  const rows = chess.board(); // 8 строк, rows[0] — 8-я горизонталь, rows[7] — 1-я
  const lines = ["  +------------------------+"];
  for (let i = 0; i < 8; i++) {
    const rank = 8 - i;
    const cells = rows[i].map((cell) => {
      if (!cell) return "·";
      return (cell.color === "w" ? UNICODE_WHITE : UNICODE_BLACK)[cell.type];
    });
    lines.push(`${rank} | ${cells.join("  ")} |`);
  }
  lines.push("  +------------------------+");
  lines.push("    a  b  c  d  e  f  g  h");
  return lines.join("\n");
}

// Порядок для сортировки съеденных фигур в счёте — сильные впереди,
// чисто эстетика вывода, на подсчёт не влияет.
const CHESS_PIECE_ORDER = ["q", "r", "b", "n", "p"];
function sortCapturedPieces(list) {
  return [...list].sort((a, b) => CHESS_PIECE_ORDER.indexOf(a) - CHESS_PIECE_ORDER.indexOf(b));
}

// Строка символов съеденных фигур одного цвета в нужном виде отображения.
function capturedPiecesGlyphs(list, color, view) {
  const sorted = sortCapturedPieces(list);
  if (sorted.length === 0) return "—";
  if (view === "unicode") {
    const map = color === "w" ? UNICODE_WHITE : UNICODE_BLACK;
    return sorted.map((t) => map[t]).join("");
  }
  return sorted.map((t) => (color === "w" ? t.toUpperCase() : t)).join("");
}

// Строка счёта под доской — сколько и каких фигур съедено у каждой
// стороны. captured — { w: [...], b: [...] }, где captured.w — типы
// белых фигур, которых не стало (их съел чёрный), и наоборот.
function formatCapturedLine(captured, userColor, view) {
  if (!captured) return null;
  const oppColor = userColor === "w" ? "b" : "w";
  const yourLost = captured[userColor] || [];
  const myLost = captured[oppColor] || [];
  if (yourLost.length === 0 && myLost.length === 0) return null;
  const yourGlyphs = capturedPiecesGlyphs(yourLost, userColor, view);
  const myGlyphs = capturedPiecesGlyphs(myLost, oppColor, view);
  return `Съедено у тебя: ${yourGlyphs} (${yourLost.length}) | у меня: ${myGlyphs} (${myLost.length})`;
}

// userColor — какой стороной играет пользователь в ЭТОЙ партии (после
// смены сторон бот тоже может быть белыми и ходить первым, см. ниже),
// view — "ascii" (буквы, по умолчанию) или "unicode" (символы фигур),
// переключается за партию через CHESS_VIEW_*_REGEX ниже. playerName —
// с кем идёт партия, показывается заголовком над доской (актуально в
// группах, где партий с ботом может быть несколько одновременно).
// captured — счёт съеденных фигур (см. formatCapturedLine), опционален.
function formatBoard(chess, userColor, view, playerName, captured) {
  const board = view === "unicode" ? formatBoardUnicode(chess) : formatBoardAscii(chess);

  let caption;
  if (view === "unicode") {
    // Символы легенды тоже с VS15 (см. комментарий у UNICODE_WHITE/BLACK) —
    // легенда в том же ```-блоке, что и доска, поэтому должна рендериться
    // так же узко, иначе сама строка легенды может "поплыть". Одна фигура
    // на сторону достаточно для примера — раньше показывали все шесть,
    // это было лишним.
    const wPiece = UNICODE_WHITE.k;
    const bPiece = UNICODE_BLACK.k;
    caption =
      userColor === "w"
        ? `(${wPiece} — твои белые, ${bPiece} — мои чёрные)`
        : `(${bPiece} — твои чёрные, ${wPiece} — мои белые)`;
  } else {
    caption =
      userColor === "w"
        ? "(заглавные — твои белые, строчные — мои чёрные)"
        : "(строчные — твои чёрные, заглавные — мои белые)";
  }

  const capturedLine = formatCapturedLine(captured, userColor, view);
  const captionBlock = capturedLine ? `${caption}\n${capturedLine}` : caption;

  const header = playerName ? `Партия с ${playerName}:\n` : "";
  return header + "```\n" + board + "\n" + captionBlock + "\n```";
}

// На русской раскладке "е2е4" легко напечатать кириллическими е/а, которые
// выглядят как латинские, но ими не являются — chess.js такое не распознает.
// Нормализуем самые частые омоглифы перед разбором хода.
// "B3 - c2" — частый способ написать ход с пробелами вокруг дефиса
// (визуально копируют с доски, где так рисуют разделитель клеток). Без
// этой замены токенизация по пробелам (см. tryApplyUserMove) режет такую
// строку на три отдельных куска — "B3", "-", "c2" — и ни один из них не
// проходит как ход, хотя сам ход абсолютно однозначный. Схлопываем пробелы
// вокруг дефиса ДО разбивки на токены, чтобы "B3 - c2" стало "B3-c2" и
// осталось одним токеном (подходит и под UCI-формат b3-c2, и заодно чинит
// "o - o" -> "o-o" для рокировки).
function normalizeMoveText(text) {
  return text
    .trim()
    .replace(/\s*-\s*/g, "-")
    .replace(/а/g, "a")
    .replace(/А/g, "A")
    .replace(/е/g, "e")
    .replace(/Е/g, "E");
}

// Пытается распознать ход из текста сообщения — либо в UCI-формате
// (e2e4, e7e8q), либо обычной шахматной нотацией (SAN: e4, Nf3, O-O, exd5).
// Сообщение может содержать не только сам ход (например "e2e4, покажи
// доску" одним сообщением) — разбиваем на токены по пробелам/запятым и
// пробуем каждый по очереди, применяя первый, который окажется легальным
// ходом. Применяет ход к переданному объекту chess.js и возвращает Move,
// либо null, если ни один токен на ход не похож (тогда сообщение уйдёт в
// обычный чат).
// Возвращает { move, style }, где style — "uci" (e2e4) или "san" (Nf3) —
// в каком формате пользователь фактически написал ЭТОТ ход, чтобы бот мог
// ответить своим ходом в том же формате (см. formatChessMove). null, если
// ни один токен на ход не похож.
function tryApplyUserMove(chess, rawText) {
  const text = normalizeMoveText(rawText);
  const tokens = text.split(/[\s,;]+/).filter(Boolean);

  for (const token of tokens) {
    const uciMatch = token.match(/^([a-h][1-8])-?([a-h][1-8])=?([qrbn])?$/i);
    try {
      if (uciMatch) {
        const [, from, to, promo] = uciMatch;
        const move = chess.move({
          from: from.toLowerCase(),
          to: to.toLowerCase(),
          promotion: (promo || "q").toLowerCase(),
        });
        if (move) return { move, style: "uci" };
      } else {
        const move = chess.move(token);
        if (move) return { move, style: "san" };
      }
    } catch {
      // не подошло — пробуем следующий токен сообщения
    }
  }
  return null;
}

// Форматирует ход в нужном стиле — "uci" (e2e4, при превращении e7e8q) или
// "san" (Nf3, exd5, O-O) — так бот отвечает ходом в той же нотации, в
// которой пишет ходы пользователь в этой партии, а не всегда SAN.
function formatChessMove(move, style) {
  if (style === "uci") {
    return `${move.from}${move.to}${move.promotion || ""}`;
  }
  return move.san;
}

// Похоже ли сообщение на ПОПЫТКУ хода (по форме, не по легальности) —
// если да, но tryApplyUserMove его не принял (нелегальный ход или опечатка),
// об этом надо сказать явно, а не молча отдавать сообщение в обычный LLM-чат:
// иначе модель, не зная реальной позиции, сама выдумает правдоподобный
// шахматный комментарий, а доска на самом деле не изменится — выглядит как
// баг с "игра идёт своим чередом", хотя ход просто не применился.
const MOVE_SHAPE_UCI = /^[a-h][1-8]-?[a-h][1-8]=?[qrbn]?$/i;
const MOVE_SHAPE_SAN = /^(?:[nbrqk][a-h]?[1-8]?x?[a-h][1-8]|[a-h]x?[a-h]?[1-8]|o-o(-o)?)(=[qrbn])?[+#]?$/i;

function looksLikeMoveAttempt(rawText) {
  const tokens = normalizeMoveText(rawText).split(/[\s,;]+/).filter(Boolean);
  if (tokens.length === 0 || tokens.length > 3) return false; // длинная фраза — не ход
  return tokens.every((t) => MOVE_SHAPE_UCI.test(t) || MOVE_SHAPE_SAN.test(t));
}

// ==== Простой шахматный движок для хода бота (material + PST + minimax) ====
const PIECE_VALUES = { p: 100, n: 320, b: 330, r: 500, q: 900, k: 0 };

// Позиционные бонусы (с точки зрения белых, индекс 0 = 8-я горизонталь) —
// чтобы бот тянулся в центр пешками/конями, а не просто считал материал.
// Для остальных фигур обходимся без таблиц: на глубине поиска в несколько
// полуходов материала + этих двух таблиц достаточно для вменяемой игры.
const PST_PAWN = [
  0, 0, 0, 0, 0, 0, 0, 0,
  50, 50, 50, 50, 50, 50, 50, 50,
  10, 10, 20, 30, 30, 20, 10, 10,
  5, 5, 10, 25, 25, 10, 5, 5,
  0, 0, 0, 20, 20, 0, 0, 0,
  5, -5, -10, 0, 0, -10, -5, 5,
  5, 10, 10, -20, -20, 10, 10, 5,
  0, 0, 0, 0, 0, 0, 0, 0,
];
const PST_KNIGHT = [
  -50, -40, -30, -30, -30, -30, -40, -50,
  -40, -20, 0, 0, 0, 0, -20, -40,
  -30, 0, 10, 15, 15, 10, 0, -30,
  -30, 5, 15, 20, 20, 15, 5, -30,
  -30, 0, 15, 20, 20, 15, 0, -30,
  -30, 5, 10, 15, 15, 10, 5, -30,
  -40, -20, 0, 5, 5, 0, -20, -40,
  -50, -40, -30, -30, -30, -30, -40, -50,
];
const PST = { p: PST_PAWN, n: PST_KNIGHT };

function squareIndex(square, color) {
  const file = square.charCodeAt(0) - "a".charCodeAt(0);
  const rank = parseInt(square[1], 10) - 1; // 0 = 1-я горизонталь
  const rankFromTop = color === "w" ? 7 - rank : rank; // таблицы выше — сверху вниз, для чёрных зеркалим
  return rankFromTop * 8 + file;
}

function evaluateBoard(chess) {
  let score = 0;
  for (const row of chess.board()) {
    for (const cell of row) {
      if (!cell) continue;
      const value = PIECE_VALUES[cell.type];
      const table = PST[cell.type];
      const bonus = table ? table[squareIndex(cell.square, cell.color)] : 0;
      score += (cell.color === "w" ? 1 : -1) * (value + bonus);
    }
  }
  return score;
}

const MATE_SCORE = 100000;

function minimax(chess, depth, alpha, beta, maximizing) {
  if (chess.isCheckmate()) return maximizing ? -MATE_SCORE - depth : MATE_SCORE + depth;
  if (chess.isDraw() || chess.isStalemate()) return 0;
  if (depth === 0) return evaluateBoard(chess);

  const moves = chess.moves({ verbose: true });
  moves.sort((a, b) => (b.captured ? 1 : 0) - (a.captured ? 1 : 0)); // взятия вперёд — отсечения эффективнее

  let best = maximizing ? -Infinity : Infinity;
  for (const m of moves) {
    chess.move(m);
    const score = minimax(chess, depth - 1, alpha, beta, !maximizing);
    chess.undo();

    if (maximizing) {
      best = Math.max(best, score);
      alpha = Math.max(alpha, best);
    } else {
      best = Math.min(best, score);
      beta = Math.min(beta, best);
    }
    if (beta <= alpha) break;
  }
  return best;
}

const CHESS_SEARCH_DEPTH = 3; // полуходов вперёд для хода бота — баланс силы игры и скорости ответа

function findBestMove(chess) {
  const color = chess.turn(); // чей сейчас ход — ходит бот
  const moves = chess.moves({ verbose: true });
  moves.sort((a, b) => (b.captured ? 1 : 0) - (a.captured ? 1 : 0));

  let bestMove = null;
  let bestScore = color === "w" ? -Infinity : Infinity;

  for (const m of moves) {
    chess.move(m);
    const score = minimax(chess, CHESS_SEARCH_DEPTH - 1, -Infinity, Infinity, color !== "w");
    chess.undo();

    if (color === "w" ? score > bestScore : score < bestScore) {
      bestScore = score;
      bestMove = m;
    }
  }
  return bestMove;
}

function pickRandom(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

const CHESS_START_PHRASES_WHITE = [
  "го, давай сыграем. Ты за белых, ходи первым — пиши как e2e4 или обычной нотацией типа Nf3.",
  "чё бы и не сыграть. Бери белых, начинай — формат хода e2e4 или Nf3, как удобнее.",
  "ладно, давай. Ты белыми, я чёрными — жду твой ход (e2e4 или Nf3, без разницы).",
];
const CHESS_START_PHRASES_BLACK = [
  "го, давай сыграем. Ты за чёрных, значит я белыми и хожу первым.",
  "чё бы и не сыграть. Бери чёрных — я тогда за белых, начинаю.",
  "ладно, давай. Ты чёрными, я белыми — открываю партию.",
];
const CHESS_CHECKMATE_WIN_PHRASES = ["мат, я выиграл. Ну ты держался норм", "всё, мат. Реванш будешь брать?"];
const CHESS_CHECKMATE_LOSE_PHRASES = ["ну и мат мне... красиво сыграл", "мат мне, засчитано — забирай победу"];
const CHESS_DRAW_PHRASES = ["ничья, разошлись как в море корабли", "пат или ничья короче — никто не выиграл"];
const CHESS_RESIGN_PHRASES = ["принято, партия окончена", "ладно, сдался — так сдался"];

// ==== Шашки (русские шашки, 8x8, обязательное взятие) ====
// Реализовано с нуля (готовой библиотеки уровня chess.js для шашек в
// зависимостях нет) — доска, генератор ходов, движок для хода бота.
// Общая архитектура намеренно скопирована с шахматного блока выше:
// своя Map(chatId:userId -> состояние), зеркалирование в Redis
// (ключ checkers:{chatId}:{userId}), тот же parseRequestedUserColor и те
// же регэкспы "покажи доску"/"новая партия"/переключение вида — эти фразы
// не специфичны для шахмат, так что переиспользуются как есть.
//
// Упрощения относительно официальных турнирных правил (осознанно, чтобы
// не раздувать движок): при взятии ходить обязательно (в т.ч. добивать
// цепочку, пока есть куда), но правило "бить максимально длинную цепочку,
// если есть выбор" не форсируется — бот и игрок могут выбрать любую
// доступную цепочку взятий. Дамка, проходящая через последнюю
// горизонталь ВНУТРИ цепочки взятий, превращается в дамку только по
// завершении всего хода, а не сразу посреди прыжков.
//
// Координаты — как в шахматах, a1..h8. Доска хранится как массив из 8
// строк (row 0 = 8-я горизонталь сверху, row 7 = 1-я горизонталь снизу),
// в каждой строке 8 клеток (col 0 = вертикаль a). Клетка — null (пусто)
// либо { color: "w"|"b", king: boolean }.

const CHECKERS_INTENT_REGEX = /шашк/i;
const CHECKERS_MOVE_REGEX = /^[a-h][1-8](?:[-:x][a-h][1-8])+$/i;
const CHECKERS_SEARCH_DEPTH = 5; // полуходов вперёд — у шашек ветвление меньше, чем в шахматах, можно глубже

// chatId:userId -> { board, turn: "w"|"b", userColor: "w"|"b", view, playerName }
const checkersGames = new Map();

function checkersMapKey(chatId, userId) {
  return `${chatId}:${userId}`;
}

function getCheckersGame(chatId, userId) {
  return checkersGames.get(checkersMapKey(chatId, userId)) || null;
}

async function saveCheckersGame(chatId, userId) {
  if (!redis) return;
  try {
    await redis.set(`checkers:${chatId}:${userId}`, checkersGames.get(checkersMapKey(chatId, userId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить партию в шашки ${chatId}:${userId}:`, err);
  }
}

async function clearCheckersGame(chatId, userId) {
  checkersGames.delete(checkersMapKey(chatId, userId));
  if (!redis) return;
  try {
    await redis.del(`checkers:${chatId}:${userId}`);
  } catch (err) {
    console.error(`Redis: не удалось удалить партию в шашки ${chatId}:${userId}:`, err);
  }
}

// Тёмная (игровая) клетка — ровно та же чётность, что и у тёмных клеток
// в шахматах (a1 тёмная, h8 тёмная), чтобы координаты совпадали с
// привычной шахматной разметкой доски.
function isDarkSquare(row, col) {
  const file = col + 1;
  const rank = 8 - row;
  return (file + rank) % 2 === 0;
}

function squareToRC(square) {
  // toLowerCase() — чтобы E7-e6 / e7-E6 / E7-E6 распознавались так же, как
  // e7-e6: сюда попадают клетки, вытащенные regexp'ом с флагом /gi, а он
  // сохраняет исходный регистр букв из сообщения пользователя.
  square = square.toLowerCase();
  const col = square.charCodeAt(0) - "a".charCodeAt(0);
  const rank = parseInt(square[1], 10);
  const row = 8 - rank;
  return { row, col };
}

function rcToSquare(row, col) {
  const file = String.fromCharCode("a".charCodeAt(0) + col);
  const rank = 8 - row;
  return `${file}${rank}`;
}

function createInitialCheckersBoard() {
  const board = Array.from({ length: 8 }, () => Array(8).fill(null));
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      if (!isDarkSquare(row, col)) continue;
      const rank = 8 - row;
      if (rank <= 3) board[row][col] = { color: "w", king: false };
      else if (rank >= 6) board[row][col] = { color: "b", king: false };
    }
  }
  return board;
}

function cloneCheckersBoard(board) {
  return board.map((row) => row.map((cell) => (cell ? { ...cell } : null)));
}

function inBounds(row, col) {
  return row >= 0 && row < 8 && col >= 0 && col < 8;
}

const DIAG_DIRS = [
  [-1, -1],
  [-1, 1],
  [1, -1],
  [1, 1],
];

// Все одиночные прыжки-взятия из клетки (row,col) для стоящей там фигуры.
// Для простой шашки — только соседняя клетка по диагонали в любом из 4
// направлений (в русских шашках бить можно и назад). Для дамки — любая
// дистанция: летит до первой фигуры на диагонали, и если это чужая, а
// сразу за ней есть свободные клетки — каждая из них отдельный вариант
// приземления.
function findJumpsFromSquare(board, row, col, piece) {
  const jumps = [];
  if (!piece.king) {
    for (const [dr, dc] of DIAG_DIRS) {
      const midR = row + dr;
      const midC = col + dc;
      const toR = row + 2 * dr;
      const toC = col + 2 * dc;
      if (!inBounds(toR, toC)) continue;
      const midCell = board[midR][midC];
      const toCell = board[toR][toC];
      if (midCell && midCell.color !== piece.color && !toCell) {
        jumps.push({ toR, toC, capR: midR, capC: midC });
      }
    }
    return jumps;
  }

  for (const [dr, dc] of DIAG_DIRS) {
    let step = 1;
    let capR = null;
    let capC = null;
    while (true) {
      const midR = row + dr * step;
      const midC = col + dc * step;
      if (!inBounds(midR, midC)) break;
      const midCell = board[midR][midC];
      if (!midCell) {
        step++;
        continue; // пусто — летим дальше в поисках фигуры
      }
      if (midCell.color === piece.color) break; // своя фигура блокирует направление
      capR = midR;
      capC = midC;
      let land = step + 1;
      while (true) {
        const landR = row + dr * land;
        const landC = col + dc * land;
        if (!inBounds(landR, landC)) break;
        if (board[landR][landC]) break; // за битой фигурой клетка занята — приземлиться нельзя
        jumps.push({ toR: landR, toC: landC, capR, capC });
        land++;
      }
      break; // вторую фигуру в этом же направлении бить нельзя без приземления между ними
    }
  }
  return jumps;
}

// Рекурсивно строит все полные цепочки взятий из клетки (row,col).
// Возвращает массив последовательностей, каждая — массив прыжков
// {toR,toC,capR,capC}; продолжает цепочку, пока с новой позиции есть
// ещё взятия (обязательное правило "бей, пока можешь").
function findCaptureSequences(board, row, col, piece) {
  const jumps = findJumpsFromSquare(board, row, col, piece);
  if (jumps.length === 0) return [[]];

  const sequences = [];
  for (const jump of jumps) {
    const nextBoard = cloneCheckersBoard(board);
    nextBoard[row][col] = null;
    nextBoard[jump.capR][jump.capC] = null;
    nextBoard[jump.toR][jump.toC] = { ...piece };
    const subSequences = findCaptureSequences(nextBoard, jump.toR, jump.toC, piece);
    for (const sub of subSequences) sequences.push([jump, ...sub]);
  }
  return sequences;
}

// Список ходов для стороны color на доске board. Если у ЛЮБОЙ её фигуры
// есть взятие — бить обязательно, и возвращаются только ходы-взятия
// (каждый — целая вынужденная цепочка прыжков) со всех фигур, у которых
// они есть. Иначе — обычные тихие ходы.
function generateCheckersMoves(board, color) {
  const captureMoves = [];
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const piece = board[row][col];
      if (!piece || piece.color !== color) continue;
      const sequences = findCaptureSequences(board, row, col, piece).filter((seq) => seq.length > 0);
      for (const seq of sequences) {
        captureMoves.push({
          fromR: row,
          fromC: col,
          isCapture: true,
          jumps: seq,
          toR: seq[seq.length - 1].toR,
          toC: seq[seq.length - 1].toC,
        });
      }
    }
  }
  if (captureMoves.length > 0) return captureMoves;

  const simpleMoves = [];
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const piece = board[row][col];
      if (!piece || piece.color !== color) continue;
      if (piece.king) {
        for (const [dr, dc] of DIAG_DIRS) {
          let step = 1;
          while (true) {
            const toR = row + dr * step;
            const toC = col + dc * step;
            if (!inBounds(toR, toC) || board[toR][toC]) break;
            simpleMoves.push({ fromR: row, fromC: col, toR, toC, isCapture: false });
            step++;
          }
        }
      } else {
        const forward = piece.color === "w" ? -1 : 1; // белые идут к 8-й горизонтали (row 0), чёрные — к 1-й (row 7)
        for (const dc of [-1, 1]) {
          const toR = row + forward;
          const toC = col + dc;
          if (inBounds(toR, toC) && !board[toR][toC]) {
            simpleMoves.push({ fromR: row, fromC: col, toR, toC, isCapture: false });
          }
        }
      }
    }
  }
  return simpleMoves;
}

function applyCheckersMove(board, move) {
  const newBoard = cloneCheckersBoard(board);
  const piece = newBoard[move.fromR][move.fromC];
  newBoard[move.fromR][move.fromC] = null;

  let curR = move.toR;
  let curC = move.toC;
  if (move.isCapture) {
    for (const jump of move.jumps) {
      newBoard[jump.capR][jump.capC] = null;
      curR = jump.toR;
      curC = jump.toC;
    }
  }

  if (!piece.king && ((piece.color === "w" && curR === 0) || (piece.color === "b" && curR === 7))) {
    piece.king = true;
  }
  newBoard[curR][curC] = piece;
  return newBoard;
}

function checkersHasAnyPiece(board, color) {
  return board.some((row) => row.some((cell) => cell && cell.color === color));
}

// null, если игра продолжается; иначе "w" или "b" — кто выиграл (у кого
// сейчас ход — colorToMove — тот проиграл, если у него нет ни фигур, ни
// ходов).
function checkCheckersWinner(board, colorToMove) {
  const other = colorToMove === "w" ? "b" : "w";
  if (!checkersHasAnyPiece(board, colorToMove)) return other;
  if (generateCheckersMoves(board, colorToMove).length === 0) return other;
  return null;
}

// ==== Простой движок для хода бота в шашках (материал + продвижение) ====
const CHECKERS_MAN_VALUE = 100;
const CHECKERS_KING_VALUE = 350;
const CHECKERS_MATE_SCORE = 100000;

function evaluateCheckersBoard(board) {
  let score = 0;
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const cell = board[row][col];
      if (!cell) continue;
      const sign = cell.color === "w" ? 1 : -1;
      if (cell.king) {
        score += sign * CHECKERS_KING_VALUE;
        continue;
      }
      // Бонус за продвижение к дамке — чем ближе к последней горизонтали,
      // тем ценнее простая шашка (у белых цель row 0, у чёрных row 7).
      const advancement = cell.color === "w" ? 7 - row : row;
      score += sign * (CHECKERS_MAN_VALUE + advancement * 6);
      // Небольшой бонус за центральные вертикали — меньше шансов попасть
      // под размен с края доски.
      const centerBonus = 4 - Math.abs(col - 3.5);
      score += sign * centerBonus;
    }
  }
  return score;
}

function minimaxCheckers(board, color, depth, alpha, beta) {
  const moves = generateCheckersMoves(board, color);
  if (moves.length === 0) {
    // Стороне color нечем/некуда ходить — она проиграла.
    return color === "w" ? -CHECKERS_MATE_SCORE - depth : CHECKERS_MATE_SCORE + depth;
  }
  if (depth === 0) return evaluateCheckersBoard(board);

  const maximizing = color === "w";
  let best = maximizing ? -Infinity : Infinity;
  const nextColor = color === "w" ? "b" : "w";
  for (const move of moves) {
    const nextBoard = applyCheckersMove(board, move);
    const score = minimaxCheckers(nextBoard, nextColor, depth - 1, alpha, beta);
    if (maximizing) {
      best = Math.max(best, score);
      alpha = Math.max(alpha, best);
    } else {
      best = Math.min(best, score);
      beta = Math.min(beta, best);
    }
    if (beta <= alpha) break;
  }
  return best;
}

function findBestCheckersMove(board, color) {
  const moves = generateCheckersMoves(board, color);
  if (moves.length === 0) return null;
  // Взятия длиннее двигаем в приоритете при равенстве оценки — эстетика,
  // не влияет на легальность (бить и так обязательно, если есть чем).
  moves.sort((a, b) => (b.jumps?.length || 0) - (a.jumps?.length || 0));

  let bestMove = moves[0];
  let bestScore = color === "w" ? -Infinity : Infinity;
  const nextColor = color === "w" ? "b" : "w";
  for (const move of moves) {
    const nextBoard = applyCheckersMove(board, move);
    const score = minimaxCheckers(nextBoard, nextColor, CHECKERS_SEARCH_DEPTH - 1, -Infinity, Infinity);
    if (color === "w" ? score > bestScore : score < bestScore) {
      bestScore = score;
      bestMove = move;
    }
  }
  return bestMove;
}

function startCheckersGame(chatId, userId, userColor, view, playerName) {
  const key = checkersMapKey(chatId, userId);
  const resolvedView = view || checkersGames.get(key)?.view || "ascii";
  // captured — как и в шахматах: captured.w — сколько/какие белые шашки
  // съедены (их съели чёрные), captured.b — наоборот. Элемент списка —
  // "man" (простая) или "king" (дамка).
  const state = {
    board: createInitialCheckersBoard(),
    turn: "w",
    userColor,
    view: resolvedView,
    playerName,
    captured: { w: [], b: [] },
  };
  checkersGames.set(key, state);
  saveCheckersGame(chatId, userId);
  return state;
}

// Из хода-взятия (move.jumps, см. generateCheckersMoves) достаёт, какие
// именно фигуры были съедены — смотрим на board ДО применения хода
// (applyCheckersMove уже убирает их с доски). Возвращает массив
// { color, king } — пусто, если ход не был взятием.
function collectCheckersCaptures(board, move) {
  if (!move.jumps) return [];
  return move.jumps.map((j) => {
    const cell = board[j.capR][j.capC];
    return { color: cell.color, king: cell.king };
  });
}

// Символы вида "картинками": простые — белый/чёрный кружок, дамки —
// латинские буквы в кружке. Геометрические фигуры и Enclosed Alphanumerics
// рендерятся как обычный узкий текст почти везде, но VS15 добавлен и сюда
// на всякий случай (см. подробный комментарий у UNICODE_WHITE в шахматах).
const CHECKERS_UNICODE = {
  wMan: withVS("○"),
  bMan: withVS("●"),
  wKing: withVS("Ⓦ"),
  bKing: withVS("Ⓑ"),
};

function checkersCellGlyph(cell, row, col, view) {
  if (!cell) return isDarkSquare(row, col) ? "." : " ";
  if (view === "unicode") {
    if (cell.king) return cell.color === "w" ? CHECKERS_UNICODE.wKing : CHECKERS_UNICODE.bKing;
    return cell.color === "w" ? CHECKERS_UNICODE.wMan : CHECKERS_UNICODE.bMan;
  }
  const letter = cell.color === "w" ? "w" : "b";
  return cell.king ? letter.toUpperCase() : letter;
}

// Строка съеденных шашек одного цвета в нужном виде — дамки вперёд, эстетика.
function checkersCapturedGlyphs(list, color, view) {
  if (list.length === 0) return "—";
  const sorted = [...list].sort((a, b) => (b === "king") - (a === "king"));
  if (view === "unicode") {
    const man = color === "w" ? CHECKERS_UNICODE.wMan : CHECKERS_UNICODE.bMan;
    const king = color === "w" ? CHECKERS_UNICODE.wKing : CHECKERS_UNICODE.bKing;
    return sorted.map((t) => (t === "king" ? king : man)).join("");
  }
  const letter = color === "w" ? "w" : "b";
  return sorted.map((t) => (t === "king" ? letter.toUpperCase() : letter)).join("");
}

// Строка счёта под доской, тот же принцип, что и у formatCapturedLine в шахматах.
function formatCheckersCapturedLine(captured, userColor, view) {
  if (!captured) return null;
  const oppColor = userColor === "w" ? "b" : "w";
  const yourLost = captured[userColor] || [];
  const myLost = captured[oppColor] || [];
  if (yourLost.length === 0 && myLost.length === 0) return null;
  const yourGlyphs = checkersCapturedGlyphs(yourLost, userColor, view);
  const myGlyphs = checkersCapturedGlyphs(myLost, oppColor, view);
  return `Съедено у тебя: ${yourGlyphs} (${yourLost.length}) | у меня: ${myGlyphs} (${myLost.length})`;
}

function formatCheckersBoard(board, userColor, view, playerName, captured) {
  const lines = ["  +------------------------+"];
  for (let row = 0; row < 8; row++) {
    const rank = 8 - row;
    const cells = board[row].map((cell, col) => checkersCellGlyph(cell, row, col, view));
    lines.push(`${rank} | ${cells.join("  ")} |`);
  }
  lines.push("  +------------------------+");
  lines.push("    a  b  c  d  e  f  g  h");
  const board_ = lines.join("\n");

  let caption;
  if (view === "unicode") {
    const you = userColor === "w" ? CHECKERS_UNICODE.wMan + CHECKERS_UNICODE.wKing : CHECKERS_UNICODE.bMan + CHECKERS_UNICODE.bKing;
    const me = userColor === "w" ? CHECKERS_UNICODE.bMan + CHECKERS_UNICODE.bKing : CHECKERS_UNICODE.wMan + CHECKERS_UNICODE.wKing;
    caption = `(${you} — твои, ${me} — мои; заглавная в кружке — дамка)`;
  } else {
    caption =
      userColor === "w"
        ? "(w/W — твои белые, b/B — мои чёрные; заглавная — дамка)"
        : "(b/B — твои чёрные, w/W — мои белые; заглавная — дамка)";
  }

  const capturedLine = formatCheckersCapturedLine(captured, userColor, view);
  const captionBlock = capturedLine ? `${caption}\n${capturedLine}` : caption;

  const header = playerName ? `Партия в шашки с ${playerName}:\n` : "";
  return header + "```\n" + board_ + "\n" + captionBlock + "\n```";
}

// Разбирает попытку хода вида "b6-c5" (тихий ход) или "b6:d4" /
// "b6xd4" / многоходовая цепочка взятий "b6:d4:f2". Ищет среди легальных
// ходов текущей стороны такой, что совпадают стартовая и финальная
// клетки (а если промежуточные клетки в тексте указаны — ещё и путь).
// Возвращает найденный ход (в исходном формате из generateCheckersMoves)
// либо null.
function tryApplyCheckersMove(board, color, rawText) {
  const text = normalizeMoveText(rawText);
  const tokens = text.split(/[\s,;]+/).filter(Boolean);
  const legalMoves = generateCheckersMoves(board, color);

  for (const token of tokens) {
    if (!CHECKERS_MOVE_REGEX.test(token)) continue;
    const squares = token.match(/[a-h][1-8]/gi);
    if (!squares || squares.length < 2) continue;

    const from = squareToRC(squares[0]);
    const to = squareToRC(squares[squares.length - 1]);
    const candidates = legalMoves.filter((m) => m.fromR === from.row && m.fromC === from.col && m.toR === to.row && m.toC === to.col);
    if (candidates.length === 0) continue;
    if (candidates.length === 1 || squares.length === 2) return candidates[0];

    // Несколько ходов дают ту же стартовую/финальную клетку (разные пути
    // взятия к одной и той же финальной клетке) — уточняем по указанным
    // в тексте промежуточным клеткам.
    const wanted = squares.slice(1, -1).map((sq) => squareToRC(sq));
    const exact = candidates.find((m) => {
      if (!m.jumps || m.jumps.length - 1 !== wanted.length) return false;
      return wanted.every((sq, i) => m.jumps[i].toR === sq.row && m.jumps[i].toC === sq.col);
    });
    if (exact) return exact;
    return candidates[0];
  }
  return null;
}

const CHECKERS_MOVE_SHAPE = /^[a-h][1-8][-:x][a-h][1-8]([-:x][a-h][1-8])*$/i;

function looksLikeCheckersMoveAttempt(rawText) {
  const tokens = normalizeMoveText(rawText).split(/[\s,;]+/).filter(Boolean);
  if (tokens.length === 0 || tokens.length > 3) return false;
  return tokens.every((t) => CHECKERS_MOVE_SHAPE.test(t));
}

const CHECKERS_START_PHRASES_WHITE = [
  "го, сыграем в шашки. Ты за белых, ходи первым — формат b6-c5, взятие b6:d4.",
  "давай в шашки. Бери белых, начинай: тихий ход через тире (b6-c5), взятие через двоеточие (b6:d4).",
];
const CHECKERS_START_PHRASES_BLACK = [
  "го, сыграем в шашки. Ты за чёрных, значит я белыми и хожу первым.",
  "давай в шашки. Бери чёрных — я тогда белыми, начинаю.",
];
const CHECKERS_WIN_PHRASES = ["всё, тебе больше нечем ходить — я выиграл", "готово, обыграл. Реванш будешь брать?"];
const CHECKERS_LOSE_PHRASES = ["хм, мне ходить нечем — забирай победу", "сдаюсь по правилам, ты выиграл эту партию"];
const CHECKERS_RESIGN_PHRASES = ["принято, партия в шашки окончена", "ладно, сдался — так сдался"];

// ==== Крокодил (объясни слово жестами/словами, чат угадывает) ====
// Состояние — на весь ЧАТ (не на пару с юзером, как шахматы/шашки): один
// раунд одновременно, ведущего видит только сам ведущий (слово шлётся
// через answerCallbackQuery({show_alert:true}) — Telegram показывает такой
// алерт ТОЛЬКО тому, кто нажал кнопку, даже в группе, независимо от того,
// что происходит в самом чате). Раунд стартует, когда кто-то жмёт кнопку
// "хочу быть ведущим"; после неё выбирает сложность слова, дальше уже сам
// придумывает, как объяснять — бот в объяснение не вмешивается, только
// сверяет обычные текстовые сообщения остальных со словом.
const KROKODIL_INTENT_REGEX = /крокодил/i;

// Словарь слов НЕ захардкожен в коде — при старте бот качает два открытых
// набора данных и сам строит из них список слов с уровнями сложности:
//   1) hermitdave/FrequencyWords (MIT) — ПОЛНЫЙ русский частотный список
//      (корпус субтитров, ~1.4 млн словоформ, а не урезанный топ-50к:
//      топ-50к почти целиком состоит из бытовой лексики, и туда физически
//      не попадают редкие/книжные слова вроде "трепанация" или "инквизитор" —
//      они просто недостаточно часто встречаются в субтитрах, на какой бы
//      позиции ни резать топ-50к. Полный список снимает это ограничение);
//   2) LussRus/Rus_words (существительные) — большой список форм русских
//      существительных, используем как фильтр "это вообще существительное",
//      чтобы не выхватывать из частотного списка глаголы/местоимения/наречия
//      (без него в топе частот сплошные "просто"/"знаю"/"почему" и т.п.).
// Пересечение двух списков даёт частотно-ранжированные существительные:
// чем чаще слово встречается в живой речи — тем оно "легче" для угадывания.
// Результат — ~20 тыс. слов вместо небольшого статичного списка, слова не
// повторяются, пока не пройден весь пул нужной сложности (см. pickKrokodilWord).
const KROKODIL_FREQ_URL =
  "https://raw.githubusercontent.com/hermitdave/FrequencyWords/master/content/2018/ru/ru_full.txt";
const KROKODIL_NOUNS_URL =
  "https://raw.githubusercontent.com/LussRus/Rus_words/master/UTF8/json/nouns/summary.json";
// Полный список весит ~29 МБ (против ~0.5 МБ у топ-50к) — на медленном
// хостинге качается дольше, поэтому таймаут увеличен.
const KROKODIL_DICT_TIMEOUT_MS = 45000;

// Служебные/местоименные/междометные слова — в частотном списке субтитров
// их и так почти не остаётся после фильтра по существительным (см. выше),
// но некоторые "существительные"-омонимы всё же проскакивают (например
// "врач" — существительное, а "просто"/"ладно" по ошибке попадают в базу
// существительных как отдельные словоформы) — отсекаем явно.
const KROKODIL_STOPWORDS = new Set(
  `я не что в и ты это на с он мы как вы да мне у нет меня так но
   все она же его к бы по только ее было вот от еще о из ему теперь
   когда даже ну вдруг ли если уже или ни быть был него до вас
   нибудь опять уж вам ведь там потом себя ничего ей может они тут
   где есть надо ней для тебя их чем была сам чтоб без будто чего
   раз тоже себе под будет тогда кто этот того потому этого какой
   совсем ним здесь этом один почти мой тем чтобы нее сейчас были
   куда зачем всех никогда можно при наконец два об другой хоть
   после над больше тот через эти нас про всего них какая много
   разве три эту моя впрочем хорошо свою этой перед иногда лучше
   чуть том нельзя такой им более всегда конечно всю между
   сэр мистер боже ладно тебе просто знаю всё почему очень могу
   спасибо нам нужно хочу знаешь думаю время должна должен нужна
   нужен пожалуйста хочешь сделать увидимся такое немного слишком
   возможно должны точно наверное правда хотя вообще именно
   короче блин типа сюда туда отсюда оттуда ага угу эй ого
   ой ах эх ух фу ба тсс алло привет пока пожалуй якобы вроде
   кажется значит итак словом однако причем притом также затем
   поэтому оттого отчего почём кой сколь коли ежели абы
   дабы либо иль аж авось буде вон вот те эва эвон энто`
    .trim()
    .split(/\s+/)
);

// Крошечный запасной словарь — только на случай, если при старте бота
// GitHub недоступен (сеть легла и т.п.) и скачать основной словарь не
// вышло. В обычной работе не используется — см. loadKrokodilDictionary.
const KROKODIL_FALLBACK_WORDS = {
  easy: ["кот", "стол", "окно", "мяч", "книга", "чашка", "машина", "дом", "часы", "телефон", "яблоко", "рыба", "птица", "ключ", "снег"],
  medium: ["врач", "светофор", "холодильник", "вулкан", "аквариум", "парашют", "компас", "глобус", "будильник", "барабан", "скрипка", "антенна", "лабиринт", "гейзер", "карнавал"],
  hard: ["трепанация", "инквизитор", "холокост", "маккартизм", "тетраэдр", "скарлатина", "гайморит", "шариат", "гидролокатор", "эмансипация", "кардиохирург", "языковед", "волюнтаризм", "сюзерен", "энциклика"],
};

// Текущий словарь — на старте это KROKODIL_FALLBACK_WORDS, после успешной
// загрузки (см. loadKrokodilDictionary, вызывается в startBot) заменяется
// на полноценный, скачанный из сети.
let krokodilDictionary = KROKODIL_FALLBACK_WORDS;

async function fetchTextWithTimeout(url) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), KROKODIL_DICT_TIMEOUT_MS);
  try {
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
    return await res.text();
  } finally {
    clearTimeout(timeoutId);
  }
}

// Качает оба источника, пересекает их и раскладывает по трём уровням
// сложности по позиции в частотном списке (чем ближе к началу — тем
// более обиходное слово). Вызывается один раз при старте бота; если
// что-то пошло не так — тихо остаётся на KROKODIL_FALLBACK_WORDS.
async function loadKrokodilDictionary() {
  try {
    const [freqText, nounsText] = await Promise.all([
      fetchTextWithTimeout(KROKODIL_FREQ_URL),
      fetchTextWithTimeout(KROKODIL_NOUNS_URL),
    ]);

    const nounsRaw = JSON.parse(nounsText);
    const nounSet = new Set();
    for (const w of nounsRaw) {
      // Только строчные — так отсеиваются имена собственные (Аббасиды и т.п.)
      if (typeof w === "string" && /^[а-яё]+$/.test(w)) nounSet.add(w);
    }

    const seen = new Set();
    const filtered = [];
    for (const line of freqText.split("\n")) {
      const word = line.trim().split(/\s+/)[0];
      if (!word) continue;
      if (!/^[а-яё]+$/.test(word)) continue;
      if (word.length < 4 || word.length > 15) continue;
      if (KROKODIL_STOPWORDS.has(word)) continue;
      if (!nounSet.has(word)) continue;
      if (/(.)\1{3,}/.test(word)) continue; // явные опечатки типа "ааааа"
      if (seen.has(word)) continue;
      seen.add(word);
      filtered.push(word);
    }

    if (filtered.length < 500) {
      throw new Error(`подозрительно мало слов после фильтрации: ${filtered.length}`);
    }

    // Границы подобраны вручную по выгрузке реального пересечения (полный
    // частотный список x существительные, ~21 тыс. слов на 2018/ru_full).
    // Порог "сложных" стоит на 6000, а не на 4000: слова из зоны 4000-6000
    // (например "десант", "тайга", "испуг") просто реже мелькают в
    // субтитрах, но по сути остаются совершенно обычными — жалоб на них
    // и позвало сдвинуть границу выше. Реальная сложность/специфичность
    // начинается ближе к 6000-й позиции ("лоботомия", "экзорцист",
    // "антисемитизм", "марксизм", "катарсис"). Зона 5000-6000 — буфер,
    // её сознательно пропускаем как промежуточную по качеству.
    // Размеры уровней держим примерно сопоставимыми (не в разы друг от
    // друга, как было изначально при 600/3400/10000):
    //  - 0..2000: топовая бытовая лексика ("день", "человек", "деньги");
    //  - 2000..5000: узнаваемые, но не самые частые слова ("десант",
    //    "тайга", "испуг", "миллиардер", "интерфейс");
    //  - 6000..8500: собственно редкая/книжная/специальная лексика
    //    ("холокост"(рядом), "лоботомия", "экзорцист", "скарлатина",
    //    "марксизм"). Дальше по списку (после ~9000-14000) в исходных
    //    данных начинаются диалектизмы и полумусорные словоформы (типа
    //    "гуммигут", "кинкажу"), непригодные для игры — не берём.
    krokodilDictionary = {
      easy: filtered.slice(0, 2000),
      medium: filtered.slice(2000, 5000),
      hard: filtered.slice(6000, 8500),
    };

    console.log(
      `Крокодил: словарь загружен — лёгких ${krokodilDictionary.easy.length}, ` +
        `средних ${krokodilDictionary.medium.length}, сложных ${krokodilDictionary.hard.length}`
    );
  } catch (err) {
    console.error("Крокодил: не удалось загрузить словарь из сети, остаюсь на встроенном запасном:", err.message);
  }
}

const KROKODIL_DIFFICULTY_LABEL = { easy: "лёгкие", medium: "средние", hard: "сложные" };

// chatId -> состояние раунда. status: "idle" (никто не ведёт) |
// "choosing" (кто-то нажал "хочу быть ведущим", выбирает сложность) |
// "active" (слово загадано, идёт раунд).
const krokodilGames = new Map();
// chatId -> Map<userId, {name, score}> — счёт копится между раундами и не
// сбрасывается при завершении конкретного раунда/игры.
const krokodilScores = new Map();

// Раунд считается "зависшим", если статус не idle (т.е. кто-то либо
// выбирает сложность, либо уже ведёт раунд), а с момента последнего
// перехода в этот статус (см. startedAt, выставляется в bot.on("callback_
// query:data") при "host"/"diff:") прошло больше этого времени — типичный
// случай: ведущий взял слово и вышел из чата/заблокировал бота. Проверяется
// централизованно в getKrokodilGame ниже, так что чинить нужно в одном
// месте: любое обращение к раунду (команда /krokodil, кнопки, проверка
// отгадки, естественный триггер "крокодил") сначала само его расчищает,
// если он завис — раунд просто тихо возвращается в "idle", а следующий
// желающий видит обычное приглашение "жми кнопку, чтобы стать ведущим".
// Для ручного сброса раньше таймаута — см. bot.command("krokodil_reset").
const KROKODIL_TIMEOUT_MS = 10 * 60 * 1000; // 10 минут без действий

function getKrokodilGame(chatId) {
  const game = krokodilGames.get(chatId) || null;
  if (game && game.status !== "idle" && game.startedAt && Date.now() - game.startedAt > KROKODIL_TIMEOUT_MS) {
    krokodilGames.set(chatId, { status: "idle", usedWords: game.usedWords || [] });
    saveKrokodilGame(chatId);
    return krokodilGames.get(chatId);
  }
  return game;
}

function getKrokodilScoreMap(chatId) {
  if (!krokodilScores.has(chatId)) krokodilScores.set(chatId, new Map());
  return krokodilScores.get(chatId);
}

async function saveKrokodilGame(chatId) {
  if (!redis) return;
  try {
    const game = krokodilGames.get(chatId);
    if (game) await redis.set(`krokodil:${chatId}`, game);
    else await redis.del(`krokodil:${chatId}`);
  } catch (err) {
    console.error(`Redis: не удалось сохранить раунд крокодила ${chatId}:`, err);
  }
}

async function saveKrokodilScores(chatId) {
  if (!redis) return;
  try {
    await redis.set(`krokodil_scores:${chatId}`, Object.fromEntries(getKrokodilScoreMap(chatId)));
  } catch (err) {
    console.error(`Redis: не удалось сохранить счёт крокодила ${chatId}:`, err);
  }
}

// Нормализация слова/токена для сравнения: нижний регистр, ё->е (частая
// вольность написания), без пунктуации. Совпадение — только точное
// (после нормализации): "работа" ≠ "работник" ≠ "робота".
function normalizeKrokodilToken(s) {
  return (s || "").toLowerCase().replace(/ё/g, "е");
}

function krokodilTokenMatches(token, secret) {
  const a = normalizeKrokodilToken(token);
  const b = normalizeKrokodilToken(secret);
  if (!a || !b) return false;
  return a === b;
}

// Выбирает случайное неиспользованное слово нужной сложности для этого
// чата; когда слова кончаются — список "использованных" очищается и
// начинается по новой (слова могут повторяться, но не раньше, чем весь
// список для этой сложности будет пройден).
function pickKrokodilWord(chatId, difficulty) {
  const pool = krokodilDictionary[difficulty] || krokodilDictionary.medium;
  const game = getKrokodilGame(chatId);
  let used = (game && Array.isArray(game.usedWords) ? game.usedWords : []).filter((w) => pool.includes(w));

  let available = pool.filter((w) => !used.includes(w));
  if (available.length === 0) {
    used = [];
    available = pool;
  }

  const word = available[Math.floor(Math.random() * available.length)];
  return { word, usedWords: [...used, word] };
}

function krokodilIdleKeyboard() {
  return new InlineKeyboard().text("🐊 Хочу быть ведущим", "krokodil:host");
}

function krokodilDifficultyKeyboard() {
  return new InlineKeyboard()
    .text("🟢 Легко", "krokodil:diff:easy")
    .text("🟡 Средне", "krokodil:diff:medium")
    .text("🔴 Сложно", "krokodil:diff:hard");
}

function krokodilActiveKeyboard() {
  return new InlineKeyboard()
    .text("👁 Показать слово", "krokodil:show")
    .text("🔄 Другое слово", "krokodil:reroll")
    .row()
    .text("🏳 Сдаюсь", "krokodil:giveup");
}

function krokodilPlayerLabel(user) {
  return user.username ? `@${user.username}` : user.first_name || "игрок";
}

// Топ игроков чата по очкам — используется и в отдельной команде, и в
// сообщении, которым бот объявляет старт нового ожидания ведущего.
function formatKrokodilLeaderboard(chatId) {
  const map = getKrokodilScoreMap(chatId);
  if (map.size === 0) return "пока никто не отгадал ни одного слова — очков нет";
  const rows = [...map.values()]
    .sort((a, b) => b.score - a.score)
    .slice(0, 10)
    .map((e, i) => `${i + 1}. ${e.name} — ${e.score}`);
  return "🏆 Таблица лидеров крокодила:\n" + rows.join("\n");
}

// ==== Анекдоты (готовая база, а не выдумки модели) ====
// Идея: LLM на просьбу "расскажи анекдот" почти всегда либо выдумывает
// несмешную белиберду, либо пересказывает один и тот же десяток баянов.
// Поэтому анекдот отвечаем НЕ через модель, а из готовой базы — она
// проверяется человеком заранее и у каждого анекдота есть rating
// (субъективная оценка смешности, 1-10 — насколько заходит средней
// аудитории). Берём только достаточно смешные (rating >= JOKE_MIN_RATING)
// и выбираем взвешенно — чем выше рейтинг, тем чаще анекдот попадается,
// но не только самый топовый, чтобы не приедалось.
const JOKES = [
  { text: "Программист прогуливается по зоопарку с ребёнком. Ребёнок:\n— Папа, купи мне это!\nПрограммист смотрит на ценник: null.\n— Не куплю, ты не определён.", rating: 8 },
  { text: "— Дорогой, купи хлеба, и если будут яйца — возьми десяток.\nМуж возвращается с десятью буханками хлеба.\n— Ты зачем столько хлеба купил?!\n— Так яйца же были!", rating: 9 },
  { text: "Штирлиц шёл по коридору. Слева от него шли двое, справа — двое.\n«Наверное, я тучный», — подумал Штирлиц.", rating: 7 },
  { text: "Разговаривают два программиста:\n— У меня сегодня баг три часа искал.\n— Нашёл?\n— Да, это была фича.", rating: 7 },
  { text: "— Вовочка, почему ты опоздал в школу?\n— Мама долго собиралась.\n— А при чём тут твоя мама?\n— Она меня в садик собирала.", rating: 8 },
  { text: "Заходит блондинка в зоомагазин:\n— У вас есть попугаи, которые уже умеют говорить?\n— Да, вот этот, например.\n— Отлично, беру! Заодно возьму того молчаливого — пусть его научит.", rating: 7 },
  { text: "— Официант, а почему в супе муха?\n— Училась плавать, доучится — и в бассейн переведём.", rating: 7 },
  { text: "Жена мужу:\n— Дорогой, признайся, ты меня любишь только за красоту?\n— Что ты, милая, ещё и за то, что готовишь плохо — это тоже характер закаляет.", rating: 6 },
  { text: "Приходит мужик к врачу:\n— Доктор, у меня будто внутри будильник — каждый час звенит.\n— Так это же прекрасно, вы что, жалуетесь?\n— Он звонит в 3 ночи, доктор!", rating: 6 },
  { text: "— Официант, у вас есть блюда для вегетарианцев?\n— Конечно! Салат из капусты и капуста из салата.", rating: 6 },
  { text: "Идёт экзамен по вождению.\n— Что вы будете делать, если увидите на дороге собаку и кошку?\n— Сначала кошку, потом собаку — они по очереди перебегают.", rating: 6 },
  { text: "На собеседовании:\n— Расскажите о своих слабых сторонах.\n— Честность.\n— Не думаю, что это слабая сторона.\n— А мне плевать, что вы думаете.", rating: 8 },
  { text: "Сын спрашивает отца:\n— Пап, а как рождаются дети?\n— Понимаешь, сынок, всё начинается с сервера…\n— Что за сервер?\n— Который постоянно падает, а обвиняют почему-то маму.", rating: 6 },
  { text: "— Что означает надпись на заводе «Не влезай — убьёт»?\n— Это чтобы ты влез, а он потом ещё и убил тебя за наглость.", rating: 5 },
  { text: "Программист приходит домой, а дома темно.\n— Хосе, ты дома?\nТишина.\n— Хосе, ты дома?\nТишина.\n— HOSE, ARE YOU HOME?\n— ДА КАКОЙ ХОСЕ, Я ДИМА, СВЕТ ВЫРУБИЛИ!", rating: 8 },
  { text: "Мужик приходит в аптеку:\n— У вас есть что-нибудь от головы?\n— От головы — гильотина, от боли в голове — вон там, второй ряд.", rating: 6 },
  { text: "— Как дела на работе?\n— Отлично, начальник сказал, что без меня как без рук.\n— Повысили?\n— Нет, руки связал и уволил.", rating: 7 },
  { text: "Мужик заходит в бар с крокодилом.\n— У вас продают алкоголиков?\nБармен, не моргнув глазом:\n— Нет, только напитки.\n— Жаль, а то мой крокодил проголодался.", rating: 6 },
  { text: "— Почему ты назвал собаку «Стек»?\n— Потому что она всё время лает последней командой.", rating: 6 },
  { text: "Разговор с техподдержкой:\n— У меня ничего не работает.\n— Вы пробовали выключить и включить?\n— Да, и жену тоже пробовал, не помогло.", rating: 5 },
  { text: "— Сколько нужно программистов, чтобы вкрутить лампочку?\n— Ни одного, это же аппаратная проблема.", rating: 7 },
  { text: "Заходит в лифт мужик с зеркалом. Лифт:\n— Осторожно, двери закрываются.\nМужик, глядя в зеркало:\n— Ну наконец-то хоть кто-то заметил.", rating: 6 },
  { text: "— Официант, долго мне ещё ждать заказ?\n— Как быстро вы готовы к разочарованию?", rating: 6 },
  { text: "Учитель спрашивает Вовочку:\n— Как называется тот, кто продолжает говорить, даже когда его никто не слушает?\n— Учитель.", rating: 8 },
  { text: "Летит самолёт, тишина в салоне. Пилот в громкую связь:\n— Приносим извинения за задержку, мы немного заблудились.\nПассажир соседу:\n— Хорошо хоть честно.", rating: 6 },
  { text: "— Как вы относитесь к критике?\n— Нормально, если она заканчивается на слове «молодец».", rating: 7 },
  { text: "Заходит таракан в бар и говорит:\n— Дайте мне того же, что и мужику вон в углу.\nБармен:\n— Хочешь, чтобы тебя тапком?", rating: 6 },
  { text: "— У тебя есть план на жизнь?\n— Да, план Б.\n— А план А?\n— Про него я и мечтал в школе.", rating: 6 },
  { text: "Мужик приходит домой поздно, жена спрашивает:\n— Где был?\n— С друзьями, обсуждали, как я тебя люблю.\n— И долго обсуждали?\n— Тема короткая, но повторяли часто.", rating: 6 },
  { text: "На собеседовании спрашивают:\n— Кем вы видите себя через пять лет?\n— На вашем месте.\n— А если серьёзно?\n— На вашем месте, но с вашей зарплатой уже сейчас.", rating: 7 },
];

const JOKE_MIN_RATING = 6; // ниже этого — не показываем, слишком "не заходит"

// Простая антиповторялка: последние выданные анекдоты в каждом чате (по
// индексу в JOKES), чтобы не прилетал один и тот же анекдот два раза
// подряд. Живёт только в памяти (не в Redis) — не критичное состояние,
// после рестарта просто начнёт по новой, это ок.
const recentJokes = new Map(); // chatId -> number[] (индексы недавно показанных)

function pickJoke(chatId) {
  const pool = JOKES.map((j, idx) => ({ ...j, idx })).filter((j) => j.rating >= JOKE_MIN_RATING);
  const recent = recentJokes.get(chatId) || [];
  // Не повторяем последние несколько анекдотов, пока есть из чего выбрать
  // помимо них; если пул почти исчерпан — снимаем ограничение.
  let candidates = pool.filter((j) => !recent.includes(j.idx));
  if (candidates.length === 0) candidates = pool;

  // Взвешенный случайный выбор: чем выше рейтинг — тем больше "веса" у
  // анекдота в розыгрыше (rating^2, чтобы разница ощущалась заметнее, но
  // без полного отсечения менее залайканных).
  const weights = candidates.map((j) => j.rating * j.rating);
  const totalWeight = weights.reduce((a, b) => a + b, 0);
  let r = Math.random() * totalWeight;
  let chosen = candidates[candidates.length - 1];
  for (let i = 0; i < candidates.length; i++) {
    r -= weights[i];
    if (r <= 0) {
      chosen = candidates[i];
      break;
    }
  }

  const updatedRecent = [chosen.idx, ...recent].slice(0, 5);
  recentJokes.set(chatId, updatedRecent);
  return chosen.text;
}

// Распознаёт просьбу рассказать анекдот. В группах это работает уже
// ПОСЛЕ обращения по имени (см. вызов ниже — на stripNameTrigger(rawText)),
// так что просто наличия слова "анекдот" достаточно: "Женя, анекдот" уже
// содержит явное обращение к боту, отдельный глагол-триггер не нужен.
function isJokeRequest(text) {
  return /анекдот/i.test(text);
}

// Живой источник анекдотов — rzhunemogu.ru отдаёт случайный анекдот без
// ключа и регистрации, но БЕЗ рейтинга смешности и без модерации (это
// сырой пользовательский контент — иногда несмешно, иногда грубовато).
// Поэтому используем его как "освежитель" поверх курируемой базы (JOKES
// выше), а не вместо неё: если сайт недоступен, ответил пусто/не тем
// форматом, или просто долго думает — тихо уходим на pickJoke() ниже,
// пользователь в любом случае получит анекдот, просто не "свежий".
const JOKE_API_URL = "http://rzhunemogu.ru/RandJSON.aspx?CType=1";
const JOKE_API_TIMEOUT_MS = 4000;

async function fetchLiveJoke() {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), JOKE_API_TIMEOUT_MS);
  try {
    const res = await fetch(JOKE_API_URL, { signal: controller.signal });
    if (!res.ok) return null;
    const buf = await res.arrayBuffer();
    // Сайт отдаёт текст в кодировке CP1251, а не UTF-8.
    let text;
    try {
      text = new TextDecoder("windows-1251").decode(buf);
    } catch {
      text = Buffer.from(buf).toString("utf8"); // на случай, если движок не знает windows-1251
    }

    // Ответ сайта — технически не всегда валидный JSON (бывают
    // неэкранированные переносы строк внутри значения content), поэтому
    // сначала пробуем честный JSON.parse, а если он упал — вытаскиваем
    // content вручную по границам кавычек.
    let content = null;
    try {
      content = JSON.parse(text)?.content ?? null;
    } catch {
      const m = text.match(/"content"\s*:\s*"([\s\S]*)"\s*}\s*$/);
      if (m) content = m[1];
    }
    if (!content) return null;

    content = content.replace(/\\r\\n|\\n|\\r/g, "\n").trim();
    // Совсем короткий/пустой ответ — не похоже на нормальный анекдот,
    // лучше фолбэкнуться на курируемую базу, чем прислать мусор.
    if (content.length < 10) return null;
    return content;
  } catch (err) {
    console.error("rzhunemogu: не удалось получить анекдот:", err.message);
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

// Единая точка получения анекдота для ответа пользователю: сначала пробуем
// живой источник, при любой неудаче — гарантированный фолбэк на
// курируемую базу (см. pickJoke). Пользователь никогда не остаётся без
// ответа из-за упавшего внешнего сайта.
async function getJoke(chatId) {
  const live = await fetchLiveJoke();
  return live || pickJoke(chatId);
}

// ==== Фолбэк между провайдерами/моделями ====
// Индекс цели (провайдер+модель), на которой бот последний раз успешно
// ответил — начинаем с неё же, чтобы не долбить мёртвую цель на каждый запрос.
let activeTargetIndex = 0;

async function saveActiveTargetIndex() {
  if (!redis) return;
  try {
    await redis.set("activeTargetIndex", activeTargetIndex);
  } catch (err) {
    console.error("Redis: не удалось сохранить activeTargetIndex:", err);
  }
}

// pinnedTargetIndex — модель, вручную закреплённая владельцем через кнопки
// в /model (см. bot.command("model") и callback_query ниже). Если задана —
// askLLM пробует её первой (при условии что она не в cooldown), иначе
// ведёт себя как раньше (обычный фолбэк). null — авто-режим.
let pinnedTargetIndex = null;

async function savePinnedTargetIndex() {
  if (!redis) return;
  try {
    // Upstash не любит хранить null как значение — используем -1 как "нет".
    await redis.set("pinnedTargetIndex", pinnedTargetIndex === null ? -1 : pinnedTargetIndex);
  } catch (err) {
    console.error("Redis: не удалось сохранить pinnedTargetIndex:", err);
  }
}

// Ошибки, при которых имеет смысл пробовать следующую цель:
// модель/провайдер недоступны, лимиты исчерпаны и т.п.
function isFallbackWorthy(status) {
  // 413 добавлен отдельно: Groq возвращает его, когда история чата вместе
  // с системным промптом превышает TPM-лимит конкретной модели (напр.
  // 8000 TPM у gpt-oss-120b/qwen3.6-27b на free tier) — это не "сообщение
  // пользователя слишком длинное", а исчерпание лимита именно ЭТОЙ модели,
  // так что имеет смысл пробовать следующую по списку, а не сразу сдаваться.
  return [400, 401, 403, 404, 413, 422, 429, 500, 502, 503, 504].includes(status);
}

// Порядок попыток для одного запроса: НЕ с начала списка TARGETS, а от
// activeTargetIndex (той цели, что ответила последней) вперёд по кругу —
// чтобы держаться уже рабочей модели и не откатываться на более ранние
// по списку цели (в т.ч. только что объявленные мёртвыми) на каждый новый
// запрос. Раньше сортировка шла по исходному индексу в TARGETS, из-за чего
// бот каждый новый запрос заново стучался в начало списка, а не продолжал
// с той цели, что реально сработала — отсюда и петля повторных таймаутов
// на уже недоступных моделях.
// Цели в cooldown всё равно уходят в конец (чтобы не ждать таймаут на
// заведомо мёртвой), но порядок ВНУТРИ каждой группы (не в cooldown / в
// cooldown) — это порядок ротации от activeTargetIndex, а не исходный
// индекс. Только когда буквально все цели в cooldown, порядок опять же
// идёт по кругу от activeTargetIndex — то есть "возврат к началу" происходит
// сам по себе, только когда действительно не осталось рабочих вариантов.
function computeTargetOrder() {
  const now = Date.now();
  const n = TARGETS.length;
  const rotationPos = (idx) => (idx - activeTargetIndex + n) % n;

  // Если сейчас активен ручной пин (и он не в cooldown) — фолбэк ПОСЛЕ его
  // провала должен идти по естественному порядку TARGETS (как задано в
  // GEMINI_MODEL/PROVIDER_ORDER, т.е. по убыванию качества: 3.7 → 3.6 →
  // 3.5 → 3.5-lite → groq → ...), а НЕ по ротации от activeTargetIndex.
  // Раньше тут всегда работала ротация — из-за этого при ручном
  // тестировании через /model бот после провала пина "прыгал" не на
  // следующую по качеству модель, а на ту, что последний раз случайно
  // ответила (activeTargetIndex), даже если она была в конце списка и
  // где-то между ней и пином оставались вполне живые модели получше.
  // В обычном авто-режиме (без пина) ротация от activeTargetIndex
  // сохраняется как раньше — там она осмысленна: не скакать между
  // моделями зря, а держаться уже рабочей.
  const usePin = pinnedTargetIndex !== null && cooldownUntil[pinnedTargetIndex] <= now;

  let order = [...TARGETS.keys()].sort((a, b) => {
    const aCold = cooldownUntil[a] > now ? 1 : 0;
    const bCold = cooldownUntil[b] > now ? 1 : 0;
    if (aCold !== bCold) return aCold - bCold;
    return usePin ? a - b : rotationPos(a) - rotationPos(b);
  });

  // Ручной пин через /model — пробуем первой (если не в cooldown), поверх
  // естественного порядка.
  if (usePin) {
    order = [pinnedTargetIndex, ...order.filter((idx) => idx !== pinnedTargetIndex)];
  }

  return order;
}

// Группирует order на подряд идущие блоки одной и той же модели (напр. все
// аккаунты gemini-3.7-flash подряд) — TARGETS строится так, что аккаунты
// одной модели изначально соседние, и сортировка в computeTargetOrder
// (cooldown-цели в конец) эту соседность не ломает внутри одной группы
// cooldown/не-cooldown. Каждая такая группа — кандидат на гонку вместо
// последовательного перебора.
function groupConsecutiveTargets(order) {
  const groups = [];
  for (const idx of order) {
    const t = TARGETS[idx];
    const last = groups[groups.length - 1];
    if (last && TARGETS[last[0]].provider === t.provider && TARGETS[last[0]].model === t.model) {
      last.push(idx);
    } else {
      groups.push([idx]);
    }
  }
  return groups;
}

// Гонка нескольких аккаунтов ОДНОЙ модели (см. GEMINI_RACE_STAGGER_MS выше).
// indices — все аккаунты этой модели из текущей группы (могут включать и те,
// что в cooldown, — их просто пропускаем). Возвращает { idx, reply,
// actualModel, systemFingerprint } от первого успешного аккаунта.
async function raceTargetGroup(indices, messagesForTarget, timeoutMs, temperature) {
  const now = Date.now();
  const available = indices.filter((idx) => cooldownUntil[idx] <= now);
  if (available.length === 0) {
    const err = new Error("Все аккаунты этой модели сейчас в cooldown");
    err.status = 503;
    throw err;
  }

  return new Promise((resolve, reject) => {
    const controller = new AbortController();
    const timers = [];
    let settled = false;
    let launched = 0;
    let pending = 0;
    let lastErr = null;

    function finishSuccess(idx, result) {
      if (settled) return;
      settled = true;
      controller.abort(); // отменяем всех остальных гонщиков этой модели
      timers.forEach(clearTimeout);
      cooldownUntil[idx] = 0;
      resolve({ idx, ...result });
    }

    function finishFailureIfDone() {
      if (settled) return;
      if (pending === 0 && launched >= available.length) {
        settled = true;
        timers.forEach(clearTimeout);
        reject(lastErr ?? new Error("Все аккаунты этой модели не ответили"));
      }
    }

    function launchNext() {
      if (settled || launched >= available.length) return;
      const idx = available[launched++];
      pending++;
      const target = TARGETS[idx];

      callTarget(target, messagesForTarget(target), timeoutMs, temperature, controller.signal)
        .then((result) => {
          pending--;
          finishSuccess(idx, result);
        })
        .catch((err) => {
          pending--;
          if (!err.raceCancelled) {
            lastErr = err;
            console.error(`Ошибка [${targetLabel(target)}] (гонка):`, err.status ?? "-", err.body ?? err.message);
            if (err.status && isFallbackWorthy(err.status)) {
              cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
            }
          }
          finishFailureIfDone();
        });

      if (launched < available.length) {
        timers.push(setTimeout(launchNext, GEMINI_RACE_STAGGER_MS));
      }
    }

    launchNext();
  });
}

// Страховка от бага некоторых reasoning-моделей (замечено у gpt-oss на Groq):
// вместо одного финального ответа модель иногда присылает черновик вида
// `"Привет!" or "Привет, чё как?"` — несколько вариантов реплики в кавычках
// через "or"/"или". Промпт это запрещает, но на случай если модель всё же
// так ответит — распознаём паттерн и берём только первый вариант.
function stripDraftVariants(text) {
  const parts = text.split(/\s+(?:or|или)\s+/i);
  if (parts.length < 2) return text;

  // Срабатываем только если КАЖДАЯ часть выглядит как реплика в кавычках —
  // иначе можно случайно обрезать обычную фразу со словом "или".
  const looksQuoted = (p) => /^["'«][\s\S]*["'»][.,!?)]*$/.test(p.trim());
  if (!parts.every(looksQuoted)) return text;

  const first = parts[0]
    .trim()
    .replace(/^["'«]+/, "")
    .replace(/["'»]+[.,!?)]*$/, "")
    .trim();

  return first || text;
}

// Страховка от утечки рассуждений: иногда вместо ответа модель (замечено
// у Gemini) присылает что-то вроде самопроверки по инструкциям —
// "только на русском (Yes) * без markdown (Yes)" — вместо реального текста.
// Если увидели характерный паттерн "(Yes)"/"(No)"/"(да)"/"(нет)" несколько
// раз подряд — считаем ответ невалидным, чтобы дальше в askLLM сработал
// фолбэк на следующую модель, а не улетело это в чат.
function looksLikeReasoningLeak(text) {
  const yesNoCount = (text.match(/\((?:yes|no|да|нет)\)/gi) || []).length;
  return yesNoCount >= 2;
}

// Страховка от протёкших CJK-иероглифов посреди русского текста —
// замечено у qwen3.6-27b на Groq (китайская модель, огромная доля
// китайских данных в обучении, периодически "проливает" случайный
// китайский/японский/корейский токен в несвязанный контекст, особенно
// при урезанном reasoning). У Gemini/gpt-oss такое не характерно (не
// китайские модели), но раз персонаж Женя в принципе говорит только на
// русском — чистим безусловно для всех моделей, не только для Groq/qwen.
//
// ВАЖНО: резать ВСЕ иероглифы подряд нельзя — если человек спросит
// что-то с легитимным CJK (название на китайском/японском, конкретный
// иероглиф и его значение и т.п.), модель имеет право процитировать его
// в ответе, и молча вырезать это — сломать ответ незаметно для себя.
// Реальная утечка токена отличается от осмысленного упоминания одним
// признаком: она ПРИКЛЕЕНА вплотную к русскому/латинскому слову без
// пробела (см. реальный пример: "раз器械 нет" — иероглифы прямо внутри
// слова), тогда как осмысленное упоминание почти всегда стоит отдельным
// "словом", окружённым пробелами/пунктуацией ("название 成龙", "иероглиф
// 龍"). Поэтому режем только те CJK-последовательности, что вплотную
// (без пробела) примыкают к букве/цифре с любой стороны — это и есть
// сигнатура утечки, а изолированные оставляем как есть.
function stripCJKLeak(text) {
  const CJK_RUN = /[\u4e00-\u9fff\u3040-\u30ff\u30a0-\u30ff\uac00-\ud7af]+/g;
  const isWordChar = (ch) => ch !== undefined && /[a-zA-Zа-яёА-ЯЁ0-9]/.test(ch);

  let result = "";
  let lastIndex = 0;
  for (const match of text.matchAll(CJK_RUN)) {
    const start = match.index;
    const end = start + match[0].length;
    const gluedToWord = isWordChar(text[start - 1]) || isWordChar(text[end]);

    result += text.slice(lastIndex, start);
    if (!gluedToWord) result += match[0]; // изолированное — вероятно осмысленное, оставляем
    lastIndex = end;
  }
  result += text.slice(lastIndex);

  const cleaned = result.replace(/[ \t]{2,}/g, " ").trim();
  return cleaned || text; // на всякий случай не отдаём пустую строку, если вдруг вычистили всё
}

async function callTarget(target, messages, timeoutMs = REQUEST_TIMEOUT_MS, temperature = 0.9, externalSignal = null) {
  const body = {
    model: target.model,
    messages,
    temperature,
    // gemini-2.5-flash (единственная линейка, где Google даёт thinking_budget=0
    // по-настоящему) снята с доступа — остался gemini-flash-latest/3.5-flash,
    // а там размышления нельзя выключить до нуля вообще никакими флагами.
    // Единственный рычаг, который реально работает — щедрый общий бюджет,
    // чтобы после того, что модель потратит на размышления, оставалось
    // достаточно на сам видимый ответ.
    max_tokens: 3000,
  };

  // Groq поддерживает reasoning_format/reasoning_effort ТОЛЬКО у
  // reasoning-моделей (qwen3, gpt-oss) — обычные модели вроде
  // llama-3.3-70b-versatile вообще не понимают это поле и падают с 400
  // "reasoning_format is not supported with this model". Раньше поле
  // слалось всем моделям на Groq без разбора — теперь только тем, что
  // реально его поддерживают.
  if (target.provider === "groq" && (target.model.includes("gpt-oss") || target.model.includes("qwen"))) {
    body.reasoning_format = "hidden";

    // У gpt-oss на Groq reasoning_effort реально снижает объём размышлений
    // (в отличие от Gemini 3, где это не гарантировано) — оставляем как
    // основной способ сэкономить бюджет для этого провайдера.
    if (target.model.includes("gpt-oss")) {
      body.reasoning_effort = "low";
    } else {
      body.reasoning_effort = "none";
    }
  }

  // Для Gemini reasoning_effort — единственное задокументированное и реально
  // принимаемое API поле для управления размышлениями (проверено curl-примером
  // Google). Поле "google.thinking_config" через голый JSON API не принимает
  // (упало с 400 Unknown name "google") — убрано. Полагаемся на max_tokens.
  if (target.provider === "gemini") {
    body.reasoning_effort = "low";
  }

  // Таймаут на весь запрос целиком: если провайдер завис и не отвечает
  // вообще (не дал ни 200, ни ошибку) — раньше это вешало ответ
  // пользователю на минуты вперёд. Через timeoutMs обрываем запрос и
  // уходим на фолбэк, как при обычной ошибке.
  // ВАЖНО: раньше clearTimeout вызывался сразу после await fetch(...), то
  // есть таймер разоружался, как только приходили заголовки ответа — но
  // fetch() резолвится по заголовкам, а не по полному телу. Для медленных
  // ответов с телом, которое досылается ещё долго после заголовков (как
  // раз кейс поиска: реального веб-поиска ещё может не быть в момент
  // заголовков) — таймаут просто не срабатывал, и запрос мог висеть
  // намного дольше timeoutMs. Теперь таймер держим до тех пор, пока не
  // прочитано и распарсено тело ответа целиком.
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  // externalSignal — для гонки нескольких аккаунтов одной модели (см.
  // raceGeminiAccounts): если параллельный "гонщик" уже победил, снаружи
  // дёргают abort() на этом сигнале, и текущий запрос обрывается ДО
  // timeoutMs, а не ждёт его целиком.
  let onExternalAbort = null;
  if (externalSignal) {
    if (externalSignal.aborted) controller.abort();
    else {
      onExternalAbort = () => controller.abort();
      externalSignal.addEventListener("abort", onExternalAbort);
    }
  }

  let res, data;
  try {
    res = await fetch(target.baseUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${target.apiKey}`,
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });

    if (!res.ok) {
      const errText = await res.text();
      const err = new Error(`${target.provider} API вернул ${res.status}`);
      err.status = res.status;
      err.body = errText;
      throw err;
    }

    data = await res.json();
  } catch (err) {
    if (err.name === "AbortError") {
      // Отменён гонкой (другой аккаунт уже ответил первым) — это НЕ
      // реальный таймаут провайдера, помечаем отдельно, чтобы вызывающий
      // код не логировал это как ошибку и не ставил cooldown этому аккаунту.
      if (externalSignal && externalSignal.aborted) {
        const cancelledErr = new Error(`${targetLabel(target)} отменён — гонку выиграл другой аккаунт`);
        cancelledErr.raceCancelled = true;
        throw cancelledErr;
      }
      const timeoutErr = new Error(
        `${targetLabel(target)} не ответил за ${timeoutMs}мс — таймаут`
      );
      timeoutErr.status = 504;
      throw timeoutErr;
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
    if (externalSignal && onExternalAbort) externalSignal.removeEventListener("abort", onExternalAbort);
  }

  const choice = data.choices?.[0];
  let reply = choice?.message?.content?.trim();
  if (!reply) throw new Error(`Пустой ответ от ${target.provider}`);

  // data.model — это то, что РЕАЛЬНО ответило (важно для роутеров вроде
  // HF/OpenRouter, которые под капотом динамически выбирают бэкенд —
  // может отличаться от target.model, который мы запросили).
  // system_fingerprint иногда содержит доп. инфо о бэкенде/версии.
  const actualModel = data.model || null;
  const systemFingerprint = data.system_fingerprint || null;

  // Если ответ обрезан по лимиту токенов — не отдаём пользователю огрызок
  // фразы, а считаем это ошибкой цели: сработает фолбэк на следующую
  // модель в TARGETS (см. askLLM). Само событие видно в логах Render.
  if (choice?.finish_reason === "length") {
    console.warn(
      `[callTarget] ${targetLabel(target)}: ответ обрезан по finish_reason=length, ухожу на фолбэк ("${reply}")`
    );
    const err = new Error(`${target.provider} обрезал ответ по длине`);
    err.status = 500; // считается фолбэк-достойной (см. isFallbackWorthy)
    throw err;
  }

  // Страховка: если какая-то модель всё же прислала рассуждения внутри
  // <think>...</think> (были баги с этим у reasoning-моделей), — вырезаем,
  // чтобы в чат не улетал внутренний монолог модели.
  reply = reply.replace(/<think>[\s\S]*?<\/think>/gi, "").trim();
  if (!reply) throw new Error(`Пустой ответ от ${target.provider} после очистки <think>`);

  reply = stripCJKLeak(reply);
  if (!reply) throw new Error(`Пустой ответ от ${target.provider} после очистки CJK-мусора`);

  reply = stripDraftVariants(reply);
  if (!reply) throw new Error(`Пустой ответ от ${target.provider} после очистки вариантов`);

  if (looksLikeReasoningLeak(reply)) {
    console.warn(`[callTarget] ${targetLabel(target)}: похоже на утечку рассуждений вместо ответа: "${reply}"`);
    throw new Error(`${target.provider} прислал утечку рассуждений вместо ответа`);
  }

  return { reply, actualModel, systemFingerprint };
}

// Триггер для подключения BOT_SKILLS_PROMPT (см. skills.js). Раньше этот
// блок (~28 КБ текста) подмешивался в системный промпт КАЖДОГО сообщения
// в чате, хотя реально нужен только когда человек спрашивает про сам
// функционал бота — "что ты умеешь", "как сделать чтобы ты...", "как
// этим пользоваться" и т.п. Для подавляющего большинства обычных реплик
// это чистый балласт: лишние токены на каждый запрос (TPM-лимиты Groq и
// объём контекста на Gemini), без всякой пользы для ответа. Подключаем
// блок только при совпадении с этим паттерном — сознательно с запасом
// (лучше иногда подключить зря, чем не подключить, когда реально нужно).
// ВАЖНО: \w в JS-регекспах без /u матчит только ASCII, кириллицу НЕ ловит —
// поэтому ниже везде конкретные окончания или \S* вместо \w*.
const SKILLS_PROMPT_TRIGGER_REGEX = new RegExp(
  [
    "умеешь",
    "умеет\\s*ли",
    "можешь\\s*ли",
    "ты\\s*(?:вообще\\s*)?можешь",
    "способн\\S*\\s*ли",
    "что\\s*за\\s*бот",
    "как(?:ие|ой|ая)?\\s*у\\s*тебя\\s*функци",
    "тво\\S+\\s*функци",
    "тво\\S+\\s*возможност",
    "как\\s*(?:мне\\s*)?(?:тебя\\s*|этим\\s*)?(?:сделать|пользоваться|воспользоваться|играть|начать\\s*играть|запустить|включить|активировать|вызвать|начать)",
  ].join("|"),
  "i"
);

function shouldIncludeSkillsPrompt(userText) {
  return SKILLS_PROMPT_TRIGGER_REGEX.test(userText);
}

// ==== Текущие дата и время для промпта ====
// Модели (Gemini/Groq) периодически путают текущий год с годом среза своих
// обучающих данных (типичный симптом — на вопрос "какой сейчас год"
// отвечают позапрошлым). Явно передаём реальные дату/время ЖИВЫМ текстом
// при КАЖДОМ обращении к LLM (а не один раз при старте процесса в
// константу) — иначе после недель аптайма бота на Render/serv00 дата в
// промпте сама начала бы врать. Часовой пояс — Украина (Женя "живёт" там
// по легенде, см. SYSTEM_PROMPT выше).
const BOT_TIMEZONE = "Europe/Kyiv";

function formatFullDateTime(date = new Date()) {
  return new Intl.DateTimeFormat("ru-RU", {
    timeZone: BOT_TIMEZONE,
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

// Короткий формат для меток внутри истории диалога (см. pushHistory) —
// "29.08 14:32", без года и дня недели, чтобы не раздувать промпт на
// каждое сообщение истории.
function formatShortDateTime(date = new Date()) {
  return new Intl.DateTimeFormat("ru-RU", {
    timeZone: BOT_TIMEZONE,
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

// Подмешивается в системный промпт каждого обращения к LLM, где важно,
// чтобы модель отвечала "как Женя" (обычный чат, гороскопы, Таро) —
// см. места вызова ниже.
function buildDateTimeBlock() {
  return `\n\nСправка: сейчас реальные дата и время — ${formatFullDateTime()} (${BOT_TIMEZONE}). Если твои внутренние представления о текущем годе или дате устарели (модель могла быть обучена раньше и по умолчанию "думать", что сейчас другой год) — доверяй этой строке, а не своим ощущениям.`;
}

// ==== Запрос к LLM с фолбэком по провайдерам и моделям ====
async function askLLM(chatId, userText, timeoutMs = REQUEST_TIMEOUT_MS) {
  const history = getHistory(chatId);

  // BOT_SKILLS_PROMPT — только когда похоже, что реально спрашивают про
  // функционал (см. SKILLS_PROMPT_TRIGGER_REGEX выше). buildMemoryPromptBlock —
  // пункты, которые явно попросили запомнить именно в этом чате командой
  // "запомни: ..." (см. память чата выше); пустая строка, если ничего не
  // запоминали — SYSTEM_PROMPT/промпт не меняется.
  const skillsBlock = shouldIncludeSkillsPrompt(userText) ? "\n\n" + BOT_SKILLS_PROMPT : "";

  const messages = [
    { role: "system", content: SYSTEM_PROMPT + buildMemoryPromptBlock(chatId) + skillsBlock + buildDateTimeBlock() },
    ...history,
    { role: "user", content: userText },
  ];

  // Урезанный вариант ТОЛЬКО для Groq: даже без BOT_SKILLS_PROMPT полный
  // контекст (SYSTEM_PROMPT + память чата + вся HISTORY_LIMIT) стабильно
  // превышает 8000 TPM free tier у gpt-oss-120b/qwen на Groq (см.
  // isFallbackWorthy выше) — это структурный потолок конкретно этих
  // моделей, а не что-то лечащееся точечно. Резать HISTORY_LIMIT глобально
  // ради этого не вариант — это ударит по памяти диалога в основном
  // провайдере (Gemini), а Groq и так дёргается только как редкий
  // аварийный фолбэк. Вместо обрезки истории — используем компактный
  // GROQ_SYSTEM_PROMPT (см. выше) вместо полного SYSTEM_PROMPT: он и
  // держит основной вес контекста, так что урезав именно его, можно
  // позволить себе больше истории (6 записей — 3 обмена), а не 1-2.
  // Gemini и другие провайдеры это не видят вообще, получают messages
  // с полным SYSTEM_PROMPT и всей HISTORY_LIMIT как обычно.
  const groqMessages = [
    { role: "system", content: GROQ_SYSTEM_PROMPT + buildDateTimeBlock() },
    ...history.slice(-6),
    { role: "user", content: userText },
  ];

  const messagesForTarget = (target) => (target.provider === "groq" ? groqMessages : messages);

  let lastErr;

  const order = computeTargetOrder();
  // Группируем по модели: несколько аккаунтов одной модели (напр. 5 ключей
  // gemini-3.7-flash) пробуем гонкой (см. raceTargetGroup) вместо строгой
  // очереди — так не ждём timeoutMs на каждом по очереди, если модель
  // объективно не в духе у Google. Группа из одного аккаунта (или другой
  // провайдер) ведёт себя ровно как раньше — просто один вызов callTarget.
  const groups = groupConsecutiveTargets(order);

  for (const groupIndices of groups) {
    const isRace = groupIndices.length > 1;

    try {
      const { idx, reply: rawReply, actualModel, systemFingerprint } = isRace
        ? await raceTargetGroup(groupIndices, messagesForTarget, timeoutMs, 0.9)
        : { idx: groupIndices[0], ...(await callTarget(TARGETS[groupIndices[0]], messagesForTarget(TARGETS[groupIndices[0]]), timeoutMs)) };

      const target = TARGETS[idx];

      // ВРЕМЕННЫЙ DEBUG-ЛОГ — убрать после проверки тегов [sticker: ...].
      // Показывает сырой ответ модели ДО вырезания тега, чтобы понять,
      // ставит ли модель тег вообще, и если ставит — с правильным ли ключом.
      // actualModel/systemFingerprint — то, что реально ответило по данным
      // самого API (важно для роутеров HF/OpenRouter: реальный бэкенд может
      // отличаться от target.model, который мы запросили).
      console.log(
        `[DEBUG rawReply от ${targetLabel(target)}${isRace ? " (выиграл гонку)" : ""}` +
          (actualModel && actualModel !== target.model ? ` → фактически ответил: ${actualModel}` : "") +
          (systemFingerprint ? ` | fingerprint: ${systemFingerprint}` : "") +
          `]:`,
        JSON.stringify(rawReply)
      );

      const { text: reply, stickerKey } = extractSticker(rawReply);

      cooldownUntil[idx] = 0; // на успехе снимаем cooldown, если он был
      if (idx !== activeTargetIndex) {
        console.warn(`Переключился на "${targetLabel(target)}" (индекс ${idx})`);
        activeTargetIndex = idx;
        saveActiveTargetIndex();
      }

      // В историю кладём чистый текст без тега — модели не нужно видеть
      // свой же служебный тег в контексте будущих сообщений.
      pushHistory(chatId, "user", userText);
      pushHistory(chatId, "assistant", reply);

      return { text: reply, stickerKey };
    } catch (err) {
      lastErr = err;

      if (isRace) {
        // raceTargetGroup уже залогировал ошибки каждого гонщика и
        // расставил cooldown там, где нужно — здесь просто решаем, идти ли
        // дальше по фолбэку.
        console.error(`Группа [${targetLabel(TARGETS[groupIndices[0]])} × ${groupIndices.length}] вся не ответила:`, err.status ?? "-", err.message);
        if (err.status && !isFallbackWorthy(err.status)) break;
        continue;
      }

      const idx = groupIndices[0];
      const target = TARGETS[idx];
      console.error(
        `Ошибка [${targetLabel(target)}]:`,
        err.status ?? "-",
        err.body ?? err.message
      );

      // Без статуса — сетевая ошибка/таймаут (см. AbortError в callTarget,
      // тому уже проставлен status=504, так что сюда попадают только совсем
      // неожиданные исключения) — тоже считаем фолбэк-достойной.
      if (err.status && !isFallbackWorthy(err.status)) break;

      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }

  throw lastErr ?? new Error("Все провайдеры и модели недоступны");
}

// ==== Фоновое извлечение фактов для досье (см. "Досье на участников чата") ====
// Узкий системный промпт под конкретную задачу — НЕ полный SYSTEM_PROMPT
// с личностью Жени (там 30+ тысяч символов), поэтому даже дешёвые Groq-
// модели с маленьким TPM это спокойно тянут на каждое сообщение.
const PROFILE_EXTRACT_SYSTEM_PROMPT = `Ты — фоновый анализатор сообщений в Telegram-чате. Тебе дают список уже известных боту людей в чате и одно новое сообщение. Задача — вытащить из сообщения ЛЮБЫЕ существенные, долгоиграющие факты о людях: страна/город проживания, семейное положение (в браке/разводе/встречается), дети (имена, пол, возраст), любые родственные связи (родители, братья/сёстры, супруги, бывшие), свидания и личная жизнь, явно заявленные вкусы (еда/музыка/цвета — см. важное ограничение ниже), поездки — прошлые, текущие или запланированные, свои или близких родственников. Вообще любая конкретная деталь о человеке, которая может пригодиться позже.

Важно: сообщение может быть НЕ о самом авторе, а о ком-то другом ("бывший муж Лиды", "у Пети дочь родилась", "мама Саши приезжает") — тогда факт относится к тому, о ком речь, а не к автору сообщения.

Если тебе передан контекст (реплай на чьё-то сообщение или несколько предыдущих реплик чата) — используй его ТОЛЬКО чтобы понять смысл короткого ответа, но факт всё равно относится к автору ЭТОГО сообщения (если он отвечает о себе), если только сам текст явно не говорит о третьем лице. Например: кто-то спросил "Люда, а у тебя сколько детей?", Люда ответила "трое" → это Люда отвечает о себе, факт "трое детей" относится к SPEAKER (то есть к Люде — автору сообщения "трое"), не к тому, кто спросил. Без контекста короткие однословные ответы обычно ничего не значат — не выдумывай факт, если из контекста не очевидно, о чём вообще речь.

КРИТИЧЕСКИ ВАЖНОЕ ОГРАНИЧЕНИЕ про вкусы и предпочтения: считай фактом ТОЛЬКО явное высказывание отношения ("мне нравится...", "обожаю...", "ненавижу...", "это моя любимая песня/еда/группа"). Просьба прислать/найти/поставить трек, фильм, песню — это НЕ факт о вкусах, даже если человек просил это несколько раз подряд или в разных сообщениях. Точно так же однократное упоминание чего-либо (посмотрел фильм, поел что-то) — это не устойчивое предпочтение. Не додумывай вкус или характер человека по его действиям/запросам — только по прямым словам.

Игнорируй: бытовую мелочь момента (что поел прямо сейчас, разовые планы на сегодня, самочувствие в моменте типа "голова болит"), шутки, флуд, игровые ходы (крокодил/шахматы/шашки и т.п.), любые запросы к самому боту (поставь трек, найди фильм, какая погода и т.п.) — если это не несёт долгоиграющей личной информации.

Формат ответа — ТОЛЬКО валидный JSON-массив, без пояснений и markdown-обёртки:
[{"person": "<имя из списка известных людей ИЛИ 'SPEAKER' если факт об авторе сообщения ИЛИ произвольное имя, если человек не из списка (например родственник/бывший)>", "entries": [{"category": "<короткая категория в 1-2 слова на русском, например: город, семья, отношения, работа, увлечения, путешествия, здоровье, другое. "семья" — про детей/родителей/родственников, "отношения" — отдельно про статус (в браке/встречается/бывшие/свидания)>", "fact": "<текст факта по этой категории>"}]}]

У каждого факта — своя категория, отдельным блоком. Если в разделе "Текущие факты" для человека уже есть блок с такой же (или явно той же по смыслу) категорией — верни для неё ПОЛНЫЙ обновлённый текст, слив старое с новым (например было "дочь София", узнали "дочери 15 лет" → верни "дочь София, 15 лет" под той же категорией). Категории, которых это сообщение не касается, вообще не включай в ответ — они и так останутся как есть, дублировать их не нужно.

Каждый факт — короткая фраза, не абзац. Если в сообщении нет ничего существенного — верни пустой массив [].`;

// Минимальная длина сообщения, чтобы вообще пробовать извлечение — короткие
// реплики ("ага", "лол", стикеры без текста) почти никогда не несут досье-
// достойной информации, а вызов API на них — просто лишний расход лимита.
const PROFILE_EXTRACT_MIN_LENGTH = 12;

function stripJsonFence(text) {
  return text
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/```\s*$/i, "")
    .trim();
}

// Дешёвый regex-предфильтр ПЕРЕД тем, как вообще дёргать Groq — экономит
// не столько TPM (промпт и так укладывается с запасом в ~12K TPM лимит
// llama-3.3-70b-versatile), сколько ЗАПРОСЫ В ДЕНЬ (RPD), а он на бесплатном
// тарифе — всего ~1000/день и ОБЩИЙ с обычными ответами бота в чате (тот же
// TARGETS/cooldownUntil пул). В активном чате без фильтра каждое сообщение
// от 12 символов — это отдельный запрос, что может откусывать заметную долю
// дневного лимита впустую на явно бытовых сообщениях. Список — не строгая
// классификация, а грубое "есть ли вообще шанс, что тут личный факт" — если
// ни одно слово не совпало, почти наверняка LLM всё равно вернула бы [].
const PROFILE_FACT_HINT_REGEX =
  /жив[ёе]т|живу|переех|город|странa|роди[лт]|дет[ия]|сын|доч[ья]|ребён|ребен|жена|муж|парен|девушк|встреча|расста|развел|развод|бывш|свида|люблю|обожа|ненавиж|нравится|нравят|любим|работа|должност|професс|устро[ий]лся|устрои|уволил|поездк|путешеств|отпуск|переезд|болею|болезн|диагноз|день рождени|годовщин|свадьб|женил|замуж/i;

// Человекочитаемый дамп текущих категорий факта для одного человека —
// используется и в подсказке модели, и (при желании) для дебага в логах.
function formatProfileFactsBlock(profile) {
  const facts = normalizeProfile(profile).facts;
  const keys = Object.keys(facts);
  if (keys.length === 0) return "(фактов ещё нет)";
  return keys.map((k) => `${k}: ${facts[k].text}`).join("; ");
}

// Фоновое, не блокирующее основной ответ бота извлечение — вызывается
// fire-and-forget (без await) из основного обработчика сообщений. Любая
// ошибка тут — просто лог, никогда не должна аукнуться на обычном чате.
// Общий рубильник фичи "досье": false — бот больше не дёргает LLM для
// извлечения фактов о участниках. Остальной код (хранение/показ уже
// накопленных досье) не тронут, чтобы вернуть фичу — просто верни true.
const PROFILE_EXTRACT_ENABLED = false;

async function extractProfileFacts(chatId, speakerId, speakerName, text, conversationContext = null) {
  if (!PROFILE_EXTRACT_ENABLED) return;

  // Фильтр минимальной длины снимаем, если есть контекст диалога — короткое
  // "розы"/"трое" само по себе бессмысленно по длине, но осмысленно вместе
  // с вопросом/предыдущими репликами (см. buildProfileExtractionContext).
  if (!text || (text.trim().length < PROFILE_EXTRACT_MIN_LENGTH && !conversationContext)) return;

  // Если ни само сообщение, ни контекст вокруг него не содержат вообще
  // никакого намёка на личный факт — не тратим на это запрос к Groq.
  // Контекст обязательно проверяем тоже: короткое "трое" само по себе не
  // матчнёт ни одно слово из списка, но вопрос-контекст "сколько детей" —
  // матчнёт, и это ровно тот случай, который не хочется потерять.
  const haystack = `${text} ${conversationContext || ""}`;
  if (!PROFILE_FACT_HINT_REGEX.test(haystack)) return;

  // Роутим строго через Groq — промпт узкий и не требует ни "личности"
  // Жени, ни мультимодальности Gemini, а бесплатный Groq для такой мелкой
  // задачи более чем достаточен. В отличие от askLLM тут своя копия
  // фолбэк-цикла (не переиспользуем computeTargetOrder — та учитывает
  // pinnedTargetIndex/выбор пользователя через /model, что тут не нужно):
  // перебираем ВСЕ Groq-цели (модель × ключ, см. GROQ_API_KEYS) по порядку
  // TARGETS, пропуская то, что сейчас в cooldown, и переходим к следующей
  // при ошибке — так лишний аккаунт реально подхватывается автоматически,
  // а не только тогда, когда на него попутно наткнётся обычный чат.
  const now = Date.now();
  const groqTargetIndices = TARGETS.map((t, idx) => (t.provider === "groq" ? idx : -1)).filter((idx) => idx !== -1);
  const availableGroqIndices = groqTargetIndices.filter((idx) => cooldownUntil[idx] <= now);
  if (availableGroqIndices.length === 0) return; // все Groq-цели остывают — пропускаем этот цикл

  // Список известных людей в чате — чтобы модель могла сослаться на
  // конкретного знакомого человека, а не только на автора сообщения.
  const knownNames = [...new Set(getMemberNameMap(chatId).values())].slice(0, 40);
  const knownList = knownNames.length ? knownNames.join(", ") : "(пока никого не знаю по именам)";

  // Подкладываем модели текущие факты (по категориям) о тех, кого сообщение
  // вероятно касается (сам автор + любой похожий по имени человек из чата) —
  // чтобы она могла отредактировать существующий блок, а не создать
  // дублирующую запись об одном и том же.
  const map = getProfileMap(chatId);
  const candidateIds = findMentionedMemberIds(chatId, text, speakerId);
  const existingBlocks = candidateIds
    .map((id) => {
      const name = id === speakerId ? speakerName : getMemberNameMap(chatId).get(id);
      if (!name) return null;
      return `${name}: ${formatProfileFactsBlock(map.get(id))}`;
    })
    .filter(Boolean)
    .join("\n");

  const messages = [
    { role: "system", content: PROFILE_EXTRACT_SYSTEM_PROMPT },
    {
      role: "user",
      content:
        `Известные люди в чате: ${knownList}\n\nТекущие факты о вероятно упомянутых людях:\n${existingBlocks}\n\n` +
        (conversationContext ? `${conversationContext}\n\n` : "") +
        `Автор сообщения: ${speakerName}\nСообщение: "${text}"`,
    },
  ];

  let reply = null;
  let lastErr = null;
  for (const idx of availableGroqIndices) {
    const target = TARGETS[idx];
    try {
      const result = await callTarget(target, messages);
      reply = result.reply;
      cooldownUntil[idx] = 0; // на успехе снимаем cooldown, если он был
      break;
    } catch (err) {
      lastErr = err;
      console.error(
        `Досье: ошибка у ${targetLabel(target)} (чат ${chatId}, от ${speakerName}):`,
        err.status ?? "-",
        err.body ?? err.message
      );
      // Без статуса — считаем фолбэк-достойной (сетевая/таймаут); с явным
      // статусом смотрим isFallbackWorthy (429/5xx — пробуем следующий
      // ключ/модель, 400 и т.п. — нет смысла, тут же и остальные упадут).
      if (err.status && !isFallbackWorthy(err.status)) break;
      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }

  if (reply === null) {
    if (lastErr) {
      console.error(`Досье: не удалось извлечь факты (чат ${chatId}, от ${speakerName}) — все Groq-цели исчерпаны`);
    }
    return;
  }

  try {
    const parsed = JSON.parse(stripJsonFence(reply));
    if (!Array.isArray(parsed)) return;

    for (const entry of parsed) {
      if (!entry || typeof entry !== "object") continue;
      const rawEntries = Array.isArray(entry.entries) ? entry.entries : [];
      const validEntries = rawEntries.filter(
        (e) => e && typeof e.category === "string" && e.category.trim() && typeof e.fact === "string" && e.fact.trim()
      );
      if (validEntries.length === 0) continue;

      const isAboutSpeaker = !entry.person || entry.person === "SPEAKER";
      const resolvedUserId = isAboutSpeaker ? speakerId : resolveUserIdByName(chatId, entry.person);
      // Если это третье лицо (не в списке чата) — прикрепляем к досье
      // автора, но помечаем категорию именем этого человека, чтобы не
      // перепутать с фактами самого автора.
      const targetUserId = resolvedUserId || speakerId;
      const categoryPrefix = resolvedUserId ? "" : `${entry.person ? `${entry.person} — ` : ""}`;

      let profile = normalizeProfile(map.get(targetUserId) || { facts: {} });
      for (const e of validEntries) {
        profile = upsertProfileCategory(profile, `${categoryPrefix}${e.category}`, e.fact);
      }
      map.set(targetUserId, profile);
      saveProfile(chatId, targetUserId);
    }
  } catch (err) {
    // Не критично — просто лог, чат не должен ничего заметить.
    console.error(`Досье: не удалось распарсить ответ модели (чат ${chatId}, от ${speakerName}):`, err.message);
  }
}

// ==== Имитация "живой" задержки перед ответом ====
function typingDelayMs(replyLength) {
  const base = 1200 + Math.min(replyLength * 15, 2000);
  const jitter = Math.random() * 500;
  return base + jitter;
}

// ==== Память чата ("запомни: ..." / "забудь ...") ====
// Отдельные факты/правила, которые бот должен постоянно учитывать именно
// в этом чате (например "цены указывай в долларах"). В отличие от
// истории диалога (см. histories выше) не устаревает и не чистится
// командой /reset — подмешивается отдельным блоком в системный промпт
// на каждый запрос (см. buildMemoryPromptBlock в askLLM). Живёт в памяти
// как кэш, зеркалится в Redis (ключ memory:{chatId}) — см.
// loadPersistedState() при старте.
const chatMemory = new Map(); // chatId -> [{ text, addedBy, addedAt }]

function getMemoryList(chatId) {
  if (!chatMemory.has(chatId)) chatMemory.set(chatId, []);
  return chatMemory.get(chatId);
}

async function saveMemory(chatId) {
  if (!redis) return true; // персистентности нет, но в оперативной памяти всё равно уже лежит
  try {
    const list = getMemoryList(chatId);
    if (list.length === 0) await redis.del(`memory:${chatId}`);
    else await redis.set(`memory:${chatId}`, list);
    return true;
  } catch (err) {
    console.error(`Redis: не удалось сохранить память чата ${chatId}:`, err);
    return false;
  }
}

// Возвращает { position, saved }: position — номер (1-based) только что
// добавленного пункта, saved — реально ли запись улетела в Redis (а не
// просто повисла в оперативной памяти процесса). saved нужен вызывающему
// коду, чтобы стикер-подтверждение (см. MEMORY_CONFIRM_STICKER_FILE_ID)
// слался только когда запоминание действительно произошло, а не по факту
// вызова функции.
async function addMemoryItem(chatId, text, addedBy) {
  const list = getMemoryList(chatId);
  list.push({ text, addedBy: addedBy || null, addedAt: Date.now() });
  const saved = await saveMemory(chatId);
  return { position: list.length, saved };
}

// index — 1-based номер пункта, как показывается в /memory и в ответах бота.
function removeMemoryItem(chatId, index) {
  const list = getMemoryList(chatId);
  if (!Number.isInteger(index) || index < 1 || index > list.length) return false;
  list.splice(index - 1, 1);
  saveMemory(chatId);
  return true;
}

function clearMemory(chatId) {
  chatMemory.set(chatId, []);
  saveMemory(chatId);
}

// Блок для системного промпта — пустая строка, если в чате ничего не запомнено.
function buildMemoryPromptBlock(chatId) {
  const list = getMemoryList(chatId);
  if (list.length === 0) return "";
  const lines = list.map((item, i) => `${i + 1}. ${item.text}`);
  return (
    "\n\nВ этом чате тебя явно попросили запомнить и всегда учитывать следующее " +
    "(это обязательные правила именно для этого чата, а не просто пожелания):\n" +
    lines.join("\n")
  );
}

// Ожидание текста для /memory -> "➕ добавить": ownerId -> chatId, куда
// добавить следующее текстовое сообщение владельца бота (откуда угодно,
// хоть из личных сообщений — см. кнопку memadd в callback_query ниже).
const pendingMemoryAdd = new Map();

// Стикер-подтверждение "реально запомнил" — шлётся ТОЛЬКО кодом, и только
// после того как addMemoryItem() подтвердил (saved === true), что запись
// действительно улетела в Redis, а не просто оказалась в оперативной
// памяти процесса. Никогда не отдаётся LLM как тег для самостоятельной
// вставки (в отличие от extractSticker/[sticker: ...] у обычных
// бантер-стикеров) — именно поэтому не может вылететь "для вида", когда
// на самом деле ничего не сохранилось.
const MEMORY_CONFIRM_STICKER_FILE_ID =
  process.env.MEMORY_CONFIRM_STICKER_FILE_ID ||
  "CAACAgIAAxkBAAFSbOBqiY9OESVr-0fcYfsQsXwg0DlNAgACc6YAAqyooUvZTPmNIYlDWz0E";

// ==== Реестр чатов, где бот хоть раз получил сообщение (для /memory —
// выбор чата кнопками) ====
// chatId -> человекочитаемое название (title группы либо имя/юзернейм в
// личке). Зеркалится в Redis одним ключом "known_chats". Обновляется на
// каждое входящее сообщение (см. rememberKnownChat в глобальном
// bot.use middleware выше).
const knownChats = new Map(); // chatId -> title

async function saveKnownChats() {
  if (!redis) return;
  try {
    await redis.set("known_chats", Object.fromEntries(knownChats));
  } catch (err) {
    console.error("Redis: не удалось сохранить реестр чатов:", err);
  }
}

function chatDisplayTitle(ctx) {
  if (ctx.chat.type === "private") {
    const c = ctx.chat;
    return c.username ? `@${c.username} (личка)` : `${[c.first_name, c.last_name].filter(Boolean).join(" ") || "личка"}`;
  }
  return ctx.chat.title || String(ctx.chat.id);
}

function rememberKnownChat(ctx) {
  if (!ctx.chat) return;
  const title = chatDisplayTitle(ctx);
  if (knownChats.get(ctx.chat.id) === title) return; // не изменилось — незачем писать в Redis
  knownChats.set(ctx.chat.id, title);
  saveKnownChats();
}

// ==== Восстановление состояния из Redis при старте ====
// Читает всё, что успели сохранить save*-хелперы выше, обратно в
// оперативные Map'ы, чтобы после рестарта бот "помнил" контекст диалогов,
// алиасы, пол и на какой модели остановился в прошлый раз.
async function loadPersistedState() {
  if (!redis) return;

  try {
    const [
      historyKeys,
      chatLogKeys,
      aliasKeys,
      usernameKeys,
      genderKeys,
      chessKeys,
      checkersKeys,
      krokodilKeys,
      krokodilScoreKeys,
      profileKeys,
      memberNameKeys,
      memoryKeys,
      ignoredKeys,
      savedKnownChats,
      savedIdx,
      savedPinnedIdx,
      savedWatchDisabledChats,
      savedVoiceEnabledChats,
    ] = await Promise.all([
      redis.keys("history:*"),
      redis.keys("chatlog:*"),
      redis.keys("aliases:*"),
      redis.keys("usernames:*"),
      redis.keys("genders:*"),
      redis.keys("chess:*"),
      redis.keys("checkers:*"),
      redis.keys("krokodil:*"),
      redis.keys("krokodil_scores:*"),
      redis.keys("profiles:*"),
      redis.keys("members:*"),
      redis.keys("memory:*"),
      redis.keys("ignored:*"),
      redis.get("known_chats"),
      redis.get("activeTargetIndex"),
      redis.get("pinnedTargetIndex"),
      redis.get("watchDisabledChats"),
      redis.get("voiceEnabledChats"),
    ]);

    await Promise.all(
      historyKeys.map(async (key) => {
        const chatId = Number(key.slice("history:".length));
        const data = await redis.get(key);
        if (Array.isArray(data)) histories.set(chatId, data);
      })
    );

    await Promise.all(
      chatLogKeys.map(async (key) => {
        const chatId = Number(key.slice("chatlog:".length));
        const data = await redis.get(key);
        if (Array.isArray(data)) chatLogs.set(chatId, data);
      })
    );

    await Promise.all(
      aliasKeys.map(async (key) => {
        const chatId = Number(key.slice("aliases:".length));
        const data = await redis.get(key);
        if (data && typeof data === "object") {
          const map = getAliasMap(chatId);
          for (const [userId, value] of Object.entries(data)) map.set(Number(userId), value);
        }
      })
    );

    await Promise.all(
      usernameKeys.map(async (key) => {
        const chatId = Number(key.slice("usernames:".length));
        const data = await redis.get(key);
        if (data && typeof data === "object") {
          const map = getUsernameIndex(chatId);
          for (const [username, userId] of Object.entries(data)) map.set(username, Number(userId));
        }
      })
    );

    await Promise.all(
      genderKeys.map(async (key) => {
        const chatId = Number(key.slice("genders:".length));
        const data = await redis.get(key);
        if (data && typeof data === "object") {
          const map = getGenderMap(chatId);
          for (const [userId, value] of Object.entries(data)) map.set(Number(userId), value);
        }
      })
    );

    await Promise.all(
      chessKeys.map(async (key) => {
        // Ключ вида chess:{chatId}:{userId} — карту храним под тем же
        // составным ключом, что и chessMapKey() в рантайме.
        const mapKey = key.slice("chess:".length);
        const data = await redis.get(key);
        if (data && typeof data === "object" && typeof data.fen === "string") {
          chessGames.set(mapKey, data);
        }
      })
    );

    await Promise.all(
      checkersKeys.map(async (key) => {
        // Ключ вида checkers:{chatId}:{userId} — под тем же составным
        // ключом, что и checkersMapKey() в рантайме.
        const mapKey = key.slice("checkers:".length);
        const data = await redis.get(key);
        if (data && typeof data === "object" && Array.isArray(data.board)) {
          checkersGames.set(mapKey, data);
        }
      })
    );

    await Promise.all(
      krokodilKeys.map(async (key) => {
        const chatId = Number(key.slice("krokodil:".length));
        const data = await redis.get(key);
        if (data && typeof data === "object" && typeof data.status === "string") {
          krokodilGames.set(chatId, data);
        }
      })
    );

    await Promise.all(
      krokodilScoreKeys.map(async (key) => {
        const chatId = Number(key.slice("krokodil_scores:".length));
        const data = await redis.get(key);
        if (data && typeof data === "object") {
          const map = getKrokodilScoreMap(chatId);
          for (const [userId, value] of Object.entries(data)) map.set(Number(userId), value);
        }
      })
    );

    await Promise.all(
      profileKeys.map(async (key) => {
        // Ключ вида profiles:{chatId}:{userId} — досье на конкретного
        // человека отдельным ключом (не общим дампом на весь чат), чтобы
        // было удобно смотреть/чистить по одному человеку через Redis.
        const rest = key.slice("profiles:".length);
        const sepIdx = rest.lastIndexOf(":");
        if (sepIdx === -1) return;
        const chatId = Number(rest.slice(0, sepIdx));
        const userId = Number(rest.slice(sepIdx + 1));
        const data = await redis.get(key);
        if (data && typeof data === "object" && Number.isInteger(chatId) && Number.isInteger(userId)) {
          getProfileMap(chatId).set(userId, data);
        }
      })
    );

    await Promise.all(
      memberNameKeys.map(async (key) => {
        const chatId = Number(key.slice("members:".length));
        const data = await redis.get(key);
        if (data && typeof data === "object") {
          const map = getMemberNameMap(chatId);
          for (const [userId, value] of Object.entries(data)) map.set(Number(userId), value);
        }
      })
    );

    await Promise.all(
      memoryKeys.map(async (key) => {
        const chatId = Number(key.slice("memory:".length));
        const data = await redis.get(key);
        if (Array.isArray(data)) chatMemory.set(chatId, data);
      })
    );

    await Promise.all(
      ignoredKeys.map(async (key) => {
        const chatId = Number(key.slice("ignored:".length));
        const data = await redis.get(key);
        if (Array.isArray(data)) chatIgnored.set(chatId, new Set(data.map(Number)));
      })
    );

    if (savedKnownChats && typeof savedKnownChats === "object") {
      for (const [chatIdRaw, title] of Object.entries(savedKnownChats)) {
        knownChats.set(Number(chatIdRaw), title);
      }
    }

    if (typeof savedIdx === "number" && Number.isInteger(savedIdx) && savedIdx >= 0 && savedIdx < TARGETS.length) {
      activeTargetIndex = savedIdx;
    }

    if (
      typeof savedPinnedIdx === "number" &&
      Number.isInteger(savedPinnedIdx) &&
      savedPinnedIdx >= 0 &&
      savedPinnedIdx < TARGETS.length
    ) {
      pinnedTargetIndex = savedPinnedIdx;
    }

    if (Array.isArray(savedWatchDisabledChats)) {
      for (const chatId of savedWatchDisabledChats) {
        if (Number.isInteger(chatId)) watchDisabledChats.add(chatId);
      }
    }

    if (Array.isArray(savedVoiceEnabledChats)) {
      for (const chatId of savedVoiceEnabledChats) {
        if (Number.isInteger(chatId)) voiceEnabledChats.add(chatId);
      }
    }

    console.log(
      `Восстановлено из Redis: истории — ${historyKeys.length}, логи чатов — ${chatLogKeys.length}, алиасы — ${aliasKeys.length}, ` +
        `юзернеймы — ${usernameKeys.length}, пол — ${genderKeys.length}, шахматные партии — ${chessKeys.length}, ` +
        `шашечные партии — ${checkersKeys.length}, раунды крокодила — ${krokodilKeys.length}, ` +
        `счёт крокодила — ${krokodilScoreKeys.length} чатов, досье — ${profileKeys.length}, имена участников — ${memberNameKeys.length} чатов, ` +
        `память чатов — ${memoryKeys.length} чатов, реестр чатов — ${knownChats.size}` +
        (typeof savedIdx === "number" ? `, активная модель — индекс ${activeTargetIndex}` : "") +
        (pinnedTargetIndex !== null ? `, закреплена вручную — индекс ${pinnedTargetIndex}` : "") +
        `, чатов с выключенной слежкой (watch) — ${watchDisabledChats.size}` +
        `, чатов с включённым голосом — ${voiceEnabledChats.size}`
    );
  } catch (err) {
    console.error("Не удалось восстановить состояние из Redis, стартую с чистой памятью:", err);
  }
}


// ==== Поиск и отправка музыки с Deezer ====
// Основной сервер (SnapDeploy): сам качает трек, расшифровывает и грузит в Telegram
// через Bot API (send_audio) — работает для любых форматов, включая FLAC.
const DEEZER_SPACE_URL = process.env.DEEZER_SPACE_URL || "https://deezer-ae701.containers.snapdeploy.app";
// Фолбэк-сервер (Hugging Face): используется только если основной недоступен.
// У HF ограничение на аплоад через API, поэтому туда просто ходим за прямой
// ссылкой на MP3 320kbps и отдаём её Telegram — тот качает файл сам (FLAC так не работает).
// Задаётся только через env, без дефолта — если не задан, фолбэк просто пропускается.
const DEEZER_SPACE_URL_FALLBACK = process.env.DEEZER_SPACE_URL_FALLBACK || "";
const DEEZER_ARL = process.env.DEEZER_ARL || "";
const DEFAULT_DEEZER_QUALITY = process.env.DEEZER_QUALITY || "MP3_320";
const DEEZER_SEND_AUDIO_TIMEOUT_MS = Number(process.env.DEEZER_SEND_AUDIO_TIMEOUT_MS || 60000);

// ==== SoundCloud ====
// SoundCloud работает через HF сервер (тот же что и Deezer fallback).
// Максимальное качество: 256kbps AAC для Go+ треков, 128kbps MP3 для остальных.
const SOUNDCLOUD_SERVER_URL = process.env.SOUNDCLOUD_SERVER_URL || DEEZER_SPACE_URL_FALLBACK || "";
const SOUNDCLOUD_QUALITY = process.env.SOUNDCLOUD_QUALITY || "best"; // best, 256, 128

const SECRET = "g4el58wc0zvf9na1";

function getBlowfishKeyBuffer(trackId) {
  const md5hex = crypto.createHash("md5").update(String(trackId)).digest("hex");
  const key = Buffer.alloc(16);
  for (let i = 0; i < 16; i++) {
    key[i] = md5hex.charCodeAt(i) ^ md5hex.charCodeAt(i + 16) ^ SECRET.charCodeAt(i);
  }
  return key;
}

function decryptStripeNative(block2048, keyBuffer) {
  const iv = Buffer.from([0, 1, 2, 3, 4, 5, 6, 7]);
  const decipher = crypto.createDecipheriv("bf-cbc", keyBuffer, iv);
  decipher.setAutoPadding(false);
  return Buffer.concat([decipher.update(block2048), decipher.final()]);
}

function looksMp3OrFlac(u8) {
  if (!u8 || u8.length < 4) return false;
  if (u8[0] === 0x49 && u8[1] === 0x44 && u8[2] === 0x33) return true; // ID3 tag
  if (u8[0] === 0x66 && u8[1] === 0x4c && u8[2] === 0x61 && u8[3] === 0x43) return true; // FLAC tag

  const limit = Math.min(4096, u8.length - 1);
  for (let i = 0; i < limit; i++) {
    if (u8[i] === 0xff && (u8[i + 1] & 0xe0) === 0xe0) {
      return true;
    }
  }
  return false;
}

function decryptDeezerBufferIfNeeded(trackId, rawBuffer) {
  const raw = new Uint8Array(rawBuffer);
  if (looksMp3OrFlac(raw)) {
    return Buffer.from(rawBuffer);
  }
  const BLOCK = 2048;
  const keyBuffer = getBlowfishKeyBuffer(trackId);
  const outChunks = [];
  let blockIndex = 0;

  for (let off = 0; off < raw.length; off += BLOCK) {
    const chunk = raw.subarray(off, off + BLOCK);
    if (blockIndex % 3 === 0 && chunk.length === BLOCK) {
      try {
        outChunks.push(decryptStripeNative(chunk, keyBuffer));
      } catch (e) {
        outChunks.push(chunk);
      }
    } else {
      outChunks.push(chunk);
    }
    blockIndex++;
  }
  return Buffer.concat(outChunks);
}

// ==== Инициализация бота ====
const bot = new Bot(BOT_TOKEN);

// ==== Разрешённые группы ====
// ALLOWED_GROUP_IDS — id групп/супергрупп через запятую, где боту разрешено
// отвечать. Личные чаты этим списком НЕ ограничиваются — там бот всегда
// доступен. Если список пуст — ограничения нет, бот работает в любой группе.
const ALLOWED_GROUP_IDS = (process.env.ALLOWED_GROUP_IDS || "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean)
  .map(Number);

function isAllowedChat(ctx) {
  const isGroup = ctx.chat?.type === "group" || ctx.chat?.type === "supergroup";
  if (!isGroup) return true;
  if (ALLOWED_GROUP_IDS.length === 0) return true;
  return ALLOWED_GROUP_IDS.includes(ctx.chat.id);
}

// Глобальный фильтр — стоит раньше всех bot.command/bot.on, поэтому
// отсекает неразрешённые группы до того, как сообщение попадёт в любой
// хендлер (команды, текст, реакции на аудио — вообще всё). В логах
// печатает id и название группы, откуда прилетело сообщение — удобно,
// чтобы потом просто скопировать id в ALLOWED_GROUP_IDS.
bot.use(async (ctx, next) => {
  if (!ctx.chat) return next();
  if (!isAllowedChat(ctx)) {
    const senderName =
      ctx.from?.username
        ? `@${ctx.from.username}`
        : [ctx.from?.first_name, ctx.from?.last_name].filter(Boolean).join(" ") || "неизвестно";
    // Ссылка на отправителя: если есть username — обычная t.me-ссылка (кликабельна
    // отовсюду), иначе tg://user?id= — открывается только в самом Telegram, но
    // работает даже без username.
    const senderLink = ctx.from?.username
      ? `https://t.me/${ctx.from.username}`
      : ctx.from?.id
      ? `tg://user?id=${ctx.from.id}`
      : null;
    // Ссылка на чат возможна только если у группы есть публичный username —
    // Bot API не даёт invite-ссылку на приватную группу без прав администратора там.
    const chatLink = ctx.chat.username ? `https://t.me/${ctx.chat.username}` : null;
    const preview = ctx.message ? watchMessagePreview(ctx.message) : "[не текстовое обновление]";
    console.warn(
      `Сообщение из неразрешённой группы (id: ${ctx.chat.id}, название: "${ctx.chat.title}"` +
        `${chatLink ? `, ${chatLink}` : ""}) ` +
        `от ${senderName}${senderLink ? ` (${senderLink})` : ""} (id: ${ctx.from?.id}): ${preview} — игнорирую. ` +
        `Чтобы разрешить, добавь ${ctx.chat.id} в ALLOWED_GROUP_IDS.`
    );
    if (OWNER_ID) {
      bot.api
        .sendMessage(
          OWNER_ID,
          `🚫 сообщение из чужой группы "${ctx.chat.title}" (id: ${ctx.chat.id})\n` +
            `${chatLink ? `чат: ${chatLink}\n` : "чат: приватный, ссылки нет\n"}` +
            `от: ${senderName} (id: ${ctx.from?.id})\n` +
            `${senderLink ? `${senderLink}\n` : ""}` +
            `\n${preview}`
        )
        .catch((err) => console.error("Не удалось отправить уведомление о чужой группе:", err));
    }
    return;
  }
  // Реестр чатов для /memory — см. rememberKnownChat выше. Ставим уже
  // после фильтра неразрешённых групп, чтобы в списке не всплывали чаты,
  // куда бота добавили чужие люди без ведома хозяина.
  rememberKnownChat(ctx);
  await next();
});

// ==== Уведомления владельцу о новых сообщениях в "тихих" чатах ====
// Идея: по умолчанию слежка включена сразу для ВСЕХ разрешённых групповых
// чатов (см. ALLOWED_GROUP_IDS/isAllowedChat выше — сюда мы попадаем уже
// только с разрешённым чатом). На ПЕРВОЕ новое сообщение в чате бот шлёт
// хозяину уведомление в ЛС и на час "замолкает" по этому чату — дальнейшие
// сообщения в течение часа уведомлений не вызывают. Если за час никто
// больше не написал — бот просто продолжает ждать; если написал — цикл
// повторяется. Командой /watch хозяин может выключить слежку за конкретным
// чатом (и обратно включить тем же /watch) — см. хендлер ниже.
//
// Храним не "кого отслеживаем" (по умолчанию — все), а "кого ИСКЛЮЧИЛИ" —
// id чатов, персистится в Redis одним массивом под ключом
// "watchDisabledChats" (тем же паттерном, что activeTargetIndex/
// pinnedTargetIndex выше — см. loadPersistedState).
const watchDisabledChats = new Set();

const WATCH_COOLDOWN_MS = 60 * 60 * 1000; // час

// Кулдаун "чат сейчас не уведомляем" храним в Redis как ключ с TTL —
// сам по себе факт существования ключа и есть кулдаун, отдельный таймер
// не нужен, Redis сам удалит ключ через час. Если Redis не настроен —
// запасной вариант в памяти процесса (chatId -> unix ms окончания
// кулдауна), переживёт только до рестарта.
const watchCooldownMemory = new Map();

async function isWatchCooldownActive(chatId) {
  if (redis) {
    try {
      const marker = await redis.get(`watchCooldown:${chatId}`);
      return !!marker;
    } catch (err) {
      console.error("Не удалось проверить кулдаун уведомлений в Redis:", err);
    }
  }
  const until = watchCooldownMemory.get(chatId);
  return typeof until === "number" && Date.now() < until;
}

async function startWatchCooldown(chatId) {
  watchCooldownMemory.set(chatId, Date.now() + WATCH_COOLDOWN_MS);
  if (redis) {
    try {
      await redis.set(`watchCooldown:${chatId}`, "1", { ex: Math.round(WATCH_COOLDOWN_MS / 1000) });
    } catch (err) {
      console.error("Не удалось выставить кулдаун уведомлений в Redis:", err);
    }
  }
}

async function saveWatchDisabledChats() {
  if (!redis) return;
  try {
    await redis.set("watchDisabledChats", Array.from(watchDisabledChats));
  } catch (err) {
    console.error("Не удалось сохранить список исключённых из слежки чатов:", err);
  }
}

// ==== Режим голоса ("/voice") ====
// Чаты, где обычные ответы бота уходят ТОЛЬКО голосовым сообщением, без
// текстового дубля (см. основной хук в конце bot.on("message:text"), где
// это разруливается через переменную voiceOnly, и триггер "скажи
// голосом"/"озвучь" ниже для разовой озвучки конкретного текста без
// включения режима на весь чат — он работает независимо от этого
// тумблера). Если синтез речи не удался (Space не ответил/упал) — ответ
// всё равно уходит текстом, чтобы человек не остался без ответа вовсе.
// По умолчанию выключено везде — список ВКЛЮЧЁННЫХ чатов, персистится в
// Redis одним массивом под ключом "voiceEnabledChats" (тот же паттерн,
// что watchDisabledChats выше, только с обратным смыслом — там список
// исключений, тут список включений).
const voiceEnabledChats = new Set();

async function saveVoiceEnabledChats() {
  if (!redis) return;
  try {
    await redis.set("voiceEnabledChats", Array.from(voiceEnabledChats));
  } catch (err) {
    console.error("Не удалось сохранить список чатов с включённым голосом:", err);
  }
}

// Слежка включена по умолчанию для любого группового/супергруппового чата
// (личка и каналы не считаются — уведомлять там не о чем), если только
// хозяин явно не выключил её через /watch.
function isWatchedChat(ctx) {
  const isGroup = ctx.chat?.type === "group" || ctx.chat?.type === "supergroup";
  if (!isGroup) return false;
  return !watchDisabledChats.has(ctx.chat.id);
}

// Короткое текстовое превью сообщения любого типа — используется в тексте
// уведомления. Полноценный forwardMessage был бы точнее, но простой текст
// проще читать вперемешку с остальной перепиской в ЛС у хозяина.
function watchMessagePreview(msg) {
  if (msg.text) return msg.text.length > 300 ? `${msg.text.slice(0, 300)}…` : msg.text;
  if (msg.caption) return `[подпись к медиа] ${msg.caption}`;
  if (msg.photo) return "[фото]";
  if (msg.video) return "[видео]";
  if (msg.video_note) return "[видео-кружок]";
  if (msg.voice) return "[голосовое]";
  if (msg.audio) return "[аудио]";
  if (msg.document) return "[файл]";
  if (msg.sticker) return `[стикер${msg.sticker.emoji ? " " + msg.sticker.emoji : ""}]`;
  if (msg.animation) return "[гифка]";
  if (msg.poll) return "[опрос]";
  if (msg.location) return "[геолокация]";
  return "[сообщение]";
}

// Сам хук — стоит после фильтра разрешённых групп, но до всех остальных
// command/on-хендлеров, чтобы отлавливать вообще любое сообщение (текст,
// фото, стикер и т.п.), а не только текстовые. Не мешает остальной
// обработке — всегда зовёт next().
bot.use(async (ctx, next) => {
  if (
    OWNER_ID &&
    ctx.message &&
    isWatchedChat(ctx) &&
    !ctx.from?.is_bot &&
    ctx.from?.id !== OWNER_ID
  ) {
    isWatchCooldownActive(ctx.chat.id)
      .then(async (onCooldown) => {
        if (onCooldown) return;
        await startWatchCooldown(ctx.chat.id);
        const chatTitle = ctx.chat.title || ctx.chat.username || "чат";
        const senderName = getDisplayName(ctx.chat.id, ctx.from) || ctx.from?.first_name || "кто-то";
        const preview = watchMessagePreview(ctx.message);
        await bot.api.sendMessage(OWNER_ID, `🔔 новое сообщение в "${chatTitle}"\nот: ${senderName}\n\n${preview}`);
      })
      .catch((err) => console.error("Не удалось отправить уведомление о новом сообщении:", err));
  }
  await next();
});

bot.command("start", async (ctx) => {
  const chatId = ctx.chat.id;
  await clearHistory(chatId); // сброс истории при /start
  await ctx.reply("йо");
  const stickerId = pickSticker("greeting");
  if (stickerId) await ctx.replyWithSticker(stickerId);
});

// Выключает/обратно включает уведомления в ЛС хозяину о новых сообщениях
// в ЭТОМ чате — см. блок watchDisabledChats/WATCH_COOLDOWN_MS выше.
// Слежка по умолчанию включена для всех разрешённых групп, эта команда
// нужна только чтобы точечно исключить (или вернуть) конкретный чат.
// Только владелец, вызывать прямо в том чате, который нужно исключить.
bot.command("watch", async (ctx) => {
  if (!isOwner(ctx)) return;
  if (!OWNER_ID) {
    await ctx.reply("не задан OWNER_ID в переменных окружения — некому слать уведомления в ЛС");
    return;
  }
  const chatId = ctx.chat.id;
  if (watchDisabledChats.has(chatId)) {
    watchDisabledChats.delete(chatId);
    await saveWatchDisabledChats();
    await ctx.reply("слежку за этим чатом снова включил");
  } else {
    watchDisabledChats.add(chatId);
    await saveWatchDisabledChats();
    await ctx.reply("слежку за этим чатом выключил");
  }
});

// Включает/выключает режим голоса в ЭТОМ чате — пока включён, каждый
// обычный ответ бота (через askLLM, см. переменную voiceOnly в хуке в
// конце message:text) уходит ТОЛЬКО голосовым сообщением через
// synthesizeSpeech, без текстового дубля. Если синтез не удастся — ответ
// всё равно уйдёт текстом (см. тот же хук). Влияет на всех участников
// чата, поэтому — как и /watch/reset — только владелец. Разовая озвучка
// отдельного ответа без включения режима на весь чат — см. триггер
// "скажи голосом"/"озвучь" ниже, он работает независимо от этого
// тумблера.
bot.command("voice", async (ctx) => {
  if (!isOwner(ctx)) return;
  if (!TTS_SPACE) {
    await ctx.reply("озвучка не настроена — не задан TTS_SPACE в переменных окружения");
    return;
  }
  const chatId = ctx.chat.id;
  if (voiceEnabledChats.has(chatId)) {
    voiceEnabledChats.delete(chatId);
    await saveVoiceEnabledChats();
    await ctx.reply("режим голоса в этом чате выключил — дальше отвечаю текстом");
  } else {
    voiceEnabledChats.add(chatId);
    await saveVoiceEnabledChats();
    await ctx.reply("режим голоса в этом чате включил — теперь отвечаю только голосовыми (если озвучка не удастся — пришлю текст)");
  }
});

// Доступна только владельцу — сброс контекста диалога влияет на всех
// в чате, не должен быть в руках любого участника группы.
bot.command("reset", async (ctx) => {
  if (!isOwner(ctx)) return;
  await clearHistory(ctx.chat.id);
  await ctx.reply("память почистил");
});

// /alias — задать, как бот будет называть человека вместо ника.
// Варианты использования:
//   1) ответом (reply) на сообщение человека: "/alias Андрей"
//   2) по нику:                              "/alias @user1 Андрей"
//   3) через знак равно:                     "/alias user1=Андрей"
bot.command("alias", async (ctx) => {
  const chatId = ctx.chat.id;
  const raw = (ctx.match || "").trim();

  // Вариант 1: реплай на чьё-то сообщение
  const replyTarget = ctx.message.reply_to_message?.from;
  if (replyTarget && raw) {
    const label = replyTarget.username ? `@${replyTarget.username}` : (replyTarget.first_name || "юзер");
    setAlias(chatId, replyTarget.id, raw, label);
    await ctx.reply(`ок, теперь ${label} = "${raw}"`);
    return;
  }

  if (!raw) {
    await ctx.reply(
      "как пользоваться:\n" +
        "ответь на сообщение человека командой /alias Имя\n" +
        "или так: /alias @ник Имя\n" +
        "или так: /alias ник=Имя"
    );
    return;
  }

  // Вариант 2/3: "@ник Имя" или "ник=Имя"
  let username;
  let alias;
  if (raw.includes("=")) {
    [username, ...alias] = raw.split("=");
    alias = alias.join("=").trim();
  } else {
    const spaceIdx = raw.indexOf(" ");
    if (spaceIdx === -1) {
      await ctx.reply("нужно указать и ник, и имя — например: /alias @user1 Андрей");
      return;
    }
    username = raw.slice(0, spaceIdx);
    alias = raw.slice(spaceIdx + 1).trim();
  }

  username = username.replace(/^@/, "").trim().toLowerCase();

  if (!username || !alias) {
    await ctx.reply("нужно указать и ник, и имя — например: /alias @user1 Андрей");
    return;
  }

  const userId = getUsernameIndex(chatId).get(username);
  if (!userId) {
    await ctx.reply(
      `не встречал в этом чате ника @${username} — пусть человек сначала что-нибудь напишет, ` +
        `либо задай алиас реплаем на его сообщение`
    );
    return;
  }

  setAlias(chatId, userId, alias, `@${username}`);
  await ctx.reply(`ок, теперь @${username} = "${alias}"`);
});

bot.command("unalias", async (ctx) => {
  const chatId = ctx.chat.id;
  const raw = (ctx.match || "").trim();
  const replyTarget = ctx.message.reply_to_message?.from;

  let userId;
  if (replyTarget) {
    userId = replyTarget.id;
  } else if (raw) {
    const username = raw.replace(/^@/, "").trim().toLowerCase();
    userId = getUsernameIndex(chatId).get(username);
  }

  if (!userId) {
    await ctx.reply("укажи ник (/unalias @ник) или ответь на сообщение человека");
    return;
  }

  removeAlias(chatId, userId);
  await ctx.reply("алиас убрал");
});

bot.command("aliases", async (ctx) => {
  const aliases = getAliasMap(ctx.chat.id);
  if (aliases.size === 0) {
    await ctx.reply("алиасов пока нет");
    return;
  }
  const lines = [...aliases.values()].map((a) => `- ${a.label} → ${a.name}`);
  await ctx.reply(`текущие алиасы:\n${lines.join("\n")}`);
});

// /ignored — посмотреть, кого сейчас игнорирует бот в этом чате (см.
// ignoreUser/unignoreUser, задаётся через "запомни игнорируй ...").
// Только владелец — как и сама возможность игнорировать/разигнорить.
bot.command("ignored", async (ctx) => {
  if (!isOwner(ctx)) return;
  const chatId = ctx.chat.id;
  const set = getIgnoredSet(chatId);
  if (set.size === 0) {
    await ctx.reply("сейчас никого не игнорирую в этом чате");
    return;
  }
  const lines = [...set].map((userId) => {
    const name =
      getAliasMap(chatId).get(userId)?.name || getMemberNameMap(chatId).get(userId) || null;
    const username = getKnownUsername(chatId, userId);
    const label = [name, username ? `@${username}` : null].filter(Boolean).join(", ");
    return `- ${userId}${label ? ` (${label})` : ""}`;
  });
  await ctx.reply(`сейчас в игноре:\n${lines.join("\n")}`);
});

// /gender — посмотреть или задать пол вручную (перекрывает эвристику навсегда).
// Использование: /gender м | /gender ж — про себя
//                реплаем на чьё-то сообщение — про этого человека
//                без аргументов — показать текущее значение
// Доступно только владельцу (см. OWNER_USERNAME / isOwner) — остальным
// не сообщаем, через какого провайдера сейчас отвечает бот, и не даём
// переключать модели. Тем же способом (if (!isOwner(ctx)) return;) можно
// закрыть и любую другую команду ниже, если понадобится.

// Текст статуса для сообщения с кнопками /model — вынесен отдельно, чтобы
// переиспользовать и при первой отправке, и при обновлении того же
// сообщения после нажатия кнопки (см. callback_query ниже).
function buildModelsStatusText() {
  const now = Date.now();
  const active = TARGETS[activeTargetIndex];
  let text = `сейчас отвечаю через: ${targetLabel(active)}`;

  if (pinnedTargetIndex !== null) {
    const pinned = TARGETS[pinnedTargetIndex];
    text +=
      cooldownUntil[pinnedTargetIndex] > now
        ? `\n📌 закреплено: ${targetLabel(pinned)} (сейчас в cooldown, пока отвечаю в авто-режиме)`
        : `\n📌 закреплено вручную: ${targetLabel(pinned)}`;
  }

  const cooling = TARGETS
    .map((t, i) => ({ t, until: cooldownUntil[i] }))
    .filter((x) => x.until > now);
  if (cooling.length) {
    const list = cooling
      .map((x) => `${targetLabel(x.t)} (ещё ~${Math.ceil((x.until - now) / 1000)}с)`)
      .join(", ");
    text += `\nв cooldown: ${list}`;
  }

  text += `\n\nвыбери модель кнопкой (✅ доступна сейчас, ⏳ в cooldown — нажать нельзя):`;
  return text;
}

// Клавиатура: одна кнопка на цель (provider/model), плюс кнопка "авто" —
// снять ручное закрепление и вернуться к обычному фолбэку.
function buildModelsKeyboard() {
  const now = Date.now();
  const rows = TARGETS.map((t, i) => {
    const cold = cooldownUntil[i] > now;
    let mark = cold ? "⏳" : "✅";
    if (i === activeTargetIndex) mark += "👉";
    if (i === pinnedTargetIndex) mark += "📌";
    const label = `${mark} ${targetLabel(t)}`.slice(0, 64); // лимит Telegram на текст кнопки
    return [{ text: label, callback_data: `setmodel:${i}` }];
  });
  rows.push([{ text: "🔄 авто (снять закрепление)", callback_data: "setmodel:auto" }]);
  return { inline_keyboard: rows };
}

bot.command("model", async (ctx) => {
  if (!isOwner(ctx)) return;
  await ctx.reply(buildModelsStatusText(), { reply_markup: buildModelsKeyboard() });
});

// Обработка нажатий на кнопки из /model. Закрыто владельцем так же, как
// и сама команда — на всякий случай, если кто-то доберётся до кнопок в
// групповом чате (например, переслав сообщение с меню).
bot.on("callback_query:data", async (ctx, next) => {
  const data = ctx.callbackQuery.data;
  // ВАЖНО: это не единственный обработчик "callback_query:data" — ниже
  // есть отдельный для крокодила (см. bot.on("callback_query:data", ...)
  // дальше по файлу). grammY выполняет такие обработчики цепочкой через
  // next(), и если тут просто сделать return без next() — апдейт до
  // крокодила и других обработчиков дальше по цепочке вообще не дойдёт
  // (сама кнопка будет выглядеть так, будто "ничего не происходит" при
  // нажатии). Поэтому на чужой префикс явно передаём управление дальше.
  if (!data.startsWith("setmodel:")) return next();

  if (!isOwner(ctx)) {
    await ctx.answerCallbackQuery({ text: "эта кнопка только для владельца", show_alert: true });
    return;
  }

  const value = data.slice("setmodel:".length);

  if (value === "auto") {
    pinnedTargetIndex = null;
    savePinnedTargetIndex();
    await ctx.answerCallbackQuery({ text: "снял закрепление, вернулся в авто-режим" });
  } else {
    const idx = Number(value);
    if (!Number.isInteger(idx) || idx < 0 || idx >= TARGETS.length) {
      await ctx.answerCallbackQuery();
      return;
    }

    const now = Date.now();
    if (cooldownUntil[idx] > now) {
      const secLeft = Math.ceil((cooldownUntil[idx] - now) / 1000);
      await ctx.answerCallbackQuery({
        text: `${TARGETS[idx].provider}/${TARGETS[idx].model} ещё в cooldown ~${secLeft}с — недоступна`,
        show_alert: true,
      });
      return;
    }

    pinnedTargetIndex = idx;
    savePinnedTargetIndex();
    await ctx.answerCallbackQuery({
      text: `закрепил: ${TARGETS[idx].provider}/${TARGETS[idx].model}`,
    });
  }

  // Обновляем то же сообщение, чтобы отметки (👉/📌/⏳) на кнопках и текст
  // статуса сразу отражали новый выбор.
  try {
    await ctx.editMessageText(buildModelsStatusText(), { reply_markup: buildModelsKeyboard() });
  } catch (err) {
    // Например "message is not modified", если состояние не изменилось — не страшно.
    console.error("Не удалось обновить сообщение /model после нажатия кнопки:", err.message);
  }
});

// ==== /memory — память чата по чатам, кнопками ====
// Скрыта из списка команд (не добавлена в setMyCommands ниже) и доступна
// только владельцу — см. isOwner. Работает из любого чата, включая личку
// с ботом: показывает список всех чатов, где бот хоть раз получил
// сообщение (см. knownChats/rememberKnownChat), по каждому — пункты
// памяти с кнопками удаления и кнопкой добавления нового пункта. Добавить
// пункт можно из ЛЮБОГО места — после нажатия "➕ добавить" следующее
// текстовое сообщение владельца (в любом чате) уйдёт в память выбранного
// чата (см. pendingMemoryAdd и перехват в самом начале message:text).
function buildMemoryChatsKeyboard() {
  const rows = [...knownChats.entries()]
    .sort((a, b) => a[1].localeCompare(b[1], "ru"))
    .map(([chatId, title]) => {
      const count = getMemoryList(chatId).length;
      const label = `${title}${count ? ` (${count})` : ""}`.slice(0, 64);
      return [{ text: label, callback_data: `memview:${chatId}` }];
    });
  return { inline_keyboard: rows };
}

function buildMemoryItemsText(chatId) {
  const title = knownChats.get(chatId) || String(chatId);
  const list = getMemoryList(chatId);
  if (list.length === 0) return `«${title}» — память пока пуста`;
  const lines = list.map(
    (item, i) => `${i + 1}. ${item.text}${item.addedBy ? ` (добавил: ${item.addedBy})` : ""}`
  );
  return `«${title}»:\n${lines.join("\n")}`;
}

function buildMemoryItemsKeyboard(chatId) {
  const list = getMemoryList(chatId);
  const rows = list.map((item, i) => [
    { text: `❌ ${i + 1}. ${item.text}`.slice(0, 64), callback_data: `memdel:${chatId}:${i + 1}` },
  ]);
  rows.push([{ text: "➕ добавить", callback_data: `memadd:${chatId}` }]);
  rows.push([{ text: "← к списку чатов", callback_data: "memback" }]);
  return { inline_keyboard: rows };
}

bot.command("memory", async (ctx) => {
  if (!isOwner(ctx)) return;
  if (knownChats.size === 0) {
    await ctx.reply("пока не знаю ни одного чата — бот должен хотя бы раз получить в нём сообщение");
    return;
  }
  await ctx.reply("память по чатам — выбери чат:", { reply_markup: buildMemoryChatsKeyboard() });
});

// Обработка кнопок /memory. Отдельный обработчик callback_query (grammY
// цепочкой прогоняет несколько таких через next() — см. пояснение у
// setmodel: выше), закрыт владельцем так же, как и сама команда.
bot.on("callback_query:data", async (ctx, next) => {
  const data = ctx.callbackQuery.data;
  if (!data.startsWith("mem")) return next();

  if (!isOwner(ctx)) {
    await ctx.answerCallbackQuery({ text: "это только для хозяина", show_alert: true });
    return;
  }

  if (data === "memback") {
    pendingMemoryAdd.delete(ctx.from.id);
    await ctx.editMessageText("память по чатам — выбери чат:", { reply_markup: buildMemoryChatsKeyboard() });
    await ctx.answerCallbackQuery();
    return;
  }

  if (data.startsWith("memview:")) {
    const chatId = Number(data.slice("memview:".length));
    await ctx.editMessageText(buildMemoryItemsText(chatId), { reply_markup: buildMemoryItemsKeyboard(chatId) });
    await ctx.answerCallbackQuery();
    return;
  }

  if (data.startsWith("memdel:")) {
    const [, chatIdRaw, idxRaw] = data.split(":");
    const chatId = Number(chatIdRaw);
    const idx = Number(idxRaw);
    removeMemoryItem(chatId, idx);
    await ctx.editMessageText(buildMemoryItemsText(chatId), { reply_markup: buildMemoryItemsKeyboard(chatId) });
    await ctx.answerCallbackQuery({ text: "убрал" });
    return;
  }

  if (data.startsWith("memadd:")) {
    const chatId = Number(data.slice("memadd:".length));
    pendingMemoryAdd.set(ctx.from.id, chatId);
    const title = knownChats.get(chatId) || String(chatId);
    await ctx.answerCallbackQuery();
    await ctx.reply(`пришли текст, что запомнить для «${title}» — следующим сообщением, откуда угодно`, {
      reply_markup: { inline_keyboard: [[{ text: "❌ отмена", callback_data: "memaddcancel" }]] },
    });
    return;
  }

  if (data === "memaddcancel") {
    pendingMemoryAdd.delete(ctx.from.id);
    await ctx.editMessageText("отменил, ничего не добавил");
    await ctx.answerCallbackQuery();
    return;
  }

  return next();
});

bot.command("gender", async (ctx) => {
  const chatId = ctx.chat.id;
  const raw = (ctx.match || "").trim().toLowerCase();
  const target = ctx.message.reply_to_message?.from || ctx.from;
  const targetLabel = target.first_name || target.username || "этот юзер";

  if (!raw) {
    const current = getGender(chatId, target.id);
    await ctx.reply(
      current
        ? `сейчас для ${targetLabel} стоит: ${current === "m" ? "мужской" : "женский"}`
        : `пол для ${targetLabel} не задан — напиши /gender м или /gender ж (можно реплаем на чьё-то сообщение)`
    );
    return;
  }

  const MALE_WORDS = new Set(["м", "муж", "мужской", "male", "m"]);
  const FEMALE_WORDS = new Set(["ж", "жен", "женский", "female", "f"]);

  let gender;
  if (MALE_WORDS.has(raw)) gender = "m";
  else if (FEMALE_WORDS.has(raw)) gender = "f";
  else {
    await ctx.reply("не понял — напиши /gender м или /gender ж");
    return;
  }

  setGender(chatId, target.id, gender, "manual");
  await ctx.reply(`ок, записал: ${targetLabel} — ${gender === "m" ? "мужской" : "женский"}`);
});

// ==== Команда и кнопки для крокодила ====
// /krokodil работает как обычная команда — независимо от того, что в
// группе бот обычно отвечает только "по имени"/реплаем/упоминанием (это
// правило касается message:text, а не bot.command). Показывает либо
// приглашение стать ведущим (если раунда сейчас нет), либо статус
// текущего раунда — и в обоих случаях таблицу лидеров чата.
async function sendKrokodilIdleMessage(ctx, chatId) {
  const text = `🐊 Крокодил свободен — жми кнопку, чтобы стать ведущим и получить слово.\n\n${formatKrokodilLeaderboard(chatId)}`;
  await ctx.reply(text, { reply_markup: krokodilIdleKeyboard() });
}

bot.command("krokodil", async (ctx) => {
  const chatId = ctx.chat.id;
  const game = getKrokodilGame(chatId);

  if (!game || game.status === "idle") {
    await sendKrokodilIdleMessage(ctx, chatId);
    return;
  }

  if (game.status === "choosing") {
    await ctx.reply(`${game.candidateName} сейчас выбирает сложность слова — подожди секунду`);
    return;
  }

  // status === "active"
  await ctx.reply(
    `идёт раунд — ведёт ${game.hostName}, остальные угадывают словом в чат.\n\n${formatKrokodilLeaderboard(chatId)}`
  );
});

// /krokodil_reset — ручной "рестарт": принудительно закрывает текущий
// раунд (в статусе "choosing" ИЛИ "active") и возвращает игру в "idle" —
// не дожидаясь автосброса по таймауту (см. KROKODIL_TIMEOUT_MS выше).
// Специально доступна ЛЮБОМУ в чате, а не только ведущему/владельцу:
// единственный сценарий, ради которого она вообще нужна — ведущий взял
// слово и пропал, так что дожидаться его же команды на сброс бессмысленно.
// Читаем raw из Map, а не через getKrokodilGame — не хотим, чтобы
// автосброс по таймауту внутри getKrokodilGame тихо подменил game на уже
// idle ДО того, как мы соберём wasActive/revealedWord для сообщения.
// Счёт игроков (krokodilScores) не трогаем — сбрасывается только сам
// раунд, таблица лидеров чата остаётся как есть.
bot.command("krokodil_reset", async (ctx) => {
  const chatId = ctx.chat.id;
  const game = krokodilGames.get(chatId);

  if (!game || game.status === "idle") {
    await ctx.reply("раунд и так не идёт — жми кнопку, чтобы начать");
    return;
  }

  const wasActive = game.status === "active";
  const revealedWord = wasActive ? game.word : null;
  krokodilGames.set(chatId, { status: "idle", usedWords: game.usedWords || [] });
  saveKrokodilGame(chatId);

  const wordNote = revealedWord ? ` Слово было: «${revealedWord}».` : "";
  await ctx.reply(`🔄 раунд сброшен вручную.${wordNote}\n\n${formatKrokodilLeaderboard(chatId)}`, {
    reply_markup: krokodilIdleKeyboard(),
  });
});

// Естественный триггер вроде "Женя, крокодил" — проверяется в основном
// обработчике текстовых сообщений, ДО шахматно-шашечной логики (см.
// KROKODIL_INTENT_REGEX и блок "Крокодил" там) — специально раньше, чтобы
// незавершённая шахматная/шашечная партия не перехватывала это сообщение
// как попытку хода.

// ВАЖНО: как и у setmodel-обработчика выше — на чужой префикс нужно явно
// передавать управление дальше через next(), иначе апдейт не дойдёт до
// обработчиков ниже по цепочке (например, выбора фильма — см.
// bot.on("callback_query:data") для "movie:" дальше по файлу).
bot.on("callback_query:data", async (ctx, next) => {
  const data = ctx.callbackQuery.data;
  if (!data.startsWith("krokodil:")) return next();

  const chatId = ctx.chat.id;
  const action = data.slice("krokodil:".length);
  const game = getKrokodilGame(chatId);
  const clicker = ctx.callbackQuery.from;

  // --- Кто-то хочет стать ведущим ---
  if (action === "host") {
    if (game && game.status === "active") {
      await ctx.answerCallbackQuery({ text: "раунд уже идёт — дождись, пока кто-то отгадает", show_alert: true });
      return;
    }
    if (game && game.status === "choosing" && game.candidateId !== clicker.id) {
      await ctx.answerCallbackQuery({ text: `${game.candidateName} уже выбирает слово — подожди`, show_alert: true });
      return;
    }

    krokodilGames.set(chatId, {
      status: "choosing",
      candidateId: clicker.id,
      candidateName: krokodilPlayerLabel(clicker),
      usedWords: game?.usedWords || [],
      startedAt: Date.now(),
    });
    saveKrokodilGame(chatId);

    await ctx.answerCallbackQuery();
    try {
      await ctx.editMessageText(`${krokodilPlayerLabel(clicker)} выбирает сложность слова...`, {
        reply_markup: krokodilDifficultyKeyboard(),
      });
    } catch (err) {
      console.error("Не удалось обновить сообщение крокодила (выбор сложности):", err.message);
    }
    return;
  }

  // --- Выбор сложности (только тот, кто нажал "хочу быть ведущим") ---
  if (action.startsWith("diff:")) {
    if (!game || game.status !== "choosing" || game.candidateId !== clicker.id) {
      await ctx.answerCallbackQuery({ text: "эта кнопка не для тебя", show_alert: true });
      return;
    }

    const difficulty = action.slice("diff:".length);
    const { word, usedWords } = pickKrokodilWord(chatId, difficulty);

    krokodilGames.set(chatId, {
      status: "active",
      hostId: clicker.id,
      hostName: krokodilPlayerLabel(clicker),
      word,
      difficulty,
      usedWords,
      startedAt: Date.now(),
    });
    saveKrokodilGame(chatId);

    // show_alert: true — Telegram показывает этот текст ТОЛЬКО тому, кто
    // нажал кнопку (даже в группе), поэтому слово не палится остальным.
    await ctx.answerCallbackQuery({
      text: `Твоё слово (${KROKODIL_DIFFICULTY_LABEL[difficulty]}): ${word}\n\nОбъясняй жестами/синонимами, само слово и однокоренные говорить нельзя!`,
      show_alert: true,
    });

    try {
      await ctx.editMessageText(
        `🐊 Раунд начался! Ведёт ${krokodilPlayerLabel(clicker)} (сложность: ${KROKODIL_DIFFICULTY_LABEL[difficulty]}).\nОстальные — пишите отгадки прямо в чат.`,
        { reply_markup: krokodilActiveKeyboard() }
      );
    } catch (err) {
      console.error("Не удалось обновить сообщение крокодила (старт раунда):", err.message);
    }
    return;
  }

  // --- Ведущий просит показать слово ещё раз ---
  if (action === "show") {
    if (!game || game.status !== "active") {
      await ctx.answerCallbackQuery({ text: "раунд уже не активен", show_alert: true });
      return;
    }
    if (game.hostId !== clicker.id) {
      await ctx.answerCallbackQuery({ text: "эта кнопка только для ведущего", show_alert: true });
      return;
    }
    await ctx.answerCallbackQuery({ text: `твоё слово: ${game.word}`, show_alert: true });
    return;
  }

  // --- Ведущий просит другое слово той же сложности ---
  if (action === "reroll") {
    if (!game || game.status !== "active") {
      await ctx.answerCallbackQuery({ text: "раунд уже не активен", show_alert: true });
      return;
    }
    if (game.hostId !== clicker.id) {
      await ctx.answerCallbackQuery({ text: "эта кнопка только для ведущего", show_alert: true });
      return;
    }
    const { word, usedWords } = pickKrokodilWord(chatId, game.difficulty);
    krokodilGames.set(chatId, { ...game, word, usedWords });
    saveKrokodilGame(chatId);
    await ctx.answerCallbackQuery({
      text: `новое слово (${KROKODIL_DIFFICULTY_LABEL[game.difficulty]}): ${word}`,
      show_alert: true,
    });
    return;
  }

  // --- Ведущий сдаётся — раунд заканчивается без победителя ---
  if (action === "giveup") {
    if (!game || game.status !== "active") {
      await ctx.answerCallbackQuery({ text: "раунд уже не активен", show_alert: true });
      return;
    }
    if (game.hostId !== clicker.id) {
      await ctx.answerCallbackQuery({ text: "эта кнопка только для ведущего", show_alert: true });
      return;
    }

    const revealedWord = game.word;
    krokodilGames.set(chatId, { status: "idle", usedWords: game.usedWords });
    saveKrokodilGame(chatId);

    await ctx.answerCallbackQuery({ text: "ладно, раунд окончен" });
    try {
      await ctx.editMessageText(
        `🏳 ${game.hostName} сдался, слово было: «${revealedWord}».\n\n${formatKrokodilLeaderboard(chatId)}`,
        { reply_markup: krokodilIdleKeyboard() }
      );
    } catch (err) {
      console.error("Не удалось обновить сообщение крокодила (сдался):", err.message);
    }
    return;
  }

  await ctx.answerCallbackQuery();
});

// ==== Погода (Open-Meteo, без ключа) ====
// Ходим не напрямую в api.open-meteo.com/geocoding-api.open-meteo.com, а
// через свой Cloudflare Worker-проксик — у Render общий IP-пул на бесплатном
// тарифе, и публичный (без ключа) лимит open-meteo на него быстро ловит 429.
// Воркер шлёт запрос с IP Cloudflare, так что лимит по IP не бьётся с
// остальными Render-клиентами. См. воркер: openmeteo.xyisterio.workers.dev
const METEO_PROXY_BASE = "https://openmeteo.xyisterio.workers.dev/";

async function fetchViaMeteoProxy(targetUrl) {
  return fetch(`${METEO_PROXY_BASE}?url=${encodeURIComponent(targetUrl)}`);
}

// Триггер — слово "погода"/"погоды" в сообщении, адресованном боту (та же
// гейтовая логика, что и у остального: в личке всегда, в группе — после
// имени/реплая/упоминания, см. ниже перед основным блоком). Понимает и
// текущую погоду ("погода в Киеве"), и прогноз ("погода в Киеве на 10
// дней"/"на неделю"). Города — на русском (в т.ч. в разных падежах, см.
// geocodeCity) и на английском, для любой точки на планете — используется
// геокодер Open-Meteo (geocoding-api.open-meteo.com), а не захардкоженный
// список городов.
const WMO_WEATHER = {
  0: { icon: "☀️", desc: "ясно" },
  1: { icon: "🌤", desc: "малооблачно" },
  2: { icon: "⛅", desc: "переменная облачность" },
  3: { icon: "☁️", desc: "пасмурно" },
  45: { icon: "🌫", desc: "туман" },
  48: { icon: "🌫", desc: "изморозь" },
  51: { icon: "🌦", desc: "морось слабая" },
  53: { icon: "🌦", desc: "морось" },
  55: { icon: "🌧", desc: "морось сильная" },
  56: { icon: "🌧", desc: "ледяная морось слабая" },
  57: { icon: "🌧", desc: "ледяная морось сильная" },
  61: { icon: "🌦", desc: "дождь слабый" },
  63: { icon: "🌧", desc: "дождь" },
  65: { icon: "🌧", desc: "дождь сильный" },
  66: { icon: "🌧", desc: "ледяной дождь слабый" },
  67: { icon: "🌧", desc: "ледяной дождь сильный" },
  71: { icon: "🌨", desc: "снег слабый" },
  73: { icon: "❄️", desc: "снег" },
  75: { icon: "❄️", desc: "снег сильный" },
  77: { icon: "❄️", desc: "снежная крупа" },
  80: { icon: "🌦", desc: "ливень слабый" },
  81: { icon: "🌧", desc: "ливень" },
  82: { icon: "⛈", desc: "ливень сильный" },
  85: { icon: "🌨", desc: "снегопад слабый" },
  86: { icon: "❄️", desc: "снегопад сильный" },
  95: { icon: "⛈", desc: "гроза" },
  96: { icon: "⛈", desc: "гроза с градом" },
  99: { icon: "⛈", desc: "гроза с сильным градом" },
};
function describeWeatherCode(code) {
  return WMO_WEATHER[code] || { icon: "🌡", desc: "погода без сюрпризов" };
}

// Разбирает намерение "погода в <город>[ на N дней|на неделю]" из текста.
// Возвращает { city, days } (days=1 — текущая погода) или null.
// ВАЖНО: \b в JS работает через \w, который НЕ включает кириллицу (то же
// уже отмечено в parseRequestedUserColor выше) — поэтому тут вместо \b
// используются обычные пробелы/якоря начала-конца строки.
// Разбирает намерение "погода в <город>[ на N дней|на неделю]" из текста.
// Возвращает { city, days } (days=1 — текущая погода) или null.
// ВАЖНО: \b в JS работает через \w, который НЕ включает кириллицу (то же
// уже отмечено в parseRequestedUserColor выше) — поэтому тут вместо \b
// используются обычные пробелы/якоря начала-конца строки.
//
// Раньше триггер ловил только "погода"/"погоды" (именительный/родительный
// падеж) — из-за этого "пришли ПОГОДУ в Киеве" (винительный падеж) не
// матчился вообще и улетало в обычный LLM-чат, где модель могла попытаться
// сама придумать прогноз вместо реального. Теперь ловим слово "погод..." с
// любым русским окончанием (погода/погоды/погоду/погоде/погодой и т.п.).
// Раньше триггер ловил только "погода"/"погоды" (именительный/родительный
// падеж) — из-за этого "пришли ПОГОДУ в Киеве" (винительный падеж) не
// матчился вообще и улетало в обычный LLM-чат, где модель могла попытаться
// сама придумать прогноз вместо реального. Теперь ловим конкретный набор
// падежных окончаний слова "погода" (а/ы/е/у/ой/ою) — не любое окончание
// подряд, иначе заодно матчилось бы "Погоди" (подожди) и подобные слова,
// начинающиеся на "погод", но не имеющие отношения к погоде.
const WEATHER_WORD_REGEX = /погод(?:а|ы|е|у|ой|ою)(?![а-яё])/i;

// "сегодня"/"завтра"/"послезавтра" — единственные относительные даты,
// которые бот понимает (без полноценного разбора произвольных дат/"через
// 3 дня" и т.п. — это отдельная, более сложная задача). dayOffset: 0/1/2.
const RELATIVE_DAY_REGEX = /(?:^|\s)(?:на\s+)?(послезавтра|завтра|сегодня)(?![а-яё])/i;
const RELATIVE_DAY_OFFSET = { сегодня: 0, завтра: 1, послезавтра: 2 };

// "почасовой прогноз"/"прогноз по часам"/"по часам"/"каждый час" — просьба
// показать не общую сводку за день, а температуру и вероятность осадков по
// каждому часу. Слово "прогноз" рядом с "почасов..."/"по часам" съедаем
// вместе с триггером, иначе оно осталось бы висеть в оставшемся тексте и
// испортило бы дальнейшее вычленение названия города.
const HOURLY_REGEX =
  /(?:^|\s)(?:почасов[а-яё]*(?:\s+прогноз[а-яё]*)?|прогноз[а-яё]*\s+по\s+часам|по\s+часам|каждый\s+час)/i;

function parseWeatherIntent(text) {
  const weatherWordMatch = WEATHER_WORD_REGEX.exec(text);
  if (!weatherWordMatch) return null;
  let rest = text.slice(weatherWordMatch.index + weatherWordMatch[0].length).trim();
  if (!rest) return null;

  let days = 1;
  // dayOffset === null — конкретный день не указан явно (сегодня/сейчас по
  // умолчанию); 0/1/2 — "сегодня"/"завтра"/"послезавтра" явно указаны.
  let dayOffset = null;
  let hourly = false;

  const hourlyMatch = HOURLY_REGEX.exec(rest);
  if (hourlyMatch) {
    hourly = true;
    rest = (rest.slice(0, hourlyMatch.index) + rest.slice(hourlyMatch.index + hourlyMatch[0].length)).trim();
  }

  const relDayMatch = RELATIVE_DAY_REGEX.exec(rest);
  if (relDayMatch) {
    dayOffset = RELATIVE_DAY_OFFSET[relDayMatch[1].toLowerCase()];
    rest = (rest.slice(0, relDayMatch.index) + rest.slice(relDayMatch.index + relDayMatch[0].length)).trim();
  }

  // "на" перед числом/"неделю" необязателен — "погода Киев 10 дней" (без
  // предлога) должна пониматься так же, как "погода в Киеве на 10 дней".
  const weekMatch = /(?:^|\s)(?:на\s+)?недел[а-яё]*/i.exec(rest);
  const daysMatch = /(?:^|\s)(?:на\s+)?(\d{1,2})\s*(?:дн[а-яё]*|days?)/i.exec(rest);
  if (daysMatch) {
    days = Math.min(16, Math.max(1, parseInt(daysMatch[1], 10)));
    rest = rest.slice(0, daysMatch.index).trim();
  } else if (weekMatch) {
    days = 7;
    rest = rest.slice(0, weekMatch.index).trim();
  }

  const hadPreposition = /^(?:в|во|для|по)\s+/i.test(rest);
  rest = rest.replace(/^(?:в|во|для|по)\s+/i, "").trim();
  // "в городе Киев" / "в городе Киеве" — филлер-слово "город(е/а/у)" перед
  // самим названием, из-за геокодер получал бы "городе Киев" целиком и не
  // нашёл бы ничего (геокодинг матчит по префиксу самого имени города, а
  // не по произвольной фразе). Срезаем только когда после него идёт ещё
  // слово — иначе случайно обрежем реальный город, у которого имя само
  // начинается на "город..." (напр. "Городня"), если он указан без филлера.
  rest = rest.replace(/^город[а-яё]*\s+(?=\S)/i, "").trim();
  rest = rest.replace(/[.,!?;:]+$/g, "").trim();
  if (!rest) return null;
  // Без предлога ("погода Львов") принимаем, только если похоже на имя
  // города (с большой буквы) — иначе просто разговорное упоминание погоды
  // ("хорошая погода сегодня") улетало бы в геокодер как имя города.
  if (!hadPreposition && !/^[А-ЯЁA-Z]/.test(rest)) return null;
  return { city: rest, days, dayOffset, hourly };
}


// Геокодинг с фолбэком на грамматические падежи: Open-Meteo матчит только
// по ПРЕФИКСУ индексированного имени (см. docs geocoding-api.open-meteo.com),
// а "Киеве"/"Одессе" — это предложный падеж, не префикс "Киев"/"Одесса".
// Большинство русских окончаний падежей — это 1-2 лишних символа В КОНЦЕ
// слова, так что обрубание хвоста по одному символу обычно и даёт нужный
// префикс ("Киеве" → "Киев" — точное совпадение, "Одессе" → "Одесс" —
// префикс "Одессы"). Пробуем от полной строки и короче, до 3 символов.
// Для ранжирования результатов геокодера: "ё" в написании пользователя
// нередко на деле означает "е" (Королёв/Королев и т.п.), а count=1 в
// Open-Meteo не гарантирует, что вернётся самый крупный/точный по имени
// населённый пункт — маленький посёлок с похожим названием (тоже
// подходящий по префиксу) может обогнать миллионник. Нормализуем и для
// сравнения точности, и приводим population к числу для сравнения размера.
function normalizeCityName(s) {
  return (s || "").toLowerCase().replace(/ё/g, "е");
}

// Оценивает, насколько хорошо кандидат geocoder'а соответствует запросу:
// точное совпадение имени весит намного больше, чем просто совпадение по
// префиксу (на которое опирается geocodeCity из-за падежей) — иначе
// небольшой населённый пункт, начинающийся на то же слово, может
// перевесить нужный крупный город только за счёт населения.
function scoreGeocodeHit(hit, query) {
  const name = normalizeCityName(hit.name);
  const q = normalizeCityName(query);
  const exact = name === q ? 1_000_000_000 : 0;
  const population = Number(hit.population) || 0;
  return exact + population;
}

// Геокодинг с фолбэком на грамматические падежи: Open-Meteo матчит только
// по ПРЕФИКСУ индексированного имени (см. docs geocoding-api.open-meteo.com),
// а "Киеве"/"Одессе" — это предложный падеж, не префикс "Киев"/"Одесса".
// Большинство русских окончаний падежей — это 1-2 лишних символа В КОНЦЕ
// слова, так что обрубание хвоста по одному символу обычно и даёт нужный
// префикс ("Киеве" → "Киев" — точное совпадение, "Одессе" → "Одесс" —
// префикс "Одессы"). Пробуем от полной строки и короче, до 3 символов.
async function geocodeCity(rawCity) {
  const base = rawCity.trim();
  const candidates = [base];
  for (let len = base.length - 1; len >= Math.min(3, base.length); len--) {
    candidates.push(base.slice(0, len));
  }

  for (const candidate of candidates) {
    if (candidate.length < 2) continue;
    try {
      // count=10, а не 1 — чтобы было из чего выбрать: при обрезанном по
      // падежу префиксе под него может подходить сразу несколько мест
      // (крупный город и созвучный посёлок), а нам нужен самый релевантный,
      // а не первый по версии API (см. scoreGeocodeHit).
      const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(
        candidate
      )}&count=10&language=ru&format=json`;
      const res = await fetchViaMeteoProxy(url);
      if (!res.ok) continue;
      const data = await res.json();
      const hits = data?.results;
      if (!hits || hits.length === 0) continue;

      const best = hits.reduce((a, b) => (scoreGeocodeHit(b, base) > scoreGeocodeHit(a, base) ? b : a));

      return {
        name: best.name,
        country: best.country || "",
        admin1: best.admin1 || "",
        latitude: best.latitude,
        longitude: best.longitude,
        timezone: best.timezone || "auto",
      };
    } catch (err) {
      console.error(`Геокодинг "${candidate}" не удался:`, err.message);
    }
  }
  return null;
}

function locationLabel(place) {
  const parts = [place.name];
  if (place.admin1 && place.admin1 !== place.name) parts.push(place.admin1);
  if (place.country) parts.push(place.country);
  return parts.join(", ");
}

// Русские названия дней недели для человекочитаемых дат в ответах о погоде
// — чтобы явно было видно, к какому числу и времени относится прогноз/
// показание (а не просто "1…2…3" без привязки к календарю). Числа месяца —
// в числовом формате DD.MM (раньше было полное название месяца, напр.
// "13 августа" — по просьбе пользователя заменено на "13.08").
const RU_WEEKDAYS_SHORT = ["Вс", "Пн", "Вт", "Ср", "Чт", "Пт", "Сб"]; // Date#getUTCDay(): 0=Вс

function pad2(n) {
  return String(n).padStart(2, "0");
}

// "YYYY-MM-DDTHH:MM" (локальное время места, как отдаёт Open-Meteo при
// заданной timezone) -> "13.08, 14:32".
function formatDateTimeLabel(isoDateTime) {
  const [datePart, timePart] = isoDateTime.split("T");
  const [year, month, day] = datePart.split("-").map(Number);
  return `${pad2(day)}.${pad2(month)}${timePart ? `, ${timePart}` : ""}`;
}

async function fetchCurrentWeatherText(place) {
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}` +
    `&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m` +
    `&timezone=${encodeURIComponent(place.timezone)}`;
  const res = await fetchViaMeteoProxy(url);
  if (!res.ok) throw new Error(`open-meteo forecast: ${res.status}`);
  const data = await res.json();
  const c = data.current;
  const w = describeWeatherCode(c.weather_code);
  // c.time — локальное время места на момент замера (то самое "сейчас"),
  // выводим его явно, а не просто слово "сейчас" без конкретики.
  const whenLabel = c.time ? formatDateTimeLabel(c.time) : null;
  return (
    `Погода в ${locationLabel(place)}${whenLabel ? ` на ${whenLabel} (по местному времени)` : " сейчас"}:\n` +
    `${w.icon} ${w.desc}, ${Math.round(c.temperature_2m)}°C (ощущается как ${Math.round(c.apparent_temperature)}°C)\n` +
    `💧 влажность ${c.relative_humidity_2m}% · 💨 ветер ${Math.round(c.wind_speed_10m)} м/с`
  );
}

async function fetchForecastWeatherText(place, days) {
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}` +
    `&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max` +
    `&forecast_days=${days}&timezone=${encodeURIComponent(place.timezone)}`;
  const res = await fetchViaMeteoProxy(url);
  if (!res.ok) throw new Error(`open-meteo forecast: ${res.status}`);
  const data = await res.json();
  const d = data.daily;
  const lines = [`Погода в ${locationLabel(place)} на ${days} ${daysWordForm(days)}:`];
  for (let i = 0; i < d.time.length; i++) {
    const w = describeWeatherCode(d.weather_code[i]);
    const date = formatShortDate(d.time[i]);
    const tMax = Math.round(d.temperature_2m_max[i]);
    const tMin = Math.round(d.temperature_2m_min[i]);
    const precip = d.precipitation_probability_max[i];
    lines.push(`${date}: ${w.icon} ${tMin}…${tMax}°C, осадки ${precip}%`);
  }
  return lines.join("\n");
}


// Русские подписи для dayOffset (0/1/2) в ответах о конкретном дне.
const DAY_OFFSET_LABEL = { 0: "сегодня", 1: "завтра", 2: "послезавтра" };

// Сводка (мин/макс температура + осадки) на конкретный будущий день
// ("погода в Киеве на завтра") — не текущие показания (open-meteo "current"
// работает только для "сейчас") и не диапазон из нескольких дней, а именно
// один день по смещению от сегодня (dayOffset: 0=сегодня, 1=завтра и т.д.).
async function fetchDaySummaryWeatherText(place, dayOffset) {
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}` +
    `&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max` +
    `&forecast_days=${dayOffset + 1}&timezone=${encodeURIComponent(place.timezone)}`;
  const res = await fetchViaMeteoProxy(url);
  if (!res.ok) throw new Error(`open-meteo forecast: ${res.status}`);
  const data = await res.json();
  const d = data.daily;
  if (!d.time[dayOffset]) throw new Error("day out of range");
  const w = describeWeatherCode(d.weather_code[dayOffset]);
  const date = formatShortDate(d.time[dayOffset]);
  const dayLabel = DAY_OFFSET_LABEL[dayOffset] || date;
  const tMax = Math.round(d.temperature_2m_max[dayOffset]);
  const tMin = Math.round(d.temperature_2m_min[dayOffset]);
  const precip = d.precipitation_probability_max[dayOffset];
  return (
    `Погода в ${locationLabel(place)} на ${dayLabel} (${date}):\n` +
    `${w.icon} ${tMin}…${tMax}°C, осадки ${precip}%`
  );
}

// Почасовой прогноз (температура + вероятность осадков за каждый час) на
// конкретный день (dayOffset: 0=сегодня, 1=завтра, 2=послезавтра). Open-Meteo
// отдаёт hourly-массив по 24 записи на день начиная с сегодняшних 00:00 (в
// таймзоне места) — просто берём срез [dayOffset*24, dayOffset*24+24).
async function fetchHourlyWeatherText(place, dayOffset) {
  // &current=temperature_2m нужен здесь не ради самой температуры (она не
  // используется), а чтобы получить data.current.time — текущее время в
  // ЛОКАЛЬНОЙ таймзоне места (place.timezone), а не время сервера бота: по
  // нему для "сегодня" отсекаем уже прошедшие часы (см. ниже).
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}` +
    `&hourly=temperature_2m,precipitation_probability,weather_code` +
    `&current=temperature_2m` +
    `&forecast_days=${dayOffset + 1}&timezone=${encodeURIComponent(place.timezone)}`;
  const res = await fetchViaMeteoProxy(url);
  if (!res.ok) throw new Error(`open-meteo forecast: ${res.status}`);
  const data = await res.json();
  const h = data.hourly;
  let start = dayOffset * 24;
  const end = Math.min(start + 24, h.time.length);
  if (start >= h.time.length) throw new Error("day out of range");
  // Для "сегодня" (dayOffset=0) прячем уже прошедшие часы — иначе список
  // на весь день загромождён давно истёкшими показаниями (спросил вечером
  // "погода по часам" — незачем видеть, что было в 8 утра). Для "завтра"/
  // "послезавтра" ничего не режем: там всё ещё в будущем целиком.
  if (dayOffset === 0 && data.current?.time) {
    const currentHour = Number(data.current.time.split("T")[1]?.slice(0, 2));
    if (Number.isFinite(currentHour)) {
      while (start < end && Number(h.time[start].split("T")[1]?.slice(0, 2)) <= currentHour) start++;
    }
  }
  const date = formatShortDate(h.time[dayOffset * 24].split("T")[0]);
  const dayLabel = DAY_OFFSET_LABEL[dayOffset] || date;
  if (start >= end) {
    return `Погода в ${locationLabel(place)} по часам на ${dayLabel} (${date}): на сегодня почасовых данных больше не осталось — день закончился, спроси про завтра`;
  }
  const lines = [`Погода в ${locationLabel(place)} по часам на ${dayLabel} (${date}):`];
  for (let i = start; i < end; i++) {
    const timePart = (h.time[i].split("T")[1] || "").slice(0, 5);
    const w = describeWeatherCode(h.weather_code[i]);
    const temp = Math.round(h.temperature_2m[i]);
    const precip = h.precipitation_probability[i];
    lines.push(`${timePart} ${w.icon} ${temp}°C, осадки ${precip}%`);
  }
  return lines.join("\n");
}

// "1 день" / "2 дня" / "5 дней" — русское словообразование числительных.
function daysWordForm(n) {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return "день";
  if ([2, 3, 4].includes(mod10) && ![12, 13, 14].includes(mod100)) return "дня";
  return "дней";
}

// "2026-08-13" -> "Чт, 13.08" (день недели + число.месяц числом).
function formatShortDate(isoDate) {
  const [year, month, day] = isoDate.split("-").map(Number);
  const weekday = RU_WEEKDAYS_SHORT[new Date(Date.UTC(year, month - 1, day)).getUTCDay()];
  return `${weekday}, ${pad2(day)}.${pad2(month)}`;
}

async function handleWeatherQuery(ctx, intent) {
  sendTypingAction(ctx);
  const place = await geocodeCity(intent.city);
  if (!place) {
    await ctx.reply(`не нашёл такой город — "${intent.city}". Проверь название и попробуй ещё раз`);
    return;
  }
  try {
    let text;
    if (intent.hourly) {
      // Почасовой прогноз — если день не уточнён явно, показываем на
      // сегодня (dayOffset=0).
      text = await fetchHourlyWeatherText(place, intent.dayOffset ?? 0);
    } else if (intent.dayOffset) {
      // dayOffset=1/2 ("завтра"/"послезавтра") — сводка на конкретный
      // будущий день. dayOffset=0 ("сегодня") сюда не попадает намеренно —
      // для "сегодня" логичнее показать текущие показания (ветка ниже), а
      // не мин/макс на весь день.
      text = await fetchDaySummaryWeatherText(place, intent.dayOffset);
    } else if (intent.days > 1) {
      text = await fetchForecastWeatherText(place, intent.days);
    } else {
      text = await fetchCurrentWeatherText(place);
    }
    await ctx.reply(text);
  } catch (err) {
    console.error("Ошибка получения погоды:", err);
    await ctx.reply("не получилось узнать погоду, сервис погоды сейчас недоступен — попробуй позже");
  }
}

// ==== Натальная карта / гороскопы ====
//
// Сами расчёты (парсинг даты, построение карты, аспекты, транзиты,
// форматирование в текст) — в natal.js, тут только: хранение даты рождения
// пользователя в Redis, обвязка команды /natal, роутинг запросов гороскопа
// и вызов LLM поверх готового астрологического контекста. Геокодинг города
// переиспользует geocodeCity/locationLabel выше (тот же Open-Meteo, что и
// у погоды) — специально не второй геокодер, чтобы не путать пользователя
// двумя разными базами городов с разным поведением.

// Кэш в памяти процесса поверх Redis — то же самое решение, что у
// deezer_quality (redis.get на каждый чих не нужен, если профиль уже
// читали в этом процессе). В отличие от алиасов/истории чата это НЕ грузим
// целиком при старте (loadPersistedState) — профилей может быть много, а
// нужны они только по явному запросу гороскопа, так что грузим лениво, по
// первому обращению конкретного userId.
const natalProfiles = new Map();

async function getNatalProfile(userId) {
  if (natalProfiles.has(userId)) return natalProfiles.get(userId);
  if (redis) {
    try {
      const data = await redis.get(`natal:${userId}`);
      if (data) {
        natalProfiles.set(userId, data);
        return data;
      }
    } catch (err) {
      console.error(`Не удалось прочитать натальный профиль ${userId} из Redis:`, err.message);
    }
  }
  return null;
}

async function saveNatalProfile(userId, profile) {
  natalProfiles.set(userId, profile);
  if (redis) {
    try {
      await redis.set(`natal:${userId}`, profile);
    } catch (err) {
      console.error(`Не удалось сохранить натальный профиль ${userId} в Redis:`, err.message);
    }
  }
}

async function deleteNatalProfile(userId) {
  natalProfiles.delete(userId);
  if (redis) {
    try {
      await redis.del(`natal:${userId}`);
    } catch (err) {
      console.error(`Не удалось удалить натальный профиль ${userId} из Redis:`, err.message);
    }
  }
}

// Задача для LLM — отдельная под каждый тип запроса (характер/аспекты/
// гороскоп на день/неделю/жизнь), приклеивается поверх SYSTEM_PROMPT (та
// же личность Жени, что и в обычном чате) и реального астрологического
// контекста из natal.js (buildChartContext и т.п.). Ключевое требование
// везде одно и то же — писать ТОЛЬКО по переданным данным, ничего не
// домысливая сверх них (см. аналогичный принцип в BOT_SKILLS_PROMPT про
// погоду: модель не должна изображать, что "знает", то чего у неё нет).
const NATAL_TASK_INSTRUCTIONS = {
  chart:
    "Ниже — реальные астрономические данные натальной карты человека " +
    "(положения планет по знакам и домам + натальные аспекты, посчитанные " +
    "по формулам, а не выдуманные). Опираясь СТРОГО на эти данные, опиши " +
    "характер, сильные и слабые стороны человека — живым языком, в своей " +
    "обычной манере, без списков и заголовков, 4-6 предложений. Явно " +
    "назови по имени хотя бы 3-4 конкретные планеты/знаки/аспекты из " +
    "данных ниже, на которые опирается разбор (не обязательно все — но " +
    "разбор должен быть прямо привязан к конкретике, а не звучать как " +
    "общий текст под любой гороскоп). Не добавляй ни одной планеты, " +
    "знака, дома или аспекта, которых нет в данных ниже. Орб в градусах " +
    "— техническая величина для тебя самой, не зачитывай её пользователю " +
    "дословно, вместо этого словами передай силу аспекта (точно проявлен " +
    "/ фоново ощущается и т.п.), если вообще об этом упоминаешь.",
  aspects:
    "Ниже — список натальных аспектов человека (реальный расчёт углов " +
    "между планетами, не выдумка). Объясни своими словами, что эти " +
    "аспекты в целом говорят о человеке — связным текстом, а не построчным " +
    "разбором каждого аспекта по отдельности, 3-5 предложений. Явно " +
    "назови по имени хотя бы 3-4 конкретных аспекта из списка ниже (какие " +
    "именно планеты и какой тип аспекта — соединение/квадрат/трин и т.п.), " +
    "вплетая их в связный текст — ответ не должен звучать как общее " +
    "описание характера без привязки к конкретным парам планет. Не " +
    "добавляй никаких аспектов сверх списка ниже и не зачитывай орбы в " +
    "градусах дословно.",
  today:
    "Ниже — реальные транзиты (текущие положения планет) и их аспекты к " +
    "натальной карте человека на сегодня. Напиши короткий гороскоп на " +
    "сегодня по этим данным — 3-5 предложений, конкретно и по делу (на " +
    "что обратить внимание, где лёгкость, где напряжение), без общих фраз " +
    "вида \"звёзды говорят\" и без единой детали сверх данных ниже.",
  tomorrow:
    "Ниже — реальные транзиты на завтра и их аспекты к натальной карте. " +
    "Напиши короткий гороскоп на завтра, 3-5 предложений, по тем же " +
    "правилам, что и для \"сегодня\" — только по этим данным, ничего не " +
    "выдумывая сверх них.",
  week:
    "Ниже — транзиты на начало и на конец недели (для сравнения динамики " +
    "внутри недели). Напиши гороскоп на неделю, 4-6 предложений — как " +
    "фон/настроение может меняться от начала к концу недели, опираясь " +
    "только на данные ниже, не выдумывая деталей на конкретные дни.",
  life:
    "Ниже — натальная карта человека (это НЕ прогноз на сегодня, тут " +
    "нет транзитов вообще — только сама карта). Напиши общий разбор " +
    "долгосрочных жизненных тем, склонностей и повторяющихся паттернов, " +
    "5-7 предложений, опираясь только на данные ниже. Не изображай " +
    "конкретные предсказуемые события (даты, имена, точные исходы) — " +
    "натальная карта про склонности и темы, а не про то, что буквально " +
    "случится.",
  // years — единственная инструкция-функция в этом объекте: текст зависит
  // от того, сколько именно лет попросили (1-10), поэтому она не строка, а
  // функция от числа лет (см. askAstroLLM: там же и проверка typeof).
  years: (n) => {
    const count = n || 1;
    const word = yearsWordRuLocal(count);
    return (
      `Ниже — реальные транзиты медленных планет (Юпитер, Сатурн, Уран, ` +
      `Нептун, Плутон) сейчас и через ${count} ${word} — сравнение, куда ` +
      `эти медленные планеты сдвинутся и с какими натальными точками ` +
      `образуют аспект. Это НЕ гороскоп на конкретный день: не изображай ` +
      `точные даты или события — опиши общие долгосрочные тенденции и ` +
      `периоды на этот срок (где вероятны перемены, рост, испытания, ` +
      `завершение старого), опираясь только на данные ниже, 4-7 ` +
      `предложений. Быстрые планеты (Луна, Солнце, Меркурий, Венера, ` +
      `Марс) в этих данных намеренно не участвуют — за ${count} ${word} ` +
      `они проходят полный круг много раз, снимок на день тут бы ничего ` +
      `не значил.`
    );
  },
};

// Небольшой дубль yearsWordRu из natal.js (там она не экспортирована —
// внутренняя деталь форматирования дат, ничего страшного, что и тут своя
// копия ради согласованных склонений в тексте промпта).
function yearsWordRuLocal(n) {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return "год";
  if (mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14)) return "года";
  return "лет";
}

// Тематический фокус — необязательная добавка ПОВЕРХ инструкции периода
// выше (см. askAstroLLM: base + focus). Данные остаются те же самые
// реальные транзиты/аспекты — тема лишь просит модель раскрыть их под
// конкретным углом, а не придумывает новые данные. Для "здоровья" —
// отдельный жёсткий запрет на медицинские советы/диагнозы: связь планет
// со здоровьем — астрологическая традиция, а не медицинский факт, и
// нельзя, чтобы это прозвучало как рекомендация врача.
const THEME_FOCUS_INSTRUCTIONS = {
  health:
    "\n\nДополнительно сделай акцент на теме самочувствия и энергии — " +
    "куда стоит быть внимательнее физически (усталость/подъём сил/дни " +
    "поберечься и т.п.), опираясь на те же данные выше. Это НЕ " +
    "медицинский совет и НЕ диагноз: никогда не называй конкретные " +
    "болезни, симптомы, диагнозы или лечение — только общий фон " +
    "энергии/нагрузки. Если уместно, мягко добавь, что при реальных " +
    "проблемах со здоровьем стоит идти к врачу, а не к гороскопу.",
  love:
    "\n\nДополнительно сделай акцент на теме отношений и личной жизни — " +
    "партнёрство, чувства, общение с близкими, — опираясь на те же " +
    "данные выше.",
  career:
    "\n\nДополнительно сделай акцент на теме работы, карьеры и денег — " +
    "дела, договорённости, финансовые решения, — опираясь на те же " +
    "данные выше.",
};

// Отдельный, но структурно такой же, как askLLM, фолбэк-цикл по TARGETS —
// не переиспользуем сам askLLM, потому что тому нужна история чата и он
// сам кладёт userText/reply в неё по фиксированному формату; тут же в
// сообщении пользователю совсем другой формат (сырые астрологические
// данные, а не то, что реально произнёс человек), и класть ИХ в историю
// как "userText" было бы нечестно по отношению к будущему контексту
// диалога. Персонаж (SYSTEM_PROMPT) тот же, чтобы ответ звучал как Женя, а
// не как безликий астрологический сервис.
// Температура здесь ниже, чем дефолтные 0.9 у обычного чата Жени — та
// живость нужна для болтовни, а не для пересказа реальных вычисленных
// данных. При 0.9 модель иногда "уплывала" в общее описание характера
// вместо конкретных аспектов из dataBlock (одна и та же карта — разный
// по конкретике ответ от раза к разу). 0.5 — заметно устойчивее к теме
// и деталям, но ещё не сухой машинный список.
const ASTRO_TEMPERATURE = 0.5;

async function askAstroLLM(taskType, dataBlock, theme = null, years = null, timeoutMs = REQUEST_TIMEOUT_MS) {
  const rawInstruction = NATAL_TASK_INSTRUCTIONS[taskType];
  const baseInstruction = typeof rawInstruction === "function" ? rawInstruction(years) : rawInstruction;
  const themeFocus = theme && THEME_FOCUS_INSTRUCTIONS[theme] ? THEME_FOCUS_INSTRUCTIONS[theme] : "";
  const messages = [
    { role: "system", content: SYSTEM_PROMPT + buildDateTimeBlock() },
    {
      role: "user",
      content: `${baseInstruction}${themeFocus}\n\n${dataBlock}`,
    },
  ];

  let lastErr;
  const order = computeTargetOrder();
  for (const idx of order) {
    const target = TARGETS[idx];
    try {
      const { reply } = await callTarget(target, messages, timeoutMs, ASTRO_TEMPERATURE);
      cooldownUntil[idx] = 0;
      return reply;
    } catch (err) {
      lastErr = err;
      console.error(
        `Астрология: ошибка [${targetLabel(target)}]:`,
        err.status ?? "-",
        err.body ?? err.message
      );
      if (err.status && !isFallbackWorthy(err.status)) break;
      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }
  throw lastErr ?? new Error("Все провайдеры и модели недоступны");
}

// ==== Перевод и адаптация промпта для генерации картинки ====
// Pollinations (Flux/turbo и т.п.) заметно лучше понимает подробные
// промпты на английском — на русском часто получается мимо темы или
// хуже по композиции. Прогоняем промпт пользователя через тот же пул
// TARGETS/фолбэк, что и askAstroLLM выше (не сам askLLM — это разовая
// техническая задача, а не часть диалога, класть в HISTORY её не нужно).
// Системный промпт намеренно сухой, без персоны Жени — модель тут просто
// инструмент перевода+адаптации, а не собеседник. Температура выше, чем
// у askAstroLLM (0.5) — тут наоборот полезно немного "дорисовать"
// детали (свет, стиль, композицию), а не сухо переводить слово в слово.
const IMAGE_PROMPT_ADAPT_SYSTEM =
  "Ты — инструмент подготовки промптов для text-to-image модели (Flux). " +
  "Тебе дают описание картинки на любом языке (часто на русском, иногда " +
  "с опечатками и сленгом). Переведи и адаптируй его в качественный " +
  "промпт на английском для генерации изображения: сохрани исходный " +
  "смысл и все детали, но при необходимости дополни конкретикой — стиль, " +
  "освещение, композиция, ракурс, — если это поможет лучше передать " +
  "задумку. Ответь ТОЛЬКО готовым промптом на английском, без кавычек, " +
  "без пояснений, без markdown, без вступительных фраз.";
const IMAGE_PROMPT_ADAPT_TIMEOUT_MS = Number(process.env.IMAGE_PROMPT_ADAPT_TIMEOUT_MS) || 20000;

async function translatePromptForImage(prompt) {
  const messages = [
    { role: "system", content: IMAGE_PROMPT_ADAPT_SYSTEM },
    { role: "user", content: prompt },
  ];

  const order = computeTargetOrder();
  for (const idx of order) {
    const target = TARGETS[idx];
    try {
      const { reply } = await callTarget(target, messages, IMAGE_PROMPT_ADAPT_TIMEOUT_MS, 0.8);
      const cleaned = (reply || "").trim().replace(/^["'«]+|["'»]+$/g, "");
      if (cleaned) return cleaned;
    } catch (err) {
      console.error(`translatePromptForImage: ошибка [${targetLabel(target)}]:`, err.status ?? "-", err.body ?? err.message);
      // пробуем следующую цель из TARGETS, cooldown тут не выставляем —
      // это вспомогательная задача, не стоит из-за неё гасить основную
      // модель для обычного чата
    }
  }
  // Если перевод не удался вообще нигде — рисуем по исходному промпту,
  // а не роняем всю генерацию картинки из-за вспомогательного шага.
  return prompt;
}

// "/imggen <промпт>" (а также текстовое "нарисуй ..." в начале сообщения,
// см. DRAW_PREFIX_REGEX и место вызова в bot.on("message:text")) —
// сгенерировать картинку с нуля через Pollinations.ai (см.
// generateImagePollinations ниже). Промпт сначала переводится и
// адаптируется под текст-в-картинку модель (см. translatePromptForImage
// выше) — без ключей, без дневной квоты. Раньше здесь была генерация
// через Gemini (Nano Banana) с поддержкой редактирования референсного
// фото по реплаю, но free tier Gemini на картиночные модели стал
// ненадёжным (все аккаунты разом улетали в 429), поэтому Gemini-ветку
// убрали целиком. Pollinations не поддерживает conversational image
// editing — только text-to-image, так что реплай на фото больше ничего
// не даёт.
async function handleImgGenRequest(ctx, prompt, emptyPromptHint) {
  if (!prompt) {
    await ctx.reply(emptyPromptHint);
    return;
  }

  await sendTypingAction(ctx, "upload_photo");
  try {
    const adaptedPrompt = await translatePromptForImage(prompt);
    const { buffer, mime } = await generateImagePollinations(adaptedPrompt);
    const ext = mime.includes("png") ? "png" : "jpg";
    await ctx.replyWithPhoto(new InputFile(buffer, `imggen.${ext}`), {
      reply_parameters: { message_id: ctx.message.message_id },
      message_thread_id: ctx.message.message_thread_id,
    });
  } catch (err) {
    console.error("Ошибка генерации картинки (Pollinations):", err.message || err);
    await ctx.reply(`не получилось нарисовать: ${(err.message || "").slice(0, 200) || "неизвестная ошибка"}`, {
      reply_parameters: { message_id: ctx.message.message_id },
      message_thread_id: ctx.message.message_thread_id,
    });
  }
}

bot.command("imggen", async (ctx) => {
  const prompt = (ctx.match || "").trim();
  await handleImgGenRequest(ctx, prompt, "напиши, что нарисовать: /imggen рыжий кот в скафандре на Марсе");
});

// "нарисуй ..." в начале сообщения — тот же /imggen, но без слэша, для
// более естественного обращения к боту. Матчим ТОЛЬКО префикс (^), а не
// подстроку где угодно — иначе ловились бы посторонние фразы вроде
// "а помнишь, как я тебе нарисуй просил" или пересказ чужих слов.
// Опциональное обращение по имени/запятая перед словом ("Женя, нарисуй",
// "жень нарисуй") срезается через stripBotAddressing ДО проверки этого
// regex (см. место вызова в bot.on("message:text")), так что здесь сам
// regex рассчитан на текст, где обращение уже вырезано.
// ВАЖНО: тут нельзя использовать \b после "нарисуй" — в JS-регулярках \b
// завязан на \w, а \w не включает кириллицу, поэтому граница между "й" и
// пробелом/концом строки никогда не матчится как word boundary (та же
// грабля уже ловилась раньше в этом файле, см. историю правок про
// распознавание музыкальных запросов). Вместо \b — негативный lookahead:
// следующий символ не должен быть кириллической буквой (чтобы "нарисуйка"
// не матчилось как "нарисуй").
const DRAW_PREFIX_REGEX = /^нарисуй(?![а-яёА-ЯЁ])[,:]?\s*/i;

// "/natal" — без аргументов показывает то, что уже сохранено (или
// инструкцию, если ничего нет); "/natal reset" стирает сохранённые данные;
// "/natal ДД.ММ.ГГГГ[ ЧЧ:ММ] Город" сохраняет/перезаписывает дату рождения.
bot.command("natal", async (ctx) => {
  const userId = ctx.from.id;
  const args = (ctx.match || "").trim();

  if (!args) {
    const saved = await getNatalProfile(userId);
    if (!saved) {
      await ctx.reply(
        "натальную карту ещё не сохранял. Пришли дату рождения командой:\n" +
          "/natal ДД.ММ.ГГГГ ЧЧ:ММ Город\n" +
          "Например: /natal 15.03.1995 14:30 Киев\n" +
          "Время можно не указывать (тогда без домов/Асцендента):\n" +
          "/natal 15.03.1995 Киев"
      );
      return;
    }
    const label = formatSavedProfileLabel(saved, saved.locationLabel);
    await ctx.reply(
      `сейчас сохранено: ${label}\n` +
        "Чтобы поменять — просто пришли /natal с новыми данными ещё раз.\n" +
        "Чтобы стереть — /natal reset"
    );
    return;
  }

  if (/^reset$/i.test(args)) {
    await deleteNatalProfile(userId);
    await ctx.reply("стёр сохранённую дату рождения");
    return;
  }

  const parsed = parseBirthDateArgs(args);
  if (!parsed) {
    await ctx.reply(
      "не смог разобрать. Формат: /natal ДД.ММ.ГГГГ ЧЧ:ММ Город " +
        "(например /natal 15.03.1995 14:30 Киев) — время можно опустить, " +
        "если точно неизвестно"
    );
    return;
  }

  sendTypingAction(ctx);
  const place = await geocodeCity(parsed.cityRaw);
  if (!place) {
    await ctx.reply(`не нашёл такой город — "${parsed.cityRaw}". Проверь название и попробуй ещё раз`);
    return;
  }

  const profile = {
    day: parsed.day,
    month: parsed.month,
    year: parsed.year,
    hour: parsed.hour,
    minute: parsed.minute,
    hasTime: parsed.hasTime,
    latitude: place.latitude,
    longitude: place.longitude,
    timezone: place.timezone,
    locationLabel: locationLabel(place),
  };
  await saveNatalProfile(userId, profile);

  const timeNote = parsed.hasTime
    ? ""
    : "\n(время не указано — Асцендент, MC и дома считать не буду, только знаки планет)";
  await ctx.reply(
    `сохранил: ${formatSavedProfileLabel(profile, profile.locationLabel)}${timeNote}\n` +
      "Теперь можно спросить: \"гороскоп\", \"гороскоп на завтра\", " +
      "\"гороскоп на неделю\", \"гороскоп на жизнь\", \"натальная карта\" " +
      "или \"мои аспекты\"\n\n" +
      "Ошибся в данных? Пришли /natal с новыми — они перезапишут старые. " +
      "Стереть совсем — /natal reset\n\n" +
      "Эти данные привязаны к твоему аккаунту (не к этому чату) — если " +
      "вводишь не свою дату/город (например, в шутку), все дальнейшие " +
      "гороскопы будут считаться по ним, а не по твоим настоящим."
  );
});

// Общий обработчик всех видов запроса гороскопа (см. parseHoroscopeQueryIntent
// в natal.js) — если данных рождения ещё нет, вместо ошибки честно
// подсказывает команду /natal, а не пытается что-то угадать или отправить
// запрос в обычный чат с LLM (та же философия, что у ГЖЁСТКОГО ПРАВИЛА про
// погоду в skills.js: без реальных данных модель ничего не придумывает).
async function handleHoroscopeQuery(ctx, intent) {
  const userId = ctx.from.id;
  const chatId = ctx.chat.id;
  const saved = await getNatalProfile(userId);
  if (!saved) {
    await ctx.reply(
      "у меня ещё нет твоей даты рождения. Пришли:\n" +
        "/natal ДД.ММ.ГГГГ ЧЧ:ММ Город\n" +
        "Например: /natal 15.03.1995 14:30 Киев — и тогда спрашивай гороскоп"
    );
    return;
  }

  sendTypingAction(ctx);
  try {
    const natal = computeNatalProfile(saved);
    let dataBlock, taskType;
    if (intent.type === "chart") {
      dataBlock = buildChartContext(natal);
      taskType = "chart";
    } else if (intent.type === "aspects") {
      dataBlock = buildAspectsOnlyContext(natal);
      taskType = "aspects";
    } else if (intent.period === "tomorrow") {
      dataBlock = buildDayHoroscopeContext(natal, 1);
      taskType = "tomorrow";
    } else if (intent.period === "week") {
      dataBlock = buildWeekHoroscopeContext(natal);
      taskType = "week";
    } else if (intent.period === "years") {
      dataBlock = buildYearsHoroscopeContext(natal, intent.years || 1);
      taskType = "years";
    } else if (intent.period === "life") {
      dataBlock = buildLifeContext(natal);
      taskType = "life";
    } else {
      dataBlock = buildDayHoroscopeContext(natal, 0);
      taskType = "today";
    }

    const theme = intent.theme || null;
    const years = intent.years || null;
    const reply = await askAstroLLM(taskType, dataBlock, theme, years);

    // Шапка с адресатом, датой и темой (если была) — без неё в групповом
    // чате, где гороскоп могут спросить несколько человек подряд, непонятно,
    // кому конкретно ответил бот, на какой день и про какую сферу жизни
    // (см. formatHoroscopeDateLabel в natal.js). Плюс reply_parameters —
    // физический реплай на сообщение человека, а не просто сообщение
    // "в пустоту" рядом.
    // Для "chart" берём подпись из самого intent (chartLabel) — "натальная
    // карта" и "характер" считаются идентично (один и тот же
    // buildChartContext), но заголовок должен отвечать тем же словом,
    // каким спросил человек, а не всегда "натальная карта".
    const displayName = getDisplayName(chatId, ctx.from);
    const dateLabel = intent.type === "chart"
      ? (intent.chartLabel || "натальная карта")
      : formatHoroscopeDateLabel(natal, taskType, theme, years);
    const header = `${dateLabel[0].toUpperCase()}${dateLabel.slice(1)}, для ${displayName}:`;
    await ctx.reply(`${header}\n\n${reply}`, {
      reply_parameters: { message_id: ctx.message.message_id },
    });

    // Кладём в историю чата в упрощённом виде (не сырые данные карты) —
    // чтобы если человек тут же спросит "а почему так?", у бота был
    // контекст, что речь про только что данный гороскоп/разбор характера.
    pushHistory(chatId, "user", `[запрос: ${JSON.stringify(intent)}]`);
    pushHistory(chatId, "assistant", reply);
  } catch (err) {
    console.error("Ошибка гороскопа:", err.status ?? "-", err.body ?? err.message);
    await ctx.reply("не получилось составить гороскоп — все модели сейчас недоступны, попробуй чуть позже");
  }
}

// ==== Таро ====
//
// Сами данные (колода, значения карт, тасовка, расклады, форматирование
// в текст) — в tarot.js, тут только: инструкция для LLM под каждый тип
// расклада, вызов модели поверх готового текстового блока и сама команда/
// роутинг из обычного текста — та же структура, что и у натальной карты
// выше (askAstroLLM/handleHoroscopeQuery), просто без Redis-профиля: для
// Таро не нужно ничего сохранять между сообщениями (кроме детерминизма
// "карты дня" — она уже сама зашита внутри drawDailyCard в tarot.js).
const TAROT_TASK_INSTRUCTIONS = {
  day:
    "Ниже — одна карта Таро, вытянутая случайно (не выдумка), с её " +
    "реальным значением. Опиши, что эта карта говорит на сегодня, " +
    "2-4 предложения, живым языком, опираясь СТРОГО на значение ниже. " +
    "Не добавляй других карт и не выдумывай деталей сверх значения.",
  yesno:
    "Ниже — одна карта Таро как ответ на вопрос человека. Дай короткий " +
    "ответ в духе да/нет/скорее да/скорее нет, опираясь на то, прямая " +
    "карта или перевёрнутая и что она значит (перевёрнутая обычно ближе " +
    "к \"нет\"/затруднению, прямая — к \"да\"/благоприятному ходу), " +
    "2-3 предложения, без выдуманных деталей сверх значения ниже.",
  three:
    "Ниже — расклад из трёх карт Таро (реально вытянутых, не выдуманных) " +
    "по трём позициям. Опиши связный расклад 4-6 предложений: что " +
    "каждая позиция говорит и как они складываются в общую картину. " +
    "Явно упомяни все три карты по именам. Не добавляй карт или " +
    "деталей сверх данных ниже.",
  situation:
    "Ниже — расклад из трёх карт Таро на конкретный вопрос человека " +
    "(ситуация / действие / вероятный итог). Опиши связно, 4-6 " +
    "предложений, явно упомянув все три карты. Не выдумывай ничего " +
    "сверх значений ниже, и не изображай расклад как гарантию исхода — " +
    "Таро про тенденции, а не про точный факт будущего.",
  celtic:
    "Ниже — расклад Таро \"Кельтский крест\" из 10 карт (реально " +
    "вытянутых, не выдуманных) с подписанными позициями. Дай ёмкий, но " +
    "содержательный ответ, 6-9 предложений (не длиннее — ответ идёт " +
    "подписью к фото с ограничением по длине): сначала суть ситуации " +
    "(первые карты), затем внешние влияния и внутреннее состояние " +
    "человека, и в конце — к чему всё идёт (последняя карта). Явно " +
    "упомяни имена всех 10 карт хотя бы по разу, коротко. Не добавляй " +
    "карт или деталей сверх данных ниже, и не изображай итог как " +
    "гарантированный факт — Таро про тенденции.",
};

// Та же логика, что и у ASTRO_TEMPERATURE — реальным вытянутым картам
// нужна устойчивость к конкретике, а не разговорная живость 0.9 по
// умолчанию у обычного чата Жени.
const TAROT_TEMPERATURE = 0.5;

async function askTarotLLM(spreadType, dataBlock, timeoutMs = REQUEST_TIMEOUT_MS) {
  const instruction = TAROT_TASK_INSTRUCTIONS[spreadType];
  const messages = [
    { role: "system", content: SYSTEM_PROMPT + buildDateTimeBlock() },
    { role: "user", content: `${instruction}\n\n${dataBlock}` },
  ];

  let lastErr;
  const order = computeTargetOrder();
  for (const idx of order) {
    const target = TARGETS[idx];
    try {
      const { reply } = await callTarget(target, messages, timeoutMs, TAROT_TEMPERATURE);
      cooldownUntil[idx] = 0;
      return reply;
    } catch (err) {
      lastErr = err;
      console.error(`Таро: ошибка [${targetLabel(target)}]:`, err.status ?? "-", err.body ?? err.message);
      if (err.status && !isFallbackWorthy(err.status)) break;
      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }
  throw lastErr ?? new Error("Все провайдеры и модели недоступны");
}

// "/tarot" — без аргументов делает расклад на три карты; "/tarot день" —
// карта дня; "/tarot кельтский крест[ <вопрос>]" — Кельтский крест, с
// опциональным вопросом после него; "/tarot <вопрос>" — расклад на три
// карты с учётом вопроса (см. runTarotSpread ниже — та же логика выбора
// расклада, что и у parseTarotQueryIntent в tarot.js, продублирована тут
// явно для команды, а не через обычный текст).
bot.command("tarot", async (ctx) => {
  const args = (ctx.match || "").trim();
  if (/^день$/i.test(args)) {
    await runTarotSpread(ctx, "day", null);
    return;
  }
  const celticMatch = /^кельтский\s+крест(?:\s+([\s\S]+))?$/i.exec(args);
  if (celticMatch) {
    await runTarotSpread(ctx, "celtic", celticMatch[1]?.trim() || null);
    return;
  }
  const spreadType = args ? "situation" : "three";
  await runTarotSpread(ctx, spreadType, args || null);
});

// Общий обработчик и для команды /tarot, и для обычного текстового
// триггера (см. parseTarotQueryIntent в конце основного text-хендлера
// ниже). Собирает один коллаж со всеми вытянутыми картами (см.
// tarotImage.js:buildSpreadCollage — перевёрнутые карты показаны
// перевёрнутыми, у каждой карты подписана её позиция в раскладе) и шлёт
// его ОДНИМ сообщением, с текстом расклада подписью к фото — раньше это
// были две карточки: сначала картинки карт по одной, потом текст
// отдельным сообщением-реплаем.
//
// Ограничение Telegram: подпись к фото не может быть длиннее 1024
// символов. Для длинных раскладов (особенно "Кельтский крест", где нужно
// упомянуть все 10 карт) собранный текст иногда в это не влезает — в
// этом случае обрезаем по границе предложения и добавляем "…" (см.
// truncateForCaption ниже), а не молча падаем или разбиваем на два
// сообщения — так расклад всё равно приходит одним сообщением.
const TAROT_CAPTION_LIMIT = 1024;

function truncateForCaption(text, limit) {
  if (text.length <= limit) return text;
  const slice = text.slice(0, limit - 1);
  const lastEnd = Math.max(
    slice.lastIndexOf(". "),
    slice.lastIndexOf("! "),
    slice.lastIndexOf("? "),
    slice.lastIndexOf(".\n")
  );
  let cut;
  if (lastEnd > limit * 0.6) {
    cut = slice.slice(0, lastEnd + 1);
  } else {
    const lastSpace = slice.lastIndexOf(" ");
    cut = slice.slice(0, lastSpace > 0 ? lastSpace : slice.length);
  }
  return `${cut.trimEnd()}…`;
}

async function runTarotSpread(ctx, spreadType, question) {
  sendTypingAction(ctx);
  try {
    const spread = SPREADS[spreadType];
    const drawn =
      spreadType === "day"
        ? [drawDailyCard(ctx.from.id, undefined)]
        : drawCards(spread.count);

    const dataBlock = buildTarotContext(spreadType, drawn, question);
    const rawReply = await askTarotLLM(spreadType, dataBlock);
    // SYSTEM_PROMPT — тот же общий промпт персонажа, что и в обычном чате,
    // а в нём есть инструкция про теги [sticker: ...] (см. extractSticker
    // выше). Для таро своя механика стикеров не нужна, но модель всё равно
    // иногда добавляет тег по инерции — вырезаем его так же, как в
    // обычном чате, просто без последующей отправки стикера.
    const { text: reply } = extractSticker(rawReply);

    const displayName = getDisplayName(ctx.chat.id, ctx.from);
    const label = SPREAD_LABEL_RU[spreadType] || "расклад Таро";
    const header = `${label[0].toUpperCase()}${label.slice(1)}, для ${displayName}:`;
    // Названия карт на русском явно в тексте сообщения (не только на
    // картинке) — без пометки карта прямая, "(перевёрнутая)" только у тех,
    // что выпали перевёрнутыми (тот же принцип, что и в подписи на
    // коллаже — см. tarotImage.js:labelBuffer).
    const cardsLine = drawn
      .map(({ card, reversed }) => `«${card.nameRu}»${reversed ? " (перевёрнутая)" : ""}`)
      .join(", ");
    const cardsWord = drawn.length > 1 ? "Карты" : "Карта";
    const fullText = `${header}\n${cardsWord}: ${cardsLine}\n\n${reply}`;

    let collage;
    try {
      collage = await buildSpreadCollage(spreadType, drawn, spread.positions);
    } catch (err) {
      console.error("Таро: не смог собрать коллаж расклада:", err.message);
      collage = null;
    }

    if (collage) {
      const caption = truncateForCaption(fullText, TAROT_CAPTION_LIMIT);
      await ctx.replyWithPhoto(new InputFile(collage, "tarot.png"), {
        caption,
        reply_parameters: { message_id: ctx.message.message_id },
      });
    } else {
      // Фолбэк на случай, если коллаж почему-то не собрался (например,
      // проблема с sharp на конкретном деплое) — старое поведение: карты
      // по одной картинкой, затем текст отдельным сообщением. Лучше так,
      // чем упасть в ошибку и не ответить вовсе.
      for (const { card } of drawn) {
        const filePath = path.join(process.cwd(), "assets", "tarot", cardImageFileName(card));
        try {
          await ctx.replyWithPhoto(new InputFile(filePath));
        } catch (err) {
          console.error("Таро: не смог отправить картинку карты:", filePath, err.message);
        }
      }
      await ctx.reply(fullText, { reply_parameters: { message_id: ctx.message.message_id } });
    }

    pushHistory(ctx.chat.id, "user", `[запрос Таро: ${spreadType}${question ? ", вопрос: " + question : ""}]`);
    pushHistory(ctx.chat.id, "assistant", reply);
  } catch (err) {
    console.error("Ошибка расклада Таро:", err.status ?? "-", err.body ?? err.message);
    await ctx.reply("не получилось разложить карты — все модели сейчас недоступны, попробуй чуть позже");
  }
}

// ==== Поиск фильмов/сериалов/мультфильмов (TMDB) ====
// Триггер — слово из MOVIE_TRIGGER_WORDS В САМОМ НАЧАЛЕ сообщения (после
// вырезанного обращения к боту), например "фильм <название>[ год]". Это
// специально anchored к началу строки: "Женя, как тебе фильм Аватар?" НЕ
// матчится (сообщение начинается с "как", а не с триггерного слова) и
// просто уходит в обычный LLM-чат — так можно обсудить фильм с моделью, а
// не только запросить карточку из TMDB. Год в конце — опциональный: если
// под указанный год попадает ровно один результат, карточка уходит сразу
// без меню выбора; без года (или при нескольких результатах того же года)
// — динамические кнопки в столбик, как в крокодиле (см.
// krokodilIdleKeyboard/krokodilActiveKeyboard выше и
// bot.on("callback_query:data") ниже для "movie:").
//
// Триггерные слова определяют не только текст запроса, но и куда идти в
// TMDB (kind: "movie" — /search/movie, "tv" — /search/tv) и нужно ли
// после поиска отфильтровать результаты по жанру "Анимация" (id=16) —
// TMDB не разделяет мультфильмы на отдельный тип контента, это обычные
// movie/tv с этим жанром, так что фильтруем сами по genre_ids результата
// поиска (см. filterAnimated). Порядок в списке важен: более длинные/
// специфичные слова ("мультсериал", "мультфильм") должны идти раньше
// более коротких, которые являются их префиксом ("мульт"), иначе в
// alternation-регэкспе короткая альтернатива матчится первой и обрежет
// "фильм"/"сериал" из хвоста слова.
const MOVIE_TRIGGER_WORDS = [
  ["мультсериал", { kind: "tv", animated: true }],
  ["мультфильм", { kind: "movie", animated: true }],
  ["мульт", { kind: "movie", animated: true }],
  ["сериал", { kind: "tv", animated: false }],
  ["фильм", { kind: "movie", animated: false }],
  ["кино", { kind: "movie", animated: false }],
];

// Необязательный "филлер" перед триггерным словом — естественные обёртки
// вида "скинь рецензию на сериал...", "покажи фильм...", "дай инфу про
// сериал...". Раньше регэксп требовал, чтобы триггерное слово шло СТРОГО
// первым, из-за чего "скинь рецензию на сериал Х" не матчился (см. коммент
// выше про "как тебе фильм Аватар?" — тот кейс должен по-прежнему уходить
// в LLM-чат, а не в TMDB, поэтому филлер ограничен глаголами-просьбами и
// фразами "рецензия/отзыв/обзор на", а не любым словом). До двух филлеров
// подряд, чтобы поймать и "скинь", и "скинь мне" и т.п.
const MOVIE_FILLER_WORDS = [
  "скинь",
  "скинуть",
  "покажи",
  "показать",
  "дай",
  "найди",
  "найти",
  "глянь",
  "хочу",
  "посоветуй",
  "порекомендуй",
  "мне",
  "плиз",
  "пожалуйста",
  "рецензию на",
  "рецензия на",
  "отзыв на",
  "отзывы на",
  "обзор на",
  "обзор",
  "инфу про",
  "инфу о",
  "информацию про",
  "информацию о",
  "инфо про",
  "инфо о",
];

// ВАЖНО: не \b — в JS \b завязан на \w, который не включает кириллицу,
// поэтому \b после кириллической буквы никогда не срабатывает (та же
// проблема разобрана в комментарии к nameTriggerRegex выше). Вместо этого
// негативный lookahead: следующий символ не должен быть кириллической
// буквой (чтобы "фильммания" не матчилось как триггер "фильм"). Само
// триггерное слово захватываем в группу — по нему в parseMovieIntent
// определяем kind/animated.
const MOVIE_INTENT_REGEX = new RegExp(
  `^(?:(?:${MOVIE_FILLER_WORDS.join("|")})[,\\s]+){0,2}` +
    `(${MOVIE_TRIGGER_WORDS.map(([w]) => w).join("|")})(?![а-яёА-ЯЁ])[:,]?\\s*(.+)`,
  "i"
);
const TMDB_IMAGE_BASE = "https://image.tmdb.org/t/p/w500";
const TMDB_ANIMATION_GENRE_ID = 16;

function parseMovieIntent(text) {
  const match = MOVIE_INTENT_REGEX.exec(text.trim());
  if (!match) return null;

  const config = MOVIE_TRIGGER_WORDS.find(([word]) => word === match[1].toLowerCase())?.[1];
  if (!config) return null; // не должно случиться — группа взята из того же списка слов

  let rest = match[2].trim();
  if (!rest) return null;

  // Год в конце строки — "Аватар 2009" -> query "Аватар", year "2009".
  // Диапазон 19xx/20xx, чтобы не хватать случайные числа не-годы.
  let year = null;
  const yearMatch = rest.match(/(?:^|\s)((?:19|20)\d{2})\s*$/);
  if (yearMatch) {
    year = yearMatch[1];
    rest = rest.slice(0, yearMatch.index).trim();
  }
  rest = rest.replace(/[.,!?;:]+$/g, "").trim();
  if (!rest) return null;

  return { query: rest, year, kind: config.kind, animated: config.animated };
}

// Единая точка поиска для movie/tv — приводит разные поля TMDB (title/name,
// release_date/first_air_date) к общему виду, чтобы дальше по коду не
// разбирать kind на каждом шагу.
async function searchTmdbTitles(kind, query, year) {
  const endpoint = kind === "tv" ? "tv" : "movie";
  const params = new URLSearchParams({
    api_key: TMDB_API_KEY,
    query,
    language: "ru-RU",
    include_adult: "false",
  });
  if (year) params.set(kind === "tv" ? "first_air_date_year" : "year", year);

  const url = `https://api.themoviedb.org/3/search/${endpoint}?${params.toString()}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`tmdb search ${endpoint}: ${res.status}`);
  const data = await res.json();

  return (data.results || []).map((r) => ({
    id: r.id,
    title: kind === "tv" ? r.name : r.title,
    date: kind === "tv" ? r.first_air_date : r.release_date,
    genreIds: r.genre_ids || [],
  }));
}

// Отфильтровывает результаты по жанру "Анимация" — но только если после
// фильтра что-то остаётся: если у TMDB для конкретного тайтла genre_ids
// почему-то пуст/не проставлен, лучше показать что нашлось, чем ответить
// "ничего нет" на ровном месте.
function filterAnimated(results) {
  const animated = results.filter((r) => r.genreIds.includes(TMDB_ANIMATION_GENRE_ID));
  return animated.length ? animated : results;
}

async function fetchTmdbDetails(kind, id) {
  const endpoint = kind === "tv" ? "tv" : "movie";
  const url = `https://api.themoviedb.org/3/${endpoint}/${id}?api_key=${TMDB_API_KEY}&language=ru-RU`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`tmdb details ${endpoint}: ${res.status}`);
  const data = await res.json();
  return {
    title: kind === "tv" ? data.name : data.title,
    // Оригинальное (не переведённое) название — нужно, чтобы сверять с
    // ним заголовки видео из TMDB/videos: у иностранных тайтлов
    // локализованные трейлеры на английском обычно называются как раз
    // оригинальным именем, а не русским.
    originalTitle: kind === "tv" ? data.original_name : data.original_title,
    date: kind === "tv" ? data.first_air_date : data.release_date,
    voteAverage: data.vote_average,
    genres: data.genres || [],
    overview: data.overview,
    posterPath: data.poster_path,
    seasons: kind === "tv" ? data.number_of_seasons : null,
  };
}

// Достаёт трейлер с TMDB (эндпоинт /videos). Запрашиваем ОБА варианта —
// с language=ru-RU и без language — и объединяем: язык конкретного видео
// определяется его полем iso_639_1, а не тем, какой language стоял в
// запросе (это просто влияет на то, какой набор видео TMDB вообще
// отдаёт), так что смотрим на оба набора сразу. Дальше отдельно ищем
// среди YouTube-видео русское (iso_639_1 === "ru") — если такое есть,
// возвращаем его с isRu: true. Если нет — берём любое (обычно
// оригинальное/английское) и помечаем isRu: false, чтобы вызывающий код
// знал, что это не русский трейлер и мог ещё попробовать YouTube-поиск.
// Возвращает null, если видео нет вовсе.
//
// TMDB — краудсорс-база, и у видео иногда встречается кривая привязка не
// к тому тайтлу (перепутали с одноимённым/похожим фильмом). Поэтому
// доверяем не всем видео подряд, а только тем, чьё название (поле
// "name" у видео) реально пересекается с названием тайтла — русским или
// оригинальным (см. titleMatchesVideo/normalizeForMatch ниже).
async function fetchTmdbTrailerInfo(kind, id, movieTitle, originalTitle) {
  const endpoint = kind === "tv" ? "tv" : "movie";

  async function fetchVideos(lang) {
    const url = `https://api.themoviedb.org/3/${endpoint}/${id}/videos?api_key=${TMDB_API_KEY}${lang ? `&language=${lang}` : ""}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`tmdb videos ${endpoint}: ${res.status}`);
    const data = await res.json();
    return data.results || [];
  }

  const [ruSet, defaultSet] = await Promise.all([fetchVideos("ru-RU"), fetchVideos(null)]);
  const merged = new Map();
  [...ruSet, ...defaultSet].forEach((v) => merged.set(v.key, v));
  const youtube = [...merged.values()].filter((v) => v.site === "YouTube");
  const relevant = youtube.filter(
    (v) => titleMatchesVideo(v.name, movieTitle) || titleMatchesVideo(v.name, originalTitle),
  );

  function pickBest(list) {
    return (
      list.find((v) => v.type === "Trailer" && v.official) ||
      list.find((v) => v.type === "Trailer") ||
      list.find((v) => v.type === "Teaser") ||
      list[0]
    );
  }

  const ruPick = pickBest(relevant.filter((v) => v.iso_639_1 === "ru"));
  if (ruPick) return { url: `https://www.youtube.com/watch?v=${ruPick.key}`, isRu: true };

  const anyPick = pickBest(relevant);
  return anyPick ? { url: `https://www.youtube.com/watch?v=${anyPick.key}`, isRu: false } : null;
}

// Фолбэк, когда на TMDB нет русского трейлера (или вообще никакого) —
// ищем сами на YouTube через yt-search (скрейпинг страницы поиска,
// официального API/ключа не требует). Пробуем сперва запрос с явным
// "русский трейлер" (так чаще всплывают ролики от дубляжных каналов),
// потом просто "трейлер". Из результатов отсеиваем то, что явно не
// трейлер по длительности (полнометражка/эпизод), и предпочитаем видео,
// где слово "трейлер" реально есть в заголовке. Библиотека давно не
// обновлялась и может сломаться, если YouTube поменяет вёрстку —
// поэтому вся функция обёрнута так, чтобы в этом случае просто вернуть
// null, а не уронить бота.
// Убирает пунктуацию/лишние пробелы и приводит к нижнему регистру — нужно
// для сравнения названия фильма с заголовком видео из выдачи YouTube.
function normalizeForMatch(s) {
  return (s || "")
    .toLowerCase()
    .replace(/[«»"'.,:;!?()\-–—]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// Настоящий фильм/сериал сначала на YouTube ищем свободно, но БЕЗ проверки
// релевантности выдача может подсунуть совершенно левое видео — YouTube
// иногда ранжирует общие "трейлерные" каналы выше, чем конкретный тайтл
// (так однажды словили "Киностудия — Русский трейлер" вместо "Кабул").
// Поэтому обязательно требуем, чтобы нормализованное название фильма
// целиком входило в заголовок видео — это отсекает случайные совпадения
// по одному только слову "трейлер".
function titleMatchesVideo(videoTitle, movieTitle) {
  const normVideo = normalizeForMatch(videoTitle);
  const normMovie = normalizeForMatch(movieTitle);
  return normMovie.length > 0 && normVideo.includes(normMovie);
}

async function searchYoutubeTrailerRu(title, year) {
  let yts;
  try {
    ({ default: yts } = await import("yt-search"));
  } catch (err) {
    console.error("yt-search не установлен или не загрузился:", err.message);
    return null;
  }

  // Короткий запрос без "русский"/года — по наблюдению именно такой
  // формулировкой YouTube отдаёт релевантные ролики первыми (см. ручную
  // проверку "кабул трейлер"). Год пробуем вторым заходом — иногда
  // отсекает совсем старые ролики-однофамильцы, но может и увести
  // ранжирование не туда, поэтому он вторичный, а не основной.
  const queries = [`${title} трейлер`, `${title} ${year || ""} трейлер`.trim()];

  for (const q of queries) {
    try {
      const r = await yts(q);
      const candidates = (r.videos || []).filter((v) => v.seconds && v.seconds >= 20 && v.seconds <= 420);
      const pick = candidates.find(
        (v) => titleMatchesVideo(v.title, title) && /трейлер|trailer/i.test(v.title),
      );
      if (pick) return pick.videoId ? `https://www.youtube.com/watch?v=${pick.videoId}` : pick.url || null;
    } catch (err) {
      console.error(`Ошибка yt-search по запросу "${q}":`, err.message);
    }
  }
  return null;
}

// Экранирование под parse_mode: "HTML" — набор спецсимволов у Telegram тут
// значительно меньше, чем у Markdown (только &, <, >), поэтому безопаснее
// для произвольного текста описания с TMDB, чем ручное экранирование
// звёздочек/подчёркиваний markdown.
function escapeHtml(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// ==== Кэш отправленных карточек фильмов/сериалов по message_id ====
// Нужен для реплаев вида "как он тебе?" на карточку — см. блок "Ответ на
// карточку фильма/сериала" в bot.on("message:text"). Карточки шлются в
// обход askLLM, так что без этого кэша модель не знала бы, о каком именно
// тайтле речь. Тот же паттерн, что и у photoCaptionsByMessage выше — живёт
// только в памяти процесса, при рестарте бота просто начнёт заполняться
// заново, ничего критичного.
const MOVIE_CARD_CACHE_LIMIT = 500;
const movieCardsByMessage = new Map(); // `${chatId}:${messageId}` -> { kindLabel, title, year, rating, genres, summary }

function rememberMovieCard(chatId, messageId, card) {
  const key = `${chatId}:${messageId}`;
  movieCardsByMessage.set(key, card);
  if (movieCardsByMessage.size > MOVIE_CARD_CACHE_LIMIT) {
    const oldestKey = movieCardsByMessage.keys().next().value;
    movieCardsByMessage.delete(oldestKey);
  }
}

function getMovieCard(chatId, messageId) {
  return movieCardsByMessage.get(`${chatId}:${messageId}`) || null;
}

// Собирает и отправляет карточку (постер + подпись) по id и kind TMDB.
// threadId — id темы группового чата (проброс из исходного сообщения или
// из callback_query, см. вызовы ниже), replyToMessageId — опционально, на
// какое сообщение отвечать (не используется при отправке из callback, там
// это уже не нужно — старое меню к этому моменту удалено).
async function sendMovieCard(ctx, kind, id, { threadId, replyToMessageId } = {}) {
  let item;
  try {
    item = await fetchTmdbDetails(kind, id);
  } catch (err) {
    console.error("Ошибка получения карточки TMDB:", err.message);
    await ctx.reply("не получилось загрузить карточку, TMDB сейчас недоступен — попробуй позже");
    return;
  }

  const year = item.date ? item.date.slice(0, 4) : "";
  const rating = item.voteAverage ? item.voteAverage.toFixed(1) : null;
  const genres = item.genres.map((g) => g.name).join(", ");

  let caption = `<b>${escapeHtml(item.title)}</b>${year ? ` (${year})` : ""}\n`;
  if (rating) caption += `⭐ ${rating}/10 на TMDB\n`;
  if (genres) caption += `🎬 ${genres}\n`;
  if (kind === "tv" && item.seasons) {
    caption += `📺 сезонов: ${item.seasons}\n`;
  }
  // Лимит подписи к фото у Telegram — 1024 символа, оставляем запас под
  // остальные строки выше (название/рейтинг/жанры/сезоны).
  if (item.overview) {
    let overview = escapeHtml(item.overview);
    if (overview.length > 800) overview = `${overview.slice(0, 800)}…`;
    caption += `\n${overview}`;
  } else {
    caption += `\nописания нет`;
  }

  const opts = { parse_mode: "HTML", message_thread_id: threadId };
  if (replyToMessageId) opts.reply_parameters = { message_id: replyToMessageId };

  let sentMessage;
  if (item.posterPath) {
    sentMessage = await ctx.replyWithPhoto(`${TMDB_IMAGE_BASE}${item.posterPath}`, { ...opts, caption });
  } else {
    // Постера нет — шлём тем же форматированием обычным текстом.
    sentMessage = await ctx.reply(caption, opts);
  }

  // Короткая сводка (без HTML-разметки) для будущего реплая — см.
  // getMovieCard выше и блок "Ответ на карточку фильма/сериала" в
  // bot.on("message:text"). Отдельно от caption, потому что там HTML и
  // более длинный лимит на подпись к фото, а тут это просто кусок будущего
  // промпта для LLM.
  let summary = (item.overview || "").trim();
  if (summary.length > 500) summary = `${summary.slice(0, 500)}…`;
  rememberMovieCard(ctx.chat.id, sentMessage.message_id, {
    kind,
    id,
    kindLabel: kind === "tv" ? "сериал" : "фильм",
    title: item.title,
    originalTitle: item.originalTitle,
    year,
    rating,
    genres,
    summary,
  });
}

function kindNoun(kind, animated) {
  if (kind === "tv") return animated ? "мультсериал" : "сериал";
  return animated ? "мультфильм" : "фильм";
}

async function handleMovieQuery(ctx, intent) {
  if (!TMDB_API_KEY) {
    await ctx.reply("поиск фильмов сейчас не настроен — не задан TMDB_API_KEY");
    return;
  }

  sendTypingAction(ctx);

  let results;
  try {
    results = await searchTmdbTitles(intent.kind, intent.query, intent.year);
  } catch (err) {
    console.error("Ошибка поиска TMDB:", err.message);
    await ctx.reply("не получилось поискать, TMDB сейчас недоступен — попробуй позже");
    return;
  }

  if (intent.animated) results = filterAnimated(results);

  if (!results.length) {
    await ctx.reply(`не нашёл ${kindNoun(intent.kind, intent.animated)} «${intent.query}»${intent.year ? ` (${intent.year})` : ""}`);
    return;
  }

  // Если год указан и под него попадает хотя бы один результат — сужаем
  // выборку до этого года (TMDB и без этого фильтрует не строго).
  let candidates = results;
  if (intent.year) {
    const sameYear = results.filter((r) => (r.date || "").startsWith(intent.year));
    if (sameYear.length) candidates = sameYear;
  }

  if (candidates.length === 1) {
    await sendMovieCard(ctx, intent.kind, candidates[0].id, {
      threadId: ctx.message.message_thread_id,
      replyToMessageId: ctx.message.message_id,
    });
    return;
  }

  // Несколько вариантов — динамические кнопки в столбик (по одной в ряд),
  // как в крокодиле. Ограничиваем 8 штуками, чтобы меню не разрасталось —
  // дальше по релевантности TMDB это обычно уже совсем не то, что искали.
  // kind кладём прямо в callback_data ("movie:movie:<id>"/"movie:tv:<id>"),
  // чтобы при нажатии знать, какой TMDB-эндпоинт дёргать за деталями.
  const keyboard = new InlineKeyboard();
  for (const item of candidates.slice(0, 8)) {
    const yearLabel = item.date ? item.date.slice(0, 4) : "год неизвестен";
    keyboard.text(`${item.title} (${yearLabel})`, `movie:${intent.kind}:${item.id}`).row();
  }

  await ctx.reply(`нашлось несколько вариантов для «${intent.query}», выбери:`, {
    reply_markup: keyboard,
    reply_parameters: { message_id: ctx.message.message_id },
    message_thread_id: ctx.message.message_thread_id,
  });
}

// Обработка нажатия на кнопку выбора из меню выше. Как и у остальных
// callback_query-обработчиков в этом файле (см. setmodel/крокодил выше) —
// явно передаём управление дальше через next() на чужой префикс, иначе
// апдейт не дойдёт до обработчиков дальше по цепочке.
bot.on("callback_query:data", async (ctx, next) => {
  const data = ctx.callbackQuery.data;
  if (!data.startsWith("movie:")) return next();

  const [, kind, id] = data.split(":");
  await ctx.answerCallbackQuery();

  const threadId = ctx.callbackQuery.message?.message_thread_id;

  // Убираем меню выбора — по запросу удаляем само сообщение с кнопками
  // целиком (а не просто снимаем клавиатуру), чтобы вместо него сразу шла
  // карточка. Если удалить не вышло (например, прошло больше 48 часов —
  // Telegram такое не даёт удалить ботам), тихо оставляем меню как есть.
  try {
    await ctx.deleteMessage();
  } catch (err) {
    console.error("Не удалось удалить меню выбора:", err.message);
  }

  await sendMovieCard(ctx, kind, id, { threadId });
});

// ==== Пересказ чата ("о чём тут речь?") ====
// Отдельная механика поверх ChatLog (см. pushChatLog выше): пользователь
// просит вкратце пересказать последние N сообщений в группе — например
// "Женя, о чём тут речь? 100" или "Женя, что я пропустил, 50 сообщений".
// Число — сколько последних сообщений взять из лога; если не указано,
// берём DEFAULT_RECAP_COUNT. Сообщения от других ботов в лог не попадают
// вообще (см. фильтр ctx.from.is_bot в bot.on("message:text")), так что
// отдельно фильтровать их тут не нужно.
const RECAP_INTENT_REGEX =
  /(о\s*чём|о\s*чем)\s+(тут|здесь|в\s+чате)?\s*(речь|говорил|шла\s+речь)|что\s+(тут|здесь)?\s*(обсужда|происходи|писали|было|творил)|перескаж|пересказ|что\s+я\s+пропустил|краткое\s+содержан|саммари\s+чата|сумму\s+чата|сводк/i;
const DEFAULT_RECAP_COUNT = 50;

// ==== Прямой вопрос "кто зашёл/вышел из чата" ====
// Отдельно от общего пересказа (RECAP_INTENT_REGEX/handleRecapQuery): такой
// вопрос — точечный, и на него не нужен пересказ-выжимка от LLM (риск, что
// модель упомянет событие вскользь среди других тем или вовсе упустит его
// в общем списке из 3-7 пунктов). Вместо этого просто фильтруем ChatLog по
// entry.event ("join"/"leave") и отдаём готовые строки как есть — без
// похода в LLM: данные и так точные (сами формируем текст в
// joinLeaveText), гадать тут нечему.
const LEAVE_WORDS_REGEX = /ушел|ушёл|ушла|ушли|вышел|вышла|вышли|покинул|покинула|покинули/i;
const JOIN_WORDS_REGEX = /зашел|зашёл|зашла|зашли|пришел|пришёл|пришла|пришли|вступил|вступила|вступили|подключ/i;
const JOIN_LEAVE_INTENT_REGEX = /кто\s+(ушел|ушёл|ушла|ушли|вышел|вышла|вышли|покинул|покинула|покинули|зашел|зашёл|зашла|зашли|пришел|пришёл|пришла|пришли|вступил|вступила|вступили|подключился|подключилась)/i;

// Возвращает "leave" / "join" / "both" в зависимости от того, какие слова
// встретились в тексте (если упомянуты и уход, и приход — отдаём оба).
function determineJoinLeaveType(text) {
  const hasLeave = LEAVE_WORDS_REGEX.test(text);
  const hasJoin = JOIN_WORDS_REGEX.test(text);
  if (hasLeave && hasJoin) return "both";
  if (hasLeave) return "leave";
  if (hasJoin) return "join";
  return null;
}

async function handleJoinLeaveQuery(ctx, chatId, type) {
  const fullLog = getChatLog(chatId);
  // Та же логика исключения текущего сообщения из выборки, что и в
  // handleRecapQuery — см. комментарий там.
  const wasCurrentMessageLogged = !ctx.from.is_bot && !isForwardedMessage(ctx.message);
  const log = wasCurrentMessageLogged ? fullLog.slice(0, -1) : fullLog;

  const matches = log.filter((m) => m.event && (type === "both" || m.event === type));

  const replyOptions = {
    reply_parameters: { message_id: ctx.message.message_id },
    message_thread_id: ctx.message.message_thread_id,
  };

  if (matches.length === 0) {
    const label = type === "join" ? "заходил" : type === "leave" ? "выходил" : "заходил или выходил";
    await ctx.reply(`за то время, что я помню, никто не ${label}`, replyOptions);
    return;
  }

  await ctx.reply(matches.map((m) => m.text).join("\n"), replyOptions);
}

// Прямой текстовый вопрос про фото/картинку в чате (не реплай на неё) —
// см. использование в bot.on("message:text") ниже, блок про repliedTag.
// Специально пошире (не только "фото", но и "картин(ка)", "снимок",
// "скрин(шот)"), чтобы ловить живые формулировки вроде "как тебе фотка
// кота в чате" или "видел картинку, что скидывали?".
// ВАЖНО: одного этого слова недостаточно — "как сделать скриншот на
// андроид" тоже содержит "скриншот", но никакого фото из чата тут не
// просят. Поэтому ниже это используется ТОЛЬКО вместе с
// PHOTO_CONTEXT_REGEX — вторая проверка на то, что человек явно отсылает
// к чему-то уже виденному/присланному в чате, а не задаёт общий вопрос
// про фото/скриншоты как таковые.
const PHOTO_MENTION_REGEX = /фот(?:о|к)|картин|снимок|скриншот|скрин\b/i;
const PHOTO_CONTEXT_REGEX =
  /в\s+чате|тут|здесь|недавно|скидыва|кида|прислал|присыла|отправля|выложи|выклад|видел|помнишь|что\s+(?:на|за)|как\s+тебе|что\s+думаешь|это\s+фот|эту\s+фот|та\s+фот|тот\s+сним|тот\s+скрин|такое\s+фото/i;
const MAX_RECAP_COUNT = CHAT_LOG_LIMIT;

// Вытаскивает запрошенное число сообщений из текста ("... речь? 100" -> 100).
// Если чисел несколько — берём первое; если чисел нет — null (сработает
// DEFAULT_RECAP_COUNT).
function parseRecapCount(text) {
  const match = text.match(/\d{1,4}/);
  if (!match) return null;
  const n = Number(match[0]);
  if (!Number.isFinite(n) || n <= 0) return null;
  return Math.min(n, MAX_RECAP_COUNT);
}

const RECAP_SYSTEM_PROMPT = `Тебе дана выгрузка последних сообщений группового Telegram-чата в формате "Имя: текст" (для сообщений, адресованных боту, будет пометка "(обращался к боту)"). Твоя задача — коротко и по делу пересказать, о чём шла речь.

Правила:
- Пиши по-русски, живым разговорным языком, без канцелярита и без вступлений вроде "вот пересказ".
- Формат — короткие пункты (списком через дефис), 3-7 пунктов, каждый пункт — максимум 1-2 строки. Указывай, кто о чём говорил, если это понятно из текста.
- Ничего не выдумывай сверх того, что реально написано в переписке.
- Если человек за это время в основном (или только) переписывался с ботом, а не с остальными — сделай по нему отдельный короткий пункт вида "Имя общался(-ась) с ботом о том-то", не пересказывая ответы бота подробно.
- Мелкие технические реплики (одно слово, эмодзи, "+1" и т.п.) не заслуживают отдельного пункта — просто пропускай их.
- Игры (крокодил, шахматы, шашки, игры через других ботов — их реплики в выгрузке не встретятся, они уже отфильтрованы) не разбирай подробно ход за ходом — это фоновая активность, а не тема разговора. Если в этих сообщениях по существу вообще больше ничего не было (только игра), так прямо и напиши одной короткой фразой, например "в основном играли в крокодил" — без списка на 5 пунктов из отдельных раундов. Если для игры отдельно дана таблица лидеров (см. ниже в промпте пользователя) — можешь коротко назвать, кто сейчас лидирует, только по этим цифрам, не по своим догадкам из текста.
- Строки вида "→ Имя зашёл(-ла) в чат" или "→ Имя вышел(-ла) из чата" — это не реплики, а технические события входа/выхода участников. Если такие строки есть в выгрузке, обязательно упомяни их отдельным коротким пунктом (кто зашёл и/или вышел) — обычно в начале сводки, — а дальше пересказывай само общение как обычно. Если таких строк нет, про вход/выход вообще не упоминай.
- Если по существу обсуждать нечего (болтовня ни о чём, спам), но были события входа/выхода — упомяни только их, без остального списка.
- Если по существу обсуждать нечего вообще (ни событий, ни разговора) — так и скажи одной фразой, без списка.`;

// Отдельный вызов LLM в обход основной истории диалога (askLLM/pushHistory) —
// пересказ не должен засорять контекст обычного чата с ботом и не должен
// зависеть от него.
async function askRecapLLM(userPrompt) {
  const messages = [
    { role: "system", content: RECAP_SYSTEM_PROMPT },
    { role: "user", content: userPrompt },
  ];

  const order = computeTargetOrder();

  let lastErr;
  for (const idx of order) {
    const target = TARGETS[idx];
    try {
      const { reply: rawReply } = await callTarget(target, messages);
      const { text: reply } = extractSticker(rawReply); // пересказу стикеры не нужны, просто чистим тег если модель его всё же добавила
      cooldownUntil[idx] = 0;
      return reply;
    } catch (err) {
      lastErr = err;
      console.error(
        `Ошибка пересказа [${targetLabel(target)}]:`,
        err.status ?? "-",
        err.body ?? err.message
      );
      if (err.status && !isFallbackWorthy(err.status)) break;
      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }

  throw lastErr ?? new Error("Все провайдеры и модели недоступны");
}

async function handleRecapQuery(ctx, chatId, requestedCount) {
  const fullLog = getChatLog(chatId);
  // Сам текущий запрос ("Женя, что я пропустил?") уже попал в ChatLog —
  // pushChatLog вызывается ДО этой проверки (см. bot.on("message:text")),
  // так что это гарантированно последняя запись лога. Исключаем её, иначе
  // сводка пересказывает сама себя как "последнее сообщение". Условие
  // повторяет то, при котором pushChatLog реально вызывается для текущего
  // сообщения (не бот, не форвард) — если оно не выполнялось, лог трогать
  // не нужно.
  const wasCurrentMessageLogged = !ctx.from.is_bot && !isForwardedMessage(ctx.message);
  const log = wasCurrentMessageLogged ? fullLog.slice(0, -1) : fullLog;

  if (log.length === 0) {
    await ctx.reply("пока не набралось сообщений в этом чате, чтобы что-то пересказывать");
    return;
  }

  const count = Math.max(1, Math.min(requestedCount || DEFAULT_RECAP_COUNT, log.length));
  const slice = log.slice(-count);

  const transcript = slice
    .map((m) => (m.event ? `→ ${m.text}` : `${m.name}${m.toBot ? " (обращался к боту)" : ""}: ${m.text}`))
    .join("\n");

  // Реальные раунды крокодила ("🎉 Имя угадал(а) слово...") бот шлёт от
  // своего имени, а свои же сообщения в ChatLog не логирует (см. фильтр
  // ctx.from.is_bot) — значит из самой выгрузки модель не может надёжно
  // понять, кто сейчас лидирует. Если счёт в этом чате вообще есть —
  // отдаём модели реальную таблицу лидеров отдельным блоком, чтобы она
  // называла лидера по фактическим цифрам, а не гадала по переписке.
  const krokodilScoreMap = getKrokodilScoreMap(chatId);
  const krokodilBlock =
    krokodilScoreMap.size > 0 ? `\n\nТекущий счёт в крокодиле (реальные данные):\n${formatKrokodilLeaderboard(chatId)}` : "";

  sendTypingAction(ctx);
  try {
    const reply = await askRecapLLM(
      `Вот последние ${slice.length} сообщений чата:\n\n${transcript}${krokodilBlock}`
    );
    await ctx.reply(reply, {
      reply_parameters: { message_id: ctx.message.message_id },
      message_thread_id: ctx.message.message_thread_id,
    });
  } catch (err) {
    console.error("Ошибка при пересказе чата:", err);
    await ctx.reply("не получилось собрать пересказ, попробуй чуть позже");
  }
}

// ==== Фото (пассивное распознавание для лога/пересказа) ====
// Идея: НЕ дёргать основные диалоговые модели (Gemini и т.п.) на каждое
// фото — вместо этого каждое фото в группе тихо (без ответа в чат) уходит
// на отдельную vision-модель (Qwen на Groq, см. GROQ_VISION_MODEL), и её
// короткое описание попадает и в ChatLog (для команды "о чём тут речь"),
// и в обычную HISTORY диалога (см. pushHistory) — чтобы если кто-то потом
// в обычном разговоре спросит бота (на любой модели, необязательно Groq)
// "а что было на фото" — та модель уже увидит текстовое описание в
// контексте и сможет ответить, сама картинку не разбирая и не тратя на
// это токены. Работает только в группах — см. фильтр isGroup в хендлере.
const PHOTO_CAPTION_PROMPT =
  "Кратко опиши по-русски, что на этой фотографии — 1 короткое предложение, без вступлений вроде «на фото изображено». " +
  "Если это скриншот текста/переписки — перескажи суть текста, а не то, как он оформлен. Если еда — что за блюдо. " +
  "Если мем/шутка — в чём соль. Пиши только суть, без markdown и кавычек.\n\n" +
  "После описания, отдельной последней строкой, добавь тег классификации кадра — он не показывается пользователю, только тебе для принятия решения:\n" +
  '- [reaction: nice] — если это визуально красивый, качественный кадр природы/пейзажа/заката, или аппетитно снятая еда.\n' +
  '- [reaction: girl] — если на фото девушка/женщина в обычной одежде/портрет, и снимок красивый, приятный на вид (портрет, качественное фото) — не важно, реальное это фото или явно скачанное из интернета.\n' +
  '- [reaction: beach] — если на фото девушка/женщина в купальнике/бикини, или без одежды, фото женской груди без лица, откровенное фото, или девушка очень красивая.\n' +
  '- [reaction: animal] — если на фото симпатичный домашний кот или собака, и по виду животное ЗДОРОВОЕ: шерсть в порядке, нет явных ран, проплешин, сыпи, гноящихся глаз/носа, истощения, опухолей, хромоты или других признаков болезни/травмы. Если есть хоть малейшее сомнение в здоровье животного на фото (может это фото ветеринарной проблемы, а не просто милого питомца) — НЕ ставь этот тег, ставь none.\n' +
  '- [reaction: none] — если ничего из вышеперечисленного, а также если это животное с признаками болезни/травмы (тогда просто нейтрально опиши это в самом описании, не как милое фото), неясное/смазанное/плохого качества фото, случайный скриншот, посредственное фото человека, обычная случайная картинка без художественной ценности.\n' +
  "Ставь ровно один тег из пяти, всегда, даже если это none. Если сомневаешься между каким-то тегом и none — выбирай none.";

// Реакции (нативные Telegram emoji-реакции на сообщение) для красивых фото —
// см. классификацию в PHOTO_CAPTION_PROMPT выше. Ключ "none" сознательно не
// сюда не попадает — на него реакцию просто не ставим.
const PHOTO_REACTION_EMOJI = {
  nice: "🔥",
  girl: "❤️",
  beach: "🔥",
  animal: "🥰",
};

// Вычленяет тег "[reaction: ключ]" из ответа vision-модели (последняя строка)
// и возвращает { caption, reactionKey } — чистое описание без тега и ключ
// категории (null, если тег "none" или тега нет вовсе / он не распознан).
function extractPhotoReaction(text) {
  const match = text.match(/\n?\[reaction:\s*([a-zA-Zа-яёА-ЯЁ_]+)\]\s*$/i);
  if (!match) return { caption: text.trim(), reactionKey: null };
  const key = match[1].toLowerCase();
  const clean = text.slice(0, match.index).trim();
  return { caption: clean || text.trim(), reactionKey: PHOTO_REACTION_EMOJI[key] ? key : null };
}

// Скачивает файл из Telegram (по file_id) и возвращает сырые байты + путь.
// Общий хелпер и для фото (fetchTelegramFileBase64), и для голосовых
// (transcribeVoice) — раньше эта же логика (getFile + fetch по прямой
// ссылке) была продублирована внутри fetchTelegramFileBase64 целиком.
// Именно скачиваем сами, а не передаём модели прямую ссылку вида
// api.telegram.org/file/bot<TOKEN>/... — иначе токен бота улетел бы
// третьей стороне (серверам Groq, которые бы сами фетчили URL).
async function downloadTelegramFile(ctx, fileId) {
  const file = await ctx.api.getFile(fileId);
  const url = `https://api.telegram.org/file/bot${BOT_TOKEN}/${file.file_path}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Не удалось скачать файл из Telegram: ${res.status}`);
  const buffer = Buffer.from(await res.arrayBuffer());
  return { buffer, filePath: file.file_path };
}

async function fetchTelegramFileBase64(ctx, fileId) {
  const { buffer, filePath } = await downloadTelegramFile(ctx, fileId);
  const mime = filePath.toLowerCase().endsWith(".png") ? "image/png" : "image/jpeg";
  return { base64: buffer.toString("base64"), mime };
}

// Telegram-клиенты шлют музыку двумя разными способами: как полноценный
// "audio" (когда клиент сам распознал ID3-теги и показал плеер с обложкой)
// либо как обычный "document" — так часто прилетает FLAC и вообще всё, что
// клиент не смог красиво распознать как трек. mime_type у документа при
// этом иногда честный ("audio/flac"), а иногда общий
// "application/octet-stream" — поэтому подстраховываемся расширением файла.
const AUDIO_DOCUMENT_EXT_REGEX = /\.(flac|mp3|wav|m4a|ogg|oga|opus|aac|wma)$/i;
function isAudioDocument(document) {
  if (!document) return false;
  if (document.mime_type && document.mime_type.startsWith("audio/")) return true;
  return AUDIO_DOCUMENT_EXT_REGEX.test(document.file_name || "");
}

// Bot API отдаёт getFile (а значит и прямую ссылку на скачивание) только
// для файлов до 20MB — для более крупных file_path будет пустым, и скачивание
// упадёт с малопонятной ошибкой. Проверяем file_size заранее (когда Telegram
// его прислал) и отвечаем понятным текстом вместо попытки скачать.
const MAX_TRANSCRIBE_FILE_SIZE = 20 * 1024 * 1024;

// Видеофайл, присланный "как документ" (редко, но бывает — большие видео,
// которые клиент не стал заворачивать в родной video-плеер). mime_type
// иногда пустой/общий — подстраховываемся расширением, как и с аудио выше.
const VIDEO_DOCUMENT_EXT_REGEX = /\.(mp4|mov|mkv|webm|avi|3gp|m4v)$/i;
function isVideoDocument(document) {
  if (!document) return false;
  if (document.mime_type && document.mime_type.startsWith("video/")) return true;
  return VIDEO_DOCUMENT_EXT_REGEX.test(document.file_name || "");
}

// Любое "видеоподобное" медиа, на которое годится реплай с "шазам" —
// обычное видео, кружочек (video_note) и видео, присланное документом.
// Работает независимо от того, кто прислал видео — сам собеседник, другой
// бот или форвард из канала: см. вызов ниже, там НЕТ проверки
// from.is_bot/isForwardedMessage, в отличие от фонового логирования чата —
// эта команда сознательно должна работать с чужим/пересланным/ботовским
// видео тоже, раз человек явно попросил распознать трек именно из него.
function getShazamMedia(message) {
  if (!message) return null;
  if (message.video) return { fileObj: message.video, mime: message.video.mime_type || "video/mp4" };
  if (message.video_note) return { fileObj: message.video_note, mime: "video/mp4" };
  if (isVideoDocument(message.document)) return { fileObj: message.document, mime: message.document.mime_type || "video/mp4" };
  return null;
}

// Только "полноценное" видео (не кружочек) — на кружочки уже есть отдельный,
// хорошо настроенный путь через распознавание речи (Whisper, см. блок
// voice/video_note/audio ниже), дублировать его визуальным анализом Gemini
// незачем. Обычное видео и видео-документ такого пути не имеют вообще —
// для них единственный способ понять содержимое было бы вручную распознать
// текст на видео, а с Gemini можно сразу пересказать сюжет/действие.
function getVideoOnlyMedia(message) {
  if (!message) return null;
  if (message.video) return { fileObj: message.video, mime: message.video.mime_type || "video/mp4" };
  if (isVideoDocument(message.document)) return { fileObj: message.document, mime: message.document.mime_type || "video/mp4" };
  return null;
}

// ==== Shazam: распознавание трека из видео по явному запросу-реплаю ====
// Специально СТРОГО по запросу (см. вызов ниже, до срабатывания нужен и
// подходящий тип медиа, и совпадение с этим регэкспом) — никогда не
// пытаемся распознать музыку из видео "фоном"/на автомате, даже если видео
// прислали явно с музыкой. node-shazam.recognise() умеет разбирать
// звукодорожку прямо из видеофайла сама (внутри — WASM-порт shazamio-core),
// отдельно вызывать ffmpeg не нужно (в отличие от deprecated fromVideoFile
// у той же библиотеки — она в разы медленнее и тянет отдельный процесс).
const SHAZAM_INTENT_REGEX =
  /шазам|что\s*(?:тут|там|это)?\s*за\s*(?:трек|песня|музыка|мелодия|композиция)|найди\s*(?:мне\s*)?(?:эту\s*|эт[оу]\s*)?(?:песню|трек|музыку)|какая\s*(?:тут|там|это)?\s*(?:играет\s*)?(?:песня|музыка)|распознай\s*(?:трек|песню|музыку)/i;

// node-shazam не подошёл: тянет платформозависимые нативные зависимости
// (@ffmpeg-installer/ffmpeg, shazamio-core), под FreeBSD (serv00) для них
// нет прекомпилированных бинарников. Вместо него — связка из двух чистых
// частей без единого нативного модуля:
//   1) shazam-api — reverse-engineered JS-клиент, сам считает аудио-
//      отпечаток и стучится напрямую в настоящие сервера Shazam;
//      из зависимостей у него только buffer/fft.js/node-fetch, всё JS;
//   2) системный ffmpeg (уже стоит на serv00, см. `ffmpeg -version`) —
//      вызывается напрямую как процесс, декодирует видео в сырой PCM,
//      который и нужен shazam-api на вход.
// Алгоритм внутри shazam-api жёстко рассчитан на 16000 Hz / mono / s16le
// (см. algorithm.js: sampleRateHz = 16000) — ffmpeg просим отдать именно
// такой формат.
const shazamApiClient = new ShazamApi();

function decodeToPcm16k(inputPath) {
  return new Promise((resolve, reject) => {
    const ffmpeg = spawn("ffmpeg", [
      "-i", inputPath,
      "-vn",
      "-ac", "1",
      "-ar", "16000",
      "-f", "s16le",
      "-acodec", "pcm_s16le",
      "pipe:1",
    ]);
    const chunks = [];
    let stderr = "";
    ffmpeg.stdout.on("data", (chunk) => chunks.push(chunk));
    ffmpeg.stderr.on("data", (chunk) => { stderr += chunk; });
    ffmpeg.on("error", reject);
    ffmpeg.on("close", (code) => {
      if (code !== 0) {
        reject(new Error(`ffmpeg завершился с кодом ${code}: ${stderr.slice(-500)}`));
        return;
      }
      resolve(Buffer.concat(chunks));
    });
  });
}

async function recognizeTrackFromBuffer(buffer) {
  const tmpPath = path.join(os.tmpdir(), `shazam_${Date.now()}_${Math.random().toString(36).slice(2)}.mp4`);
  await fs.writeFile(tmpPath, buffer);
  try {
    const pcm = await decodeToPcm16k(tmpPath);
    if (!pcm.length) return null;
    const samples = s16LEToSamplesArray(new Uint8Array(pcm));
    const result = await shazamApiClient.recognizeSong(samples);
    if (!result || !result.title) return null;
    return { title: result.title, artist: result.artist || "" };
  } finally {
    fs.unlink(tmpPath).catch(() => {});
  }
}

// Реплай на видео с командой "шазам"/"что за трек" и т.п. — скачиваем
// файл, прогоняем через Shazam, и при удаче отдаём найденный трек через
// обычный Deezer-пайплайн (handleDeezerQuery) — для пользователя результат
// выглядит так же, как если бы он сам попросил трек по имени. Если Shazam
// ничего не нашёл (не музыкальное видео, тихая дорожка и т.п.) — по
// решению владельца бота просто короткое "не нашёл трек", без попыток
// красиво обыграть неудачу через LLM.
async function handleShazamFromReply(ctx, repliedTo, media) {
  const chatId = ctx.chat.id;
  const replyOpts = {
    reply_parameters: { message_id: repliedTo.message_id },
    message_thread_id: ctx.message.message_thread_id,
  };

  if (media.fileObj.file_size && media.fileObj.file_size > MAX_TRANSCRIBE_FILE_SIZE) {
    await ctx.reply("файл слишком большой (больше 20 МБ), Telegram не даёт его скачать ботам", replyOpts);
    return;
  }

  await withTyping(
    ctx,
    async () => {
      try {
        const { buffer } = await downloadTelegramFile(ctx, media.fileObj.file_id);
        const track = await recognizeTrackFromBuffer(buffer);
        if (!track) {
          await ctx.reply("не нашёл трек", replyOpts);
          return;
        }
        const query = [track.artist, track.title].filter(Boolean).join(" - ");
        await handleDeezerQuery(ctx, query, query);
      } catch (err) {
        console.error(`Shazam: ошибка распознавания трека из видео в чате ${chatId}:`, err.status ?? "-", err.body ?? err.message);
        await ctx.reply("не нашёл трек", replyOpts);
      }
    },
    "upload_document"
  );
}

// ==== Анализ содержимого видео через Gemini (по явному вопросу-реплаю) ====
// Отдельно от Shazam выше: тут не про музыку, а про "что вообще происходит
// в видео" — сюжет, действия, кто/что в кадре. Groq video вообще не
// понимает (только отдельные картинки, см. captionPhoto/GROQ_VISION_MODEL
// выше) — единственный рабочий вариант в текущем стеке это Gemini, и
// именно НАТИВНЫЙ его API (generateContent + inline_data), а не
// OpenAI-совместимый эндпоинт (тот же, что во всех остальных вызовах
// TARGETS/callTarget) — тот у Gemini документированно понимает только
// image_url и input_audio, видео через него не проходит вообще.
// Строго по запросу — реплай на видео с обычным вопросом ("что там?",
// "о чём это", "переведи, что говорят" и т.п.), НИКОГДА не на автомате.
const VIDEO_DESCRIPTION_PROMPT =
  "Опиши по-русски, что происходит в этом видео: сюжет, кто/что в кадре, ключевые действия по порядку — 2-4 предложения. " +
  "Если это отрывок фильма/сериала/ролика/мема — опиши именно происходящее на экране, а не только общую тему. Если в видео " +
  "есть речь — кратко перескажи, о чём говорят, но не расшифровывай дословно слово в слово. Пиши только суть, без markdown " +
  "и без вступлений вроде «в видео показано».";

const GEMINI_VIDEO_MODEL = process.env.GEMINI_VIDEO_MODEL || "gemini-flash-latest";
const GEMINI_VIDEO_TIMEOUT_MS = Number(process.env.GEMINI_VIDEO_TIMEOUT_MS) || 45000;

async function callGeminiNativeVideo(base64Video, mimeType, promptText, timeoutMs = GEMINI_VIDEO_TIMEOUT_MS) {
  let lastErr;
  // Перебираем все настроенные ключи Gemini по очереди (как и везде в
  // боте — GEMINI_API_KEYS может содержать несколько аккаунтов), чтобы
  // исчерпанная дневная квота одного не валила фичу целиком.
  for (const apiKey of GEMINI_API_KEYS) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_VIDEO_MODEL}:generateContent?key=${apiKey}`;
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [
            {
              role: "user",
              parts: [{ text: promptText }, { inline_data: { mime_type: mimeType, data: base64Video } }],
            },
          ],
          generationConfig: { maxOutputTokens: 800 },
        }),
        signal: controller.signal,
      });
      if (!res.ok) {
        const errText = await res.text();
        const err = new Error(`Gemini (видео) вернул ${res.status}`);
        err.status = res.status;
        err.body = errText;
        throw err;
      }
      const data = await res.json();
      const parts = data.candidates?.[0]?.content?.parts || [];
      const text = parts.map((p) => p.text || "").join("").trim();
      if (!text) throw new Error("Пустой ответ от Gemini на видео-запрос");
      return text;
    } catch (err) {
      lastErr = err;
      console.error(
        `Анализ видео Gemini: ошибка [ключ ***${apiKey.slice(-4)}]:`,
        err.status ?? "-",
        err.body ?? err.message
      );
    } finally {
      clearTimeout(timeoutId);
    }
  }
  throw lastErr ?? new Error("Нет доступных ключей Gemini для анализа видео");
}

async function captionVideo(ctx, fileId, mimeType) {
  const { buffer } = await downloadTelegramFile(ctx, fileId);
  const base64 = buffer.toString("base64");
  return callGeminiNativeVideo(base64, mimeType || "video/mp4", VIDEO_DESCRIPTION_PROMPT);
}

// ==== Голосовые/кружочки — расшифровка через Groq Whisper ====
// Отдельный эндпоинт (audio/transcriptions, multipart/form-data) — не тот,
// что в callTarget (chat/completions, JSON) — поэтому свой запрос, без
// переиспользования callTarget. Модель одна и без фолбэка по провайдерам:
// расшифровку из всех подключённых сейчас провайдеров умеет делать только Groq.
const GROQ_WHISPER_ENDPOINT = "https://api.groq.com/openai/v1/audio/transcriptions";
// Голосовые в несколько минут транскрибируются дольше обычного chat-запроса —
// отдельный, более щедрый таймаут, чем REQUEST_TIMEOUT_MS (тот рассчитан на
// обычную LLM-переписку, 20с).
const VOICE_TIMEOUT_MS = Number(process.env.VOICE_TIMEOUT_MS) || 60000;

// Типичные "мусорные" фразы, которые Whisper иногда галлюцинирует на
// тишине/фоновом шуме — наследие того, что модель тренировали в том числе
// на ютуб-субтитрах. Без фильтра такое иногда улетает в чат как будто
// человек это реально сказал.
const WHISPER_HALLUCINATION_PHRASES = [
  "Продолжение следует...",
  "Продолжение следует…",
  "Спасибо за просмотр!",
  "Спасибо за просмотр.",
  "Подписывайтесь на канал",
  "Субтитры сделал DimaTorzok",
  "Редактор субтитров",
  "Корректор А.Егорова",
];

function stripWhisperHallucinations(text) {
  let cleaned = text;
  for (const phrase of WHISPER_HALLUCINATION_PHRASES) {
    cleaned = cleaned.split(phrase).join("");
  }
  return cleaned.replace(/\s{2,}/g, " ").trim();
}

// Пытается распознать через свой GigaAM-Space (см. app.py) — если он не
// настроен (GIGAAM_SPACE пуст), не отвечает вовремя, или падает — просто
// возвращает null, а не бросает исключение: вызывающий код (transcribeVoice)
// в этом случае молча уходит на Groq Whisper, пользователь ничего не
// замечает. Первый запрос после того, как Space "заснул" от простоя, может
// идти долго (холодный старт контейнера + загрузка весов) — GIGAAM_TIMEOUT_MS
// это учитывает.
let gradioClientPromise = null; // переиспользуем соединение между вызовами
function getGradioClient() {
  if (!gradioClientPromise) {
    gradioClientPromise = GradioClient.connect(GIGAAM_SPACE).catch((err) => {
      gradioClientPromise = null; // при неудаче — пробуем переподключиться в следующий раз
      throw err;
    });
  }
  return gradioClientPromise;
}

async function transcribeViaGigaAM(buffer, ext, forceGiga = false) {
  if (!GIGAAM_SPACE) return null;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), GIGAAM_TIMEOUT_MS);
  try {
    const client = await getGradioClient();
    const blob = new Blob([buffer], { type: `audio/${ext}` });
    // force_giga=true — второй вход /transcribe в app.py, пропускает
    // language-id на стороне Space и всегда прогоняет через GigaAM (нужен
    // для ручного "Жень текст giga" ниже). В обычном режиме (false) Space
    // сам определяет язык и на не-русском вернёт "" — тогда просто едем
    // на Whisper как при недоступном Space, никакой отдельной обработки
    // "чужой язык" тут не нужно.
    const result = await client.predict("/transcribe", {
      audio_path: handle_file(blob),
      force_giga: forceGiga,
    });
    const text = (result?.data?.[0] || "").toString().trim();
    return text || null;
  } catch (err) {
    console.error("GigaAM-Space: не удалось распознать, фолбэк на Whisper:", err.message || err);
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

// ==== Озвучка текста через свой F5-TTS_RUSSIAN Space (см. /voice и
// триггер "скажи голосом" ниже) ====
// Тот же принцип, что и GigaAM выше: отдельное соединение (свой Space,
// свой контейнер), холодный старт после простоя может идти долго —
// TTS_TIMEOUT_MS с тем же запасом. Если TTS_SPACE не задан, Space не
// ответил вовремя или упал — synthesizeSpeech просто возвращает null,
// вызывающий код сам решает, как об этом сказать пользователю.
let ttsGradioClientPromise = null;
function getTtsGradioClient() {
  if (!ttsGradioClientPromise) {
    ttsGradioClientPromise = GradioClient.connect(TTS_SPACE).catch((err) => {
      ttsGradioClientPromise = null; // при неудаче — пробуем переподключиться в следующий раз
      throw err;
    });
  }
  return ttsGradioClientPromise;
}

// Убирает то, что вслух звучит криво или вообще не должно озвучиваться —
// блоки кода, инлайн-код, голые ссылки, служебные [теги] вроде
// [sticker: ...] (если вдруг долетят необрезанными). Не идеально, но
// заметно улучшает результат на обычных бытовых ответах бота.
function stripForVoice(text) {
  return (text || "")
    .replace(/```[\s\S]*?```/g, " код прилагается текстом ")
    .replace(/`[^`]+`/g, " ")
    .replace(/https?:\/\/\S+/g, " ссылка ")
    .replace(/\[[a-z_]+:[^\]]*\]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// Возвращает Buffer с аудио или null. text уже должен быть прогнан через
// stripForVoice вызывающим кодом — эта функция ничего не чистит сама,
// просто честно озвучивает то, что ей дали. emotion — необязательный ключ
// настроения (см. EMOTION_REFS в app.py Space'а, moodFromStickerKey ниже),
// по умолчанию "neutral"; если под настроение ещё не записан референс —
// Space сам молча упадёт обратно на neutral, тут ничего разруливать не
// нужно.
async function synthesizeSpeech(text, emotion = "neutral") {
  if (!TTS_SPACE || !text) return null;
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), TTS_TIMEOUT_MS);
  try {
    const client = await getTtsGradioClient();
    // /tts — эндпоинт из своего app.py (см. деплой-инструкцию); референсный
    // голос для клонирования зашит в сам Space (см. EMOTION_REFS), поэтому
    // тут гоняем только текст и ключ настроения, а не аудио-файл.
    const result = await client.predict("/tts", { text }); // TODO: вернуть emotion, когда обновится Space на HF
    const audioUrl = result?.data?.[0]?.url;
    if (!audioUrl) return null;
    const resp = await fetch(audioUrl, { signal: controller.signal });
    if (!resp.ok) return null;
    return Buffer.from(await resp.arrayBuffer());
  } catch (err) {
    console.error("TTS-Space: не удалось озвучить:", err.message || err);
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

// Ручной выбор движка распознавания из текста команды — "Жень текст
// Whisper" / "Жень расшифруй через гигу" и т.п. Нужен на случай, когда
// GigaAM (или, наоборот, авто-язык) ошибается — например, языковая
// детекция на коротком/тихом отрывке песни определила язык неверно, и
// расшифровка (а с ней и весь дальнейший ответ про "о чём песня")
// съехала. "giga"/"гига" ловит и "gigaam"/"гигаам" вариантах написания.
const WHISPER_ENGINE_REGEX = /\bwhisper\b|\bвиспер\b/i;
const GIGA_ENGINE_REGEX = /\bgiga\s*am\b|\bгига\s*ам?\b|\bгига\b/i;

function detectEngineOverride(text) {
  if (!text) return "auto";
  if (WHISPER_ENGINE_REGEX.test(text)) return "whisper";
  if (GIGA_ENGINE_REGEX.test(text)) return "giga";
  return "auto";
}

// Скачивает голосовое/кружочек и прогоняет через GigaAM (если настроен и
// не форсирован Whisper), с фолбэком на Groq Whisper — либо сразу через
// Whisper, если GigaAM не подключен/не справился. engine: "auto" (по
// умолчанию — GigaAM сам решает по языку), "giga" (принудительно, минуя
// language-id) или "whisper" (сразу Groq, GigaAM не трогаем вовсе). Один
// retry на 5xx/сетевую ошибку у Whisper — как в callTarget, но без общего
// cooldown-механизма TARGETS: это разовый точечный вызов, а не часть
// общего фолбэка.
async function transcribeVoice(ctx, fileId, engine = "auto") {
  const { buffer, filePath } = await downloadTelegramFile(ctx, fileId);
  // Telegram отдаёт голосовые с расширением .oga (хотя по факту это тот же
  // контейнер OGG/Opus) — Groq же принимает строго определённый список
  // расширений [flac mp3 mp4 mpeg mpga m4a ogg opus wav webm], где "oga"
  // отсутствует, и на нём падает с 400 invalid_request_error. Поэтому
  // маппим известные "чужие" расширения на то, что реально примет API,
  // вместо того чтобы слепо брать то, что прислал Telegram.
  const rawExt = (filePath.split(".").pop() || "ogg").toLowerCase();
  const EXT_ALIASES = { oga: "ogg" };
  const ext = EXT_ALIASES[rawExt] || rawExt;

  if (engine !== "whisper") {
    const gigaamText = await transcribeViaGigaAM(buffer, ext, engine === "giga");
    if (gigaamText) return { text: gigaamText, engine: "giga" };
    // GigaAM не настроен/не ответил/упал/не тот язык (auto) — либо не
    // справился даже принудительно (giga) — едем на Whisper как раньше.
  }

  let lastErr;
  for (let attempt = 0; attempt < 2; attempt++) {
    const form = new FormData();
    form.append("model", GROQ_WHISPER_MODEL);
    form.append("response_format", "verbose_json");
    form.append("temperature", "0");
    form.append("file", new Blob([buffer]), `audio.${ext}`);

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), VOICE_TIMEOUT_MS);

    let res;
    try {
      res = await fetch(GROQ_WHISPER_ENDPOINT, {
        method: "POST",
        headers: { Authorization: `Bearer ${GROQ_API_KEYS[0]}` },
        body: form,
        signal: controller.signal,
      });
    } catch (err) {
      clearTimeout(timeoutId);
      lastErr = err.name === "AbortError" ? new Error(`Whisper не ответил за ${VOICE_TIMEOUT_MS}мс — таймаут`) : err;
      if (attempt === 0) continue;
      throw lastErr;
    }
    clearTimeout(timeoutId);

    if (!res.ok) {
      if (res.status >= 500 && attempt === 0) {
        lastErr = new Error(`Groq Whisper вернул ${res.status}`);
        continue;
      }
      const errText = await res.text();
      const err = new Error(`Groq Whisper вернул ${res.status}`);
      err.status = res.status;
      err.body = errText.slice(0, 200);
      throw err;
    }

    const data = await res.json();
    const segments = data.segments || [];
    // Как и в референсном плагине для Hikka — сегменты с высоким
    // no_speech_prob (тишина/шум) не считаем реальной речью и выкидываем,
    // иначе Whisper на паузах иногда подставляет случайные слова.
    let text = segments.length
      ? segments
          .filter((s) => (s.no_speech_prob ?? 0) < 0.6)
          .map((s) => s.text.trim())
          .join(" ")
          .trim()
      : (data.text || "").trim();

    text = stripWhisperHallucinations(text);
    return { text, engine: "whisper" };
  }

  throw lastErr ?? new Error("Groq Whisper не ответил после повторной попытки");
}

// ==== Кэш расшифровок голосовых по message_id ====
// Тот же паттерн, что и photoCaptionsByMessage выше — чтобы повторный
// реплай на уже расшифрованное голосовое (например, сначала "текст", потом
// кто-то ещё спросил "о чём там вкратце") не гонял аудио через Whisper
// заново. Живёт только в памяти процесса, не в Redis — недолгоживущий кэш
// для текущей сессии, ничего критичного при потере на рестарте.
const VOICE_TRANSCRIPT_CACHE_LIMIT = 500;
const voiceTranscriptsByMessage = new Map(); // `${chatId}:${messageId}` -> { name, text }

function rememberVoiceTranscript(chatId, messageId, name, text) {
  const key = `${chatId}:${messageId}`;
  voiceTranscriptsByMessage.set(key, { name, text });
  if (voiceTranscriptsByMessage.size > VOICE_TRANSCRIPT_CACHE_LIMIT) {
    const oldestKey = voiceTranscriptsByMessage.keys().next().value;
    voiceTranscriptsByMessage.delete(oldestKey);
  }
}

function getVoiceTranscript(chatId, messageId) {
  return voiceTranscriptsByMessage.get(`${chatId}:${messageId}`) || null;
}

// Реплай на ГС/кружок с просьбой именно дословного текста — "Женя, текст",
// "Жень расшифруй", "распознай, что там", "что он сказал" и т.п. Отдельно
// от обычных вопросов ("о чём тут вкратце?") — те НЕ должны совпадать с
// этим регэкспом, чтобы уйти в обычный LLM-путь ниже (см. использование).
// ВАЖНО: как и в nameTriggerRegex выше — здесь нельзя \b после кириллицы,
// в JS-регулярках \b завязан на \w, а \w не включает кириллицу, поэтому
// \b после кириллических букв никогда не сработает (грабли, на которые я
// сам наступил в первой версии этого регэкспа — "текст" не матчился
// вообще). Для "текст"/"дословно"/"слово в слово" — негативный lookahead
// на кириллицу (не часть более длинного слова вроде "текстовый"). Для
// "расшифр"/"транскри"/"распознай" lookahead не нужен — это сознательно
// префиксы (чтобы ловить "расшифруй"/"расшифровка", "транскрибируй"/
// "транскрипция" и т.п. в одном заходе).
const VOICE_TRANSCRIBE_INTENT_REGEX =
  /^(расшифр|транскри|распознай)|^(текст|дословно|слово\s+в\s+слово)(?![а-яёА-ЯЁ])|^что\s+(он|она|там)?\s*(сказал|говорил)/i;

// Сколько символов расшифровки максимум подмешиваем в промпт модели для
// обычных вопросов по голосовому (не для литерального "текст" — там отдаём
// расшифровку целиком без обрезки). Несколько тысяч символов — это уже
// хватает на голосовое в 4-5 минут разговорной речи, дальше это, скорее
// всего, что-то экстремально длинное, и урезаем, чтобы не раздувать промпт.
const VOICE_TRANSCRIPT_PROMPT_LIMIT = 6000;

function formatVoiceDuration(sec) {
  if (sec == null || !Number.isFinite(sec)) return "";
  const m = Math.floor(sec / 60);
  const s = Math.round(sec % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

// ==== Поиск в интернете по явной просьбе ("Жень поищи в интернете X",
// "Жень глянь в интернете", "Жень поищи в нете инфу", "Жень загугли X" и
// т.п.) ====
// Два случая:
// 1) "загугли"/"погугли"/"нагугли" — сами по себе однозначно означают
//    поиск, место упоминать не нужно.
// 2) Более общие глаголы ("поищи"/"глянь"/"посмотри"/"проверь"/"найди")
//    слишком расплывчаты сами по себе (пересекаются с другими интентами —
//    "найди трек", "глянь карточку" и т.п.), поэтому для них ОБЯЗАТЕЛЬНО
//    требуем ещё и явное упоминание места поиска ("в интернете"/"в нете"/
//    "в сети"/"в гугле"/просто "гугл").
// ВАЖНО: без \b — в JS-регэкспах \b распознаёт границы слов только по
// ASCII-буквам, а не по кириллице (тот же нюанс уже обойдён выше в файле
// через lookahead, см. WEATHER_WORD_REGEX) — \b перед кириллической "в"
// после пробела тут в принципе не сработал бы. Вместо границ слов просто
// матчим корень как подстроку — коллизии в реальных фразах маловероятны.
const SEARCH_STANDALONE_VERB_REGEX = /(?:за|по|на)гугл(?:и|ишь|ить)?/i;
const SEARCH_GENERIC_VERB_REGEX = /(?:по|на)?ищ[иь]|глянь|посмотри|проверь|найд[иь]/i;
const SEARCH_LOCATION_REGEX = /в\s+(?:интернет|нет[еи]|сет[ьи])|гугл/i;

function hasSearchIntent(text) {
  if (!text) return false;
  if (SEARCH_STANDALONE_VERB_REGEX.test(text)) return true;
  return SEARCH_GENERIC_VERB_REGEX.test(text) && SEARCH_LOCATION_REGEX.test(text);
}

// ==== Определение необходимости веб-поиска через LLM (вместо чистого regex) ====
// hasSearchIntent выше остаётся как быстрый и дешёвый первый фильтр (см.
// использование ниже как фолбэка), но у чистого regex по тексту ТЕКУЩЕГО
// сообщения три системных проблемы, которые всплыли на практике:
// 1) слово-триггер ("загугли"/"поищи") никак не вырезается и утекает в сам
//    поисковый запрос — Tavily/Compound ищут по фразе "Загугли курс
//    доллара", а не по теме;
// 2) короткие follow-up'ы без темы ("Ну загугли") бесполезны — тема была в
//    предыдущих репликах, а regex видит только текущее сообщение;
// 3) естественные формулировки без прямого глагола-повеления ("а если в
//    интернете посмотреть?") вообще не ловятся.
// Эта функция решает все три: даём лёгкой модели последние HISTORY_LIMIT
// сообщений диалога (тот же формат, что и в основной истории для askLLM) и
// просим её самой решить, нужен ли поиск, и если да — сформулировать
// самодостаточный запрос (без "загугли", с уточнениями типа "Украина"/
// "НБУ", если это следует из переписки).
// Раньше тут был захардкожен ОДИН конкретный провайдер/модель/ключ
// (GROQ_API_KEYS[0] + одна groq-модель) без вообще какого-либо фолбэка —
// на практике это привело к тому, что классификация молча падала целиком,
// стоило именно этой конкретной модели стать недоступной (напр. снятой с
// доступа у Groq, см. "model_not_found" в логах), даже если остальные
// 10+ моделей/аккаунтов в TARGETS работали нормально. Теперь используем
// тот же устойчивый паттерн полного перебора пула TARGETS с cooldown, что
// и в askAstroLLM/askLLM — одна неисправная цель просто уходит в cooldown
// и подхватывается следующая по порядку (см. computeTargetOrder).
const SEARCH_INTENT_TIMEOUT_MS = Number(process.env.SEARCH_INTENT_TIMEOUT_MS) || 8000;
// Температура ниже дефолтной (0.9) — это классификация/извлечение факта из
// диалога, а не творческая болтовня в персоне; нужна стабильность
// формата (либо голый запрос, либо ровно "NONE"), а не разнообразие.
const SEARCH_INTENT_TEMPERATURE = 0.2;

const SEARCH_INTENT_SYSTEM_PROMPT =
  "Ты определяешь, нужен ли для ответа на ПОСЛЕДНЕЕ сообщение пользователя " +
  "актуальный веб-поиск (новости, курсы валют, погода, свежие факты, " +
  "события, даты — всё, что модель не может надёжно знать сама или что " +
  "могло устареть). Учитывай контекст всей переписки выше — если тема " +
  "поиска упоминалась раньше (например пользователь до этого спрашивал " +
  "про курс доллара, а потом просто написал \"загугли\" без темы), " +
  "восстанови тему из истории.\n\n" +
  "Если поиск нужен — ответь ТОЛЬКО самим поисковым запросом на русском " +
  "языке, без слов вроде \"загугли\"/\"поищи\"/\"глянь\", без кавычек и " +
  "пояснений — запрос должен быть понятен сам по себе, вне контекста " +
  "переписки (добавь уточнения по стране/валюте/дате, если это следует из " +
  "переписки, например \"курс доллара к гривне НБУ сегодня\", а не просто " +
  "\"курс доллара\").\n\n" +
  "Если поиск НЕ нужен (бытовой разговор, мнение, шутка, вопрос про то, " +
  "что и так уже есть в истории переписки) — ответь ровно одним словом: " +
  "NONE\n\n" +
  "Ничего кроме поискового запроса или NONE в ответе быть не должно.";

async function classifySearchIntent(chatId, rawText) {
  const messages = [
    { role: "system", content: SEARCH_INTENT_SYSTEM_PROMPT },
    ...getHistory(chatId),
    { role: "user", content: rawText },
  ];

  let lastErr;
  const order = computeTargetOrder();
  for (const idx of order) {
    const target = TARGETS[idx];
    try {
      const { reply } = await callTarget(target, messages, SEARCH_INTENT_TIMEOUT_MS, SEARCH_INTENT_TEMPERATURE);
      cooldownUntil[idx] = 0;
      const trimmed = (reply || "").trim().replace(/^["«]+|["»]+$/g, "");
      if (!trimmed || /^NONE$/i.test(trimmed)) return null;
      return trimmed;
    } catch (err) {
      lastErr = err;
      console.error(
        `Классификация поискового интента: ошибка [${targetLabel(target)}]:`,
        err.status ?? "-",
        err.body ?? err.message
      );
      if (err.status && !isFallbackWorthy(err.status)) break;
      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }
  throw lastErr ?? new Error("Все провайдеры и модели недоступны");
}

// Отдельный точечный вызов vision-модели — в обход askLLM/TARGETS-фолбэка:
// тут только одна конкретная модель (GROQ_VISION_MODEL), без перебора
// провайдеров, потому что это узкоспециальная задача, а не общий чат.
// callTarget переиспользуем как есть — он уже умеет reasoning_effort для
// qwen-моделей на groq, таймаут, чистку <think>/утечек рассуждений и т.п.
async function captionPhoto(ctx, fileId) {
  const { base64, mime } = await fetchTelegramFileBase64(ctx, fileId);
  const visionTarget = {
    provider: "groq",
    model: GROQ_VISION_MODEL,
    baseUrl: PROVIDER_CONFIGS.groq.baseUrl,
    apiKey: GROQ_API_KEYS[0],
  };
  const messages = [
    {
      role: "user",
      content: [
        { type: "text", text: PHOTO_CAPTION_PROMPT },
        { type: "image_url", image_url: { url: `data:${mime};base64,${base64}` } },
      ],
    },
  ];
  const { reply } = await callTarget(visionTarget, messages);
  return extractPhotoReaction(reply);
}

// ==== Генерация картинок — Pollinations.ai ====
// Полностью бесплатный, без API-ключа и без дневной квоты. Раньше здесь
// была генерация через Gemini (Nano Banana, gemini-2.5-flash-image) с
// поддержкой conversational image editing по референсному фото, но free
// tier на картиночные модели Gemini стал ненадёжным (все аккаунты сразу
// упирались в 429), и Gemini-ветку убрали целиком. Pollinations не умеет
// редактировать существующее фото — только генерация с нуля по тексту.
// GET-эндпоинт, картинка возвращается прямо в теле ответа (JPEG/PNG).
const POLLINATIONS_TIMEOUT_MS = Number(process.env.POLLINATIONS_TIMEOUT_MS) || 60000;

async function generateImagePollinations(prompt) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), POLLINATIONS_TIMEOUT_MS);
  try {
    // nologo=true убирает водяной знак, seed — случайный, чтобы повторный
    // промпт не возвращал закэшированную ту же самую картинку.
    const seed = Math.floor(Math.random() * 1_000_000_000);
    const url =
      `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}` +
      `?nologo=true&seed=${seed}`;
    const res = await fetch(url, { signal: controller.signal }).finally(() => clearTimeout(timeoutId));
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      throw new Error(`status ${res.status}: ${text.slice(0, 300)}`);
    }
    const arrayBuffer = await res.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);
    if (!buffer.length) throw new Error("Pollinations вернул пустой ответ");
    const contentType = res.headers.get("content-type") || "";
    return { buffer, mime: contentType.includes("png") ? "image/png" : "image/jpeg" };
  } catch (err) {
    clearTimeout(timeoutId);
    throw err;
  }
}

// ==== Поиск в интернете (Groq Compound) ====
// Разделение по задачам, как просили: Compound сам решает, гуглить ли,
// реально ходит в интернет и возвращает сырой фактический конспект — НЕ
// финальный ответ в персоне Жени. Этот конспект дальше подмешивается
// тегом в userText (см. SEARCH_INTENT_REGEX/hasSearchIntent и место
// вызова в bot.on("message:text")) и уходит в обычный askLLM/TARGETS —
// то есть уже сам финальный ответ с сарказмом и с учётом истории
// переписки формулирует Gemini (или следующий по фолбэку), как обычно.
// Compound тут только "гуглит", не "разговаривает" — поэтому и системный
// промпт ниже намеренно сухой и фактический, а не в характере бота.
const WEB_SEARCH_SYSTEM_PROMPT =
  "Ты — инструмент веб-поиска. По запросу пользователя найди актуальную " +
  "информацию через поиск в интернете и изложи её кратким фактическим " +
  "конспектом на русском: конкретика (даты, цифры, названия), без " +
  "вступлений и без собственных оценок. Если источники противоречат " +
  "друг другу — отметь это прямо в тексте. В конце ОБЯЗАТЕЛЬНО добавь " +
  "строку \"Источники: \" и через запятую прямые URL страниц, которые " +
  "реально использовал (не выдумывай ссылки, если поиск их не дал — " +
  "тогда просто не добавляй эту строку).";

async function searchWebGroq(query) {
  const searchTarget = {
    provider: "groq",
    model: GROQ_SEARCH_MODEL,
    baseUrl: PROVIDER_CONFIGS.groq.baseUrl,
    apiKey: GROQ_API_KEYS[0],
  };
  const messages = [
    { role: "system", content: WEB_SEARCH_SYSTEM_PROMPT },
    { role: "user", content: query },
  ];
  const { reply } = await callTarget(searchTarget, messages, SEARCH_TIMEOUT_MS);
  return reply;
}

// ==== Веб-поиск через Tavily ====
// В отличие от Gemini grounding (см. историю правок выше — квота на free
// tier там оказалась нулевой без биллинга), у Tavily честный бесплатный
// тир БЕЗ привязки карты — 1000 запросов/мес на аккаунт. Несколько
// аккаунтов (TAVILY_API_KEYS через запятую) суммарно продлевают бюджет,
// как и с Gemini/Groq — при 6 ключах это ~6000 запросов/мес.
// include_answer:true просит Tavily самой синтезировать краткий ответ по
// найденным источникам — этого обычно достаточно; если Tavily его не
// вернула (бывает на совсем свежих/редких темах), собираем конспект сами
// из сниппетов топ-результатов, чтобы не возвращать пустоту.
const TAVILY_SEARCH_TIMEOUT_MS = Number(process.env.TAVILY_SEARCH_TIMEOUT_MS || SEARCH_TIMEOUT_MS || 15000);

async function searchWebTavily(query) {
  if (!TAVILY_API_KEYS.length) return null;

  for (let i = 0; i < TAVILY_API_KEYS.length; i++) {
    const apiKey = TAVILY_API_KEYS[i];
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), TAVILY_SEARCH_TIMEOUT_MS);
    try {
      const res = await fetch("https://api.tavily.com/search", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        signal: controller.signal,
        body: JSON.stringify({
          query,
          search_depth: "basic",
          max_results: 5,
          include_answer: true,
        }),
      }).finally(() => clearTimeout(timeoutId));

      if (!res.ok) {
        const text = await res.text().catch(() => "");
        throw new Error(`status ${res.status}: ${text.slice(0, 300)}`);
      }

      const json = await res.json();
      const results = Array.isArray(json.results) ? json.results : [];
      const sourceUrls = results.map((r) => r.url).filter(Boolean);
      const sourcesLine = sourceUrls.length ? `\nИсточники: ${sourceUrls.slice(0, 3).join(", ")}` : "";

      if (json.answer && json.answer.trim()) return `${json.answer.trim()}${sourcesLine}`;

      // Fallback внутри самого Tavily-пути: ответа нет, но есть результаты —
      // собираем короткий конспект сами, а не сдаёмся раньше времени.
      // Каждый пункт сразу со своим URL — иначе если попросят прислать
      // ссылку на конкретный источник, боту нечего будет прислать.
      if (results.length) {
        return results
          .slice(0, 3)
          .map((r) => `${r.title || ""} (${r.url || "без ссылки"}): ${(r.content || "").slice(0, 300)}`)
          .join("\n");
      }
      throw new Error("пустой ответ без результатов");
    } catch (err) {
      console.error(
        `searchWebTavily: ошибка у аккаунта ${i + 1}/${TAVILY_API_KEYS.length}:`,
        err.message || err
      );
      // пробуем следующий ключ из TAVILY_API_KEYS
    }
  }
  return null;
}

// Единая точка входа для веб-поиска (см. вызовы ниже) — сначала пробует
// Tavily (честная отдельная квота, см. searchWebTavily выше), и только
// если ВСЕ аккаунты Tavily не сработали (ключи не заданы/квота
// исчерпана/таймаут) — откатывается на Groq compound-mini, чтобы поиск не
// переставал работать целиком из-за одного упавшего провайдера.
async function searchWeb(query) {
  console.log(`searchWeb: запрос «${query}»`);
  try {
    const tavilyReply = await searchWebTavily(query);
    if (tavilyReply) {
      console.log(`searchWeb: ответ от Tavily (${tavilyReply.length} симв.): ${tavilyReply.slice(0, 200)}`);
      return tavilyReply;
    }
    console.log("searchWeb: Tavily не дал результата (ключи не заданы/пусто), пробую Groq");
  } catch (err) {
    console.error("searchWebTavily упал целиком, откатываюсь на Groq:", err.message || err);
  }
  const groqReply = await searchWebGroq(query);
  console.log(`searchWeb: ответ от Groq compound (${groqReply.length} симв.): ${groqReply.slice(0, 200)}`);
  return groqReply;
}

// ==== Фоновая расшифровка голосовых/аудио для сводки чата ====
// В отличие от реактивной расшифровки выше (реплай на ГС с "текст"/"о чём
// там") — эта молчаливая: результат никогда не уходит в сам чат, только в
// ChatLog (см. pushChatLog) и в общий кэш расшифровок
// (voiceTranscriptsByMessage), чтобы "Женя, что я пропустил?" (см.
// RECAP_INTENT_REGEX/handleRecapQuery) знал реальное содержание голосовых,
// а не только факт "кто-то прислал голосовое". Кэш общий с реактивным
// путём — если кто-то потом реплайнет на ЭТО ЖЕ голосовое с "текст"/"о чём
// там" (см. VOICE_TRANSCRIBE_INTENT_REGEX/getVoiceTranscript выше по коду),
// расшифровка уже готова и повторного прохода через GigaAM/Whisper не
// будет — engine="auto" тут и там даёт один и тот же кэш-ключ.
// Молчим полностью при любой ошибке — это фон, отдельно ловим и логируем
// в консоль на вызывающей стороне (см. bot.on ниже), в чат ничего не
// падает.
//
// ВАЖНО: гоняем через Whisper тут ТОЛЬКО голосовые/OGG-подобное аудио, а не
// вообще любой присланный звук. voice (ctx.message.voice) — это всегда OGG/
// Opus, реальная речь. audio (ctx.message.audio) — это чаще всего музыка
// (mp3/flac/wav/m4a и т.п.), которую кто-то скинул как трек: гонять её
// через речевое распознавание для сводки чата бессмысленно (текст песни
// никому не нужен в "что я пропустил") и просто тратит лимит Whisper
// впустую на каждый шаренный трек. Если кому-то реально нужен текст
// песни — есть отдельный явный путь (реплай "о чём песня"/"текст" на
// трек, см. комментарий выше про реактивный блок) — там transcribeVoice
// вызывается намеренно и по запросу, эта функция его не трогает.
const VOICE_LIKE_AUDIO_EXT_REGEX = /\.(ogg|oga|opus)$/i;
function isVoiceLikeAudio(mediaObj, kind) {
  if (kind === "voice") return true; // Telegram voice — всегда OGG/Opus, других вариантов не бывает
  const mime = (mediaObj.mime_type || "").toLowerCase();
  if (mime.includes("ogg") || mime.includes("opus")) return true;
  return VOICE_LIKE_AUDIO_EXT_REGEX.test(mediaObj.file_name || "");
}

async function backgroundTranscribeVoiceForRecap(ctx) {
  const chatId = ctx.chat.id;
  const mediaObj = ctx.message.voice || ctx.message.audio;
  if (!mediaObj) return;

  rememberUsername(chatId, ctx.from);
  const displayName = getDisplayName(chatId, ctx.from);
  const kind = ctx.message.voice ? "voice" : "audio";
  const label = kind === "voice" ? "голосовое" : "аудиофайл";
  const durationLabel = formatVoiceDuration(mediaObj.duration);
  const durationPart = durationLabel ? ` (${durationLabel})` : "";
  // Название/исполнитель — есть только у audio (см. аналогичный код в
  // реактивном блоке выше).
  const trackMeta =
    kind === "audio" && (mediaObj.title || mediaObj.performer)
      ? ` (${[mediaObj.performer, mediaObj.title].filter(Boolean).join(" — ")})`
      : "";

  const isMusic = !isVoiceLikeAudio(mediaObj, kind);

  let text = null;
  if (isMusic) {
    // Музыкальный трек — сознательно не расшифровываем в фоне (см.
    // комментарий выше), просто зафиксируем сам факт в логе ниже.
  } else if (mediaObj.file_size && mediaObj.file_size > MAX_TRANSCRIBE_FILE_SIZE) {
    // Файл крупнее 20MB Bot API всё равно не отдаст (см. tooLarge в
    // реактивном блоке) — даже не пытаемся скачивать.
  } else {
    try {
      ({ text } = await transcribeVoice(ctx, mediaObj.file_id, "auto"));
    } catch (err) {
      console.error(
        `Фоновая расшифровка ${label} в чате ${chatId} не удалась:`,
        err.status ?? "-",
        err.body ?? err.message
      );
    }
  }

  if (text) {
    // Тот же кэш и тот же ключ (chatId:messageId), что читает реактивный
    // блок выше — реплай на это голосовое с "текст" отдаст готовый
    // результат мгновенно, без повторной расшифровки.
    rememberVoiceTranscript(chatId, ctx.message.message_id, displayName, text);
  }

  const logLine = text
    ? `[${label}${trackMeta}${durationPart}]: ${text}`
    : isMusic
      ? `[${label}${trackMeta}${durationPart} — музыкальный трек, распознавание речи не запускали]`
      : `[${label}${trackMeta}${durationPart} — текст не распознан]`;
  // toBot=false — сам факт присылки голосового не значит, что обратились к
  // боту (в отличие от caption у фото, тут никакого текста-обращения нет).
  pushChatLog(chatId, displayName, logLine, false);
}

// ==== Фоновая расшифровка кружочков (video_note) для сводки чата ====
// Тот же принцип, что и у голосовых/аудио выше (см.
// backgroundTranscribeVoiceForRecap) — молчаливо, только в ChatLog и в
// общий кэш расшифровок, никакого ответа в чат. Отдельная функция, а не
// переиспользование backgroundTranscribeVoiceForRecap, потому что у
// video_note нет ни title/performer, ни смысла в стикер-реакции "music"
// (это видеосообщение, а не музыка) — общего между ними по факту только
// сама расшифровка через transcribeVoice.
async function backgroundTranscribeVideoNoteForRecap(ctx) {
  const chatId = ctx.chat.id;
  const mediaObj = ctx.message.video_note;
  if (!mediaObj) return;

  rememberUsername(chatId, ctx.from);
  const displayName = getDisplayName(chatId, ctx.from);
  const durationLabel = formatVoiceDuration(mediaObj.duration);
  const durationPart = durationLabel ? ` (${durationLabel})` : "";

  let text = null;
  if (mediaObj.file_size && mediaObj.file_size > MAX_TRANSCRIBE_FILE_SIZE) {
    // Файл крупнее 20MB Bot API всё равно не отдаст — даже не пытаемся.
  } else {
    try {
      ({ text } = await transcribeVoice(ctx, mediaObj.file_id, "auto"));
    } catch (err) {
      console.error(
        `Фоновая расшифровка кружочка в чате ${chatId} не удалась:`,
        err.status ?? "-",
        err.body ?? err.message
      );
    }
  }

  if (text) {
    rememberVoiceTranscript(chatId, ctx.message.message_id, displayName, text);
  }

  const logLine = text
    ? `[кружочек${durationPart}]: ${text}`
    : `[кружочек${durationPart} — текст не распознан]`;
  pushChatLog(chatId, displayName, logLine, false);
}

bot.on("message:video_note", async (ctx) => {
  const chatId = ctx.chat.id;
  const isGroup = ctx.chat.type === "group" || ctx.chat.type === "supergroup";
  if (!isGroup || ctx.from.is_bot) return; // в личке ChatLog не ведётся, чужих ботов не логируем

  backgroundTranscribeVideoNoteForRecap(ctx).catch((err) => {
    console.error(`Фоновая расшифровка кружочка в чате ${chatId} упала:`, err.message || err);
  });
});


// Стикер — отдельно от текстовых ответов через LLM, модель тут не
// участвует: пришло аудио/голосовое → шлём стикер из категории "music". В
// группе стикером реагируем ТОЛЬКО если это реплай на сообщение бота
// (иначе бот реагировал бы на любую музыку/ГС в чате подряд) — но
// расшифровка для сводки, в отличие от стикера, уходит в фон для ЛЮБОГО
// голосового/аудио в группе, вне зависимости от реплая, чтобы "что я
// пропустил" знал содержание всех голосовых, а не только тех, на которые
// среагировал бот.
bot.on(["message:audio", "message:voice"], async (ctx) => {
  const chatId = ctx.chat.id;
  const isGroup = ctx.chat.type === "group" || ctx.chat.type === "supergroup";
  const isReply = isGroup && isReplyToBot(ctx);

  if (!isGroup || isReply) {
    const stickerId = pickSticker("music");
    if (stickerId) {
      await ctx.replyWithSticker(stickerId, {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: ctx.message.message_thread_id,
      });
    }
  }

  // Фоновая расшифровка для ChatLog — только в группах (в личке ChatLog
  // вообще не ведётся, см. комментарий у chatLogs выше) и не для других
  // ботов (тот же фильтр, что у фото/текста).
  if (isGroup && !ctx.from.is_bot) {
    // Намеренно не await — это фон, не должен задерживать обработку
    // сообщения (стикер уже отправлен выше). Ошибки ловятся внутри самой
    // функции и здесь же on catch — в чат ничего не падает.
    backgroundTranscribeVoiceForRecap(ctx).catch((err) => {
      console.error(`Фоновая расшифровка голосового/аудио в чате ${chatId} упала:`, err.message || err);
    });
  }
});

// ==== Вход/выход участников группы ====
// Служебные сообщения Telegram о добавлении/уходе участников — пишем их в
// ChatLog (см. pushChatLog) как события, а не обычные реплики, чтобы они
// попадали в пересказ ("Женя, что я пропустил?" — см. RECAP_INTENT_REGEX /
// handleRecapQuery) в хронологическом порядке вместе с обычной перепиской.
// Сам бот тут ничего не пишет в чат — это чисто фоновая запись в лог, как
// и с фото (см. bot.on("message:photo") ниже). Себя и других ботов в лог
// не пишем — не интересно для пересказа.
bot.on(["message:new_chat_members", "message:left_chat_member"], async (ctx) => {
  const chatId = ctx.chat.id;
  const isGroup = ctx.chat.type === "group" || ctx.chat.type === "supergroup";
  if (!isGroup) return;

  for (const member of ctx.message.new_chat_members ?? []) {
    if (member.is_bot) continue;
    rememberUsername(chatId, member);
    const name = getDisplayName(chatId, member);
    const gender = getGender(chatId, member.id);
    pushChatLog(chatId, name, joinLeaveText(name, gender, "join"), false, "join");
  }

  const leftMember = ctx.message.left_chat_member;
  if (leftMember && !leftMember.is_bot) {
    rememberUsername(chatId, leftMember);
    const name = getDisplayName(chatId, leftMember);
    const gender = getGender(chatId, leftMember.id);
    pushChatLog(chatId, name, joinLeaveText(name, gender, "leave"), false, "leave");
  }
});

// ==== Фото в группе ====
// Срабатывает на КАЖДОЕ фото в группе (не только адресованное боту) — см.
// пояснение к captionPhoto выше. Если фото НЕ адресовано боту — чисто
// фоновая запись в ChatLog + HISTORY, бот ничего не пишет в чат. Если же
// фото адресовано боту (подпись с обращением "Женя", реплай на бота или
// упоминание через @) — бот отвечает сразу, а не молчит в ожидании
// отдельного текстового вопроса про картинку (раньше молчал именно тут).
// Фото от других ботов игнорируем (как и в общем текстовом логе).
bot.on("message:photo", async (ctx) => {
  const chatId = ctx.chat.id;
  const isGroup = ctx.chat.type === "group" || ctx.chat.type === "supergroup";
  if (!isGroup) return; // в личке фото не разбираем вообще — см. обсуждение в чате с разработчиком
  if (ctx.from.is_bot) return;

  rememberUsername(chatId, ctx.from);
  const displayName = getDisplayName(chatId, ctx.from);

  // Была ли подпись/реплай адресованы боту — тот же набор сигналов, что и
  // для обычных текстовых сообщений (см. bot.on("message:text")), только
  // источник текста — caption, а не сам текст сообщения (у фото его нет).
  const captionText = ctx.message.caption || "";
  const isReply = isReplyToBot(ctx);
  const isMentioned =
    ctx.message.caption_entities?.some(
      (e) =>
        e.type === "mention" &&
        captionText.substring(e.offset, e.offset + e.length).toLowerCase() ===
          `@${ctx.me.username?.toLowerCase()}`
    ) ?? false;
  const toBot = nameTriggerRegex.test(captionText) || isReply || isMentioned || ownerMentionRegex.test(captionText);

  // Пересланное фото (мем/новость из канала) — если оно НЕ адресовано боту
  // явно, вообще не гоняем его через vision-модель: это самый частый
  // источник лишнего расхода TPM (кто-то кинул пачку скриншотов/мемов из
  // канала пересылкой) при том что распознавать тут особо нечего и никто
  // не просил. Если это форвард, но всё же с подписью "Женя, глянь" — всё
  // равно распознаём и отвечаем, раз явно спросили.
  const forwarded = isForwardedMessage(ctx.message);
  if (forwarded && !toBot) {
    return;
  }

  if (toBot) {
    sendTypingAction(ctx);
  }

  let caption;
  let reactionKey;
  try {
    // Берём не самый большой размер (обычно последний в массиве) — он
    // сильно тяжелее в скачивании и токенах, а для короткого текстового
    // описания достаточно среднего качества. Если размер всего один —
    // берём его же.
    const sizes = ctx.message.photo;
    const photo = sizes.length > 1 ? sizes[sizes.length - 2] : sizes[sizes.length - 1];
    ({ caption, reactionKey } = await captionPhoto(ctx, photo.file_id));
  } catch (err) {
    console.error(`Не удалось распознать фото в чате ${chatId}:`, err.status ?? "-", err.body ?? err.message);
    if (toBot) {
      await ctx
        .reply("не смог разглядеть, что на фото — попробуй ещё раз", {
          reply_parameters: { message_id: ctx.message.message_id },
          message_thread_id: ctx.message.message_thread_id,
        })
        .catch(() => {});
    }
    return;
  }

  // Не логируем форварды в ChatLog (сводку) — это чужой контент, а не то,
  // что реально написали участники чата, даже если в этот раз к боту
  // всё-таки обратились.
  if (!forwarded) {
    const logLine = captionText ? `[фото: ${caption}] ${captionText}` : `[фото] ${caption}`;
    pushChatLog(chatId, displayName, logLine, toBot);
  }

  // Запоминаем описание именно этого сообщения-с-фото — чтобы если позже
  // кто-то (необязательно автор) ответит на это сообщение вопросом к
  // боту, бот мог найти описание конкретно этой картинки (см. блок про
  // реплай на чужое фото в bot.on("message:text") ниже).
  rememberPhotoCaption(chatId, ctx.message.message_id, displayName, caption);

  // Реакция эмодзи (нативная Telegram-реакция) на красивые/приятные фото —
  // см. классификацию в PHOTO_CAPTION_PROMPT. Ставим её независимо от того,
  // toBot или нет (красивый закат остаётся красивым закатом, даже если его
  // никто не адресовал боту) — но только если фото реально распознали.
  // Ошибку реакции (например, если у бота не хватает прав в чате) не считаем
  // критичной — тихо логируем и не мешаем остальной обработке.
  if (reactionKey) {
    ctx.react(PHOTO_REACTION_EMOJI[reactionKey]).catch((err) =>
      console.error(`Не удалось поставить реакцию на фото в чате ${chatId}:`, err.description ?? err.message)
    );
  }

  if (!toBot) {
    // Не адресовано боту — НЕ кладём в HISTORY (скользящий контекст
    // диалога с ботом). Раньше клали — из-за этого бот "вспоминал" фото
    // не к месту: комментировал его в ответах на совсем другие вопросы,
    // либо когда реплаем отвечали не на само фото, а на следующее за ним
    // сообщение того же автора (фото просто ещё сидело в HISTORY рядом).
    // Достаточно того, что оно уже ушло в ChatLog (см. pushChatLog выше) —
    // оттуда его достанут либо явным реплаем на фото (см.
    // bot.on("message:text") -> repliedTo.photo), либо прямым текстовым
    // вопросом про фото/картинку в чате (см. PHOTO_MENTION_REGEX ниже).
    return;
  }

  // Адресовано боту — отвечаем сразу, тем же путём (askLLM/HISTORY), что и
  // обычные текстовые сообщения, чтобы ответ был живым и вариативным, а не
  // шаблонным пересказом описания. Тег "[фото от Имя: описание]" разобран
  // в SYSTEM_PROMPT.
  try {
    let question = captionText ? stripNameTrigger(captionText) : "";
    if (isMentioned && question) {
      question = question.replace(new RegExp(`@${ctx.me.username}`, "i"), "").trim();
    }

    const userText =
      `[фото от ${displayName}: ${caption}] ${displayName}: ` +
      (question || "гляну, что скажешь про фото?");

    let reply, stickerKey;
    await withTyping(ctx, async () => {
      const res = await askLLM(chatId, userText);
      reply = res.text;
      stickerKey = res.stickerKey;
      await new Promise((r) => setTimeout(r, typingDelayMs(reply.length)));
    });

    const threadId = getThreadId(ctx);
    // Анти-спам: та же проверка, что и в основном текстовом хендлере —
    // не повторяем стикер той же категории подряд одному человеку.
    const stickerId =
      stickerKey && canSendStickerReaction(chatId, ctx.from.id, stickerKey) && pickSticker(stickerKey);
    if (stickerId) {
      const sentMsg = await ctx.replyWithSticker(stickerId, {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: threadId,
      });
      rememberBotReply(chatId, sentMsg.message_id, displayName, reply);
    } else {
      const sentMsg = await ctx.reply(reply, {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: threadId,
      });
      rememberBotReply(chatId, sentMsg.message_id, displayName, reply);
    }
  } catch (err) {
    console.error(`Ошибка ответа на фото в чате ${chatId}:`, err.status ?? "-", err.body ?? err.message);
    await ctx
      .reply("блин, что-то сломалось, попробуй ещё раз", {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: ctx.message.message_thread_id,
      })
      .catch(() => {});
  }
});


// ==== Поиск и отправка музыки с Deezer ====
const DEEZER_INTENT_REGEX = /^(?:скинь|найди|включи|поставь|отправь|пришли)?\s*(?:песню|трек|музыку|мелодию|композицию)\s+["«]?(.*?)["»]?$/i;
const DEEZER_COMMAND_REGEX = /^\/(?:song|deezer|music|track)(?:@\w+)?\s+(.+)$/i;

// Неполный/двусмысленный запрос трека — название либо не названо явно
// ("скинь этот трек", "пришли её"), либо описано не через явный формат
// "исполнитель - название" ("пришли главный хит o-zone", "их самый
// известный трек"). DEEZER_INTENT_REGEX ловит только чистый явный формат
// (глагол + трек/песня + название целиком) — всё остальное, что явно
// похоже на просьбу прислать музыку, но не распарсилось туда, отправляем
// на разбор в LLM вместе с текущим сообщением и историей переписки (см.
// resolveTrackQuery ниже) вместо того, чтобы пытаться перечислить регэкспом
// каждую возможную формулировку.
const DEEZER_REQUEST_VERB_REGEX = /(скин|кин|найд|включ|постав|отправ|пришл|дай|дашь)/i;
// Узкий подмножество глаголов-просьб, которые в разговорной речи почти
// всегда означают "пришли мне файл/трек" и редко используются в бытовом
// контексте не про музыку - используется только в самой широкой ветке
// isDeezerAmbiguousMusicRequest (см. ниже), где нет ни слова-носителя, ни
// местоимения для подстраховки.
const DEEZER_SEND_VERB_REGEX = /(скин|кин|пришл)/i;
const DEEZER_TRACK_NOUN_REGEX = /(песн|трек|музык|мелоди|композици|хит|сингл|заставк|опенинг|интро)/i;
// ВАЖНО: \b в JS работает только по ASCII \w и не распознаёт кириллицу как
// "словесные" символы — с кириллическим текстом границы \b просто нигде не
// находятся, и любой regex вида \b(эту|его)\b молча никогда не совпадёт.
// Поэтому границы слова эмулируем вручную через "не-кириллический символ
// или начало/конец строки".
const DEEZER_BARE_PRONOUN_REGEX = /(?:^|[^а-яёa-z])(её|ее|его|их)(?:[^а-яёa-z]|$)/i;

// Голое подтверждение без всякого объекта - "Кидай", "Давай", "Го", "Ну
// ещё раз пришли значит" - т.е. просто повелительное "дай/присылай" без
// названия трека, местоимения или слова-носителя ("трек"/"хит") рядом.
// Само по себе оно ничего не значит, но если последний ответ бота в
// истории уже называл конкретный трек (см. resolveTrackQuery ниже,
// который смотрит на getHistory), это однозначно "пришли именно его".
// ВАЖНО: это САМОДОСТАТОЧНЫЙ триггер, который не должен идти через общий
// DEEZER_REQUEST_VERB_REGEX-гейт ниже - некоторые формы туда не проходят.
// Например "Давай" не матчится по стему "дай": буквы д-а-й в "Давай" не
// стоят подряд, между ними "в" (Д-а-В-а-й), поэтому DEEZER_REQUEST_VERB_REGEX
// его не ловит, хотя как голое подтверждение оно ровно то же самое, что
// "Кидай" или "Дай".
const DEEZER_CONFIRM_FILLER_LEAD_REGEX = /^(?:ну|да|ладно|ок(?:ей|ай)?|хорошо|ага)[,\s]+/i;
const DEEZER_CONFIRM_FILLER_TRAIL_REGEX = /[,\s]+(?:значит|тогда|же|давай|пожалуйста|плиз|ладно|уже)$/i;
const DEEZER_BARE_CONFIRM_CORE_REGEX =
  /^(?:дав[ае]й(?:те)?|дай|дашь|кидай|кинь|скинь|пришли|отправь|включи|поставь|го|жми|повтори(?:те)?|ещ[её]\s*раз(?:ик)?(?:\s+пришли)?)$/i;

function isDeezerBareConfirmation(text) {
  if (!text) return false;
  let t = text.trim().replace(/[.!]+$/, "");
  // Срезаем окружающие слова-заполнители ("ну", "значит", "тогда"...) с
  // обоих концов, по кругу - в "Ну ещё раз пришли значит" их сразу два.
  let prev;
  do {
    prev = t;
    t = t.replace(DEEZER_CONFIRM_FILLER_LEAD_REGEX, "").trim();
    t = t.replace(DEEZER_CONFIRM_FILLER_TRAIL_REGEX, "").trim();
  } while (t !== prev && t.length > 0);
  if (!t) return false;
  return DEEZER_BARE_CONFIRM_CORE_REGEX.test(t);
}

function isDeezerAmbiguousMusicRequest(text) {
  if (!text) return false;
  const t = text.trim();
  if (!t) return false;
  // Если уже есть явное название трека в формате "трек X"/"песню X" - это
  // не двусмысленный случай, им займётся обычный parseDeezerIntent.
  if (parseDeezerIntent(t)) return false;
  // Голое подтверждение - самостоятельный триггер, см. комментарий выше.
  // Проверяем его ДО общего гейта на DEEZER_REQUEST_VERB_REGEX.
  if (isDeezerBareConfirmation(t)) return true;
  if (!DEEZER_REQUEST_VERB_REGEX.test(t)) return false;
  // Глагол-просьба + слово "трек/песня/хит/сингл/..." рядом - уже
  // достаточный сигнал, что человек просит музыку, независимо от того,
  // указано название местоимением ("этот хит"), явным именем артиста без
  // формата "исполнитель - название" ("хит o-zone") или вовсе описательно
  // ("их самый известный трек").
  if (DEEZER_TRACK_NOUN_REGEX.test(t)) return true;
  // Без слова-носителя ("трек"/"хит"/...) - смотрим на голое "её"/"его"/"их"
  // ("скинь её", "пришли его", "кинь их").
  if (DEEZER_BARE_PRONOUN_REGEX.test(t)) return true;
  // Ни слова-носителя, ни местоимения - но глагол-просьба есть, и рядом с
  // ним что-то содержательное. Это частый случай, когда человек называет
  // артиста/трек прямым текстом, без "трек"/"песня" и часто с глаголом в
  // конце фразы, а не в начале ("Блек сабат параноид скинь", "скинь скруджи
  // макдак заставку"). DEEZER_INTENT_REGEX такое не ловит (ждёт слово-носитель
  // сразу после глагола), а формальных признаков "это точно название трека"
  // тут нет - поэтому просто вырезаем сам глагол и явный "мусор" вокруг
  // (местоимения-адресаты, вежливые словечки) и если содержательный остаток
  // не пустой - отдаём его на разбор resolveTrackQuery. Она сама, через
  // LLM, решит, похоже ли это на трек, и вернёт null, если нет - тогда
  // просто получим вежливый уточняющий вопрос вместо ошибочного попадания
  // в обычный чат, где LLM может выдать правдоподобный, но бесполезный ответ.
  //
  // Специально используем УЗКИЙ список глаголов (не весь
  // DEEZER_REQUEST_VERB_REGEX) - "включи"/"поставь"/"отправь"/"дай" слишком
  // общеупотребимы в бытовой речи ("включи свет", "поставь чайник", "отправь
  // документ", "дай денег"), и без слова-носителя/местоимения рядом эта
  // ветка ловила бы их как ложные срабатывания. "скинь"/"кинь"/"пришли" в
  // разговорном рунете почти всегда означают "отправь мне файл/ссылку" -
  // именно на них и сужаем.
  if (!DEEZER_SEND_VERB_REGEX.test(t)) return false;
  // Риторический вопрос/комментарий про уже отправленный трек ("Ну. А я
  // просил что скинуть?", "я разве это просил скинуть?") не должен снова
  // запускать поиск - это разбор происходящего, а не новый запрос. Общий
  // DEEZER_QUESTION_REGEX (вопросительный знак, "что значит", "разве" и
  // т.п.) уже используется ниже для той же цели в реплаях на сообщения
  // бота - переиспользуем его и тут, до того как считать "остаток".
  if (DEEZER_QUESTION_REGEX.test(t)) return false;
  const leftover = t
    .replace(DEEZER_SEND_VERB_REGEX, " ")
    .replace(/\b(мне|нам|тебе|пожалуйста|плиз|давай|ну|же)\b/gi, " ")
    .replace(/[^\p{L}\s]/gu, " ")
    .trim();
  return leftover.replace(/\s+/g, "").length >= 4;
}

// Сколько последних сообщений диалога смотрим, пытаясь понять, о каком
// треке речь (см. resolveTrackQuery).
const TRACK_CONTEXT_LOOKBACK = 8;
const TRACK_CONTEXT_RESOLVE_TIMEOUT_MS = 12000;

const TRACK_CONTEXT_SYSTEM_PROMPT =
  "Тебе даны последняя переписка в чате и текущее сообщение пользователя. " +
  "Пользователь просит прислать трек, но не назвал его в чистом виде " +
  "\"Исполнитель - Название\" — сослался местоимением (\"этот трек\", \"её\", " +
  "\"их\"), описал его (\"главный хит\", \"их самый известный трек\") и/или " +
  "мог упомянуть исполнителя прямо в текущем сообщении. Используя оба " +
  "источника — текущее сообщение и контекст переписки (о какой группе/треке " +
  "шла речь) — определи, какую именно песню он имеет в виду. Ответь СТРОГО " +
  "в формате \"Исполнитель - Название\" в оригинальном написании (латиницей, " +
  "если оригинал на латинице), без кавычек и пояснений. Если невозможно " +
  "понять, о какой песне речь, ответь ровно словом NONE. ВАЖНО: если " +
  "исполнитель/трек в текущем сообщении похож на фонетическую " +
  "транслитерацию кириллицей иностранного названия (например, \"трития " +
  "рикошет\"), но ты НЕ уверен, что это конкретное известное " +
  "исполнитель+название - не пытайся сам её \"причесать\" или досочинить " +
  "правдоподобно выглядящее имя. Это отдельная задача другого шага " +
  "распознавания. Вместо этого верни исходный текст как есть, без " +
  "изменений (транслитерацией займутся позже) - или NONE, если это явно " +
  "не про музыку вообще.";

const TRACK_QUERY_NORMALIZE_SYSTEM_PROMPT =
  "Тебе дан поисковый запрос трека для Deezer, который мог быть написан с " +
  "ошибками, кириллицей вместо оригинального написания (фонетическая " +
  "транслитерация вроде \"Даугтри ИТС нот овер\") или неточно. Верни ИСПРАВЛЕННЫЙ " +
  "запрос в формате \"Исполнитель - Название\" в оригинальном написании " +
  "(латиницей, если оригинал на латинице), без кавычек и пояснений. Если " +
  "узнаёшь исполнителя/трек по звучанию хотя бы приблизительно - дай " +
  "наиболее вероятный вариант, не отказывайся отвечать из-за одной лишь " +
  "неуверенности в мелких деталях. Но если транслитерация настолько " +
  "нечитаемая или искажённая, что ты БЫ ПРОСТО УГАДЫВАЛ случайного " +
  "исполнителя без реальной звуковой похожести (а не восстанавливал " +
  "узнаваемое название) - НЕ подставляй первое пришедшее в голову: ответь " +
  "ровно словом NONE. Лучше честно не найти, чем прислать заведомо другую " +
  "песню. Ответь только самим запросом или словом NONE, ничего больше.";

// Порядок целей "с нуля": как computeTargetOrder (cooldown-цели в конец,
// пин через /model — первым), но БЕЗ ротации от activeTargetIndex — всегда
// начинаем с начала TARGETS (обычно это основной провайдер/аккаунт, напр.
// gemini/gemini-flash-latest аккаунт 1), а не с той цели, на которой сейчас
// "застрял" общий разговорный поток. Используется там, где нужен разовый,
// не завязанный на текущее состояние ротации запрос (см. askOnceForTrack) —
// иначе такой запрос стартовал бы с того же места, где случайно остановилась
// ротация обычного чата (см. activeTargetIndex/computeTargetOrder), и мог бы
// сходу упереться в аккаунт/модель, которые сейчас не отвечают, хотя основной
// провайдер прекрасно доступен.
function computeStaticTargetOrder() {
  const now = Date.now();
  let order = [...TARGETS.keys()].sort((a, b) => {
    const aCold = cooldownUntil[a] > now ? 1 : 0;
    const bCold = cooldownUntil[b] > now ? 1 : 0;
    return aCold - bCold || a - b;
  });

  if (pinnedTargetIndex !== null && cooldownUntil[pinnedTargetIndex] <= now) {
    order = [pinnedTargetIndex, ...order.filter((idx) => idx !== pinnedTargetIndex)];
  }

  return order;
}

// Общий хелпер: разовый (без истории чата) запрос к общему пулу целей
// (TARGETS) с фолбэком по провайдерам/моделям — переиспользует тот же пул
// TARGETS, что и askLLM (поэтому уважает основной провайдер пользователя,
// напр. Gemini, и не завязан жёстко на Groq), но со СВОИМ порядком через
// computeStaticTargetOrder() — всегда от начала списка, а не с текущей
// точки ротации обычного чата (см. комментарий над computeStaticTargetOrder).
// Раньше это было захардкожено только на Groq-цели — из-за этого при
// мёртвой/недоступной модели на Groq функция возвращала null, даже если
// Gemini прекрасно работал. Не годится для тяжёлых промптов, только для
// маленьких классификационных/нормализующих задач.
async function askOnceForTrack(systemPrompt, userContent, timeoutMs) {
  const order = computeStaticTargetOrder();
  if (order.length === 0) return null;

  const messages = [
    { role: "system", content: systemPrompt },
    { role: "user", content: userContent },
  ];

  for (const idx of order) {
    const target = TARGETS[idx];
    try {
      const { reply } = await callTarget(target, messages, timeoutMs, 0.2);
      const cleaned = reply.trim().replace(/^["«]+|["»]+$/g, "");
      cooldownUntil[idx] = 0;
      return cleaned || null;
    } catch (err) {
      console.error(
        `askOnceForTrack: ошибка у ${targetLabel(target)}:`,
        err.status ?? "-",
        err.body ?? err.message
      );
      if (err.status && !isFallbackWorthy(err.status)) break;
      cooldownUntil[idx] = Date.now() + MODEL_COOLDOWN_MS;
    }
  }
  return null;
}

// Пытается понять, о каком треке речь, когда пользователь не назвал его в
// чистом виде "Исполнитель - Название" — смотрит и на текущее сообщение
// (там может быть прямое имя артиста, как в "пришли главный хит o-zone"),
// и на последние сообщения диалога с ботом (та же история, что видит
// askLLM), и просит модель назвать исполнителя и название. Возвращает
// null, если не удалось определить.
async function resolveTrackQuery(chatId, currentText) {
  const history = getHistory(chatId).slice(-TRACK_CONTEXT_LOOKBACK);

  const transcript = history
    .map((m) => `${m.role === "user" ? "Пользователь" : "Бот"}: ${m.content}`)
    .join("\n");

  const userContent =
    (transcript ? `Переписка:\n${transcript}\n\n` : "") +
    `Текущее сообщение пользователя: "${currentText}"`;

  const result = await askOnceForTrack(TRACK_CONTEXT_SYSTEM_PROMPT, userContent, TRACK_CONTEXT_RESOLVE_TIMEOUT_MS);
  if (!result || /^none$/i.test(result)) return null;
  return result;
}

// Пытается восстановить нормальное написание трека из "шумного" запроса
// (опечатки, фонетическая транслитерация кириллицей и т.п.) — используется
// как фолбэк, когда прямой поиск по Deezer вернул пустой результат.
async function normalizeTrackQueryViaLLM(rawQuery) {
  return askOnceForTrack(TRACK_QUERY_NORMALIZE_SYSTEM_PROMPT, rawQuery, TRACK_CONTEXT_RESOLVE_TIMEOUT_MS);
}

// Вопросы/комментарии о самой песне (реплай на сообщение бота с треком),
// НЕ являющиеся новым явным поисковым запросом ("найди трек X" уже ловится
// DEEZER_INTENT_REGEX выше) — такой текст не должен запускать повторный
// поиск трека на Deezer по своему же содержимому (см. использование ниже,
// в bot.on("message:text")): "о чём эта песня?", "переведи", "кто поёт?",
// "нравится?", "не присылай ничего, просто объясни о чём тут поётся" и
// т.п. — это вопрос/комментарий ПРО трек, а не название нового трека.
// Слова ищем по всему тексту (не только в начале) — реальные фразы часто
// начинаются с преамбулы вроде "не присылай мне ничего, просто объясни...".
const DEEZER_QUESTION_REGEX =
  /[?？]|о\s+ч[её]м|про\s+что|что\s+(за|там|тут|это|значит|значат)|перевед|переведи|перевод\b|перескаж|расскаж|объясн|смысл|означа|нрав|понрав|люб(ишь|лю)|как\s+тебе|не\s+(присылай|отправляй|скидывай|ищи|кидай|надо|нужно)/i;

function parseDeezerIntent(rawText) {
  if (!rawText) return null;
  const text = rawText.trim();
  const cmdMatch = text.match(DEEZER_COMMAND_REGEX);
  if (cmdMatch && cmdMatch[1]) return cmdMatch[1].trim();

  const intentMatch = text.match(DEEZER_INTENT_REGEX);
  if (intentMatch && intentMatch[1]) return intentMatch[1].trim();

  return null;
}

// ==== SoundCloud функции ====

// Проверяет, есть ли в запросе явное упоминание "soundcloud"
function isSoundCloudIntent(text) {
  return /\bsoundcloud\b/i.test(text);
}

// Убирает слово "soundcloud" из поискового запроса
function stripSoundCloudKeyword(text) {
  return text.replace(/\bsoundcloud\b/gi, "").trim();
}

// Поиск треков на SoundCloud через сервер
async function searchSoundCloudTracks(query, limit = 5) {
  if (!SOUNDCLOUD_SERVER_URL) {
    throw new Error("SoundCloud server не настроен");
  }
  
  const url = `${SOUNDCLOUD_SERVER_URL}/soundcloud/search?q=${encodeURIComponent(query)}&limit=${limit}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`SoundCloud search status: ${res.status}`);
  const data = await res.json();
  return data.tracks || [];
}

// Формирует URL для скачивания трека с SoundCloud
function getSoundCloudDownloadUrl(trackUrl, meta = {}) {
  const params = new URLSearchParams({
    url: trackUrl,
    quality: SOUNDCLOUD_QUALITY,
  });
  
  if (meta.title) params.set("title", meta.title);
  if (meta.performer) params.set("performer", meta.performer);
  if (meta.duration) params.set("duration", String(meta.duration));
  
  return `${SOUNDCLOUD_SERVER_URL}/soundcloud/download?${params.toString()}`;
}

// Извлекает метаданные из объекта трека SoundCloud
function getSoundCloudTrackMeta(track = {}) {
  return {
    title: track.title || "",
    performer: track.user?.username || track.artist || "",
    duration: Math.floor((track.duration || 0) / 1000), // SoundCloud в миллисекундах
    url: track.permalink_url || "",
  };
}

// ==== Выбор конкретного трека из списка кандидатов Deezer ====
// Deezer /search сам ранжирует по релевантности, но у этого два практических
// последствия, с которыми сталкивается пользователь:
// 1) иногда в топ проскакивает совсем левый исполнитель — например по
//    запросу "сектор газа частушки" вторым результатом может оказаться
//    ремикс/нарезка совсем другого автора, просто из-за совпадения слов в
//    названии трека. Такие подвигаем в конец, если хотя бы у одного из
//    кандидатов имя исполнителя явно встречается в запросе (см.
//    reorderByArtistRelevance) — но не трогаем порядок вообще, если в
//    запросе нет узнаваемого имени исполнителя ни у кого (обычные запросы
//    без исполнителя не должны из-за этого ломаться).
// 2) на повторный похожий запрос в том же чате ("а других нету?", "ещё
//    разок" и т.п.) resolveTrackQuery сводит текст к тому же самому
//    "Исполнитель - Название", Deezer возвращает тот же список, и без этой
//    логики handleDeezerQuery всегда брал бы tracks[0] — тот же самый
//    трек, что уже отправляли. Поэтому запоминаем id последнего реально
//    отправленного в чате трека (см. lastSentDeezerTrack/
//    rememberSentDeezerTrack) и при следующем выборе пропускаем его,
//    беря следующего по релевантности кандидата.
const lastSentDeezerTrack = new Map(); // chatId -> { id, artistId }

function rememberSentDeezerTrack(chatId, track) {
  lastSentDeezerTrack.set(chatId, { id: track.id, artistId: track.artist?.id });
}

function normalizeArtistMatchWords(text) {
  return (text || "")
    .toLowerCase()
    .replace(/[^a-zа-яё0-9\s]/gi, " ")
    .split(/\s+/)
    .filter(Boolean);
}

function reorderByArtistRelevance(query, tracks) {
  const queryWords = new Set(normalizeArtistMatchWords(query));
  if (queryWords.size === 0) return tracks;

  const scored = tracks.map((t, i) => {
    const artistWords = normalizeArtistMatchWords(t.artist?.name);
    const matches = artistWords.some((w) => w.length > 2 && queryWords.has(w));
    return { t, i, matches };
  });

  const anyMatch = scored.some((s) => s.matches);
  if (!anyMatch) return tracks; // в запросе нет узнаваемого имени исполнителя вообще — не мешаем

  return scored.sort((a, b) => Number(b.matches) - Number(a.matches) || a.i - b.i).map((s) => s.t);
}

function chooseDeezerTrack(chatId, query, tracks) {
  const ordered = reorderByArtistRelevance(query, tracks);
  const last = lastSentDeezerTrack.get(chatId);
  if (last) {
    const alternative = ordered.find((t) => t.id !== last.id);
    if (alternative) return alternative;
  }
  return ordered[0];
}

async function searchDeezerTracks(query, limit = 10) {
  const url = `https://api.deezer.com/search?q=${encodeURIComponent(query)}&limit=${limit}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Deezer API status: ${res.status}`);
  const data = await res.json();
  return data.data || [];
}

function getDeezerStreamUrl(trackId, format = "MP3_320") {
  let url = `${DEEZER_SPACE_URL}/stream?id=${encodeURIComponent(trackId)}&format=${encodeURIComponent(format)}`;
  if (DEEZER_ARL) {
    url += `&arl=${encodeURIComponent(DEEZER_ARL)}`;
  }
  return url;
}

// /download — полный файл с Content-Length (для sendAudio по URL)
function appendDeezerMetaParams(params, meta = {}) {
  if (meta.title) params.set("title", meta.title);
  if (meta.performer) params.set("performer", meta.performer);
  if (meta.duration) params.set("duration", String(meta.duration));
  if (meta.album) params.set("album", meta.album);
  if (meta.cover_url) params.set("cover_url", meta.cover_url);
  return params;
}

function getDeezerTrackMeta(track = {}) {
  const album = track.album || {};
  return {
    title: track.title || "",
    performer: track.artist?.name || "",
    duration: track.duration || 0,
    album: album.title || "",
    cover_url: album.cover_xl || album.cover_big || album.cover_medium || album.cover || "",
  };
}

function getDeezerDownloadUrl(trackId, format = "MP3_320", meta = {}, baseUrl = DEEZER_SPACE_URL) {
  const params = new URLSearchParams({
    id: String(trackId),
    format: String(format || "MP3_320"),
  });
  if (DEEZER_ARL) params.set("arl", DEEZER_ARL);
  appendDeezerMetaParams(params, meta);
  return `${baseUrl}/download?${params.toString()}`;
}

function getDeezerSendAudioUrl(trackId, format, chatId, meta = {}, messageId = null) {
  const params = new URLSearchParams({
    id: String(trackId),
    format: String(format || "MP3_320"),
    chat_id: String(chatId),
  });

  // Если передан message_id — просим сервер сразу отредактировать это
  // сообщение через editMessageMedia (см. handleDeezerQuery), а не слать
  // трек отдельным sendAudio. Так в чате не мелькает лишнее сообщение,
  // которое бот тут же удаляет — правка идёт напрямую на бэкенде.
  if (messageId) params.set("message_id", String(messageId));

  if (DEEZER_ARL) params.set("arl", DEEZER_ARL);
  appendDeezerMetaParams(params, meta);

  return `${DEEZER_SPACE_URL}/send_audio?${params.toString()}`;
}

async function getDeezerCdnUrl(trackId, format = "MP3_320") {
  try {
    const payload = {
      formats: [format, "MP3_128"],
      ids: [parseInt(trackId, 10)],
    };
    if (DEEZER_ARL) payload.arl = DEEZER_ARL;

    const res = await fetch(`${DEEZER_SPACE_URL}/get_url`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (res.ok) {
      const json = await res.json();
      const mediaList = json?.data?.[0]?.media;
      if (mediaList && mediaList.length) {
        for (const m of mediaList) {
          if (m?.sources && m.sources.length) {
            for (const s of m.sources) {
              if (s?.url) return s.url;
            }
          }
        }
      }
    }
  } catch (e) {
    console.error("Ошибка запроса CDN URL Deezer:", e.message);
  }
  return getDeezerStreamUrl(trackId, format);
}

async function getDeezerAudioBuffer(trackId, format = "MP3_320") {
  // Step 1: get CDN URL via /stream_info which returns real quality + signed URL in log field
  try {
    const infoUrl = new URL(`${DEEZER_SPACE_URL}/stream_info`);
    infoUrl.searchParams.set("id", String(trackId));
    infoUrl.searchParams.set("format", format);
    if (DEEZER_ARL) infoUrl.searchParams.set("arl", DEEZER_ARL);
    const infoRes = await fetch(infoUrl.toString());
    if (infoRes.ok) {
      const info = await infoRes.json();
      // CDN URL is embedded in info.log as a JSON string starting with "{"
      let cdnUrl = null;
      try {
        const logStart = (info.log || "").indexOf("{");
        if (logStart !== -1) {
          const mediaJson = JSON.parse(info.log.slice(logStart));
          cdnUrl = mediaJson?.data?.[0]?.media?.[0]?.sources?.[0]?.url || null;
        }
      } catch (_) {}
      if (cdnUrl) {
        const res = await fetch(cdnUrl);
        if (res.ok) {
          const rawBuf = await res.arrayBuffer();
          // trackId for key derivation should be the real ID from stream_info
          return decryptDeezerBufferIfNeeded(info.id || trackId, rawBuf);
        }
      }
    }
  } catch (e) {
    console.error("stream_info failed:", e.message);
  }

  // Fallback: proxy /stream (decrypts server-side, quality depends on ARL)
  const streamUrl = getDeezerStreamUrl(trackId, format);
  const res = await fetch(streamUrl);
  if (!res.ok) throw new Error(`Failed to fetch audio stream: ${res.status}`);
  const buf = await res.arrayBuffer();
  return Buffer.from(buf);
}

// Пытается превратить статусное сообщение "Загружаю..." прямо в аудио-сообщение
// через editMessageMedia (media может быть file_id или прямой URL/InputFile).
// Возвращает отредактированное Message при успехе, иначе null (нужен фолбэк на replyWithAudio).
async function editStatusMessageIntoAudio(ctx, statusMsg, media, trackMeta) {
  try {
    const mediaPayload = {
      type: "audio",
      media,
      title: trackMeta.title,
      performer: trackMeta.performer,
      duration: trackMeta.duration,
    };
    
    // Добавляем thumbnail если есть
    if (trackMeta.thumb) {
      mediaPayload.thumb = trackMeta.thumb;
    }
    
    const edited = await ctx.api.editMessageMedia(ctx.chat.id, statusMsg.message_id, mediaPayload);
    // editMessageMedia возвращает Message (не true), когда правим не inline-сообщение
    markDeezerFlowMessage(ctx.chat.id, typeof edited === "object" ? edited.message_id : statusMsg.message_id);
    return typeof edited === "object" ? edited : null;
  } catch (e) {
    console.error("Не удалось отредактировать статусное сообщение в аудио:", e.message || e);
    return null;
  }
}

// Достаёт числовой ID трека из ссылки на Deezer, если она есть в тексте.
// Поддерживает: deezer.com/track/123, deezer.com/en/track/123 (и любой
// другой локали), www.deezer.com, и короткие share-ссылки deezer.page.link
// (там ID нет в самом URL — их нужно раскрывать через редирект отдельно,
// см. resolveDeezerShareLink).
const DEEZER_TRACK_LINK_REGEX = /(?:https?:\/\/)?(?:www\.)?deezer\.com\/(?:[a-z]{2}\/)?track\/(\d+)/i;
const DEEZER_SHARE_LINK_REGEX = /(?:https?:\/\/)?(?:link\.deezer\.com|deezer\.page\.link)\/\S+/i;

function extractDeezerTrackId(text) {
  const match = text.match(DEEZER_TRACK_LINK_REGEX);
  return match ? match[1] : null;
}

// Короткие share-ссылки (из шаринга в приложении Deezer) редиректят на
// полный URL с ID трека — просто идём по редиректу и вытаскиваем ID оттуда.
async function resolveDeezerShareLink(url) {
  try {
    const res = await fetch(url, { redirect: "follow" });
    return extractDeezerTrackId(res.url || "");
  } catch (e) {
    console.error("Не удалось раскрыть Deezer share-ссылку:", url, e.message || e);
    return null;
  }
}

// Ищет в тексте сообщения ссылку на трек Deezer (обычную или короткую) и
// возвращает числовой ID трека, либо null, если ссылок нет.
async function findDeezerTrackIdInText(text) {
  if (!text) return null;
  const directId = extractDeezerTrackId(text);
  if (directId) return directId;
  const shareMatch = text.match(DEEZER_SHARE_LINK_REGEX);
  if (shareMatch) return await resolveDeezerShareLink(shareMatch[0]);
  return null;
}

// Получить трек с Deezer напрямую по ID (для ссылок вида deezer.com/track/ID) —
// в отличие от searchDeezerTracks не полагается на текстовый поиск.
async function getDeezerTrackById(trackId) {
  const url = `https://api.deezer.com/track/${encodeURIComponent(trackId)}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Deezer API status: ${res.status}`);
  const data = await res.json();
  if (data.error) throw new Error(data.error.message || "Deezer track not found");
  return data;
}

// Обработка ссылки на трек Deezer, кинутой в чат: находим ID, тянем метаданные
// напрямую по ID (без поиска) и скачиваем тем же путём, что и обычный /song.
//
// Оборачиваем весь флоу в withTyping("upload_document") — иначе между
// запросом пользователя и появлением статусного "🎵 Загружаю..." (которое
// шлётся только ПОСЛЕ похода за метаданными трека на Deezer) в чате полная
// тишина без какой-либо индикации, что бот вообще что-то делает. action
// "upload_document" — это тот же chat action, что Telegram показывает при
// реальной отправке аудио/документа ("отправляет файл..."), сюда подходит
// больше чем "typing". withTyping сам обновляет статус каждые 4с, так что
// заодно перекрывает и возможную паузу при скачивании/аплоаде самого трека.
async function handleDeezerLinkQuery(ctx, trackId) {
  await withTyping(
    ctx,
    async () => {
      try {
        const track = await getDeezerTrackById(trackId);
        await handleDeezerTrackObject(ctx, track);
      } catch (err) {
        console.error("Ошибка при получении трека Deezer по ссылке:", trackId, err.message || err);
        const errMsg = await ctx.reply("⚠️ Не удалось найти этот трек на Deezer.");
        markDeezerFlowMessage(ctx.chat.id, errMsg.message_id);
      }
    },
    "upload_document"
  );
}

// Тот же приём с withTyping("upload_document"), что и в handleDeezerLinkQuery
// выше — покрывает тишину и на самом поиске (searchDeezerTracks), и на
// возможной LLM-нормализации запроса, и на последующем скачивании/аплоаде
// внутри handleDeezerTrackObject.
async function handleDeezerQuery(ctx, query, originalQuery) {
  await withTyping(ctx, () => handleDeezerQueryInner(ctx, query, originalQuery), "upload_document");
}

async function handleDeezerQueryInner(ctx, query, originalQuery) {
  try {
    let tracks = await searchDeezerTracks(query, 5);

    // Прямой поиск ничего не дал — возможно, запрос "шумный" (опечатки,
    // фонетическая транслитерация кириллицей вроде "Даугтри ИТС нот
    // овер" и т.п.). Просим LLM восстановить нормальное написание и
    // пробуем ещё раз, прежде чем сдаваться/уходить на SoundCloud.
    if (!tracks || tracks.length === 0) {
      try {
        // Нормализуем по возможности ПОДЛИННЫЙ сырой текст пользователя
        // (originalQuery), а не уже "причёсанный" resolveTrackQuery результат
        // (query) - если он был передан и отличается от query. Иначе
        // получается испорченный телефон: resolveTrackQuery не умеет сама
        // расшифровывать фонетическую транслитерацию (это работа именно
        // normalizeTrackQueryViaLLM) и иногда просто слегка причёсывает
        // "шумный" текст во что-то похожее на имя ("трития рикошет" →
        // "Трий Ю — Рикошет"), а normalizeTrackQueryViaLLM потом угадывает
        // уже по этому вторично исказившемуся тексту, теряя всякую связь с
        // оригиналом и уезжая в случайного артиста ещё дальше.
        const sourceForNormalize =
          originalQuery && originalQuery.trim() ? originalQuery : query;
        const normalized = await normalizeTrackQueryViaLLM(sourceForNormalize);
        // "NONE" - модель явно отказалась гадать по нечитаемой
        // транслитерации (см. TRACK_QUERY_NORMALIZE_SYSTEM_PROMPT) - это
        // такой же честный отказ, как и null/пустая строка, и не должен
        // сам по себе улетать в поиск на Deezer буквальной строкой "NONE".
        if (normalized && !/^none$/i.test(normalized) && normalized.toLowerCase() !== query.trim().toLowerCase()) {
          const retryTracks = await searchDeezerTracks(normalized, 5);
          if (retryTracks && retryTracks.length > 0) {
            console.log(`Deezer: запрос "${query}" (исходный текст: "${sourceForNormalize}") переформулирован как "${normalized}" и найден`);
            tracks = retryTracks;
          }
        }
      } catch (normErr) {
        console.error("Ошибка нормализации запроса трека:", normErr.message || normErr);
      }
    }

    if (!tracks || tracks.length === 0) {
      // Если на Deezer не найдено и настроен SoundCloud - пробуем там
      if (SOUNDCLOUD_SERVER_URL) {
        console.log(`Deezer не нашёл "${query}", пробую SoundCloud`);
        return await handleSoundCloudQuery(ctx, query);
      }
      const notFoundMsg = await ctx.reply(`🔍 По запросу «${query}» ничего не найдено.`);
      markDeezerFlowMessage(ctx.chat.id, notFoundMsg.message_id);
      return;
    }
    await handleDeezerTrackObject(ctx, chooseDeezerTrack(ctx.chat.id, query, tracks));
  } catch (err) {
    console.error("Ошибка при получении трека Deezer:", err.message || err);
    const errMsg = await ctx.reply("⚠️ Не удалось загрузить трек с Deezer. Попробуй позже.");
    markDeezerFlowMessage(ctx.chat.id, errMsg.message_id);
  }
}

// Общая логика скачивания и отправки уже найденного трека Deezer (объект
// как из /search, так и из /track/{id} — формат полей одинаковый) — раньше
// была частью handleDeezerQuery, вынесена, чтобы её же использовала
// handleDeezerLinkQuery (поиск трека по прямой ссылке).
async function handleDeezerTrackObject(ctx, bestTrack) {
  try {
    const trackMeta = getDeezerTrackMeta(bestTrack);
    // Запоминаем ДО отправки (а не после) — даже если дальше по каким-то
    // причинам отправка не удастся, при следующем запросе в этом чате всё
    // равно не должны сразу же снова предложить именно этот трек как
    // первый кандидат (см. chooseDeezerTrack/lastSentDeezerTrack выше).
    rememberSentDeezerTrack(ctx.chat.id, bestTrack);
    const statusMsg = await ctx.reply(`🎵 Загружаю «${bestTrack.artist?.name || ""} — ${bestTrack.title}»...`);
    markDeezerFlowMessage(ctx.chat.id, statusMsg.message_id);

    const userId = ctx.from?.id;
    const format = userId
      ? ((await redis.get(`deezer_quality:${userId}`)) || DEFAULT_DEEZER_QUALITY)
      : DEFAULT_DEEZER_QUALITY;

    // Кэш file_id — полный аплоад в Telegram нужен только один раз
    const cacheKey = `deezer_fid:${bestTrack.id}:${format}`;
    const cachedFileId = await redis.get(cacheKey);

    // Если true — статусное сообщение уже стало аудио-сообщением, отдельно
    // удалять его в конце не нужно (и нечего).
    let statusBecameAudio = false;

    if (cachedFileId) {
      const edited = await editStatusMessageIntoAudio(ctx, statusMsg, cachedFileId, trackMeta);
      if (edited) {
        statusBecameAudio = true;
      } else {
        // Редактирование не удалось (например, сообщение слишком старое) —
        // откатываемся на старое поведение: отдельное сообщение + удаление статуса.
        const audioMsg = await ctx.replyWithAudio(cachedFileId, {
          title: trackMeta.title,
          performer: trackMeta.performer,
          duration: trackMeta.duration,
        });
        markDeezerFlowMessage(ctx.chat.id, audioMsg.message_id);
      }
    } else {
      let fileId = null;
      let usedFallback = false;

      // Основной путь: SnapDeploy сам скачивает, расшифровывает, зашивает метаданные
      // и грузит трек в Telegram через Bot API (send_audio). Работает для любых
      // форматов, включая FLAC.
      try {
        const sendAudioUrl = getDeezerSendAudioUrl(bestTrack.id, format, ctx.chat.id, trackMeta, statusMsg.message_id);
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), DEEZER_SEND_AUDIO_TIMEOUT_MS);
        const res = await fetch(sendAudioUrl, { signal: controller.signal }).finally(() => clearTimeout(timeoutId));
        if (res.ok) {
          const json = await res.json();
          if (json?.ok && json?.file_id) {
            fileId = json.file_id;

            if (json?.edited) {
              // Новый контракт: сервер сам отредактировал переданное
              // message_id через editMessageMedia — никакого отдельного
              // сообщения не создавалось, нам тут больше нечего делать.
              statusBecameAudio = true;
            } else if (json?.message_id) {
              // Старый контракт (или сервер сам откатился на sendAudio,
              // например если правка по message_id не удалась на его
              // стороне) — сервер прислал трек ОТДЕЛЬНЫМ сообщением.
              // Подчищаем: удаляем присланное им сообщение и вместо
              // него редактируем своё статусное в аудио.
              try {
                await ctx.api.deleteMessage(ctx.chat.id, json.message_id);
              } catch (e) {
                // Игнорируем — если не удалилось, просто оставим как есть ниже
              }
              const edited = await editStatusMessageIntoAudio(ctx, statusMsg, fileId, trackMeta);
              if (edited) {
                statusBecameAudio = true;
              } else {
                markDeezerFlowMessage(ctx.chat.id, json.message_id);
              }
            } else {
              // Ни edited, ни message_id — сервер просто вернул file_id
              // без побочных действий в Telegram. Редактируем статусное
              // сообщение сами (гладко, без мелькания).
              const edited = await editStatusMessageIntoAudio(ctx, statusMsg, fileId, trackMeta);
              statusBecameAudio = Boolean(edited);
            }
          } else {
            throw new Error(json?.error || json?.description || "send_audio returned no file_id");
          }
        } else {
          const text = await res.text().catch(() => "");
          throw new Error(`send_audio status ${res.status}: ${text.slice(0, 200)}`);
        }
      } catch (e) {
        console.error("Ошибка серверной отправки трека в Telegram (основной сервер):", e.message || e);

        // Фолбэк: основной сервер лёг — берём у HF прямую ссылку на MP3 320kbps
        // и отдаём её Telegram, чтобы тот сам скачал файл. FLAC через HF не отдаём —
        // там ограничение на аплоад через API, поэтому фолбэк всегда только MP3.
        // Если DEEZER_SPACE_URL_FALLBACK не задан — фолбэка нет, пробрасываем исходную ошибку.
        if (!DEEZER_SPACE_URL_FALLBACK) {
          throw e;
        }
        try {
          const fallbackFormat = "MP3_320";
          const fallbackUrl = getDeezerDownloadUrl(bestTrack.id, fallbackFormat, trackMeta, DEEZER_SPACE_URL_FALLBACK);
          const edited = await editStatusMessageIntoAudio(ctx, statusMsg, fallbackUrl, trackMeta);
          if (edited) {
            statusBecameAudio = true;
            fileId = edited?.audio?.file_id || null;
          } else {
            const sentMsg = await ctx.replyWithAudio(fallbackUrl, {
              title: trackMeta.title,
              performer: trackMeta.performer,
              duration: trackMeta.duration,
            });
            markDeezerFlowMessage(ctx.chat.id, sentMsg.message_id);
            fileId = sentMsg?.audio?.file_id || null;
          }
          usedFallback = true;
        } catch (fallbackErr) {
          console.error("Ошибка фолбэк-отправки трека через HF:", fallbackErr.message || fallbackErr);
          throw fallbackErr;
        }
      }

      if (fileId) {
        // Фолбэк всегда MP3_320, независимо от запрошенного качества — кэшируем
        // под своим ключом, чтобы не подсунуть MP3 вместо запрошенного FLAC в другой раз.
        const cacheKeyToUse = usedFallback ? `deezer_fid:${bestTrack.id}:MP3_320` : cacheKey;
        await redis.set(cacheKeyToUse, fileId, { ex: 60 * 60 * 24 * 30 });
      }
    }

    if (!statusBecameAudio) {
      try {
        await ctx.api.deleteMessage(ctx.chat.id, statusMsg.message_id);
      } catch (e) {
        // Игнорируем ошибку если сообщение уже удалено или слишком старое
      }
    }
  } catch (err) {
    console.error("Ошибка при получении трека Deezer:", err.message || err);
    const errMsg = await ctx.reply("⚠️ Не удалось загрузить трек с Deezer. Попробуй позже.");
    markDeezerFlowMessage(ctx.chat.id, errMsg.message_id);
  }
}

// ==== Обработка запросов SoundCloud ====
async function handleSoundCloudQuery(ctx, query) {
  try {
    const tracks = await searchSoundCloudTracks(query, 5);
    if (!tracks || tracks.length === 0) {
      const notFoundMsg = await ctx.reply(`🔍 По запросу «${query}» ничего не найдено на SoundCloud.`);
      markDeezerFlowMessage(ctx.chat.id, notFoundMsg.message_id);
      return;
    }
    
    const bestTrack = tracks[0];
    const trackMeta = getSoundCloudTrackMeta(bestTrack);
    const statusMsg = await ctx.reply(`🎵 Загружаю с SoundCloud: «${trackMeta.performer} — ${trackMeta.title}»...`);
    markDeezerFlowMessage(ctx.chat.id, statusMsg.message_id);

    // Кэш file_id
    const cacheKey = `soundcloud_fid:${bestTrack.id || bestTrack.permalink}`;
    const cachedFileId = await redis.get(cacheKey);

    let statusBecameAudio = false;

    if (cachedFileId) {
      const edited = await editStatusMessageIntoAudio(ctx, statusMsg, cachedFileId, trackMeta);
      if (edited) {
        statusBecameAudio = true;
      } else {
        const audioMsg = await ctx.replyWithAudio(cachedFileId, {
          title: trackMeta.title,
          performer: trackMeta.performer,
          duration: trackMeta.duration,
        });
        markDeezerFlowMessage(ctx.chat.id, audioMsg.message_id);
      }
    } else {
      // Отправляем по URL - Telegram сам скачивает
      const audioUrl = getSoundCloudDownloadUrl(trackMeta.url, trackMeta);
      
      try {
        // Делаем HEAD запрос чтобы получить thumbnail из заголовков
        let thumbnailUrl = null;
        try {
          const headResponse = await fetch(audioUrl, { method: 'HEAD' });
          thumbnailUrl = headResponse.headers.get('x-thumbnail-url');
          if (thumbnailUrl) {
            console.log(`📸 Found thumbnail for SoundCloud track: ${thumbnailUrl}`);
          }
        } catch (e) {
          console.warn('Failed to fetch thumbnail URL:', e.message);
        }

        // Пробуем отредактировать статусное сообщение в аудио
        const edited = await editStatusMessageIntoAudio(ctx, statusMsg, audioUrl, {
          ...trackMeta,
          thumb: thumbnailUrl || undefined,
        });

        if (edited) {
          statusBecameAudio = true;
          // Сохраняем file_id из отредактированного сообщения
          const fileId = edited?.audio?.file_id || null;
          if (fileId) {
            await redis.set(cacheKey, fileId, { ex: 60 * 60 * 24 * 30 });
          }
        } else {
          // Редактирование не удалось - откат на обычную отправку
          const audioMsg = await ctx.replyWithAudio(audioUrl, {
            title: trackMeta.title,
            performer: trackMeta.performer,
            duration: trackMeta.duration,
            thumb: thumbnailUrl || undefined,
          });
          markDeezerFlowMessage(ctx.chat.id, audioMsg.message_id);
          
          const fileId = audioMsg?.audio?.file_id || null;
          if (fileId) {
            await redis.set(cacheKey, fileId, { ex: 60 * 60 * 24 * 30 });
          }
        }
      } catch (e) {
        console.error("Ошибка отправки SoundCloud трека в Telegram:", audioUrl, e.message || e);
        throw e;
      }
    }

    // Удаляем статусное сообщение только если оно не стало аудио
    if (!statusBecameAudio) {
      try {
        await ctx.api.deleteMessage(ctx.chat.id, statusMsg.message_id);
      } catch (e) {
        // Игнорируем ошибку если сообщение уже удалено
      }
    }
  } catch (err) {
    console.error("Ошибка при получении трека SoundCloud:", err.message || err);
    await ctx.reply("⚠️ Не удалось загрузить трек с SoundCloud. Попробуй позже.");
  }
}

bot.command(["song", "deezer", "music", "track"], async (ctx) => {
  const match = ctx.message.text.match(/^\/(?:song|deezer|music|track)(?:@\w+)?\s+(.+)$/i);
  if (!match || !match[1]) {
    await ctx.reply("🎵 Использование: /song название песни");
    return;
  }
  
  const rawQuery = match[1].trim();
  
  // Если в запросе явно указан "soundcloud" - ищем только там
  if (isSoundCloudIntent(rawQuery)) {
    const query = stripSoundCloudKeyword(rawQuery);
    await handleSoundCloudQuery(ctx, query);
  } else {
    // Иначе ищем на Deezer (с fallback на SoundCloud если не найдено)
    await handleDeezerQuery(ctx, rawQuery);
  }
});

bot.command("quality", async (ctx) => {
  const userId = ctx.from?.id;
  const current = userId
    ? ((await redis.get(`deezer_quality:${userId}`)) || DEFAULT_DEEZER_QUALITY)
    : DEFAULT_DEEZER_QUALITY;
  const labels = { MP3_128: "128 kbps", MP3_320: "320 kbps", FLAC: "FLAC (lossless)" };
  const keyboard = new InlineKeyboard()
    .text((current === "MP3_128" ? "✅ " : "") + "128 kbps", "dq:MP3_128")
    .text((current === "MP3_320" ? "✅ " : "") + "320 kbps", "dq:MP3_320")
    .text((current === "FLAC" ? "✅ " : "") + "FLAC", "dq:FLAC");
  await ctx.reply(
    `🎚️ Качество скачивания Deezer\n\nТекущее: **${labels[current] || current}**\n\nВыбери формат:`,
    { parse_mode: "Markdown", reply_markup: keyboard }
  );
});

bot.callbackQuery(/^dq:(MP3_128|MP3_320|FLAC)$/, async (ctx) => {
  const format = ctx.match[1];
  const userId = ctx.from?.id;
  if (userId) {
    await redis.set(`deezer_quality:${userId}`, format, { ex: 60 * 60 * 24 * 365 });
  }
  const labels = { MP3_128: "128 kbps", MP3_320: "320 kbps", FLAC: "FLAC (lossless)" };
  const keyboard = new InlineKeyboard()
    .text((format === "MP3_128" ? "✅ " : "") + "128 kbps", "dq:MP3_128")
    .text((format === "MP3_320" ? "✅ " : "") + "320 kbps", "dq:MP3_320")
    .text((format === "FLAC" ? "✅ " : "") + "FLAC", "dq:FLAC");
  await ctx.editMessageText(
    `🎚️ Качество скачивания Deezer\n\nТекущее: **${labels[format]}**\n\nВыбери формат:`,
    { parse_mode: "Markdown", reply_markup: keyboard }
  );
  await ctx.answerCallbackQuery(`✅ Качество изменено на ${labels[format]}`);
});

bot.on("inline_query", async (ctx) => {
  const query = ctx.inlineQuery.query.trim();
  if (!query) return;
  try {
    const userId = ctx.from?.id;
    const format = userId
      ? ((await redis.get(`deezer_quality:${userId}`)) || DEFAULT_DEEZER_QUALITY)
      : DEFAULT_DEEZER_QUALITY;
    
    // В inline режиме Telegram не может скачивать FLAC по URL,
    // поэтому для FLAC используем MP3_320
    const inlineFormat = format === "FLAC" ? "MP3_320" : format;
    
    const tracks = await searchDeezerTracks(query, 10);
    const results = (await Promise.all(tracks.map(async (track) => {
      const trackMeta = getDeezerTrackMeta(track);
      const cacheKey = `deezer_fid:${track.id}:${inlineFormat}`;
      const cachedFileId = await redis.get(cacheKey);
      if (cachedFileId) {
        return {
          type: "audio",
          id: `cached:${track.id}:${inlineFormat}`,
          audio_file_id: cachedFileId,
          caption: `${trackMeta.performer} - ${trackMeta.title}`,
        };
      }

      const audioUrl = getDeezerDownloadUrl(track.id, inlineFormat, trackMeta);
      return {
        type: "audio",
        id: String(track.id),
        audio_url: audioUrl,
        title: track.title,
        performer: track.artist?.name || "Deezer",
        audio_duration: track.duration,
      };
    }))).filter(Boolean);
    await ctx.answerInlineQuery(results, { cache_time: 60 });
  } catch (err) {
    console.error("Ошибка inline-поиска Deezer:", err.message);
    await ctx.answerInlineQuery([], { cache_time: 10 });
  }
});

bot.on("message:text", async (ctx) => {
  const chatId = ctx.chat.id;
  const isGroup = ctx.chat.type === "group" || ctx.chat.type === "supergroup";

  // ==== Перехват текста для /memory -> "➕ добавить" ====
  // Должен идти РАНЬШЕ вообще всего остального в этом хендлере: пока
  // владелец в режиме "жду текст для памяти чата X" (см. кнопку memadd в
  // callback_query выше), следующее его текстовое сообщение ИЗ ЛЮБОГО
  // ЧАТА — это не обычная реплика боту, а содержимое нового пункта
  // памяти. Разовый режим — сбрасывается сразу после использования.
  if (isOwner(ctx) && pendingMemoryAdd.has(ctx.from.id)) {
    const targetChatId = pendingMemoryAdd.get(ctx.from.id);
    pendingMemoryAdd.delete(ctx.from.id);
    const text = ctx.message.text.trim();
    if (text) {
      const addedBy = getDisplayName(targetChatId, ctx.from);
      const { position, saved } = await addMemoryItem(targetChatId, text, addedBy);
      const title = knownChats.get(targetChatId) || String(targetChatId);
      if (saved) {
        await ctx
          .replyWithSticker(MEMORY_CONFIRM_STICKER_FILE_ID)
          .catch((err) => console.error("Не удалось отправить стикер-подтверждение памяти:", err.message));
        await ctx.reply(`пункт ${position} для «${title}»: «${text}»`);
      } else {
        await ctx.reply(
          `пункт ${position} для «${title}» добавил, но сохранить в Redis не получилось — переживёт только до рестарта`
        );
      }
    }
    return;
  }

  // ==== "Немой" префикс "*" ====
  // Если сообщение начинается с "*" — это реплика "для людей", не для
  // бота (например, реплай на сообщение бота, который увидят другие
  // участники чата, но реакция бота не нужна). Просто выходим сразу,
  // не логируя и не обрабатывая сообщение дальше никакими триггерами.
  if (ctx.message.text.trim().startsWith("*")) {
    return;
  }

  let userText = ctx.message.text;
  // Ставим true при успешном веб-поиске (см. ниже оба места вызова
  // searchWeb) — используется, чтобы дать финальному askLLM больше
  // времени: с подмешанными результатами поиска промпт длиннее обычного,
  // и модель объективно отвечает на нём дольше (см. POST_SEARCH_ASK_TIMEOUT_MS).
  let searchUsedThisMessage = false;
  // Сырой текст без последующих преобразований userText (вырезание имени,
  // добавление префиксов) — нужен для распознавания шахматных ходов,
  // которые парсит не LLM, а chess.js.
  const rawText = ctx.message.text;

  // ==== Музыка / Deezer / SoundCloud ====
  // 0. Прямая ссылка на трек Deezer в сообщении — качаем без всякого
  // распознавания интента, независимо от того, что написано вокруг ссылки.
  const deezerLinkTrackId = await findDeezerTrackIdInText(rawText);
  if (deezerLinkTrackId) {
    await handleDeezerLinkQuery(ctx, deezerLinkTrackId);
    return;
  }

  // 1. Прямой intent-запрос ("скинь песню X", "найди трек X")
  const strippedText = stripBotAddressing(rawText, ctx);

  // 1a. "нарисуй <промпт>" в начале сообщения — тот же /imggen, но без
  // слэша (см. DRAW_PREFIX_REGEX/handleImgGenRequest выше). Тот же гейт
  // isBotAddressed в группах, что и у музыкального интента ниже — иначе
  // в группе бот реагировал бы на "нарисуй" в чужой переписке, не
  // адресованной ему вовсе.
  if (!isGroup || isBotAddressed(ctx, rawText)) {
    const drawMatch = strippedText.match(DRAW_PREFIX_REGEX);
    if (drawMatch) {
      const drawPrompt = strippedText.slice(drawMatch[0].length).trim();
      await handleImgGenRequest(ctx, drawPrompt, "напиши, что нарисовать, например: нарисуй рыжего кота в скафандре на Марсе");
      return;
    }
  }

  // 1b. Неполный/двусмысленный запрос трека ("скинь этот трек", "пришли
  // её", "пришли главный хит o-zone") — пытаемся понять из текущего
  // сообщения и контекста переписки, о каком треке речь, и если
  // получилось — ведём себя так же, как при обычном intent-запросе.
  // Если понять не удалось, явно сообщаем об этом (см. ниже).
  //
  // ВАЖНО: в группе гоняем через этот разбор только сообщения, реально
  // адресованные боту (обращение по имени "Женя", реплай на сообщение
  // бота, упоминание через @username) — см. isBotAddressed. Без этого
  // гейта широкие regex'ы внутри isDeezerAmbiguousMusicRequest (ловящие
  // подстроки вроде "пришл"/"дашь" где угодно в тексте) разбирали вообще
  // любую реплику в чате, включая не адресованные боту вовсе — например
  // "запчасти пришли" (прошедшее время "прийти", а не просьба прислать
  // трек) или "предашь" (подстрока "дашь" внутри не связанного слова).
  // В личке (isGroup === false) это ограничение не нужно — там боту
  // адресовано вообще всё.
  if ((!isGroup || isBotAddressed(ctx, rawText)) && isDeezerAmbiguousMusicRequest(strippedText)) {
    const resolvedTrack = await resolveTrackQuery(chatId, strippedText);
    if (resolvedTrack) {
      await handleDeezerQuery(ctx, resolvedTrack, strippedText);
      return;
    }
    // Явно даём знать, что не поняли, о каком треке речь — вместо того,
    // чтобы молча падать в обычный чат, где LLM может выдать
    // правдоподобный, но по факту придуманный ответ вместо честного
    // "не понял". Так же сюда попадаем, если распознали такой запрос, но
    // у всех целей сейчас cooldown/ошибка (см. askOnceForTrack).
    console.log(`Deezer: неполный запрос "${strippedText}" в чате ${chatId} - не удалось определить трек по контексту`);
    const clarifyMsg = await ctx.reply(
      "Не понял, о каком треке речь — напиши название явно, например: «скинь трек Radio Company - Sounds of Someday»."
    );
    markDeezerFlowMessage(ctx.chat.id, clarifyMsg.message_id);
    return;
  }

  const deezerQuery = parseDeezerIntent(strippedText);
  if (deezerQuery) {
    // Проверяем, есть ли явное указание на SoundCloud
    if (isSoundCloudIntent(deezerQuery)) {
      const query = stripSoundCloudKeyword(deezerQuery);
      await handleSoundCloudQuery(ctx, query);
    } else {
      await handleDeezerQuery(ctx, deezerQuery);
    }
    return;
  }

  // 2. Reply на сообщение бота с intent-запросом или просто названием трека
  const replyMsg = ctx.message.reply_to_message;
  if (replyMsg && replyMsg.from?.is_bot) {
    // Пользователь ответил на сообщение бота — проверяем intent
    const replyIntent = parseDeezerIntent(rawText);
    if (replyIntent) {
      // Проверяем SoundCloud intent
      if (isSoundCloudIntent(replyIntent)) {
        const query = stripSoundCloudKeyword(replyIntent);
        await handleSoundCloudQuery(ctx, query);
      } else {
        await handleDeezerQuery(ctx, replyIntent);
      }
      return;
    }
    // Раньше тут был ещё и "нечёткий" фолбэк: любой реплай на сообщение,
    // помеченное как часть Deezer-потока (markDeezerFlowMessage), не
    // подошедший под явный intent выше, всё равно запускал новый поиск по
    // сырому тексту реплая (в расчёте на то, что человек мог просто
    // написать голое название трека без "найди песню..."). На практике это
    // било по любому комментарию/реакции на присланный трек, который не
    // попал под DEEZER_QUESTION_REGEX/VOICE_TRANSCRIBE_INTENT_REGEX (типа
    // "красава", "ты справился", "огонь трек") — бот воспринимал это как
    // название новой песни и лез искать её на Deezer вместо того, чтобы
    // просто ответить по-человечески с пониманием, что реплай был на
    // присланный трек. Явные запросы ("найди трек X", "/song X") уже
    // ловятся веткой выше — остальное теперь просто уходит дальше по коду
    // и попадает в блок isReplyToBot (repliedToBotMsg.audio), который сам
    // подмешивает контекст "бот ранее прислал трек «...»" в промпт LLM.
  }

  // Определяем пол пораньше (до проверки триггеров), чтобы выбрать нужный
  // блок — мужской или женский. Смотрим по исходному тексту сообщения.
  updateGenderGuess(chatId, ctx.from, ctx.message.text);
  const gender = getGender(chatId, ctx.from.id);

  // ==== "Доброе утро" — реакция ❤️ + ответный текст, только для женского
  // пола. Срабатывает на само приветствие в любом месте сообщения
  // ("доброе утро", "доброго утра" и т.п.), без учёта регистра и буквы ё.
  // Если пол мужской или ещё не определён — не срабатывает вообще (см.
  // просьбу — мужикам ни лайков, ни ответа). Останавливаем обработку этим
  // же сообщением дальше, чтобы не пришёл ещё и обычный LLM-ответ поверх.
  {
    const normalizedForMorning = userText.toLowerCase().replace(/ё/g, "е");
    if (gender === "f" && /добр(ое|ого)\s+утр[оа]/.test(normalizedForMorning)) {
      await ctx.api
        .setMessageReaction(chatId, ctx.message.message_id, [{ type: "emoji", emoji: "❤" }])
        .catch((err) => console.error("Не удалось поставить реакцию на 'доброе утро':", err));
      await ctx
        .reply("доброе утро", {
          reply_parameters: { message_id: ctx.message.message_id },
          message_thread_id: ctx.message.message_thread_id,
        })
        .catch((err) => console.error("Не удалось ответить на 'доброе утро':", err));
      return;
    }
  }

  // Стёб по триггерным фразам — срабатывает независимо от того,
  // обращались ли к боту напрямую. Блок выбирается по полу отправителя:
  // мужчины -> MALE_BANTER_TRIGGERS/"banter_male", женщины ->
  // FEMALE_BANTER_TRIGGERS/"banter_female". Если пол неизвестен — не
  // срабатывает. Дальше сообщение всё равно обрабатывается как обычно
  // (вдруг оно ещё и адресовано боту).
  // regexStickerFired — чтобы модель не прислала ещё один стикер тем же
  // тегом на то же сообщение (см. использование ниже, у отправки ответа).
  let regexStickerFired = false;
  if (gender === "m" && matchesTrigger(userText, MALE_BANTER_TRIGGERS)) {
    regexStickerFired = true;
    const stickerId = pickSticker("banter_male");
    if (stickerId) {
      await ctx
        .replyWithSticker(stickerId, {
          reply_parameters: { message_id: ctx.message.message_id },
          message_thread_id: ctx.message.message_thread_id,
        })
        .catch((err) => console.error("Не удалось отправить banter_male-стикер:", err));
    }
  } else if (gender === "f" && matchesTrigger(userText, FEMALE_BANTER_TRIGGERS)) {
    regexStickerFired = true;
    const stickerId = pickSticker("banter_female");
    if (stickerId) {
      await ctx
        .replyWithSticker(stickerId, {
          reply_parameters: { message_id: ctx.message.message_id },
          message_thread_id: ctx.message.message_thread_id,
        })
        .catch((err) => console.error("Не удалось отправить banter_female-стикер:", err));
    }
  }

  // Проверка отгадки в крокодиле — срабатывает на ЛЮБОЕ сообщение в чате,
  // без обращения к боту по имени (иначе играть было бы неудобно: в
  // реальной игре отгадки просто выкрикивают). Ведущего из проверки
  // исключаем — его собственные подсказки не должны засчитываться сами
  // себе. Если слово отгадано — раунд сразу завершается и открывается
  // кнопка для следующего ведущего.
  {
    const krokodilGame = getKrokodilGame(chatId);
    if (krokodilGame && krokodilGame.status === "active" && ctx.from.id !== krokodilGame.hostId) {
      const tokens = rawText.toLowerCase().replace(/ё/g, "е").match(/[a-zа-я]+/gi) || [];
      const guessed = tokens.some((t) => krokodilTokenMatches(t, krokodilGame.word));
      if (guessed) {
        const scoreMap = getKrokodilScoreMap(chatId);
        const label = krokodilPlayerLabel(ctx.from);
        const prev = scoreMap.get(ctx.from.id) || { name: label, score: 0 };
        const updated = { name: label, score: prev.score + 1 };
        scoreMap.set(ctx.from.id, updated);
        saveKrokodilScores(chatId);

        krokodilGames.set(chatId, { status: "idle", usedWords: krokodilGame.usedWords });
        saveKrokodilGame(chatId);

        await ctx.reply(
          `🎉 ${label} угадал(а) слово «${krokodilGame.word}»! +1 очко (теперь ${updated.score}).\n\n${formatKrokodilLeaderboard(
            chatId
          )}`,
          { reply_markup: krokodilIdleKeyboard(), reply_parameters: { message_id: ctx.message.message_id } }
        );
        return; // раунд закрыт — дальше это сообщение никуда не идёт (ни в чат-триггеры, ни в LLM)
      }
    }
  }

  // Флаг "уже ответили по существу реплая" (фото/голосовое/аудио/текст
  // чужого сообщения, см. repliedTag ниже) — используется, чтобы отличить
  // "Женя, о чём тут речь?" РЕПЛАЕМ на конкретное голосовое/аудио от той же
  // фразы без реплая (просьба пересказать чат целиком). Объявлен здесь, а
  // не внутри if (isGroup), потому что нужен ниже, за пределами этого блока
  // (в проверке RECAP_INTENT_REGEX).
  let repliedToHandled = false;

  // В личке бот отвечает на вообще любое сообщение — показываем "печатает"
  // сразу, не дожидаясь того, в какую конкретно ветку (шутка/погода/фильм/
  // обычный чат) уйдёт обработка. Не await — это просто индикатор, ждать
  // его не нужно, а ошибку (например нет прав в чате) тихо проглатываем.
  if (!isGroup) {
    sendTypingAction(ctx);
  }

  if (isGroup) {
    rememberUsername(chatId, ctx.from);

    // В группе отвечаем только если:
    // 1) сообщение начинается с обращения по имени ("Женя, ...")
    // 2) это реплай на сообщение самого бота
    // 3) бота явно упомянули через @username
    // 4) кто-то позвал настоящего Женю через его тег в Telegram (@EVGEN1Y_V)
    const startsWithName = nameTriggerRegex.test(userText);
    const isReply = isReplyToBot(ctx);
    const isMentioned =
      ctx.message.entities?.some(
        (e) =>
          e.type === "mention" &&
          userText
            .substring(e.offset, e.offset + e.length)
            .toLowerCase() === `@${ctx.me.username?.toLowerCase()}`
      ) ?? false;
    const isOwnerMentioned = ownerMentionRegex.test(userText);
    // Игнор-лист (см. tryHandleOwnerIgnoreDirective / ignoreUser) — если
    // хозяин попросил игнорировать этого человека, бот молчит ему в ответ
    // ВООБЩЕ, даже если позвали по имени/реплаем/тегом. Самого хозяина
    // так заглушить нельзя (targetId === ctx.from.id уже отсекается при
    // установке игнора, но на всякий случай не даём это обойти и тут).
    const isIgnored = !isOwner(ctx) && isUserIgnored(chatId, ctx.from.id);
    const isAddressedToBot = !isIgnored && (startsWithName || isReply || isMentioned || isOwnerMentioned);

    // Пишем сообщение в лог чата (см. pushChatLog) ДО фильтра "не наше
    // сообщение — молчим" ниже — иначе в лог попадали бы только реплики,
    // адресованные боту, и пересказывать было бы нечего. Сообщения от
    // других ботов не логируем. Пересланные сообщения (мемы/новости из
    // каналов) тоже не логируем — это чужой контент, а не то, что реально
    // писали участники чата (см. isForwardedMessage).
    if (!ctx.from.is_bot && !isForwardedMessage(ctx.message)) {
      const speakerName = getDisplayName(chatId, ctx.from);
      pushChatLog(chatId, speakerName, rawText, isAddressedToBot);

      // Запоминаем, кто есть кто — нужно для досье, чтобы извлечение
      // могло сослаться на уже знакомого человека, а не только на автора
      // сообщения (см. resolveUserIdByName).
      rememberMemberName(chatId, ctx.from.id, speakerName);

      // Реплай с обращением по имени ("Вася, ...") на другого участника —
      // надёжный сигнал для алиаса, без гадания по нику (см. VOCATIVE_NAME_REGEX).
      maybeLearnAliasFromReply(chatId, ctx, rawText);

      // Досье — фоново, без await: не должно задерживать обычный ответ
      // бота и не должно уронить обработку сообщения, если вдруг упадёт.
      // Подкладываем контекст, чтобы короткие ответы не терялись:
      // 1) если это реплай (на бота ИЛИ на другого человека) — берём текст
      //    того сообщения напрямую, это самый точный сигнал;
      // 2) иначе — несколько последних реплик чата, вдруг вопрос и ответ
      //    просто идут подряд без формального реплая ("Люда, сколько у
      //    тебя детей?" -> следующим сообщением "трое").
      const conversationContext = buildProfileExtractionContext(chatId, ctx);
      extractProfileFacts(chatId, ctx.from.id, speakerName, rawText, conversationContext).catch(() => {});
    }

    if (!isAddressedToBot) {
      return; // не наше сообщение — молчим
    }

    // Показываем "печатает" сразу, как только поняли, что сообщение
    // адресовано боту — неважно, обращением по имени, реплаем на бота,
    // упоминанием через @username или тегом настоящего Жени. Раньше
    // индикатор запускался только внутри конкретных веток обработки
    // (шутка/погода/фильм/обычный LLM-чат) — на реплае без имени триггера
    // это визуально выглядело так, будто "печатает" бывает только по
    // триггер-фразе. Более точечные вызовы replyWithChatAction("typing")
    // ниже по коду не мешают — Telegram просто продлевает уже показанный
    // статус ещё на ~5 секунд.
    console.log(`[typing] fire isReply=${isReply} startsWithName=${startsWithName} isMentioned=${isMentioned}`);
    sendTypingAction(ctx);

    if (startsWithName) {
      userText = stripNameTrigger(userText);
      if (!userText) userText = "привет"; // если написали просто "Женя"
    }

    // Если бота явно упомянули через @username — вырезаем сам тег из текста,
    // который пойдёт модели. Иначе модель увидит сырой "@EVGEN1Y_VBOT" и
    // может спутать его с тегом настоящего Жени (@EVGEN1Y_V — это ровно
    // префикс юзернейма бота), хотя isMentioned/isOwnerMentioned на уровне
    // кода уже корректно их различают (\b в ownerMentionRegex + проверка
    // !isMentioned ниже) — проблема именно в том, что сырая строка всё
    // равно долетает до LLM и вводит её в заблуждение.
    if (isMentioned) {
      const botMentionEntity = ctx.message.entities.find(
        (e) =>
          e.type === "mention" &&
          userText
            .substring(e.offset, e.offset + e.length)
            .toLowerCase() === `@${ctx.me.username?.toLowerCase()}`
      );
      if (botMentionEntity) {
        userText =
          userText.slice(0, botMentionEntity.offset) +
          userText.slice(botMentionEntity.offset + botMentionEntity.length);
        userText = userText.trim();
        if (!userText) userText = "привет"; // если написали только "@EVGEN1Y_VBOT"
      }
    }

    // Текст вопроса ДО добавления "Имя: " — нужен ниже для intent-проверки
    // реплая на голосовое ("текст" vs обычный вопрос по содержанию), см.
    // VOICE_TRANSCRIBE_INTENT_REGEX.
    const strippedQuestion = userText;

    // Подсказываем модели, кто говорит — "Имя: текст"
    const displayName = getDisplayName(chatId, ctx.from);
    userText = `${displayName}: ${userText}`;

    // Если позвали именно тег настоящего Жени (а не по имени/реплаем на
    // бота) — добавляем метку-подсказку, см. пояснение в SYSTEM_PROMPT.
    if (isOwnerMentioned && !startsWithName && !isReply && !isMentioned) {
      userText = `[позвали через тег настоящего Жени @${OWNER_USERNAME}] ${userText}`;
    }

    // Реплай на чужое сообщение (не на сообщение самого бота) с вопросом/
    // репликой к боту — например "Женя как тебе?" ответом на фото еды или
    // "Женя, что думаешь?" ответом на пересланную статью/мем. Работает и
    // для форвардов: если фото форварда не адресовали боту при пересылке
    // (см. bot.on("message:photo")), оно НЕ было распознано заранее — тут
    // догоняем и распознаём его "лениво", именно потому что сейчас его
    // явно попросили прокомментировать (в отличие от фонового распознавания
    // каждого форварда просто на всякий случай — это то, что раньше жрало
    // лимит TPM на пачках пересланных мемов).
    const repliedTo = ctx.message.reply_to_message;
    let repliedTag = "";
    if (repliedTo && !isReplyToBot(ctx)) {
      const repliedName = getDisplayName(chatId, repliedTo.from);

      const shazamMedia = getShazamMedia(repliedTo);
      const videoOnlyMedia = getVideoOnlyMedia(repliedTo);

      if (shazamMedia && SHAZAM_INTENT_REGEX.test(strippedQuestion)) {
        // Явная команда на распознавание трека — отвечаем ПРЯМО НА САМО
        // видео (см. handleShazamFromReply) и не идём в общий askLLM-путь,
        // как и с "текст"/"расшифруй" у голосовых ниже.
        await handleShazamFromReply(ctx, repliedTo, shazamMedia);
        return;
      } else if (videoOnlyMedia) {
        // Реплай на видео с обычным вопросом (не про трек) — узнаём, что
        // происходит в видео, через Gemini (см. captionVideo выше), и
        // подмешиваем это в промпт как repliedTag, как и с фото — дальше
        // отвечает уже обычный askLLM в стиле Жени.
        let info = getVideoCaption(chatId, repliedTo.message_id);
        if (!info) {
          try {
            const caption = await captionVideo(ctx, videoOnlyMedia.fileObj.file_id, videoOnlyMedia.mime);
            info = { name: repliedName, caption };
            rememberVideoCaption(chatId, repliedTo.message_id, repliedName, caption);
          } catch (err) {
            console.error(
              `Не удалось проанализировать видео из реплая в чате ${chatId}:`,
              err.status ?? "-",
              err.body ?? err.message
            );
          }
        }
        if (info) {
          repliedTag = `[видео от ${info.name}: ${info.caption}] `;
        } else {
          repliedTag = `[собеседник ответил на видео от ${repliedName}, но проанализировать его не получилось из-за технической ошибки] `;
        }
      } else if (repliedTo.photo) {
        let info = getPhotoCaption(chatId, repliedTo.message_id);
        if (!info) {
          try {
            const sizes = repliedTo.photo;
            const photo = sizes.length > 1 ? sizes[sizes.length - 2] : sizes[sizes.length - 1];
            const { caption } = await captionPhoto(ctx, photo.file_id);
            info = { name: repliedName, caption };
            rememberPhotoCaption(chatId, repliedTo.message_id, repliedName, caption);
          } catch (err) {
            console.error(
              `Не удалось лениво распознать фото из реплая в чате ${chatId}:`,
              err.status ?? "-",
              err.body ?? err.message
            );
          }
        }
        if (info) repliedTag = `[фото от ${info.name}: ${info.caption}] `;
      } else if (repliedTo.text || repliedTo.caption) {
        // Обычный текст участника или пересланный пост/статья — кладём как
        // есть, с ограничением длины, чтобы не тащить в промпт целую
        // простыню пересланной статьи. Помечаем отдельно, форвард это или
        // нет — модели полезно понимать разницу (см. SYSTEM_PROMPT).
        const raw = (repliedTo.text || repliedTo.caption || "").trim();
        const snippet = raw.length > 1000 ? `${raw.slice(0, 1000)}…` : raw;
        const kind = isForwardedMessage(repliedTo) ? "переслано" : "сообщение";
        repliedTag = `[${kind} от ${repliedName}: ${snippet}] `;
      } else if (
        repliedTo.voice ||
        repliedTo.video_note ||
        repliedTo.audio ||
        isAudioDocument(repliedTo.document)
      ) {
        // ==== Реплай на голосовое/кружочек/аудиофайл ====
        // Три вида медиа гонятся через один и тот же Whisper-пайплайн (Groq
        // Whisper одинаково умеет и в речь, и в тексты песен): voice/
        // video_note — как и раньше, audio/document(аудио) — FLAC/MP3/etc,
        // присланные и как "музыка" с плеером, и просто файлом (см.
        // isAudioDocument выше). Два разных сценария по тексту вопроса:
        // 1) "Женя, текст" / "расшифруй" / "что он сказал" — литеральная
        //    расшифровка. Отвечаем ПРЯМО НА САМО медиа (а не на сообщение с
        //    командой) — так расшифровка выглядит подписью под ним, а не
        //    тонет в переписке с ботом.
        // 2) Любой другой вопрос ("о чём тут вкратце?", "перескажи",
        //    "переведи", "что думаешь", "о чём песня") — расшифровку не
        //    показываем отдельно, а подмешиваем её в промпт как repliedTag
        //    (см. фото выше) и даём модели ответить по существу своими
        //    словами — для длинного ГС или текста песни это и есть
        //    пересказ без воды, без отдельного хардкоженного
        //    summary-пайплайна.
        const mediaKind = repliedTo.voice ? "voice" : repliedTo.video_note ? "video_note" : "audio";
        const mediaObj = repliedTo.voice || repliedTo.video_note || repliedTo.audio || repliedTo.document;
        const MEDIA_LABEL = { voice: "голосовое", video_note: "кружочек", audio: "аудиофайл" };
        const label = MEDIA_LABEL[mediaKind];
        const durationLabel = formatVoiceDuration(mediaObj.duration);
        // Название/исполнитель — есть только у audio (у document таких полей
        // нет), но когда есть — полезный контекст модели даже если сам
        // текст не распознался (инструментал).
        const trackMeta =
          mediaKind === "audio" && (mediaObj.title || mediaObj.performer)
            ? ` (${[mediaObj.performer, mediaObj.title].filter(Boolean).join(" — ")})`
            : "";
        const wantsLiteralText = VOICE_TRANSCRIBE_INTENT_REGEX.test(strippedQuestion);
        // Ручной выбор движка ("текст whisper"/"текст giga") — при явном
        // выборе не берём закэшированную расшифровку (она могла быть
        // сделана другим движком раньше), а перераспознаём и перезаписываем
        // кэш, иначе явная просьба "давай через Whisper" молча вернула бы
        // старый (возможно ошибочный) результат GigaAM.
        const engineOverride = detectEngineOverride(strippedQuestion);

        let info = engineOverride === "auto" ? getVoiceTranscript(chatId, repliedTo.message_id) : null;
        let transcribeError = null;
        let tooLarge = false;
        if (!info) {
          if (mediaObj.file_size && mediaObj.file_size > MAX_TRANSCRIBE_FILE_SIZE) {
            // Telegram Bot API не отдаёт file_path (а значит и не даёт
            // скачать) файлы крупнее 20MB — сразу честно говорим об этом
            // вместо попытки скачать и непонятной ошибки на этом месте.
            tooLarge = true;
          } else {
            try {
              const { text } = await transcribeVoice(ctx, mediaObj.file_id, engineOverride);
              info = { name: repliedName, text };
              rememberVoiceTranscript(chatId, repliedTo.message_id, repliedName, text);
            } catch (err) {
              transcribeError = err;
              console.error(
                `Не удалось расшифровать ${label} из реплая в чате ${chatId}:`,
                err.status ?? "-",
                err.body ?? err.message
              );
            }
          }
        }

        if (wantsLiteralText) {
          if (tooLarge) {
            await ctx.reply(`файл слишком большой (больше 20 МБ), Telegram не даёт его скачать ботам`, {
              reply_parameters: { message_id: ctx.message.message_id },
              message_thread_id: ctx.message.message_thread_id,
            });
          } else if (transcribeError) {
            await ctx.reply(`не смог расшифровать ${label}, попробуй ещё раз`, {
              reply_parameters: { message_id: ctx.message.message_id },
              message_thread_id: ctx.message.message_thread_id,
            });
          } else if (!info.text) {
            const emptyMsg =
              mediaKind === "audio"
                ? "не распознал текст в этом аудиофайле — похоже, инструментал, либо качество не позволило"
                : `не разобрал речь в этом ${label === "голосовое" ? "голосовом" : "кружочке"} — тишина или шум`;
            await ctx.reply(emptyMsg, {
              reply_parameters: { message_id: repliedTo.message_id },
              message_thread_id: ctx.message.message_thread_id,
            });
          } else {
            await ctx.reply(info.text, {
              reply_parameters: { message_id: repliedTo.message_id },
              message_thread_id: ctx.message.message_thread_id,
            });
          }
          return; // сюда не идём в общий askLLM-путь — расшифровка уже отправлена
        }

        if (tooLarge) {
          repliedTag = `[собеседник ответил на ${label}${trackMeta} от ${repliedName}, но файл слишком большой для распознавания (больше 20 МБ)] `;
        } else if (transcribeError) {
          repliedTag = `[собеседник ответил на ${label}${trackMeta} от ${repliedName}, но расшифровать его не получилось из-за технической ошибки] `;
        } else if (info.text) {
          const transcriptForPrompt =
            info.text.length > VOICE_TRANSCRIPT_PROMPT_LIMIT
              ? `${info.text.slice(0, VOICE_TRANSCRIPT_PROMPT_LIMIT)}…`
              : info.text;
          const textFieldLabel = mediaKind === "audio" ? "текст" : "расшифровка";
          repliedTag = `[${label}${trackMeta} от ${repliedName}${durationLabel ? ` (${durationLabel})` : ""}, ${textFieldLabel}: ${transcriptForPrompt}] `;
        } else {
          const emptyTag =
            mediaKind === "audio"
              ? `[аудиофайл${trackMeta} от ${repliedName} — текст не распознан, вероятно инструментал] `
              : `[${label} от ${repliedName} — речь не распознана, тишина или шум] `;
          repliedTag = emptyTag;
        }
      }

      if (repliedTag) {
        userText = `${repliedTag}${userText}`;
        repliedToHandled = true;
      }
    }

    // Прямой вопрос про фото/картинку в чате БЕЗ реплая на конкретное
    // сообщение — например "Женя, как тебе фото кота в чате?". Реплай на
    // само фото уже обработан выше (repliedTag); если он что-то дал —
    // повторный поиск не нужен и может привести к путанице (два разных
    // фото в одном промпте). Требуем ОБА регекса разом: PHOTO_MENTION —
    // что вообще идёт речь про фото/картинку/скриншот, и PHOTO_CONTEXT —
    // что это отсылка к чему-то из чата, а не общий вопрос в духе "как
    // сделать скриншот на андроид" (там тоже есть слово "скриншот", но
    // никакого фото из чата искать не нужно). Ищем последнее подходящее
    // фото в ChatLog (там лежат описания вообще всех фото в чате, см.
    // bot.on("message:photo")) и подсказываем его модели ТОЛЬКО для этого
    // конкретного ответа — в HISTORY это не попадает, так что в следующий
    // раз без нового вопроса бот про это фото уже не вспомнит.
    if (!repliedTag && PHOTO_MENTION_REGEX.test(rawText) && PHOTO_CONTEXT_REGEX.test(rawText)) {
      const photoEntry = [...getChatLog(chatId)]
        .reverse()
        .find((m) => m.text.startsWith("[фото"));
      if (photoEntry) {
        const match = photoEntry.text.match(/^\[фото(?::\s*([\s\S]+?))?\]/);
        const photoCaption = (match && match[1]) || photoEntry.text.replace(/^\[фото\]\s*/, "");
        userText = `[в чате недавно было фото от ${photoEntry.name}: ${photoCaption}] ${userText}`;
      }
    }
  }

  // ==== "Запомни: ..." / "забудь ..." — память чата голосом ====
  // Сюда попадаем уже только с сообщением, точно адресованным боту (для
  // групп — см. return выше по isAddressedToBot; в личке адресовано всё).
  // Работает и обращением по имени ("Женя, запомни ..."), и реплаем на
  // сообщение бота, и упоминанием через @username — как обычное
  // обращение (см. stripBotAddressing). "Запомни" может любой участник
  // чата, "забудь" — только владелец бота (см. isOwner).
  {
    const memCommandText = stripBotAddressing(rawText, ctx);
    const replyOpts = {
      reply_parameters: { message_id: ctx.message.message_id },
      message_thread_id: ctx.message.message_thread_id,
    };

    const rememberMatch = memCommandText.match(/^запомни[,:]?\s+([\s\S]+)/i);
    if (rememberMatch) {
      const text = rememberMatch[1].trim();
      if (text) {
        // Директивы хозяина (сейчас — игнор/разигнор участника) всегда
        // приоритетны и работают программно, а не через обычный пункт
        // памяти (см. tryHandleOwnerIgnoreDirective) — проверяем ДО
        // addMemoryItem, чтобы такая фраза не осела просто текстом,
        // который LLM может выполнить, а может и нет.
        if (isOwner(ctx) && (await tryHandleOwnerIgnoreDirective(chatId, text, ctx, replyOpts))) {
          return;
        }

        // Короткая форма задать алиас прямо через "запомни" — "запомни
        // пользователь 123456789 это Вася" (с/без скобок вокруг id).
        // Раньше такая фраза просто оседала как непрозрачный текст в
        // общей памяти чата (см. addMemoryItem ниже) — LLM видела текст
        // "пользователь 123456789 это Вася", но это НЕ давало боту
        // возможности сослаться на реального человека (ссылку/степень
        // на профиль LLM сама сгенерировать не может, у неё нет доступа
        // к id). Ловим этот паттерн отдельно и сразу заводим настоящий
        // алиас (см. setAlias/resolveUserIdByName) — тогда, например,
        // "кто такой Вася" (см. WHO_IS_INTENT_REGEX выше) сможет отдать
        // рабочую ссылку на аккаунт.
        const aliasShortcutMatch = text.match(/^пользовател[ья]\s*\(?\s*(\d+)\s*\)?\s*[-—]?\s*это\s+(.+)$/i);
        if (aliasShortcutMatch) {
          const targetId = Number(aliasShortcutMatch[1]);
          const aliasName = aliasShortcutMatch[2].trim();
          if (aliasName) {
            setAlias(chatId, targetId, aliasName, `id:${targetId}`);
            rememberMemberName(chatId, targetId, aliasName);
            await ctx.reply(`понял, пользователь ${targetId} — это ${aliasName}`, replyOpts);
            return;
          }
        }

        const addedBy = getDisplayName(chatId, ctx.from);
        const { position, saved } = await addMemoryItem(chatId, text, addedBy);
        if (saved) {
          // Стикер — единственное подтверждение "запомнил", которое реально
          // означает, что запись улетела в Redis (см. MEMORY_CONFIRM_STICKER_FILE_ID).
          await ctx
            .replyWithSticker(MEMORY_CONFIRM_STICKER_FILE_ID, replyOpts)
            .catch((err) => console.error("Не удалось отправить стикер-подтверждение памяти:", err.message));
        } else {
          // Redis недоступен/упал — пункт всё равно добавлен в оперативную
          // память процесса и будет использоваться до рестарта, но
          // стикер-подтверждение НЕ шлём, чтобы не создавать ложного
          // впечатления, что запоминание точно переживёт рестарт.
          await ctx.reply(
            `пункт ${position} добавил, но сохранить в Redis не получилось — переживёт только до рестарта`,
            replyOpts
          );
        }
      }
      return;
    }

    const forgetMatch = memCommandText.match(/^забудь(?:\s+([\s\S]+))?$/i);
    if (forgetMatch) {
      if (!isOwner(ctx)) {
        await ctx.reply("забывать могу только по команде хозяина", replyOpts);
        return;
      }
      const arg = (forgetMatch[1] || "").trim();
      const list = getMemoryList(chatId);

      if (!arg || /^вс[её]$/i.test(arg)) {
        clearMemory(chatId);
        await ctx.reply("почистил всю память этого чата", replyOpts);
        return;
      }

      const pointMatch = arg.match(/^пункт\s*(\d+)$/i) || arg.match(/^(\d+)$/);
      if (pointMatch) {
        const idx = Number(pointMatch[1]);
        const removedText = list[idx - 1]?.text;
        if (removeMemoryItem(chatId, idx)) {
          await ctx.reply(`забыл пункт ${idx}${removedText ? `: «${removedText}»` : ""}`, replyOpts);
        } else {
          await ctx.reply(`нет пункта ${idx} — в этом чате всего ${list.length}`, replyOpts);
        }
        return;
      }

      // Без явного номера — ищем пункт по частичному совпадению текста.
      const lower = arg.toLowerCase();
      const foundIdx = list.findIndex((item) => item.text.toLowerCase().includes(lower));
      if (foundIdx === -1) {
        await ctx.reply("не нашёл такого пункта в памяти этого чата — гляну /memory", replyOpts);
        return;
      }
      const removedText = list[foundIdx].text;
      removeMemoryItem(chatId, foundIdx + 1);
      await ctx.reply(`забыл: «${removedText}»`, replyOpts);
      return;
    }
  }

  // ==== "Скажи голосом: ..." / "озвучь ..." — разовая озвучка текста ====
  // Работает независимо от режима /voice на весь чат (см. voiceEnabledChats
  // выше) — это разовый вызов, ничего не переключает и не персистится.
  // Два варианта: 1) с текстом сразу в команде ("Жень, скажи голосом:
  // купи молока") — озвучиваем именно этот текст; 2) реплаем на
  // предыдущее сообщение бота, без текста после самой команды ("озвучь" /
  // "скажи голосом" реплаем на ответ бота) — берём текст того сообщения
  // через getBotReply (тот же кэш, что использует "Трейлер"/"как он
  // тебе?" ниже).
  if (TTS_SPACE) {
    const voiceCommandText = stripBotAddressing(rawText, ctx);
    const voiceMatch = voiceCommandText.match(/^(?:скажи\s+голосом|озвучь)[,:]?\s*([\s\S]*)$/i);
    if (voiceMatch) {
      const replyOpts = {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: ctx.message.message_thread_id,
      };
      let textToVoice = voiceMatch[1].trim();
      if (!textToVoice && isReplyToBot(ctx)) {
        const repliedBotMsg = getBotReply(chatId, ctx.message.reply_to_message.message_id);
        if (repliedBotMsg) textToVoice = repliedBotMsg.text;
      }
      if (!textToVoice) {
        await ctx.reply(
          "озвучить что? напиши текст после команды, либо реплайни этим на моё сообщение",
          replyOpts
        );
        return;
      }
      sendTypingAction(ctx, "record_voice");
      const audioBuffer = await synthesizeSpeech(stripForVoice(textToVoice));
      if (audioBuffer) {
        await ctx.replyWithVoice(new InputFile(audioBuffer, "voice.ogg"), replyOpts);
      } else {
        await ctx.reply("не получилось озвучить — Space не ответил или недоступен", replyOpts);
      }
      return;
    }
  }

  // ==== "Трейлер" реплаем на карточку фильма/сериала ====
  // Отдельно от блока ниже ("как он тебе?"), потому что тут нужен не
  // текст для LLM, а прямое действие в обход модели — сходить на TMDB за
  // /videos и прислать ссылку на YouTube. Если реплай не на карточку (или
  // в кэше почему-то нет kind/id — например, старая карточка, отправленная
  // до этого изменения) — просто идём дальше обычным путём.
  if (isReplyToBot(ctx) && /трейлер/i.test(rawText)) {
    const movieCard = getMovieCard(chatId, ctx.message.reply_to_message.message_id);
    if (movieCard && movieCard.kind && movieCard.id) {
      sendTypingAction(ctx);
      const replyOpts = {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: ctx.message.message_thread_id,
      };
      try {
        // Сначала TMDB — там же уже отдаёт русское видео, если оно есть
        // (fetchTmdbTrailerInfo сама ищет iso_639_1 === "ru" среди всех
        // видео тайтла). Если русского там нет — идём в YouTube-поиск,
        // и только если совсем ничего не нашлось нигде — отдаём
        // оригинальный TMDB-трейлер как крайний случай, с пометкой.
        const tmdbTrailer = await fetchTmdbTrailerInfo(
          movieCard.kind,
          movieCard.id,
          movieCard.title,
          movieCard.originalTitle,
        );
        let trailerUrl = tmdbTrailer && tmdbTrailer.isRu ? tmdbTrailer.url : null;
        let note = "";

        if (!trailerUrl) {
          trailerUrl = await searchYoutubeTrailerRu(movieCard.title, movieCard.year);
        }
        if (!trailerUrl && tmdbTrailer) {
          trailerUrl = tmdbTrailer.url;
          note = "\n(русского не нашёл, это оригинальный трейлер)";
        }

        if (trailerUrl) {
          await ctx.reply(`${trailerUrl}${note}`, replyOpts);
        } else {
          await ctx.reply("трейлер для этого не нашёлся ни на TMDB, ни на YouTube", replyOpts);
        }
      } catch (err) {
        console.error("Ошибка получения трейлера:", err.message);
        await ctx.reply("не получилось получить трейлер — попробуй позже", replyOpts);
      }
      return;
    }
  }

  // ==== Ответ на карточку фильма/сериала ("как он тебе?" реплаем) ====
  // Карточки из sendMovieCard отправляются напрямую (в обход askLLM), так
  // что в обычную историю диалога не попадают — без этого блока модель на
  // "как он тебе?" реплаем на карточку понятия не имела бы, о каком именно
  // фильме речь. В отличие от repliedTag выше (только для группы и только
  // для чужих сообщений) — этот работает и в группе, и в личке, потому что
  // тут всегда реплай именно на СВОЁ (ботовское) сообщение.
  if (isReplyToBot(ctx)) {
    const repliedToBotMsg = ctx.message.reply_to_message;
    const movieCard = getMovieCard(chatId, repliedToBotMsg.message_id);
    if (movieCard) {
      const parts = [`${movieCard.kindLabel} «${movieCard.title}»${movieCard.year ? ` (${movieCard.year})` : ""}`];
      if (movieCard.rating) parts.push(`рейтинг ${movieCard.rating}/10 на TMDB`);
      if (movieCard.genres) parts.push(`жанры: ${movieCard.genres}`);
      if (movieCard.summary) parts.push(`описание: ${movieCard.summary}`);
      userText = `[бот ранее прислал карточку — ${parts.join(", ")}] ${userText}`;

      // Реплаем на карточку ещё и явно попросили что-то поискать в
      // интернете ("Жень поищи когда сиквел") — гоняем отдельный запрос
      // через Compound с контекстом фильма, чтобы поиск был предметным
      // (без названия фильма в запросе "когда сиквел" ушло бы в пустоту).
      if (hasSearchIntent(rawText)) {
        sendTypingAction(ctx);
        const movieContext = `${movieCard.kindLabel} «${movieCard.title}»${movieCard.year ? ` (${movieCard.year})` : ""}`;
        try {
          const found = await searchWeb(`${movieContext}. Запрос: ${strippedQuestion}`);
          userText = `[результаты веб-поиска про ${movieContext} по запросу «${strippedQuestion}»: ${found}] ${userText}`;
          searchUsedThisMessage = true;
        } catch (err) {
          console.error(
            `Ошибка веб-поиска (карточка фильма) в чате ${chatId}:`,
            err.status ?? "-",
            err.body ?? err.message
          );
          userText = `[попытка веб-поиска про ${movieContext} не удалась технически — если знаешь ответ по своим знаниям, отвечай сам, иначе честно скажи, что не смог погуглить] ${userText}`;
        }
      }
    } else if (repliedToBotMsg.audio || getVoiceTranscript(chatId, repliedToBotMsg.message_id)) {
      // ==== Реплай на трек (Deezer) или на присланный ботом дословный
      // текст песни ====
      // Явные новые поисковые запросы ("найди трек X", просто голое
      // название) уже перехвачены раньше (см. блок Deezer выше) — сюда
      // попадают именно вопросы/комментарии о самой песне ("о чём эта
      // песня?", "переведи", "нравится?" и т.п.), причём реплаем МОГУТ быть
      // как на сам аудиофайл трека, так и на отдельное текстовое сообщение
      // с дословным текстом песни, которое бот раньше прислал по команде
      // "текст"/"текст песни" (см. ветку wantsLiteralLyrics ниже — там при
      // отправке текста мы дополнительно запоминаем его в этом же кэше
      // расшифровок под message_id ЭТОГО сообщения, иначе повторный реплай
      // на сам присланный текст песни, а не на аудиофайл, бот "не видел" —
      // repliedToBotMsg.audio у текстового сообщения нет, и раньше это
      // проваливалось в общую ветку getBotReply, которая про такое вообще
      // не знала). Если модель знает песню по названию/исполнителю — ей
      // этого обычно достаточно; если нет (или чтобы не гадать про смысл) —
      // прогоняем сам файл через тот же Whisper-пайплайн, что и для
      // аудио/голосовых от людей (см. repliedTag выше и transcribeVoice) и
      // подмешиваем распознанный текст песни в промпт. Кэш расшифровок
      // (voiceTranscriptsByMessage) общий с тем блоком — повторный реплай
      // на тот же трек/текст не гоняет файл через Whisper заново.
      const trackAudio = repliedToBotMsg.audio;
      const wantsLiteralLyrics = VOICE_TRANSCRIBE_INTENT_REGEX.test(rawText.trim());
      // Как и в блоке про голосовые выше — явный выбор движка обходит кэш
      // и перераспознаёт заново (актуально в первую очередь тут: короткий
      // отрывок иностранной песни — самый частый случай, когда GigaAM или
      // авто-язык может ошибиться, и хочется явно сказать "через Whisper").
      const engineOverride = detectEngineOverride(rawText);
      let lyricsInfo = engineOverride === "auto" ? getVoiceTranscript(chatId, repliedToBotMsg.message_id) : null;
      const trackLabel =
        (trackAudio && [trackAudio.performer, trackAudio.title].filter(Boolean).join(" — ")) ||
        lyricsInfo?.name ||
        "";

      let lyricsError = null;
      let lyricsTooLarge = false;
      if (!lyricsInfo) {
        if (trackAudio?.file_size && trackAudio.file_size > MAX_TRANSCRIBE_FILE_SIZE) {
          lyricsTooLarge = true;
        } else {
          try {
            const { text } = await transcribeVoice(ctx, trackAudio.file_id, engineOverride);
            lyricsInfo = { name: trackLabel || "бот", text };
            rememberVoiceTranscript(chatId, repliedToBotMsg.message_id, trackLabel || "бот", text);
          } catch (err) {
            lyricsError = err;
            console.error(
              `Не удалось распознать текст песни «${trackLabel}» в чате ${chatId}:`,
              err.status ?? "-",
              err.body ?? err.message
            );
          }
        }
      }

      if (wantsLiteralLyrics) {
        // Прямая просьба прислать именно текст песни (не пересказ) —
        // отвечаем дословной расшифровкой напрямую, без похода в LLM,
        // ровно так же, как для голосовых/аудио от людей выше.
        if (lyricsTooLarge) {
          await ctx.reply(`файл слишком большой (больше 20 МБ), Telegram не даёт его скачать ботам`, {
            reply_parameters: { message_id: ctx.message.message_id },
            message_thread_id: ctx.message.message_thread_id,
          });
        } else if (lyricsError) {
          await ctx.reply("не смог распознать текст песни, попробуй ещё раз", {
            reply_parameters: { message_id: ctx.message.message_id },
            message_thread_id: ctx.message.message_thread_id,
          });
        } else if (!lyricsInfo.text) {
          await ctx.reply("не распознал текст в этом треке — похоже, инструментал, либо качество не позволило", {
            reply_parameters: { message_id: repliedToBotMsg.message_id },
            message_thread_id: ctx.message.message_thread_id,
          });
        } else {
          const sentLyricsMsg = await ctx.reply(lyricsInfo.text, {
            reply_parameters: { message_id: repliedToBotMsg.message_id },
            message_thread_id: ctx.message.message_thread_id,
          });
          // Запоминаем текст под message_id ИМЕННО этого отправленного
          // сообщения — см. пояснение в комментарии выше про реплай на сам
          // присланный текст песни, а не на аудиофайл.
          rememberVoiceTranscript(chatId, sentLyricsMsg.message_id, trackLabel || "бот", lyricsInfo.text);
        }
        return;
      }

      const lyricsSnippet = lyricsInfo?.text
        ? lyricsInfo.text.length > VOICE_TRANSCRIPT_PROMPT_LIMIT
          ? `${lyricsInfo.text.slice(0, VOICE_TRANSCRIPT_PROMPT_LIMIT)}…`
          : lyricsInfo.text
        : null;
      const lyricsPart = lyricsSnippet
        ? `, текст песни: ${lyricsSnippet}`
        : lyricsError || lyricsTooLarge
          ? " (текст распознать не получилось технически — если знаешь песню по названию, отвечай по своим знаниям, иначе честно скажи, что не смог посмотреть текст)"
          : " (похоже на инструментал без слов — если только не знаешь эту песню по названию)";
      userText = `[бот ранее прислал трек «${trackLabel || "без названия"}»${lyricsPart}] ${userText}`;
    } else {
      // Реплай на обычный (не карточка, не трек) текстовый ответ бота — в
      // том числе старый, уже выпавший из HISTORY_LIMIT, и/или
      // адресованный не тому, кто сейчас отвечает (человек 2 реплаит
      // ответ, который бот когда-то дал человеку 1). Подмешиваем, что
      // именно бот тогда написал и кому — без этого модель отвечает
      // вслепую, не понимая, к чему вопрос.
      const botReply = getBotReply(chatId, repliedToBotMsg.message_id);
      if (botReply) {
        const snippet =
          botReply.text.length > 1000 ? `${botReply.text.slice(0, 1000)}…` : botReply.text;
        userText = `[бот ранее ответил ${botReply.name}: "${snippet}"] ${userText}`;
      }
    }
  }

  // ==== Анекдоты ====
  // Тоже проверяем ДО обычного чата и отвечаем не через LLM — сначала
  // пробуем свежий анекдот с внешнего источника, при неудаче/пустом
  // ответе тихо уходим на курируемую базу (см. getJoke/JOKES выше).
  // Модель на такую просьбу обычно выдумывает несмешную ерунду.
  if (isJokeRequest(stripBotAddressing(rawText, ctx))) {
    sendTypingAction(ctx);
    await ctx.reply(await getJoke(chatId), { reply_parameters: { message_id: ctx.message.message_id } });
    return;
  }

  // ==== Погода ====
  // Проверяем ДО блока веб-поиска (и ДО шахмат/шашек, обычного чата) — по
  // двум причинам разом: (1) сработавший запрос погоды отвечает сразу
  // через Open-Meteo API, а не через LLM (даты/проценты осадков модель
  // может просто выдумать), и (2) если проверять погоду ПОСЛЕ блока
  // поиска (как было раньше), classifySearchIntent успевает сработать
  // первым — в её системном промпте "погода" прямо перечислена как повод
  // для веб-поиска (см. SEARCH_INTENT_SYSTEM_PROMPT выше), из-за чего на
  // "погода в Киеве" уходил лишний платный запрос в Tavily/Compound, чей
  // результат тут же отбрасывался, как только ниже отрабатывал этот же
  // regex-парсер погоды. Теперь при совпадении parseWeatherIntent мы
  // отвечаем и выходим ДО того, как блок поиска вообще успевает
  // запуститься.
  const weatherIntent = parseWeatherIntent(stripBotAddressing(rawText, ctx));
  if (weatherIntent) {
    await handleWeatherQuery(ctx, weatherIntent);
    return;
  }

  // ==== Поиск в интернете по явной просьбе ====
  // В отличие от погоды/фильмов ниже — НЕ возвращаемся сразу. Результат
  // поиска подмешивается тегом в userText (тот же приём, что и у
  // repliedTag/movieCard выше) и уходит дальше по обычному пути в
  // askLLM в конце обработчика — так ответ идёт в персоне Жени, с учётом
  // истории переписки, а не отдельным сухим блоком фактов от Compound.
  // Дошли сюда — сообщение уже точно адресовано боту (см. isAddressedToBot
  // внутри if (isGroup) выше; в личке — адресовано по умолчанию), и уже
  // точно НЕ погода (см. блок погоды выше — он идёт раньше и выходит
  // return'ом при совпадении).
  //
  // Решение "нужен ли поиск и по какому запросу" принимает
  // classifySearchIntent (см. определение выше) — она видит историю
  // переписки, поэтому понимает follow-up'ы без темы ("Ну загугли") и не
  // тащит в сам запрос слово-триггер. Если классификатор технически упал
  // (таймаут/лимит/ошибка провайдера) — фолбэк на старый быстрый regex
  // (hasSearchIntent), чтобы явные "загугли X" не терялись совсем даже при
  // проблемах с LLM-классификацией; в этом фолбэк-случае слово-триггер из
  // самого запроса вырезаем вручную, чтобы не повторить старый баг.
  {
    const strippedForSearch = stripBotAddressing(rawText, ctx);
    let searchQuery = null;
    try {
      searchQuery = await classifySearchIntent(chatId, strippedForSearch);
    } catch (err) {
      console.error(
        "Ошибка классификации поискового интента, фолбэк на regex:",
        err.status ?? "-",
        err.body ?? err.message
      );
      if (hasSearchIntent(strippedForSearch)) {
        searchQuery =
          strippedForSearch
            .replace(SEARCH_STANDALONE_VERB_REGEX, "")
            .replace(SEARCH_GENERIC_VERB_REGEX, "")
            .trim() || strippedForSearch;
      }
    }
    if (searchQuery) {
      console.log(`Поиск в интернете: интент сработал, запрос «${searchQuery}»`);
      sendTypingAction(ctx);
      try {
        const found = await searchWeb(searchQuery);
        userText = `[результаты веб-поиска по запросу «${searchQuery}»: ${found}] ${userText}`;
        searchUsedThisMessage = true;
      } catch (err) {
        console.error("Ошибка веб-поиска:", err.status ?? "-", err.body ?? err.message);
        userText = `[попытка веб-поиска по запросу «${searchQuery}» не удалась технически — если знаешь ответ по своим знаниям, отвечай сам, иначе честно скажи, что не смог погуглить] ${userText}`;
      }
    }
  }

  // ==== Поиск фильмов ("Женя, фильм Аватар 2009") ====
  // Проверяем в том же месте, что и погоду/анекдоты — до шахмат/шашек и
  // обычного чата, по той же причине (иначе может перехватиться как
  // попытка хода в незавершённой партии).
  const movieIntent = parseMovieIntent(stripBotAddressing(rawText, ctx));
  if (movieIntent) {
    await handleMovieQuery(ctx, movieIntent);
    return;
  }

  // ==== Гороскоп / натальная карта ("гороскоп на завтра", "натальная
  // карта", "мои аспекты") ====
  // Тоже до шахмат/обычного чата, той же причины ради — иначе "гороскоп"
  // рискует улететь в LLM как обычный текст вместо реального расчёта.
  const horoscopeIntent = parseHoroscopeQueryIntent(stripBotAddressing(rawText, ctx));
  if (horoscopeIntent) {
    await handleHoroscopeQuery(ctx, horoscopeIntent);
    return;
  }

  // ==== Таро ("карта дня", "таро", "расклад таро", "три карты",
  // "кельтский крест") ====
  // Та же логика, что и у гороскопа выше — до шахмат/обычного чата, иначе
  // "таро"/"карта дня" рискует улететь в LLM как обычный текст вместо
  // реального (случайного) расклада.
  const tarotIntent = parseTarotQueryIntent(stripBotAddressing(rawText, ctx));
  if (tarotIntent) {
    await runTarotSpread(ctx, tarotIntent.spreadType, tarotIntent.question);
    return;
  }

  // ==== Пересказ чата ("Женя, о чём тут речь? 100") ====
  // Только в группах — лог (ChatLog) заполняется исключительно там, в
  // личке пересказывать нечего (там и так вся история — это диалог с
  // самим ботом). Отвечает не через обычный askLLM/историю чата, а через
  // отдельный askRecapLLM на основе лога сообщений — см. handleRecapQuery.
  // !repliedToHandled — та же самая фраза "о чём тут речь?" РЕПЛАЕМ на
  // конкретное сообщение (голосовое/аудио/фото/текст) означает вопрос про
  // ЭТО сообщение, а не просьбу пересказать весь чат — repliedTag уже
  // подмешан в userText выше, и туда должен пойти обычный askLLM, а не
  // отдельный recap-пайплайн по логу чата.
  // ==== "Кто зашёл/вышел из чата" (точечный вопрос, без похода в LLM) ====
  // Проверяем РАНЬШЕ общего пересказа: если оставить эту проверку после
  // RECAP_INTENT_REGEX, коллизии тут не случится (в нём нет слов
  // "ушёл"/"зашёл"), но порядок всё равно важен принципиально — это более
  // узкий и точный интент, и он не должен зависеть от того, что происходит
  // ниже по цепочке проверок.
  // ==== "Кто такой/такая Х" (точечный вопрос про участника чата) ====
  // Перед join/leave и вообще всем остальным — тот же принцип, что и у
  // соседних точечных интентов ниже: узкий и надёжный кейс не должен
  // зависеть от порядка более общих проверок. Если Х не резолвится ни в
  // кого знакомого — handleWhoIsQuery вернёт false, и мы просто идём
  // дальше по обычной цепочке (в итоге в LLM), ничего не потеряв.
  if (isGroup && !repliedToHandled) {
    const whoIsMatch = WHO_IS_INTENT_REGEX.exec(stripBotAddressing(rawText, ctx));
    if (whoIsMatch && (await handleWhoIsQuery(ctx, chatId, whoIsMatch[1]))) {
      return;
    }
  }

  if (isGroup && !repliedToHandled) {
    const strippedForJoinLeave = stripBotAddressing(rawText, ctx);
    if (JOIN_LEAVE_INTENT_REGEX.test(strippedForJoinLeave)) {
      const joinLeaveType = determineJoinLeaveType(strippedForJoinLeave);
      if (joinLeaveType) {
        await handleJoinLeaveQuery(ctx, chatId, joinLeaveType);
        return;
      }
    }
  }

  if (isGroup && !repliedToHandled && RECAP_INTENT_REGEX.test(stripBotAddressing(rawText, ctx))) {
    await handleRecapQuery(ctx, chatId, parseRecapCount(stripBotAddressing(rawText, ctx)));
    return;
  }

  // ==== Крокодил (естественный триггер "Женя, крокодил") ====
  // Проверяем ДО шахмат/шашек — по той же причине, что и погода/анекдоты
  // выше: если оставить эту проверку в конце шахматно-шашечной цепочки (как
  // было раньше), то при незавершённой шахматной/шашечной партии у этого
  // пользователя сообщение "Женя, крокодил" сначала пыталось бы
  // распознаться как ход/команда партии, не подошло бы под них — и тихо
  // улетало в обычный LLM-чат вместо запуска крокодила. Здесь же триггер
  // не может ничего сломать в шахматах/шашках (слово "крокодил" не
  // пересекается ни с одной из их команд), так что вынести его раньше
  // безопасно.
  if (KROKODIL_INTENT_REGEX.test(rawText)) {
    const krokodilGame = getKrokodilGame(chatId);
    if (!krokodilGame || krokodilGame.status === "idle") {
      await sendKrokodilIdleMessage(ctx, chatId);
    } else if (krokodilGame.status === "choosing") {
      await ctx.reply(`${krokodilGame.candidateName} сейчас выбирает сложность слова — подожди секунду`);
    } else {
      await ctx.reply(
        `идёт раунд — ведёт ${krokodilGame.hostName}, остальные угадывают словом в чат.\n\n${formatKrokodilLeaderboard(
          chatId
        )}`
      );
    }
    return;
  }

  // ==== Шахматы ====
  // Дошли сюда — значит сообщение точно адресовано боту (в личке всегда,
  // в группе — прошло проверку выше). Партия привязана к паре
  // chatId+userId (см. chessMapKey), поэтому в одном чате (особенно
  // группе) у разных людей могут одновременно идти свои отдельные партии,
  // и ходить в партии может только тот, кто её начал — сообщения других
  // людей просто не видят чужую chessGame и уходят в обычный чат/заводят
  // свою партию. Если для этого пользователя уже идёт партия, пробуем
  // понять сообщение как ход/команду партии; если это ни на что из этого
  // не похоже — просто продолжаем как обычное сообщение в чат ниже (можно
  // болтать параллельно с игрой).
  const userId = ctx.from.id;
  const chessGame = getChessGame(chatId, userId);
  // То же самое для шашек — своя независимая партия под тем же составным
  // ключом chatId+userId, см. checkersMapKey. Один и тот же пользователь
  // не может одновременно вести и шахматную, и шашечную партию: шахматный
  // блок ниже проверяется первым, шашечный — только если шахматной партии
  // нет (см. цепочку if/else if дальше).
  const checkersGame = getCheckersGame(chatId, userId);

  if (chessGame) {
    if (CHESS_RESIGN_REGEX.test(rawText)) {
      await clearChessGame(chatId, userId);
      await ctx.reply(pickRandom(CHESS_RESIGN_PHRASES));
      return;
    }

    // Ход проверяем ДО команд "покажи доску"/"новая партия" — сообщение
    // вида "e2e4, покажи доску" должно сначала применить ход (новая доска
    // и так придёт в ответе), а не просто напечатать старую позицию,
    // проигнорировав сам ход.
    const chess = new Chess(chessGame.fen);
    if (chess.turn() === chessGame.userColor) {
      const applied = tryApplyUserMove(chess, rawText);
      if (applied) {
        const { move, style } = applied;
        // Съеденную ходом пользователя фигуру (если был размен) — в счёт.
        // move.captured — тип чужой фигуры, которую съели (принадлежит
        // противнику хода, т.е. боту), кладём в captured[botColor].
        const prevCaptured = chessGame.captured || { w: [], b: [] };
        const captured = { w: [...prevCaptured.w], b: [...prevCaptured.b] };
        const botColor = chessGame.userColor === "w" ? "b" : "w";
        if (move.captured) captured[botColor].push(move.captured);

        chessGames.set(chessMapKey(chatId, userId), {
          fen: chess.fen(),
          userColor: chessGame.userColor,
          view: chessGame.view,
          playerName: chessGame.playerName,
          captured,
          moveStyle: style,
        });
        saveChessGame(chatId, userId);

        const userMoveText = formatChessMove(move, style);

        if (chess.isCheckmate()) {
          await ctx.reply(
            `${userMoveText}\n${formatBoard(chess, chessGame.userColor, chessGame.view, chessGame.playerName, captured)}\n\n${pickRandom(CHESS_CHECKMATE_LOSE_PHRASES)}`,
            { parse_mode: "Markdown" }
          );
          await clearChessGame(chatId, userId);
          return;
        }
        if (chess.isDraw() || chess.isStalemate()) {
          await ctx.reply(
            `${userMoveText}\n${formatBoard(chess, chessGame.userColor, chessGame.view, chessGame.playerName, captured)}\n\n${pickRandom(CHESS_DRAW_PHRASES)}`,
            { parse_mode: "Markdown" }
          );
          await clearChessGame(chatId, userId);
          return;
        }

        // Ходит бот
        const botMove = findBestMove(chess);
        chess.move(botMove);
        // Съеденную ходом бота фигуру пользователя — тоже в счёт.
        if (botMove.captured) captured[chessGame.userColor].push(botMove.captured);
        chessGames.set(chessMapKey(chatId, userId), {
          fen: chess.fen(),
          userColor: chessGame.userColor,
          view: chessGame.view,
          playerName: chessGame.playerName,
          captured,
          moveStyle: style,
        });
        saveChessGame(chatId, userId);
        const checkNote = chess.isCheck() ? " шах" : "";
        const botMoveText = formatChessMove(botMove, style);

        if (chess.isCheckmate()) {
          await ctx.reply(
            `Мой ход: ${botMoveText}${checkNote}\n${formatBoard(chess, chessGame.userColor, chessGame.view, chessGame.playerName, captured)}\n\n${pickRandom(CHESS_CHECKMATE_WIN_PHRASES)}`,
            { parse_mode: "Markdown" }
          );
          await clearChessGame(chatId, userId);
          return;
        }
        if (chess.isDraw() || chess.isStalemate()) {
          await ctx.reply(
            `Мой ход: ${botMoveText}${checkNote}\n${formatBoard(chess, chessGame.userColor, chessGame.view, chessGame.playerName, captured)}\n\n${pickRandom(CHESS_DRAW_PHRASES)}`,
            { parse_mode: "Markdown" }
          );
          await clearChessGame(chatId, userId);
          return;
        }

        await ctx.reply(
          `Мой ход: ${botMoveText}${checkNote}\n${formatBoard(chess, chessGame.userColor, chessGame.view, chessGame.playerName, captured)}`,
          { parse_mode: "Markdown" }
        );
        return;
      }
      // Ход не распознан. Если сообщение по форме — попытка хода
      // (нелегальный ход/опечатка), говорим об этом прямо, а не отдаём
      // в обычный чат (иначе модель выдумает шахматный комментарий, хотя
      // на доске ничего не изменилось — см. комментарий у looksLikeMoveAttempt).
      if (looksLikeMoveAttempt(rawText)) {
        await ctx.reply(
          "такой ход сделать нельзя (нелегален или опечатка). Глянь позицию — \"покажи доску\" — и попробуй другой, формат e2e4 или Nf3"
        );
        return;
      }
      // Иначе — проверяем, не команда ли это ("покажи доску", "новая партия", смена вида/сторон).
    }

    // Запрошен ли конкретный цвет — нужно и для рестарта ниже, и на
    // случай если запрос пришёл без ход-подобного текста вовсе.
    const requestedColor = parseRequestedUserColor(rawText);

    // Смена вида отображения доски — не трогает саму партию, только то,
    // как её рисуем дальше.
    if (CHESS_VIEW_UNICODE_REGEX.test(rawText) || CHESS_VIEW_ASCII_REGEX.test(rawText)) {
      const newView = CHESS_VIEW_UNICODE_REGEX.test(rawText) ? "unicode" : "ascii";
      if (newView !== chessGame.view) {
        chessGames.set(chessMapKey(chatId, userId), { ...chessGame, view: newView });
        saveChessGame(chatId, userId);
      }
      await ctx.reply(formatBoard(chess, chessGame.userColor, newView, chessGame.playerName, chessGame.captured), {
        parse_mode: "Markdown",
      });
      return;
    }

    if (CHESS_BOARD_REGEX.test(rawText)) {
      await ctx.reply(formatBoard(chess, chessGame.userColor, chessGame.view, chessGame.playerName, chessGame.captured), {
        parse_mode: "Markdown",
      });
      return;
    }

    if (CHESS_NEW_GAME_REGEX.test(rawText) || (requestedColor && requestedColor !== chessGame.userColor)) {
      // Либо явная фраза-рестарт ("новая партия"), либо попросили другой
      // цвет ("играй за белых", "давай ты за белых") — в обоих случаях
      // это фактически перезапуск партии с нужными цветами.
      const userColor = requestedColor || chessGame.userColor;
      const newChess = startChessGame(chatId, userId, userColor, chessGame.view, chessGame.playerName);
      const colorNote = userColor === "w" ? ", ты снова белыми — ходи" : ", ты чёрными — я белыми и хожу первым";
      await ctx.reply(`окей, погнали заново${colorNote}`);
      if (userColor === "b") {
        const botMove = findBestMove(newChess);
        newChess.move(botMove);
        const captured = { w: [], b: [] };
        if (botMove.captured) captured[userColor].push(botMove.captured);
        chessGames.set(chessMapKey(chatId, userId), {
          fen: newChess.fen(),
          userColor,
          view: chessGame.view,
          playerName: chessGame.playerName,
          captured,
          moveStyle: "san",
        });
        saveChessGame(chatId, userId);
        await ctx.reply(
          `Мой ход: ${botMove.san}\n${formatBoard(newChess, userColor, chessGame.view, chessGame.playerName, captured)}`,
          { parse_mode: "Markdown" }
        );
      }
      return;
    }

    // Дошли до конца шахматного блока — ни ход, ни команда партии не
    // распознаны. Если это похоже на приглашение в шашки — не молчим и не
    // отдаём в обычный чат (модель наврёт что-то невпопад про игру),
    // а прямо говорим, что сначала нужно закрыть текущую шахматную
    // партию: одновременно у одного пользователя может идти только одна
    // игра с ботом (шахматы либо шашки), см. пояснение у checkersGame ниже.
    if (CHECKERS_INTENT_REGEX.test(rawText)) {
      await ctx.reply(
        "у нас же ещё не доиграна шахматная партия — доиграй или сдайся (\"сдаюсь\"), тогда сыграем в шашки"
      );
      return;
    }
  } else if (CHESS_INTENT_REGEX.test(rawText)) {
    // Партии для этого пользователя нет, но упомянули шахматы — считаем
    // приглашением и стартуем именно ЕГО партию (chatId+userId), не трогая
    // партии других людей в этом же чате. По умолчанию пользователь играет
    // белыми и ходит первым, но можно сразу попросить чёрных ("сыграем в
    // шахматы за чёрных") — тогда бот берёт белые и ходит первым.
    const userColor = parseRequestedUserColor(rawText) || "w";
    const playerName = getDisplayName(chatId, ctx.from);
    const chess = startChessGame(chatId, userId, userColor, undefined, playerName);
    const view = chessGames.get(chessMapKey(chatId, userId)).view;
    if (userColor === "b") {
      await ctx.reply(pickRandom(CHESS_START_PHRASES_BLACK));
      const botMove = findBestMove(chess);
      chess.move(botMove);
      const captured = { w: [], b: [] };
      if (botMove.captured) captured[userColor].push(botMove.captured);
      chessGames.set(chessMapKey(chatId, userId), { fen: chess.fen(), userColor, view, playerName, captured, moveStyle: "san" });
      saveChessGame(chatId, userId);
      await ctx.reply(`Мой ход: ${botMove.san}\n${formatBoard(chess, userColor, view, playerName, captured)}`, {
        parse_mode: "Markdown",
      });
    } else {
      await ctx.reply(pickRandom(CHESS_START_PHRASES_WHITE));
    }
    return;
  } else if (checkersGame) {
    if (CHESS_RESIGN_REGEX.test(rawText)) {
      await clearCheckersGame(chatId, userId);
      await ctx.reply(pickRandom(CHECKERS_RESIGN_PHRASES));
      return;
    }

    // Ход проверяем ДО команд "покажи доску"/"новая партия" — та же логика,
    // что и в шахматном блоке выше (см. подробный комментарий там).
    if (checkersGame.turn === checkersGame.userColor) {
      const move = tryApplyCheckersMove(checkersGame.board, checkersGame.userColor, rawText);
      if (move) {
        // Съеденные ходом пользователя шашки — до применения хода, доска
        // ещё содержит съедаемые фигуры (см. collectCheckersCaptures).
        const prevCaptured = checkersGame.captured || { w: [], b: [] };
        const captured = { w: [...prevCaptured.w], b: [...prevCaptured.b] };
        for (const c of collectCheckersCaptures(checkersGame.board, move)) {
          captured[c.color].push(c.king ? "king" : "man");
        }

        let board = applyCheckersMove(checkersGame.board, move);
        const opponentColor = checkersGame.userColor === "w" ? "b" : "w";
        const moveNote = move.jumps ? move.jumps.map((j) => rcToSquare(j.toR, j.toC)).join(":") : rcToSquare(move.toR, move.toC);

        const userWinner = checkCheckersWinner(board, opponentColor);
        checkersGames.set(checkersMapKey(chatId, userId), { ...checkersGame, board, turn: opponentColor, captured });
        saveCheckersGame(chatId, userId);

        if (userWinner) {
          await ctx.reply(
            `${moveNote}\n${formatCheckersBoard(board, checkersGame.userColor, checkersGame.view, checkersGame.playerName, captured)}\n\n${pickRandom(CHECKERS_LOSE_PHRASES)}`,
            { parse_mode: "Markdown" }
          );
          await clearCheckersGame(chatId, userId);
          return;
        }

        // Ходит бот
        const botMove = findBestCheckersMove(board, opponentColor);
        for (const c of collectCheckersCaptures(board, botMove)) {
          captured[c.color].push(c.king ? "king" : "man");
        }
        board = applyCheckersMove(board, botMove);
        const botMoveNote = botMove.jumps
          ? botMove.jumps.map((j) => rcToSquare(j.toR, j.toC)).join(":")
          : rcToSquare(botMove.toR, botMove.toC);

        const botWinner = checkCheckersWinner(board, checkersGame.userColor);
        checkersGames.set(checkersMapKey(chatId, userId), { ...checkersGame, board, turn: checkersGame.userColor, captured });
        saveCheckersGame(chatId, userId);

        if (botWinner) {
          await ctx.reply(
            `Мой ход: ${botMoveNote}\n${formatCheckersBoard(board, checkersGame.userColor, checkersGame.view, checkersGame.playerName, captured)}\n\n${pickRandom(CHECKERS_WIN_PHRASES)}`,
            { parse_mode: "Markdown" }
          );
          await clearCheckersGame(chatId, userId);
          return;
        }

        await ctx.reply(
          `Мой ход: ${botMoveNote}\n${formatCheckersBoard(board, checkersGame.userColor, checkersGame.view, checkersGame.playerName, captured)}`,
          { parse_mode: "Markdown" }
        );
        return;
      }
      if (looksLikeCheckersMoveAttempt(rawText)) {
        await ctx.reply(
          "такой ход сделать нельзя (нелегален, или есть обязательное взятие, или опечатка). Глянь позицию — \"покажи доску\" — и попробуй другой, формат b6-c5 или взятие b6:d4"
        );
        return;
      }
    }

    const requestedColor = parseRequestedUserColor(rawText);

    if (CHESS_VIEW_UNICODE_REGEX.test(rawText) || CHESS_VIEW_ASCII_REGEX.test(rawText)) {
      const newView = CHESS_VIEW_UNICODE_REGEX.test(rawText) ? "unicode" : "ascii";
      if (newView !== checkersGame.view) {
        checkersGames.set(checkersMapKey(chatId, userId), { ...checkersGame, view: newView });
        saveCheckersGame(chatId, userId);
      }
      await ctx.reply(
        formatCheckersBoard(checkersGame.board, checkersGame.userColor, newView, checkersGame.playerName, checkersGame.captured),
        { parse_mode: "Markdown" }
      );
      return;
    }

    if (CHESS_BOARD_REGEX.test(rawText)) {
      await ctx.reply(
        formatCheckersBoard(checkersGame.board, checkersGame.userColor, checkersGame.view, checkersGame.playerName, checkersGame.captured),
        { parse_mode: "Markdown" }
      );
      return;
    }

    if (CHESS_NEW_GAME_REGEX.test(rawText) || (requestedColor && requestedColor !== checkersGame.userColor)) {
      const userColor = requestedColor || checkersGame.userColor;
      const newState = startCheckersGame(chatId, userId, userColor, checkersGame.view, checkersGame.playerName);
      const colorNote = userColor === "w" ? ", ты снова белыми — ходи" : ", ты чёрными — я белыми и хожу первым";
      await ctx.reply(`окей, погнали заново${colorNote}`);
      if (userColor === "b") {
        const captured = { w: [], b: [] };
        const botMove = findBestCheckersMove(newState.board, "w");
        for (const c of collectCheckersCaptures(newState.board, botMove)) {
          captured[c.color].push(c.king ? "king" : "man");
        }
        const board = applyCheckersMove(newState.board, botMove);
        const botMoveNote = botMove.jumps
          ? botMove.jumps.map((j) => rcToSquare(j.toR, j.toC)).join(":")
          : rcToSquare(botMove.toR, botMove.toC);
        checkersGames.set(checkersMapKey(chatId, userId), { ...newState, board, turn: "b", captured });
        saveCheckersGame(chatId, userId);
        await ctx.reply(
          `Мой ход: ${botMoveNote}\n${formatCheckersBoard(board, userColor, checkersGame.view, checkersGame.playerName, captured)}`,
          { parse_mode: "Markdown" }
        );
      }
      return;
    }

    // Аналогично шахматному блоку выше — если это похоже на приглашение в
    // шахматы, а не в шашки, явно говорим, что сначала нужно закрыть
    // текущую шашечную партию.
    if (CHESS_INTENT_REGEX.test(rawText)) {
      await ctx.reply(
        "у нас же ещё не доиграна партия в шашки — доиграй или сдайся (\"сдаюсь\"), тогда сыграем в шахматы"
      );
      return;
    }
  } else if (CHECKERS_INTENT_REGEX.test(rawText)) {
    // Партии нет, но упомянули шашки — считаем приглашением, та же логика,
    // что и у шахматного CHESS_INTENT_REGEX выше.
    const userColor = parseRequestedUserColor(rawText) || "w";
    const playerName = getDisplayName(chatId, ctx.from);
    const state = startCheckersGame(chatId, userId, userColor, undefined, playerName);
    if (userColor === "b") {
      await ctx.reply(pickRandom(CHECKERS_START_PHRASES_BLACK));
      const botMove = findBestCheckersMove(state.board, "w");
      const captured = { w: [], b: [] };
      for (const c of collectCheckersCaptures(state.board, botMove)) {
        captured[c.color].push(c.king ? "king" : "man");
      }
      const board = applyCheckersMove(state.board, botMove);
      const botMoveNote = botMove.jumps
        ? botMove.jumps.map((j) => rcToSquare(j.toR, j.toC)).join(":")
        : rcToSquare(botMove.toR, botMove.toC);
      checkersGames.set(checkersMapKey(chatId, userId), { ...state, board, turn: "b", captured });
      saveCheckersGame(chatId, userId);
      await ctx.reply(`Мой ход: ${botMoveNote}\n${formatCheckersBoard(board, userColor, state.view, playerName, captured)}`, {
        parse_mode: "Markdown",
      });
    } else {
      await ctx.reply(pickRandom(CHECKERS_START_PHRASES_WHITE));
    }
    return;
  }

  // Дошли сюда — значит ни шахматной, ни шашечной партии с этим
  // пользователем нет (иначе выше случился бы return), и сообщение не
  // похоже на приглашение начать игру. Если при этом оно похоже на команду
  // "покажи доску" — отвечаем явно, а не отдаём в обычный LLM-чат: модели
  // не с чем сверяться (никакой партии и её позиции у неё нет), и ответ
  // получится выдуманным и вводящим в заблуждение.
  if (CHESS_BOARD_REGEX.test(rawText)) {
    await ctx.reply('нет с тобой партий — ни шахматной, ни шашечной. Начать: просто напиши "шахматы" или "шашки"');
    return;
  }

  // Пол уже определён выше (до блока с banter-триггерами) — тут просто
  // добавляем метку для модели, если он известен. См. пояснение метки
  // в SYSTEM_PROMPT.
  if (gender) {
    userText = `[пол собеседника: ${gender === "m" ? "мужской" : "женский"}] ${userText}`;
  }

  try {
    let reply, stickerKey, voiceBuffer;
    // Режим /voice (см. voiceEnabledChats выше) — если включён и TTS
    // настроен, вместо "печатает..." показываем "записывает голосовое
    // сообщение", и синтез речи делаем сразу тут же, под тем же
    // индикатором, чтобы он не пропадал между "подумал" и "озвучил".
    const voiceOnly = !!TTS_SPACE && voiceEnabledChats.has(chatId);
    await withTyping(
      ctx,
      async () => {
        const res = await askLLM(
          chatId,
          userText,
          searchUsedThisMessage ? POST_SEARCH_ASK_TIMEOUT_MS : undefined
        );
        reply = res.text;
        stickerKey = res.stickerKey;
        await new Promise((r) => setTimeout(r, typingDelayMs(reply.length)));
        if (voiceOnly) {
          voiceBuffer = await synthesizeSpeech(stripForVoice(reply), moodFromStickerKey(stickerKey));
        }
      },
      voiceOnly ? "record_voice" : "typing"
    );

    // Если явная фраза уже вызвала стикер по regex выше — не дублируем
    // ещё одним стикером от тега модели на то же сообщение. Плюс анти-спам:
    // если этому человеку только что уже слали стикер той же категории —
    // не повторяем, отвечаем текстом (см. canSendStickerReaction выше).
    const stickerId =
      !regexStickerFired &&
      stickerKey &&
      canSendStickerReaction(chatId, ctx.from.id, stickerKey) &&
      pickSticker(stickerKey);

    const senderDisplayName = getDisplayName(chatId, ctx.from);

    if (stickerId) {
      // Стикер реально есть чем отправить — шлём ТОЛЬКО его, без текста
      // и без голоса. Текст модели в этом случае был просто реакцией
      // ("спасибо" и т.п.), дублировать её не нужно. В историю (см.
      // askLLM) уже положен полный текст с вырезанным тегом — бот всё
      // равно будет помнить, что "ответил", даже если пользователю ушёл
      // только стикер.
      const sentMsg = await ctx.replyWithSticker(stickerId, {
        reply_parameters: isGroup ? { message_id: ctx.message.message_id } : undefined,
        message_thread_id: ctx.message.message_thread_id,
      });
      rememberBotReply(chatId, sentMsg.message_id, senderDisplayName, reply);
    } else if (voiceOnly && voiceBuffer) {
      // Режим /voice сработал — шлём ТОЛЬКО голосовое, без текстового
      // дубля.
      const sentMsg = await ctx.replyWithVoice(new InputFile(voiceBuffer, "voice.ogg"), {
        reply_parameters: isGroup ? { message_id: ctx.message.message_id } : undefined,
        message_thread_id: ctx.message.message_thread_id,
      });
      rememberBotReply(chatId, sentMsg.message_id, senderDisplayName, reply);
    } else if (isGroup) {
      // Обычный текстовый ответ — либо режим /voice выключен, либо
      // синтез не удался (Space не ответил/упал) и мы не хотим оставлять
      // человека без ответа вовсе.
      const sentMsg = await ctx.reply(reply, {
        reply_parameters: { message_id: ctx.message.message_id },
        message_thread_id: ctx.message.message_thread_id,
      });
      rememberBotReply(chatId, sentMsg.message_id, senderDisplayName, reply);
    } else {
      const sentMsg = await ctx.reply(reply);
      rememberBotReply(chatId, sentMsg.message_id, senderDisplayName, reply);
    }
  } catch (err) {
    console.error("Ошибка обработки сообщения:", err);
    await ctx.reply("блин, что-то сломалось, попробуй ещё раз");
  }
});

bot.catch((err) => {
  console.error("Необработанная ошибка бота:", err);
});

// ==== HTTP-заглушка, чтобы Render/HF Spaces считали сервис "живым" ====
const app = express();
app.get("/", (req, res) => res.send("bot is alive"));
app.listen(PORT, () => console.log(`HTTP ping-сервер запущен на порту ${PORT}`));

// ==== Регистрация команд в Telegram (чтобы появлялись в автоподсказке "/") ====
async function registerCommands() {
  await bot.api.setMyCommands([
    { command: "song", description: "найти и прислать песню с Deezer" },
    { command: "quality", description: "выбрать качество Deezer (128 / 320 / FLAC)" },
    { command: "start", description: "начать (сброс памяти)" },
    { command: "reset", description: "очистить историю переписки" },
    { command: "alias", description: "задать имя человеку вместо ника" },
    { command: "unalias", description: "убрать заданное имя" },
    { command: "aliases", description: "показать список алиасов" },
    { command: "gender", description: "посмотреть/задать пол (свой или реплаем)" },
    { command: "model", description: "выбрать модель / посмотреть текущую" },
    { command: "krokodil", description: "сыграть в крокодил (объясни слово)" },
    { command: "krokodil_reset", description: "сбросить зависший раунд крокодила" },
    { command: "natal", description: "сохранить дату рождения / посмотреть натальную карту" },
    { command: "tarot", description: "расклад Таро (день / три карты / вопрос / кельтский крест)" },
    { command: "imggen", description: "нарисовать картинку по описанию" },
  ]);
  console.log("Команды зарегистрированы в Telegram");
}

// ==== Запуск long polling ====
registerCommands().catch((err) =>
  console.error("Не удалось зарегистрировать команды:", err)
);

// Перед стартом на всякий случай сбрасываем возможный "зависший" вебхук
// и висящие апдейты — помогает от 409 Conflict при передеплое, когда
// старый инстанс на Render ещё не до конца отключился от getUpdates.
async function startBot() {
  await Promise.all([loadPersistedState(), loadKrokodilDictionary()]);

  try {
    await bot.api.deleteWebhook({ drop_pending_updates: true });
  } catch (err) {
    console.error("Не удалось сбросить вебхук перед стартом:", err);
  }

  // onStart просто подтверждает успешный запуск; сама ошибка 409, если
  // всё-таки возникнет во время работы, ловится ниже через .catch —
  // без него необработанный reject валит процесс с голым стектрейсом.
  bot.start({
    onStart: () => console.log("Бот запущен (long polling)"),
  }).catch((err) => {
    console.error("Бот остановился с ошибкой:", err);
    // Даём Render перезапустить процесс начисто, а не висеть в непонятном состоянии
    process.exit(1);
  });
}

startBot();

// Корректно останавливаем поллинг при рестарте/остановке контейнера на Render,
// чтобы старый инстанс не оставался "подвешенным" и не создавал 409 у нового
process.once("SIGINT", () => bot.stop());
process.once("SIGTERM", () => bot.stop());
